/* ÇEVİRİ pl · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("pl","olay",{
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Wycofanie armii egipskiej z Anatolii zakończone przez Gülek", "a53ac2a3"], "d": ["Po układzie z Kütahyi siły egipskie opuściły Anatolię; około połowy czerwca cała armia przeszła przez przełęcz Gülek do Çukurovy. Wybrzeże İçil (Mersin, Silifke) wraca pod zarząd osmański; muhassıllık Adany i Syria pozostają przy Egipcie.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Traktat w Hünkâr İskelesi", "da741d5c"], "d": ["Podpisano z Rosją ośmioletni sojusz obronny. Według tajnego artykułu Osmanowie mieli zamknąć cieśniny dla okrętów wojennych, jeśli Rosja zostanie zaatakowana. Była to jedna z najbardziej spornych decyzji osmańskiej dyplomacji, która uaktywniła Anglię w sprawie egipskiej.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Powstanie w Palestynie-Nablus przeciw zarządowi egipskiemu", "4fe43e27"], "d": ["Obowiązkowa służba wojskowa, zbieranie broni i nowe podatki wywołały w Palestynie szerokie powstanie. Powstanie surowo stłumiono; poparcie dla zarządu egipskiego wśród miejscowej ludności szybko się wyczerpało.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Koniec egipskiego zarządu Maraşu (w przybliżeniu)", "bb46ca42"], "d": ["Gdy zdanie TDV o czasie „blisko dziewiętnastu miesięcy” liczy się od okupacji w 1833, zarząd egipski kończy się około lata 1834. To, że Mustafa Bej z Küçükalioğulları nie zdołał w 1834 stawić oporu armii egipskiej i wycofał się w stronę Maraşu, pokazuje też, że Maraş był wówczas schronieniem poza kontrolą egipską.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Powstanie w Dżabal ad-Druz", "12e74626"], "d": ["Opór, który wybuchł w regionie druzyjskim, trwał dwa lata. Niezadowolenie nagromadzone w Syrii miało w 1840, gdy floty sprzymierzonych wylądowały na wybrzeżu, odsłonić tyły armii egipskiej.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali ogłosił zamiar niepodległości", "48633bbd"], "d": ["Namiestnik oznajmił konsulom wielkich mocarstw, że rozważa ogłoszenie niepodległości Egiptu i Syrii. Anglia stanowczo temu się sprzeciwiła: powstanie silnego państwa na Morzu Śródziemnym, bliskiego Francji, zagrażałoby drodze do Indii.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Armia osmańska przekroczyła Eufrat", "9af1ea69"], "d": ["Mahmud II skierował armię na granicę syryjską, by odzyskać to, co stracił pod Kütahyą. Pruski oficer Moltke, który przebywał w armii jako doradca, sprzeciwił się wyborowi pozycji i wczesnemu atakowi; jego sprzeciwów nie wysłuchano.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Bitwa pod Nizip — armia osmańska rozproszona", "156b3cdf"], "d": ["Źle rozstawiona armia osmańska została rozbita w ciągu kilku godzin. Sułtan zmarł, zanim wieść o klęsce dotarła do Stambułu; państwo w ciągu kilku dni miało stracić armię, władcę, a następnie flotę.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Śmierć Mahmuda II", "07eccfff"], "d": ["Sułtan, który w ciągu trzydziestojednoletniego panowania zniósł janczarów i odbudował zarząd centralny, zmarł, nie pokonawszy swego największego przeciwnika. Choroby nie rozpoznano trafnie. Jego śmierć utrzymywano w tajemnicy do 30 czerwca, aż w mieście przedsięwzięto środki wojskowe, z obawy przed poruszeniem się mentalności janczarskiej.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Wstąpienie na tron Abdülmecida i pogrzeb Mahmuda II", "d0f3d2cc"], "d": ["Po śmierci ojca na tron wstąpił szesnastoletni Abdülmecid. W tym samym dniu zwłoki Mahmuda II przewieziono do Pałacu Topkapı; obawiane zamieszki nie wybuchły, a w kondukcie uczestniczyły szerokie rzesze muzułmanów i niemuzułmanów.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Oddanie floty Aleksandrii", "a53e6103"], "d": ["Kapudan pasza Ahmed Fevzi Pasza, podejrzewając, że wielki wezyr Koca Hüsrev Pasza odda flotę Rosji, zaprowadził flotę do Aleksandrii i oddał ją Mehmedowi Alemu. Państwo osmańskie w tym samym miesiącu pozostało bez armii, bez sułtana i bez floty.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Wspólna nota wielkich mocarstw", "2a3b8316"], "d": ["Pięć mocarstw przekazało Bâbıâli notę, żądając, by w sprawie egipskiej nie zawierało porozumienia samodzielnie. Wewnętrzna sprawa stała się w ten sposób oficjalnie „kwestią europejską”; państwo osmańskie faktycznie utraciło prawo decydowania o własnej prowincji.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Traktat londyński: cztery mocarstwa po stronie Osmanów", "a517f775"], "d": ["Traktat podpisany z pominięciem Francji dał Mehmedowi Alemu ultimatum: jeśli zgodzi się w ciągu dziesięciu dni — dziedziczne namiestnictwo Egiptu i Akka dożywotnio; jeśli w ciągu dwudziestu dni — tylko Egipt; jeśli odmówi — nic. Namiestnik odmówił.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Bombardowanie Bejrutu i lądowanie sprzymierzonych", "0905ce92"], "d": ["Flota angielsko-austriacka ostrzelała Bejrut; ludności, która powstała w górach Libanu przeciw zarządowi egipskiemu, rozdano broń. Kontrola İbrâhima Paszy w Syrii załamała się między buntem wewnętrznym a interwencją zewnętrzną.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Utrata Bejrutu i miast przybrzeżnych", "09bdaf23"], "d": ["Po walkach w kierunku Baalbeku siły egipskie wycofały się znad wybrzeża. Na mapie wybrzeże Libanu wychodzi z odcienia zależnego i wraca pod zarząd bezpośrednio osmański.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Akka padła w dwie godziny", "5aec21f0"], "d": ["Pod bombardowaniem floty sprzymierzonych wybuchł arsenał twierdzy, a Akka poddała się w ciągu kilku godzin. Twierdza, którą osiem lat wcześniej İbrâhim Pasza zdobył w sześć miesięcy, pokazała przewagę artylerii morskiej.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Konwencja aleksandryjska", "85cb47b0"], "d": ["Mehmed Ali zgodził się zrzec Syrii, Adany, Krety i Hidżazu, zwrócić flotę osmańską i uznać zwierzchnictwo sułtana; w zamian zagwarantowano dziedziczne namiestnictwo Egiptu.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Armia egipska opuściła Syrię i Çukurovę", "719a28dc"], "d": ["Dziewięcioletnia okupacja dobiegła końca; armia İbrâhima Paszy wróciła do Egiptu przez Synaj. Na mapie szeroki pas od Aleppo po Gazę i od Adany po Kretę przechodzi ponownie pod zarząd bezpośrednio osmański. W tym samym dniu utracono także inne miejscowości: Urfa, Maraş, Tarsus, Antiochia, Kandia (Kreta), Hama, Damaszek, Jerozolima, Jafa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Ferman: namiestnictwo Egiptu zostawione dziedzicznie rodzinie z Kawali", "87b89ff8"], "d": ["Ferman sułtański uznał namiestnictwo za przechodzące w obrębie dynastii z ojca na syna; w zamian liczebność armii obniżono do osiemnastu tysięcy, podatek związano ze Stambułem, a uprawnienia do bicia monety i zawierania traktatów odebrano. Egipt pozostał prowincją, lecz był już krajem odrębnej dynastii. Zarząd Hidżazu i Haremejn wrócił do Bâbıâli. W tym samym dniu z warstwy zależnej wracają do warstwy bezpośredniej inne miejscowości: Mekka, Medyna, Dżudda, Yanbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Konwencja o cieśninach w Londynie", "0e95a1ea"], "d": ["Konwencja, która zastąpiła Hünkâr İskelesi, postanowiła, że w czasie pokoju cieśniny są zamknięte dla wszystkich okrętów wojennych. Przywilej, który Rosja zyskała sama, stał się w ten sposób wspólną gwarancją Europy; kwestia cieśnin zyskała status międzynarodowy.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["İbrâhim Pasza faktycznie namiestnikiem Egiptu", "9e14f5d9"], "d": ["W miejsce starzejącego się i tracącego władze umysłowe Mehmeda Alego na namiestnictwo wprowadzono jego syna İbrâhima Paszę. Jednak po kilku miesiącach, w listopadzie 1848, zmarł przed ojcem.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Śmierć Mehmeda Alego Paszy z Kawali", "871310e0"], "d": ["Namiestnik, który urodził się w Kawali, założył dynastię w Egipcie i dwukrotnie doprowadził imperium na skraj przepaści, zmarł w wieku osiemdziesięciu lat. Założona przezeń dynastia panowała w Egipcie do 1953; państwo zaś, widząc, że ranę otwartą przezeń zdołało zamknąć interwencją europejską, poszło drogą Tanzimatu.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Süleyman b. Kutalmış pokonany i zabity pod Ajn Sulajm; Antiochia wyszła spod Seldżuków Anatolijskich", "0412dfa1"], "d": ["Süleyman b. Kutalmış, który w 1084 zajął Antiochię od Bizancjum, zginął w bitwie pod Ajn Sulajm stoczonej z władcą Seldżuków Syryjskich Tutuşem; miasto przeszło pod kontrolę sułtana Wielkich Seldżuków Melikszaha, a namiestnikiem mianowano Yağısıyana.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Melikszah zmarł; Antiochia wraz z Yağısıyanem została przyłączona do Tutuşa z Seldżuków Syryjskich", "c61da1b4"], "d": ["Po śmierci sułtana Wielkich Seldżuków Melikszaha państwo zostało podzielone między dziedziców; namiestnik Antiochii Yağısıyan związał się z panem Syrii Tutuşem.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Nikea poddała się krzyżowcom; ośrodek seldżucki cofnął się do Konyi, Bizancjum zaczęło odzyskiwać zachodnią Anatolię", "8a4e90fa"], "d": ["Po oblężeniu Nikei przez krzyżowców miasto poddało się 19 czerwca 1097 Bizancjum; sułtan seldżucki Kılıç Arslan I wycofał swój ośrodek w głąb kraju, do Konyi, a Bizancjum odzyskało miejsca na wybrzeżu zachodniej Anatolii, takie jak Efez.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Kılıç Arslan II zajął od Bizancjum Dorylaion (Eskişehir) i Kütahyę", "3ddee6c2"], "d": ["Po Myriokefalonie (1176) bizantyjskie twierdze Dorylaion i Kütahya we wnętrzu Anatolii wpadły w ostatnich latach Manuela / po jego śmierci w 576/1180 w ręce Kılıça Arslana II.", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Karamanoğlu Mehmed Bej mianowany subaszą Ermenek, objął İç İl", "6d62be11"], "d": ["Karamanoğlu Mehmed Bej został w 675 (1276) mianowany subaszą Ermenek i objął İç İl swoim zarządem; Ermenek stał się pierwszym ośrodkiem Karamanoğulları, którzy w następnym roku mieli pomaszerować na Konyę.", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Śmierć Ertuğrula Gazi i przejęcie bejlika przez Osmana Beja — spuścizna Söğüt i Domaniç", "395fb9fa"], "d": ["Według TDV Ertuğrul Gazi zmarł w 680 (1281–82); hasło odnotowuje, że podaje się też daty 1288 i 1289. Osman Bej przejął po ojcu nie zdobyte miasto, lecz dwa nadania, które sułtan seldżucki dał Ertuğrulowi, osadzonemu na najdalszej linii pogranicza: zimowisko (yurtluk) w Söğüt i pastwisko letnie w Domaniç. Bejlik rozpoczął więc nie ze spuścizną zdobyczy, lecz z dwoma nadaniami pastwisk; na mapie te dwa miejsca są pokazane nie jako „zdobycz”, lecz „spuścizna”.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Nieszpory sycylijskie — dynastia Andegawenów utraciła wyspę Sycylię", "547db635"], "d": ["Powstanie, które w Palermo wybuchło w poniedziałek wielkanocny o godzinie nieszporów przeciw rządom Karola I Andegaweńskiego, oderwało wyspę Sycylię od dynastii Andegawenów. Królestwo Sycylii podzieliło się na dwie części: wyspa zwróciła się ku Aragonii, a dynastia Andegawenów utrzymała się w królestwie kontynentalnym z ośrodkiem w Neapolu. Zamorskie posiadłości dynastii na Adriatyku i Morzu Śródziemnym pozostały też przy tym królestwie: Korfu, które trzymali od 1267, i Durrës, które trzymali od lat 70. XIII wieku, trwały jako część Królestwa Neapolu; również twierdze Wlora, Kaninë i Himara na wybrzeżu albańskim pozostały w królestwie z ośrodkiem w Neapolu (dowódca Wlory John of Taxis opierał się Bizantyńczykom przez cały 1282; Durrës, Wlora i Kaninë najpewniej przeszły do Bizancjum na początku 1285). Malta wpadła natomiast w ręce Aragończyków dopiero w 1284.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Napad na Kulacahisar — pierwsza akcja wojskowa Osmana Beja", "79b00b14"], "d": ["Hasło TDV Osman I: „Złupił i spalił małą twierdzę Kulaca Hisarı w pobliżu İnegöl (684/1285).” Jest to pierwsza w źródłach datowalna akcja wojskowa Osmana Beja. Nie zdobyto trwałego osiedla, twierdzę złupiono i spalono; jest to więc raczej klasyczny napad pograniczny niż zdobycie. Uważa się ją za punkt początkowy działalności wojskowej bejliku.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Zdobycie Karacahisar — pierwsze zdobycie miasta i panowanie nad Eskişehir", "178ae619"], "d": ["Hasło TDV Osman I: w 687 (1288) Osman Bej „zdobył Karacahisar i stał się panem Eskişehir”. Jest to pierwsze prawdziwe zdobycie miasta przez bejlik; według przekazu Osman Bej dzięki temu sukcesowi awansował do rangi sandżakbeja na pograniczu; opowiada się, że pierwsza piątkowa chutba została odczytana w jego imieniu w Karacahisar i że mianowano tam pierwszego kadiego. Hasło TDV o Eskişehir odnotowuje, że tradycja osmańska podaje datę 1291, lecz jej prawdziwość jest wątpliwa.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Upadek Akki w ręce mameluków — likwidacja obecności krzyżowców na wybrzeżu Syrii: Sajda i Bejrut", "3ca7a464"], "d": ["Akka, długo będąca ośrodkiem Królestwa Jerozolimskiego krzyżowców, została zdobyta przez sułtana mameluckiego al-Maliku l-Aszrafa Chalila, a panowanie krzyżowców w Palestynie dobiegło końca. Templariusze wycofani z Akki schronili się w Sajdzie; gdy zbliżyła się armia mamelucka, opuścili zamek morski i uciekli na Cypr, a miasto w to samo lato przeszło w ręce mameluków. Bejrut, od 1197 w rękach krzyżowców, został w 1291 zdobyty przez namiestnika Damaszku Sencera aş-Şücâîego. W ten sposób dwuwiekowa obecność krzyżowców została wymazana z wybrzeża Syrii i Palestyny.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Zdobycie Bileciku i Yarhisar nocnym napadem", "f461b0af"], "d": ["Hasło TDV Bilecik: „Choć inni tekfurzy regionu, wśród nich tekfur Bileciku, przygotowali zamach na Osmana Gazi, po wykryciu tego spisku siły osmańskie nagłym napadem zdobyły Yarhisar i Bilecik (1299).” Dwie twierdze zdobyto w jednej akcji, jednym nocnym napadem. Data ta jest punktem zwrotnym uznawanym za rok założenia państwa osmańskiego. W tym samym dniu przyłączono także inne miejscowości: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Bitwa pod Koyunhisar (Bafeusem) — pierwsze wielkie zwycięstwo nad armią bizantyjską", "584a9512"], "d": ["Hasło TDV Osman I: 27 lipca 1302 Osman Bej stoczył pod Bafeusem (Koyunhisar) bitwę z armią bizantyjską i ją pokonał. Zwycięstwo to jest punktem zwrotnym, który z regionalnego beja pogranicza wyniósł Osmana Beja do statusu założyciela dynastii. Po bitwie równina Bursy znalazła się pod kontrolą osmańską i rozpoczęła się blokada Nikei.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Zwycięstwo pod Dimbos i zajęcie Kite oraz Ulubatu", "e168ab64"], "d": ["Hasło TDV Osman I: w 702 (1303) sojusz utworzony przez tekfurów Bursy, Kestel, Kite i Adranos został rozbity w przełęczy Dimbos; wróg, walcząc, został cofnięty aż do wąskiego przesmyku, a tekfur Kestel poległ na polu bitwy. Zaraz po zwycięstwie zajęto twierdze Kite i Ulubat, odcinając lądowe połączenie Bursy i zacieśniając jej blokadę. Młody Orhan również uczestniczył w tej bitwie.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Wyprawa nad Sakaryę: zajęcie Leblebicihisar, Lefke, Mekece i Geyve", "a51ba4d3"], "d": ["Hasło TDV Osman I podaje kolejność wyprawy nad Sakaryę w 704 (1304): „Gdy przybył do Leblebüci Hisarı, tekfur okazał posłuszeństwo... Dotarł do Lefke... Doszedł do Mekece... Poszedł do Geyve i zajął twierdzę, którą zastał opuszczoną.” Lefke jest bramą doliny Sakaryi otwierającą się na Bilecik. Ta jedna wyprawa, oddając pod kontrolę osmańską łańcuch twierdz ciągnący się wzdłuż doliny, zamknęła wschodnie skrzydło basenu Nikei.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Chios przeszło pod kontrolę genueńskiego rodu Zaccaria", "9eebe4de"], "d": ["Wobec zagrożenia ze strony Aydınoğulları cesarz bizantyjski poprosił o pomoc Genueńczyka Benedetta Zaccaria; wyspa przeszła pod jego kontrolę (nominalna wasalność bizantyjska). Panowanie Zaccariów trwało do 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Samos weszło we władanie Genueńczyków (Zaccaria) z Chios", "0e6f51e3"], "d": ["Genueński ród Zaccaria, który przejął kontrolę nad Chios, dołączył do swej własności także niemal opuszczone Samos (TDV: 1304–1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Zdobycie twierdz przełęczy Geyve: Karaçepüş, Karatigin i Absu", "76907c78"], "d": ["Hasło TDV Orhan: w wyprawie nad Sakaryę w 705 (1305) Orhan „zdobył twierdze Karaçepüş (Katoikia), Karatigin pod Nikeą i Absu (Hypsu: w przełęczy Geyve)”. Te trzy twierdze, zamykając przejście między doliną Sakaryi a basenem Nikei, całkowicie odcięły Nikeę od pomocy lądowej. W Karaçepüş i Absu w przełęczy Geyve osadzono Gazi Abdurrahmana; miasto mogło być odtąd zdobyte już tylko głodem.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Wyprawa na Adranos (Orhaneli) — ostatnia wyprawa Osmana Beja", "4811546c"], "d": ["Hasło TDV Orhan notuje wyprawę na twierdzę Adranos jesienią 1323 jako ostatnią wyprawę Osmana Beja. Tekfur Adranos był członkiem sojuszu tekfurów zawiązanego przeciw Osmanom dwadzieścia lat wcześniej pod Dimbos; wyprawa ta oznaczała zamknięcie tamtego rachunku. Dokładny dzień zdobycia twierdzy jest nieznany; działania kontynuował Orhan Bej.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Śmierć Osmana Gazi i objęcie bejliku przez Orhana Beja", "021487cd"], "d": ["Osman Gazi, od którego bejlik wziął nazwę, zmarł według świadectwa wakfów Asporça Hatun i Mekece w 724 (1324). Jego syn Orhan, który od 1305 stał na czele armii w wyprawach, objął bejlik po śmierci ojca bez żadnego sporu o tron. Bezwstrząsowe przekazanie sztandaru przez pokolenie założycieli pokazuje, że dynastia spokojnie przeszła pierwszy wielki sprawdzian na drodze od bejliku pogranicznego do państwa.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Odebranie Chios Zaccariom i związanie z Bizancjum", "f6741b26"], "d": ["Cesarz Andronik III oddalił Zaccariów z wyspy i związał wyspę z Bizancjum pod namiestnictwem Benedetta III. Wyspa miała zostać zajęta w 1346 przez Genueńczyka Simone Vignosi.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Samos wróciło od Zaccariów do Bizancjum (łańcuch Chios)", "08034974"], "d": ["Wraz z upadkiem panowania Zaccariów (związanie Chios z Bizancjum w 1329) skończyła się także genueńska własność na Samos.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Bitwa pod Pelekanonem (Maltepe) i zajęcie całego Kocaeli", "389e7bd4"], "d": ["Hasło TDV Orhan: pierwszego dnia bitwy Orhan Gazi wysłał trzystuosobowy oddział, by ściągnąć na siebie armię bizantyjską; drugiego dnia, gdy oddziały pod dowództwem Pazarlu zeszły na równinę, bitwa się rozszerzyła, a gdy cesarz został ranny strzałą, w armii bizantyjskiej wybuchła panika. Wynik jest rozstrzygający: „Orhan zajął całe Kocaeli; po zwycięstwie mieszkańcy Nikei nie mieli już żadnej nadziei.” Miasteczka przybrzeżne od Hereke po Üsküdar weszły pod panowanie osmańskie, a Gebze uczyniono ośrodkiem regionu. Była to ostatnia cesarska armia bizantyjska, która przybyła na ratunek Stambułowi.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Założenie pierwszej medresy osmańskiej w Nikei", "c85fb625"], "d": ["Orhan Bej, zaraz po zajęciu Nikei, mianował tu kadiego Çandarlı Kara Halila, przekształcił bazylikę w meczet i, kazawszy obok niego zbudować imaret i medresę, rozpoczął odbudowę miasta. Według hasła TDV o Dâvûd-i Kayserî budowę medresy ukończono w 1336, a Orhan Gazi sprowadził Dâvûd-i Kayserîego na stanowisko profesora z dziennym uposażeniem 30 akçe. Medresa ta jest pierwszym instytucjonalnym krokiem osmańskiego życia naukowego; bejlik obok siły zdobywczej dodał tradycję nauki. Przekształcenie zdobytej stolicy bizantyjskiej w ośrodek nauki islamu było pierwszym konkretnym znakiem osmańskich pretensji do bycia państwem osiadłym.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Objęcie Bizancjum daniną — oblężenie İzmitu i układ", "0c1ec8d3"], "d": ["Hasło TDV Orhan: latem 733 (1333) Orhan oblegał İzmit ogromną armią i machinami miotającymi, a cesarz zgodził się na układ. W zamian za zaniechanie oblężenia Bizancjum zgodziło się płacić Orhanowi rocznie 12 000 złotych (hyperpyrów); „w ten sposób w oczach emira osmańskiego Bizancjum znalazło się w położeniu kraju płacącego daninę”. W zamian Orhan miał być przyjacielem cesarza i nie atakować miast zależnych od Bizancjum. Obłożenie podatkiem Wschodniego Rzymu przez bejlik pograniczny było oznajmieniem, jak bardzo obrócił się układ sił.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Samotraka przeszła od Wenecjan do genueńskiego rodu Gattilusio", "c499ed5f"], "d": ["Genueński ród Gattilusio wypędził z wyspy Wenecjan, którzy trzymali ją od 1204.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Aneksja Bejliku Karesi: Balıkesir, Bergama, Biga, Edremit i Erdek", "c7cb0511"], "d": ["Hasło TDV Orhan (İnalcık) umieszcza aneksję w 735 (1334–35): po śmierci Demirhana Beja gazi z Karesi i Hacı İlbey zaprosili Dursuna Beja na tron i poprosili Orhana o pomoc. Orhan ruszył najpierw na Balıkesir; gdy Dursun Bej, idący na rokowania pokojowe, zginął od strzały wypuszczonej z twierdzy Bergama, bejlik został w całości przyłączony do ziem osmańskich. W tej samej akcji Kirmasti i Mihaliç okazały posłuszeństwo, zajęto Gölyazı, a Ulubat, wcześniej pozostawiony na mocy zapewnienia, został ostatecznie zdobyty. Orhan mianował do sandżaku Karesi Süleymana Paszę i uczynił Biga ośrodkiem pogranicznym — w ten sposób zdobyto morskie kadry dla przejścia do Rumelii. Uwaga: hasło TDV o Karesioğulları podaje dla tego samego wydarzenia datę 746 (1345); encyklopedia jest sama ze sobą sprzeczna. W tym samym dniu przyłączono także inne miejscowości: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Samos weszło we władanie Maony Chios", "01628b2f"], "d": ["Gdy Genueńczyk Simone Vignosi zajął Chios, a zarząd pozostawiono spółce Maona, Samos również weszło we własność Genueńczyków (Maona) z Chios (TDV: 1346–1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Pierwsze kapitulacje Orhana Gazi z Genueńczykami", "e64cb196"], "d": ["Orhan Gazi, który podczas wojny wenecko-genueńskiej porozumiał się z Genueńczykami, po bitwie w cieśninie w lutym 1352 wysłał do obrony Pery 1000 łuczników i dostarczył 60 000 złotych na przewóz żołnierzy; w zamian nadał Genueńczykom pierwsze kapitulacje. Pełny tekst układu nie dotrwał do naszych czasów. Jest to pierwszy oficjalny układ Osmanów z europejską potęgą morską i miał zostać odnowiony po trzydziestu pięciu latach, w 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Zajęcie Gallipoli — trwały przyczółek w Rumelii", "ba51a160"], "d": ["Gallipoli, które Osmanowie poznali w latach 1349–1352 jako sojusznicy Kantakuzena, zajęli w 1354; okazję stworzyło wielkie trzęsienie ziemi, które zburzyło mury miasta. Wąski przyczółek w Çimpe stał się w ten sposób prawdziwą bazą na rumelijskim brzegu cieśniny, a brama otwierająca się na Trację została szeroko uchylona. Gallipoli miało zostać utracone w 1366 wskutek wyprawy krzyżowej sabaudzkiej, lecz w drugim zdobyciu w 1376 miało ostatecznie wejść pod panowanie osmańskie. W tym samym dniu przyłączono także inne miejscowości: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Śmierć zdobywcy Rumelii Süleymana Paszy", "2dc98228"], "d": ["Süleyman Pasza, najstarszy syn Orhana Beja i architekt zdobyczy w Rumelii, zmarł jesienią 1357, spadłszy z konia podczas polowania, co jest najszerzej przyjętą z dat podawanych w źródłach jako 758 (1357), 759 i 760 (1359). Śmierć księcia, który swymi przeprawami z lat 1352–1354 ustanowił trwałą obecność osmańską w Rumelii, zostawiła kolej sukcesji jego bratu Muradowi. Mauzoleum Süleymana Paszy pochowanego w Bolayırze pozostało najstarszym pomnikiem dynastii osmańskiej w Europie.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Prawo pençik — położenie podwalin pod korpus janczarów", "e5877c2d"], "d": ["Po zdobyczach w Rumelii, za radą uczonego Karamanlı Kara Rüstema, wprowadzono system pençik, przewidujący przeznaczenie dla państwa jednej piątej jeńców wojennych lub jej równowartości w pieniądzach. Dzięki temu, że wybranych spośród tych jeńców wychowywano w rodzinach tureckich i wcielano do wojska, powstał zalążek stałej piechoty podległej bezpośrednio sułtanowi — korpusu janczarów. Przemiana bejliku pogranicznego opartego na konnicy plemiennej w państwo z armią centralną rozpoczęła się od tego rozporządzenia.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Zejście do Tracji Zachodniej: zdobycie Gümülcine", "9ef69221"], "d": ["Siły pograniczne, które po zdobyciu Edirne zwróciły się na zachód od Maricy, zajęły pod dowództwem Gazi Evrenosa Beja Gümülcine, ośrodek Tracji Zachodniej. Miasto stało się wysuniętą kwaterą, z której Evrenos Bej miał przenosić swe napady na Macedonię. W ten sposób odcinek Tracji sięgający wybrzeża Morza Egejskiego znalazł się pod kontrolą osmańską i otwarto drogę do Salonik.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Warna przeszła do Księstwa Dobrudży i została stolicą", "2bfe73f9"], "d": ["W procesie rozpadu Carstwa Bułgarskiego Warna nad Morzem Czarnym została przyłączona do Księstwa Dobrudży założonego przez Dobrotica i uczyniona stolicą tego małego państwa.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Na zachód od Płowdiwu: przyłączenie Tatarpazarcığı i İhtiman", "1664d0e1"], "d": ["Po zdobyciu Płowdiwu w 1372 Tatarpazarcığı w górnym krańcu doliny Maricy i İhtiman, trzymający przełęcz otwierającą się ku Sofii, zostały przyłączone do zarządu osmańskiego. Ta linia, pozostająca w rękach lokalnych bejów, którzy stali się wasalami po bitwie pod Çirmen, została przeniesiona pod zarząd bezpośredni, a szlak Płowdiw–Sofia stał się nieprzerwany. To natarcie jest przygotowaniem drogi do zdobycia Sofii dwanaście lat później.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Bunt Savcı Beja — wspólne powstanie księcia i bizantyjskiego następcy tronu", "75198c33"], "d": ["Savcı Bej, syn Murada I, i Andronik Paleolog, syn cesarza bizantyjskiego Jana V, zbuntowali się równocześnie przeciw ojcom w Bursie i Stambule na początku maja 1373. Sojusz łączący następców tronu dwóch dynastii został szybko stłumiony; Savcı Bej został schwytany, oślepiony i stracony. Data 787 (1385) podawana przez przekaz osmański dla buntu jest błędna; wydarzenie przypada tuż po latach, w których Bizancjum weszło w wasalność osmańską, i pokazuje, jak bardzo splecione były oba pałace.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Doliny Strumy i Mesty: przyłączenie Köstendil, Petriç, Nevrokop i Drama", "8c0980c4"], "d": ["Doliny Strumy i Mesty, pozostające w rękach serbskich i bułgarskich lokalnych bejów, którzy po zwycięstwie pod Çirmen zaczęli płacić Osmanom daninę, zostały dzięki natarciu bejów pogranicznych objęte zarządem bezpośrednio osmańskim. Wraz z przyłączeniem Köstendil, Petriç, Nevrokop i Drama otwarto wschodnią połowę Macedonii, a Saloniki i Serez znalazły się w pierścieniu oblężenia. Na mapie rozszerzenie Rumelii ku południowemu zachodowi jest skutkiem tej akcji.", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timur zdobył Herat: koniec dynastii Kertów i przejście Chorasanu do Timurydów", "15f6019e"], "d": ["W 1380 Chorasan był rozdarty walką między Sarbadarami, Kertami i Muzaffarydami. Timur, wysławszy do regionu syna Mîrân Szaha, sam ruszył na Herat i po pewnym oblężeniu przyjął poddanie miasta od meliki Kertów Gıyâseddina Pîr Alego. Bunt, który wybuchł po jego odejściu, został krwawo stłumiony przez Mîrân Szaha, a dynastia Kertów, panująca w Heracie od 1255, dobiegła końca. Cały Chorasan od Meszhedu po Niszapur wszedł w tym czasie pod zarząd timurydzki.", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["Koniec Bejliku Eretna i założenie Państwa Kadı Burhâneddina", "60dcaf57"], "d": ["Eretnaoğulları, którzy powstali w 1335 z namiestnictwa ilchanidzkiego i przez czterdzieści sześć lat rządzili Anatolią Środkową z ośrodkami w Sivas i Kayseri, rozpadli się wskutek sporów wewnątrz pałacu. Kadı Burhâneddin, który w maju 1378 został wezyrem, po usunięciu rywali Kılıcarslana i Hacı Şadgeldiego ogłosił jesienią 1381 swój sułtanat, położył kres bejlikowi i założył państwo noszące jego imię. Wschodni sąsiad Osmanów zmienił w ten sposób właściciela; linia Sivas–Kayseri miała odtąd przez siedemnaście lat pozostawać w rękach Kadı Burhâneddina.", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Natarcie w głąb Macedonii: zdobycie Monastyru i Ochrydy", "63bb7838"], "d": ["Monastyr na Via Egnatia i Ochryda nad jeziorem weszły pod zarząd osmański w czasie napadów w kierunku Albanii. Oba były kluczowymi punktami drogi sięgającej Adriatyku; Ochryda była ponadto najstarszym prawosławnym ośrodkiem arcybiskupim Bałkanów. TDV odnotowuje, że co do daty zdobycia Ochrydy nie ma pewnych informacji, że podaje się daty 787 (1385) i 797 (1395), po śmierci Marka Kraljevicia; tu przyjęto 1385. Monastyr miał w następnych stuleciach stać się jednym z najważniejszych ośrodków wojskowych Rumelii.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Bitwa nad Saurą — otwarcie bram Albanii", "dda6671b"], "d": ["Na wezwanie o pomoc albańskiego beja Karla Thopii, przyciśniętego przez dynastię Balszów, siły osmańskie rozbiły na równinie Saura armię Balszy II; Balsza poległ na polu bitwy. Bitwa, do której wkroczono na zaproszenie miejscowego beja, dała Osmanom pierwsze trwałe wpływy na ziemiach albańskich sięgających wybrzeży Adriatyku. Polityka wykorzystywania kłótni między bejami regionu miała w następnym stuleciu stać się niezmienną metodą zdobyczy bałkańskich.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["„Trzyletnia wyprawa” Timura: zajęcie Azerbejdżanu i Północnego Iranu", "2a98ec51"], "d": ["Timur, który podczas wypraw chorasańskich z bliska poznał rozdrobnienie Iranu, wyruszył na zachód w 788 (1386). W wyprawie 1386–1388, zwanej „trzyletnią”, przeszedł przez Mazandaran, Luristan i Gruzję do Azerbejdżanu i dotarł do Karabachu; Tabriz, Ardabil, Urmia i Nachiczewan weszły pod zarząd timurydzki. Opanowanie Północnego Iranu i Azerbejdżanu stało się też, jak niegdyś między ulusem Dżocziego a Ilchanami, początkiem długiego sporu ze Złotą Ordą.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Bitwa pod Frenkyazısı i oblężenie Konyi — pierwsza wyprawa na Karaman", "af4e5d77"], "d": ["Murad I osobiście wyruszył na wyprawę przeciw Karamanoğlu Alâeddinowi Alemu Bejowi, który mimo że był jego zięciem, niepokoił się osmańską ekspansją w Anatolii Zachodniej; w bitwie stoczonej na miejscu zwanym Frenk Yazısı wyszkolona i doświadczona armia osmańska pokonała siły karamańskie. Następnie oblężono twierdzę Konya, lecz wskutek ułaskawienia Alâeddina Beja bejlik nie został całkowicie zlikwidowany. Wyprawa ta jest otwierającym aktem długiego rozrachunku między Osmanami a Karamanem, który miał trwać stulecie i zakończyć się ostateczną aneksją dopiero w 1468.", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Muş przeszło od zarządu Karakoyunlu pod zarząd Timura (789/1387)", "ed2e7a11"], "d": ["Muş, które po epoce mongolskiej przeszło pod zarząd Karakoyunlu, weszło w 789 (1387) pod zarząd Timura, który posiadał ziemie Karakoyunlu. W atlasie Muş jest zapisane w tym roku jako przechodzące od Karakoyunlu do Timurydów.", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Założenie stoczni w Gallipoli — narodziny floty osmańskiej", "47546241"], "d": ["Pierwszą zorganizowaną stocznię państwa osmańskiego założył w 1390 Bayezid Błyskawica w Gallipoli, w miejscu stoczni pozostałej po Bizancjum. Osmanowie, przejmując morskie dziedzictwo bejlików Anatolii Zachodniej, stali się w ten sposób po raz pierwszy potęgą morską budującą własne okręty. Stocznia, położona w kluczowym punkcie Dardaneli, pełniła przez półtora stulecia rolę głównej bazy floty osmańskiej, od oblężenia Stambułu po wyprawy egejskie.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Prowincja Hamîd przyłączona do Osmanów: Isparta, Burdur, Uluborlu, Eğirdir", "e3da7de5"], "d": ["Bayezid Błyskawica, który po napaści Karamanoğlu Alâeddina Beja na prowincję Hamîd i skargach ludności wyruszył na wyprawę, zajął całość pozostałych ziem Hamîdoğulları i oddał ich zarząd synowi İsie Çelebiemu.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Koniec dynastii Muzaffarydów: klęska Szacha Mansûra pod Szirazem", "5fd14eb8"], "d": ["Szach Mansûr, ostatni silny władca Muzaffarydów, którzy od 1318 panowali w Jazd, Fars, Isfahanie i Kirmanie, połączył siły z krewnymi i wystąpił przeciw Timurowi. W bitwie pod Szirazem, gdy jeden z jego emirów przeszedł na stronę przeciwną, stracił większość sił, został pokonany i zabity. Gdy Timur kazał następnie zabić wszystkich członków dynastii, panowanie Muzaffarydów dobiegło końca, a Fars i Kirman przyłączono do zarządu timurydzkiego.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Przyłączenie Amasyi do ziem osmańskich", "fe2860cf"], "d": ["Emir Amasyi, oblężonej w czasie kampanii Bayezida Błyskawicy w Anatolii Środkowej, oddał miasto Osmanom i Bayezid wkroczył doń w 1393. Sułtan zostawił zarząd nad miastem synowi Mehmedowi Çelebiemu; Amasya jako sandżak książęcy stała się odtąd jednym z najważniejszych ośrodków wychowania dynastii osmańskiej. Ten wybór miał okazać się rozstrzygający w późniejszym Interregnum, a Çelebi Mehmed miał prowadzić walkę o ponowne zjednoczenie państwa właśnie z bazy w Amasyi.", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timur zdobył Bagdad — Dżalajirydzi uciekli do Anatolii", "4d5602b3"], "d": ["Timur po długim oblężeniu zajął Bagdad; władca miasta, dżalajirydzki sułtan Ahmed, uciekł na zachód i schronił się najpierw u mameluków, potem na dworze osmańskim. Ekspansja Timura na zachód po raz pierwszy zetknęła się w ten sposób bezpośrednio ze strefą wpływów osmańskich. Stąd zaczyna się pierwsze ogniwo wrogości między dwoma władcami.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Zajęcie Warny nad Morzem Czarnym", "a84b2abf"], "d": ["W czasie ściskania ziem Carstwa Bułgarskiego między Dunajem a Morzem Czarnym Warna, największy port na wybrzeżu, przeszła pod zarząd osmański. Zajęcie portu otworzyło drogę natarciu w kierunku Dobrudży i dało Osmanom pierwszą wielką przystań na zachodnim wybrzeżu Morza Czarnego. Warna miała też być sceną zwycięstwa z 1444, w którym pięćdziesiąt jeden lat później zniszczono armię krzyżowców.", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Okolice Nevşehir i Ürgüp przeszły od Karamanoğulları w ręce osmańskie", "06ff59e8"], "d": ["W wyprawach Bayezida Błyskawicy przeciw Karamanoğulları okolice Nevşehir (Muşkara) i Ürgüp przeszły w 800/1398 pod zarząd osmański; w 1402, po bitwie pod Ankarą, Timur zwrócił region Karamanoğulları.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Upadek Państwa Kadı Burhâneddina", "b13391e3"], "d": ["Kadı Burhâneddin, który dostał się do niewoli władcy Akkoyunlu Karayülüka Osmana Beja, zaproponował wypuszczenie w zamian za poddanie Sivas, lecz mieszkańcy miasta stawili opór, a sułtana stracono przed murami. Choć notable Sivas wprowadzili na tron jego syna Alâeddina Alego Çelebiego, wobec nacisku Akkoyunlu poprosili o pomoc Bayezida Błyskawicę; siły osmańskie pod dowództwem Süleymana Çelebiego pokonały Karayülüka i opanowały miasto. W ten sposób Państwo Kadı Burhâneddina przeszło do historii, a Sivas, Tokat, Niksar i Kayseri przyłączono do ziem osmańskich. W tym samym dniu przyłączono także inne miejscowości: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Przeciąganie liny przez Timura: odrzucenie wydania zbiegów", "33790bc8"], "d": ["Pod naciskiem Timura dżalajirydzki sułtan Ahmed i przywódca Karakoyunlu Kara Yûsuf schronili się na ziemiach osmańskich; Timur zażądał wydania tych dwóch zbiegów, a Bayezid Błyskawica odmówił. Wtedy między dwoma władcami zaczęto wymieniać listy pełne wzajemnych ciężkich obelg. Ideologiczny grunt wojny został założony tą korespondencją, zanim jeszcze ruszył jakikolwiek żołnierz.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Dârüşşifâ Błyskawicy w Bursie — pierwszy szpital osmański", "5f0dc59a"], "d": ["Bayezid Błyskawica, w latach, gdy kazał zbudować w Bursie wspaniały Wielki Meczet, podarował miastu także dârüşşifâ; było to ogniwo przeznaczone dla medycyny w obszernym programie dzieł dobroczynnych, obejmującym imaret, medresę, han i most. Ta budowla, pierwszy szpital założony przez państwo, pełniąc też funkcję szkoły medycznej kształcącej lekarzy, wyznaczyła model osmańskich instytucji zdrowotnych. Dzieło ukończone zaledwie dwa lata przed katastrofą pod Ankarą należy do ostatnich ogniw wizji Błyskawicy przekształcenia Bursy w stolicę imperium.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timur zrównał Sivas z ziemią", "f4d79de6"], "d": ["Timur, który pod przewodnictwem Karayülüka Osmana Beja z Akkoyunlu i emira Erzincan Mutahhartena pomaszerował na Sivas, oblegał miasto osiemnaście dni i po przyjęciu poddania z obietnicą, że niczyja krew nie zostanie przelana, dokonał wielkiej rzezi; obrońców kazał wrzucić do rowów i zasypać żywcem. Zniszczono ważne dzieła miasta, na czele z murami, a Sivas załamało się demograficznie. Jest to pierwszy wielki cios, który Timur zadał ziemiom osmańskim na dwa lata przed bitwą pod Ankarą.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Bayezid Błyskawica odzyskał Erzincan i Kemah", "7047ca08"], "d": ["Bayezid Błyskawica, wykorzystując wyjście Timura na wyprawę syryjską, odebrał Erzincan i Kemah emirowi Erzincan Mutahharteneowi, zależnemu od Timura. Choć nie interweniował przy zniszczeniu Sivas, ten ruch oznaczał bezpośrednie rzucenie wyzwania sferze wpływów Timura we Wschodniej Anatolii. Stosunki między dwoma władcami były odtąd nie do naprawienia.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ultimatum Timura z Tabrizu — cztery warunki", "3e1ac50e"], "d": ["Timur przez posła wysłanego z Tabrizu ogłosił cztery warunki: zwrot Kemah Mutahharteneowi, zwrócenie właścicielom ziem odebranych bejom anatolijskim, wysłanie jako zakładnika osmańskiego księcia oraz przyjęcie czapki i pasa jako znaku poddaństwa, wydanie Kara Yûsufa. Bayezid nie przyjął żadnego z nich; mimo nalegań mężów stanu i pośrednictwa Mutahhartena rokowania się załamały. Timur był zdecydowany przed wyprawą do Chin ostatecznie zamknąć sprawę Anatolii.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Odtworzenie Saruhanoğulları — Manisa wychodzi z rąk osmańskich", "ac747b05"], "d": ["Trzy tygodnie po klęsce pod Ankarą Orhan Bej z poparciem Timura stanął na czele bejliku i prowincja Saruhan odzyskała niepodległość. Region z ośrodkiem w Manisie zniknął z mapy dwanaście lat po osmańskiej aneksji z 1390. Jest to jedno z pierwszych o dokładnie znanej dacie zastosowań polityki Timura odtwarzania bejlików.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emir Süleyman uciekł do Rumelii ze skarbem państwa", "0a2b7363"], "d": ["Emir Süleyman, zabrawszy ze sobą skarb państwa w Bursie, archiwa, rodzinę i braci, przeprawił się okrętem z Gemlik do Güzelcehisar (Anadoluhisarı), stamtąd dotarł do Gallipoli i ogłosił w Edirne swoje panowanie. Przeniesienie archiwum państwowego i skarbu do Rumelii jest początkiem przesunięcia osmańskiego środka ciężkości na Bałkany na jedno pokolenie. Na mapie Rumelia od tej daty jest rysowana kolorem samego emira Süleymana.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timur odtworzył bejliki anatolijskie — rozpad jedności tureckiej", "15187774"], "d": ["Timur po zwycięstwie pod Ankarą zwrócił będącym przy nim bejom ich dawne ziemie. Karamanoğlu Mehmedowi i Alemu Bejom przyznano prowincję Karaman oraz Kayseri, Kırşehir, Sivrihisar i Beyşehir; Germiyanoğlu Yâkubowi Bejowi II — Kütahyę i prowincję Germiyan; Candaroğlu İsfendiyarowi Bejowi, oprócz linii Kastamonu–Synopa, Çankırı i Kalecik. Prowincje Aydın, Menteşe i Teke wróciły także do dawnych dynastii. Jedność turecka Anatolii, zbudowana przez Bayezida Błyskawicę w dziesięć lat, rozpadła się w jedno lato; na mapie te bejliki pojawiają się ponownie w swoich kolorach.", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timur zdobył Izmir od joannitów", "66dd1dd4"], "d": ["Timur, który przez Kütahyę, Denizli, Aydın, Ayasuluk i Tire zszedł na zachód, oblegał i zdobył nadmorski Izmir, od 1344 pozostający w rękach chrześcijan. Twierdzę, której Bayezid Błyskawica przez lata nie mógł zdobyć, Timur zajął w krótkim czasie, a zająwszy także okoliczne twierdze, zostawił prowincję Aydın dawnym właścicielom i zawrócił na wschód. Miasto weszło odtąd pod zarząd Aydınoğlu Cüneyda Beja.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Îsâ Çelebi zajął Bursę — narodził się dział anatolijski", "955128c1"], "d": ["Îsâ Çelebi, który po klęsce pod Ankarą wycofał się w okolice Karesi, zajął Bursę, gdy Timur był w Izmirze. W dawnej stolicy, złupionej i spalonej przez żołnierzy Timura, ogłosił swoje panowanie i kazał bić monetę w swoim imieniu; w styczniu 1403 był w Anatolii uznawany jako „władca Turków”. Na mapie ten dział wzdłuż azjatyckiego wybrzeża Marmary jest pokazany kolorem samego Îsâ Çelebiego.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Wycofanie się Timura z Anatolii", "93a98839"], "d": ["Timur, otrzymawszy wiadomość o śmierci Bayezida Błyskawicy w Akşehir, uznał swą sprawę w Anatolii za skończoną i zwrócił się na wschód. Zostawił za sobą bejliki deklarujące mu wierność oraz zwaśnionych książąt osmańskich; niektóre miasta, takie jak Sivas, zostały pozostawione w rękach emirów zależnych od Timura, podobnych do Mezida Beja. Timur do Anatolii już nie wrócił, lecz ten rozdrobniony ład, który ustanowił, trwał dziesięć lat.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emir Süleyman przeszedł do Anatolii: Bursa wpadła w jego ręce", "9b27aa5f"], "d": ["Emir Süleyman, który usłyszał o klęsce Îsâ Çelebiego, przeszedł z silną armią do Anatolii wraz z Çandarlı Alim Paszą i zajął Bursę; zapisy z marca 1404 wskazują, że także Karadeniz Ereğli było pod jego zarządem. Çelebi Mehmed nie zdołał się oprzeć Süleymanowi, który w krótkim czasie zapanował nad Rumelią i większą częścią Anatolii. Na mapie od tej daty aż do ponownego zajęcia Bursy przez Çelebiego Mehmeda (1410) oba brzegi pokazane są jednym kolorem, w dziale emira Süleymana.", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Bitwa na równinie Yenişehir — Çelebi Mehmed wycofał się do Amasyi", "f1568288"], "d": ["Çelebi Mehmed, który stracił Bursę i Ankarę, został pokonany na równinie Yenişehir przez emira Süleymana, utracił wszystkie zdobycze w Anatolii Zachodniej i wycofał się do bazy Tokat–Amasya. Po tej klęsce unikając bezpośredniego starcia, zwrócił się ku umacnianiu władzy w głębi Anatolii. Tak rozpoczęła się najdłuższa cicha faza Interregnum.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emir Süleyman zajął Ankarę Çelebiemu Mehmedowi", "d6a2acd6"], "d": ["Ankarę, która po wycofaniu się Timura z Anatolii pozostała w rękach Çelebiego Mehmeda, oblegał w 1406 emir Süleyman. Komendant twierdzy Yâkub Bej przez jakiś czas się opierał, lecz podstępem wielkiego wezyra Çandarlı Alego Paszy oddał twierdzę Süleymanowi. Wówczas Çelebi Mehmed, porozumiawszy się z Karamanoğlu Mehmedem Bejem, wystąpił przeciw Süleymanowi.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Çelebi Mehmed odzyskał Sivas od timurydzkiego Mezida Beja", "90079b0c"], "d": ["Po najeździe Timura zarząd Sivas pozostawiono Mezidowi Bejowi, zależnemu od Timura. Çelebi Mehmed z Amasyi wysłał swego dowódcę Bayezida Paszę, by zajął miasto, i po zaciętym oporze Sivas po raz drugi wpadło w ręce dynastii osmańskiej. W ten sposób dział Mehmeda osiągnął sześć lat po bitwie pod Ankarą swą dawną granicę na wschodzie.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Koniec dynastii Artukidów: poddanie Mardinu Karakoyunlu", "15b06f33"], "d": ["Artukidzi, panujący w Mardinie od 1106 i będący najdłużej trwającą gałęzią dynastii, nie utrzymali się wobec nacisku Akkoyunlu. Melik Ahmed, zrozumiawszy, że nie obroni miasta, porozumiał się z władcą Karakoyunlu Kara Yûsufem i oddał mu Mardin. Panowanie Artukidów, trwające ponad trzy wieki, dobiegło w ten sposób końca; Mardin i okolice były sceną walki Karakoyunlu z Akkoyunlu, aż po stuleciu przeszły do Osmanów.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Bitwa pod Yambol — Mûsâ Çelebi wkroczył do Edirne", "8f978408"], "d": ["Mûsâ Çelebi, który przeszedł do Rumelii przez Wołoszczyznę, rozbił pod Yambol siły emira Süleymana z poparciem wołoskim i serbskim i wkroczył do Edirne. W czasie Interregnum Rumelia po raz pierwszy wyszła z rąk emira Süleymana. Jego panowanie nie było jednak trwałe; po czterech miesiącach, pokonany pod Kosmidion, miał wycofać się w głąb Bałkanów.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Bitwa pod İnceğiz — pierwsza porażka Çelebiego Mehmeda w Rumelii", "3c35cd43"], "d": ["Çelebi Mehmed, który przeprawił się do Rumelii okrętami bizantyjskimi, stoczył pod İnceğiz bitwę z Mûsâ Çelebim; Mûsâ pokonał Mehmeda siedmioma tysiącami janczarów i Mehmed musiał wrócić do Anatolii. Ta klęska skierowała Mehmeda ku strategii przeciągnięcia na swoją stronę bejów pogranicznych Rumelii i serbskiego despotatu zamiast bezpośredniej walki. Grunt pod zwycięstwo pod Çamurlu po dziewięciu miesiącach przygotowano tą dyplomacją.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Oblężenie Konyi i układ z Karamanoğulları — odzyskano Hamîd-ili, Said-ili, Beyşehir, Seydişehir i Akşehir", "0996257e"], "d": ["Çelebi Mehmed zorganizował wielką wyprawę przeciw Karamanoğulları, którzy w czasie Interregnum napadli na ziemie osmańskie oraz oblegali i spalili Bursę, i oblegał Konyę w muharremie 818. Karamanoğlu Mehmed Bej II musiał prosić o pokój; w wyniku układu Hamîd-ili (okolice Isparty) i Said-ili zostały ponownie przyłączone do ziem osmańskich, zwrócono też Beyşehir, Seydişehir i Akşehir; Sivrihisar, który Timur dał Karamanoğulları w 1402, wrócił do Osmanów. Wyprawa ta, w której zaczęła się łatać jedność Anatolii rozbita bitwą pod Ankarą, jest jednym z konkretnych powodów uznawania Çelebiego Mehmeda za „drugiego założyciela”.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Zajęcie Izmiru od Aydınoğlu Cüneyda Beja", "2377ca51"], "d": ["Izmir, ośrodek Aydınoğlu Cüneyda Beja, który w czasie Interregnum stale zmieniał strony między książętami, został po dziesięciodniowym oblężeniu zdobyty przez Çelebiego Mehmeda; Cüneyd został ułaskawiony i wysłany do sandżakbejlika Nikopolis. Miasto zwrócone przez Timura w 1402 Aydınoğullarom wróciło w ten sposób po trzynastu latach do Osmanów. Cüneyd miał ponownie zająć miasto w 1422, a sprawę zamknął dopiero w latach 1424–1426 Murad II.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Stracenie Torlaka Kemala — Saruhan ostatecznie osmański", "8a09dbf1"], "d": ["Torlak Kemal, który prowadził zachodnioanatolijską gałąź ruchu szejcha Bedreddina, został pokonany w okolicach Manisy i stracony. Od tej daty region Saruhan ostatecznie wszedł pod kontrolę osmańską, a odtworzony przez Timura w 1402 bejlik przeszedł do historii. Ostatnie polityczne resztki Interregnum w Anatolii Zachodniej zostały w ten sposób oczyszczone.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Zdobycie Wlory, Beratu i Kaninë", "1e1949b8"], "d": ["Osmanowie w 1417 objęli swoim panowaniem Wlorę nad Adriatykiem wraz z położonym w głębi kraju miastem Berat i twierdzą Kaninë. Po roku próba odzyskania miasta przez Wenecję się nie powiodła, utworzono tu organizację sandżaku i władza osmańska się utrwaliła. Zajęcie Wlory dało Osmanom po raz pierwszy bezpośredni port na Adriatyku, a tym samym zamorski trampolinę wobec Włoch.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Odzyskanie Anatolii Środkowej: Kayseri i Kırşehir", "204eacb3"], "d": ["Miasta Anatolii Środkowej, które w czasie Interregnum wpadły w ręce Karamanoğulları, wróciły pod zarząd osmański podczas wypraw Çelebiego Mehmeda mających na celu odbudowę państwa. Wraz z przyłączeniem Kayseri i Kırşehir w dużej mierze odzyskano dorzecze Kızılırmaku utracone w bitwie pod Ankarą. To natarcie jest ciągiem polityki zwrotu ku wschodowi, zapoczątkowanej oblężeniem Konyi cztery lata wcześniej.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Mamelucy oddali Kayseri Dulkadırlı Nâsırüddinowi Muhammedowi", "aad4b00c"], "d": ["Armia mameluków, wyruszywszy na wyprawę przeciw Karamanoğlu Mehmedowi Bejowi, zajęła Kayseri; dowódca mamelucki zostawił miasto i okolice Dulkadırlı Nâsırüddinowi Muhammedowi i wrócił do swego kraju.", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Śmierć Mehmeda I i wstąpienie na tron Murada II", "98acac77"], "d": ["Mehmed I, który zakończył Interregnum i ponownie zjednoczył ziemie osmańskie w jednym ręku, zmarł 25 czerwca 1421 w Edirne, a jego syn Murad wstąpił na tron w Bursie. Według układu zawartego z Bizancjum przed jego śmiercią młodsi synowie mieli zostać wysłani jako zakładnicy do cesarza, a cesarz nie miał wypuścić pretendenta do tronu Mustafy Çelebiego, którego trzymał; Murad II odmówił wysłania braci do cesarza.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Ostateczna likwidacja Tekeoğulları: zajęcie Antalyi", "e65565b2"], "d": ["Bejlik Tekeoğulları, odtworzony po bitwie pod Ankarą przez Timura, dobiegł końca, gdy siły osmańskie pod dowództwem Hamzy Beja oblegały Antalyę; usunięto ostatniego ważnego męża beyliku, Osmana Çelebiego. W ten sposób prowincja Teke nad Morzem Śródziemnym została po dwudziestojednoletnim oddzieleniu ostatecznie przyłączona do Osmanów. Bejlik jako gałąź oddzielona od Hamîdoğulları panował w Antalyi od 1321.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Wyprawa Turahana Beja do Morei i zburzenie muru Hexamilion", "c6c2706d"], "d": ["Gdy Bizancjum poparło konkurencyjnego pretendenta do tronu Mustafę Çelebiego, Murad II wysłał Turahana Beja na Moreę. Turahan Bej, zburzywszy mur Hexamilion zamykający od końca do końca przesmyk Koryntu, wkroczył na półwysep i dokonał wielkich zniszczeń. Pokój zawarto pod warunkiem, że mur nie zostanie ponownie zbudowany i że będzie płacony roczny podatek; despotat Morei został w ten sposób pozbawiony obrony wojskowej, a grunt pod ostateczne zdobycie z 1460 przygotowano na trzydzieści siedem lat wcześniej.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Objęcie klasztorów Athos protekcją osmańską", "562de5ea"], "d": ["W latach oblężenia Salonik republika klasztorna Athos na wschodnim palcu Chalkidiki zwróciła się do Murada II o protekcję i uznała panowanie osmańskie. Zagwarantowano mnichom prawa własności i kultu; klasztory pozostawiono w zamian za podatek swobodne w sprawach wewnętrznych. Ten ład stał się najtrwalszym przykładem stosunku protekcji, jaki Osmanowie nawiązali z instytucjami prawosławnymi, i trwał pięć stuleci.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Aneksja Bejliku Tâceddinoğulları: Niksar", "370ffd47"], "d": ["Pod naciskiem beylerbeja Amasyi Yörgüça Paszy Tâceddinoğlu Hüsâmeddin Hasan Bej oddał w 830 (1427) klucze swego kraju z ośrodkiem w Niksarze; otrzymał sandżak w Rumelii. Bejlik założony w drugiej połowie XIV wieku, którego granice sięgały czasem Kelkit, Amasyi, Samsun, Ordu i Giresun, w ten sposób dobiegł końca. W tym samym roku ziemie należące do Hacıemiroğulları zostały także objęte tahrirem i przyłączone do sandżaku Canik; epoka bejlików na środkowym wybrzeżu Morza Czarnego się zamknęła.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Oddanie Belgradu Węgrom — traktat w Tata", "62481183"], "d": ["Po śmierci serbskiego despoty Stefana Lazarevicia, zgodnie z traktatem w Tata między królem węgierskim Zygmuntem a następcą Đurađem Brankoviciem, twierdza Belgrad została przekazana Węgrom. Twierdza, stojąca u zbiegu Dunaju i Sawy, była do tej pory w rękach despotatu serbskiego i dla Osmanów stanowiła zamek zamykający bramę otwierającą się na Europę Środkową. To przekazanie uczyniło z Belgradu na sto lat najsurowszą przeszkodę dla osmańskiego natarcia: oblężenia z 1440 i 1456 miały się nie udać, a twierdza miała upaść dopiero w 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin przeszedł od załogi Karakoyunlu do Karayülüka Osmana Beja z Akkoyunlu", "d82bc97f"], "d": ["Mardin, zajęty przez Kara Yûsufa w 1409, był zarządzany przez namiestników Karakoyunlu; Emîr Nâsır, pozostawiony jako komendant, oddał miasto w 835 (1432) Karayülükowi Osmanowi Bejowi z Akkoyunlu. Zarząd Akkoyunlu trwał do początku XVI wieku.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["Karamanoğulları zabrali Kayseri Dulkadırlım", "2b09e8e8"], "d": ["Bej Karamanu, dzięki zwycięstwu nad Dulkadırlı, przyłączył do swego kraju Kayseri, Ürgüp, Develi Karahisârı i Uçhisar.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Wydarzenie na Buçuktepe — pierwszy bunt janczarów i powrót Murada II na tron", "6388dda1"], "d": ["Wydarzenie na Buçuktepe, pierwszy znany historii bunt janczarów, który wybuchł w Edirne, zaczęło się od żądania podwyższenia ich żołdu o pół akçe i zakończyło się detronizacją młodego Mehmeda II. Murad II w 8 safarze 850 pospiesznie wyruszył z Manisy i rozpoczął swoje drugie panowanie. Wydarzenie było pierwszym znakiem, że korpus kapıkulu stał się siłą mającą głos w sprawie tronu, i ukształtowało trwającą przez całe życie ostrożność Zdobywcy wobec janczarów.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Przyłączenie wybrzeża Epiru: Arta i Preweza", "796f7ecf"], "d": ["Dziewiętnaście lat po poddaniu się Janiny w 1430 Arta i Preweza w przybrzeżnej części despotatu Epiru weszły pod zarząd osmański. W ten sposób objęto kontrolą otwartą na Morze Jońskie zatokę Ambrakijską i dopełniono morskie połączenie Janiny. Preweza jest kluczowym punktem zatoki, która miała dziewięćdziesiąt lat później dać swoją nazwę słynnemu zwycięstwu Barbarossy.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Śmierć Murada II i drugie wstąpienie na tron Mehmeda II", "8f8256ad"], "d": ["Murad II, który zachorował po weselu syna, zmarł w Edirne 1 muharrema 855 (3 lutego 1451). Dziewiętnastoletni Mehmed II wstąpił na tron osmański po raz drugi 16 muharrema 855 (18 lutego 1451) — tym razem na stałe. Powrót młodego władcy, zdetronizowanego pięć lat wcześniej na Buçuktepe, jest początkiem panowania, które miało zostać ukoronowane dwa lata później zdobyciem Stambułu i przekształcić Bejlik Osmański w światowe imperium.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Pierwsze oblężenie Kafy przez połączone siły osmańsko-krymskie", "e346d163"], "d": ["Chan krymski Hacı Giray, który w czerwcu 1454 porozumiał się z sułtanem Mehmedem Zdobywcą, oblegał Kafę od strony lądu z 7000 jeźdźców; osmańska flota z pięćdziesięciu–sześćdziesięciu galer stanęła także na redzie. Genueńska Kafa zniosła oblężenie, płacąc daninę, a ostateczne zdobycie odłożono o dwadzieścia jeden lat, do 1475. Ta pierwsza wspólna akcja była pierwszym przykładem współpracy wojskowej osmańsko-krymskiej, który miał się powtórzyć przy ostatecznym zdobyciu Kafy.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Zajęcie wysp północnego Morza Egejskiego: Bozcaada, İmroz i Thasos", "76575895"], "d": ["Bezpośrednio po zdobyciu Stambułu sułtan Mehmed Zdobywca, by zabezpieczyć drogę morską nowej stolicy, zwrócił się ku wyspom u egejskiego wejścia do Dardaneli; Bozcaada i İmroz zostały zabrane Bizancjum, Thasos zaś rodowi Gattilusio genueńskiego pochodzenia. Wyspy zamykające oba brzegi cieśniny stały się odtąd pierwszym ogniwem linii zaopatrzenia i obrony Stambułu. Wskutek interwencji flot papieskiej i weneckiej panowanie przez pewien czas się chwiało i ostatecznie ustaliło się dopiero w 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Zdobycie Kosowa: zajęcie Prisztiny i Novi Pazaru", "d7ed2345"], "d": ["Armia osmańska, ruszająca na Despotat Serbski, zajęła Prisztinę na Kosowym Polu i Novi Pazar, ośrodek regionu Raszka; w tej samej akcji zdobyto także Novo Brdo, słynne ze srebrnych kopalń. W ten sposób południowa połowa Serbii została objęta bezpośrednim zarządem osmańskim, a despotat w Smederevie został odcięty od swoich ziem centralnych. To zdobycie było rozstrzygającym krokiem na drodze do całkowitej aneksji Serbii cztery lata później.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["Peć (İpek) pod zarządem osmańskim — jeden z ośrodków sandżaku Dukakin", "19511588"], "d": ["W 1455, bezpośrednio po wyprawie serbskiej sułtana Mehmeda Zdobywcy, Peć, ośrodek patriarchatu serbskiego, przeszła pod zarząd osmański; w źródłach osmańskich nie ma zapisu o tym przejściu. Miasteczko z czasem stało się małym miasteczkiem muzułmańskim i jednym z miejsc rezydencji sandżakbeja w sandżaku Dukakin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Zdobycie Enez i Samotraki — dopełnienie wybrzeża Tracji Zachodniej", "106e723b"], "d": ["Enez u ujścia Maricy do morza zostało zajęte od rodu Gattilusio genueńskiego pochodzenia, który trzymał je od osiemdziesięciu lat; w tej samej akcji zdobyto też podległą mu wyspę Samotrakę. Wraz z upadkiem Enez pas przybrzeżny Tracji Zachodniej od Salonik po Gallipoli stał się nieprzerwaną ziemią osmańską. W rękach rodu Gattilusio pozostała jedynie Lesbos; i ona miała zostać zdobyta po sześciu latach.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Niepowodzenie oblężenia Belgradu", "3d53a604"], "d": ["Mehmed Zdobywca po zdobyciu Stambułu oblegał Belgrad, uchodzący za klucz do Europy Środkowej; jednak posiłki sprowadzone przez Jana Hunyadiego Dunajem i ochotnicy zebrani przez kaznodzieję krzyżowego Kapistrano uchroniły twierdzę przed upadkiem. Sułtan, mimo osobistego bohaterstwa okazanego przed oblężeniem, został ranny i musiał się wycofać. Ta porażka na sześćdziesiąt pięć lat zamknęła granicę z Węgrami przed osmańskim natarciem; Belgrad miał zostać zdobyty dopiero w 1521 przez Sulejmana.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Zdobycie północnej Morei: Patras (Balyabadra)", "c08a8509"], "d": ["Siły sułtana Mehmeda Zdobywcy, który w tych samych latach co aneksja Serbii zwrócił się ku despotatowi Morei, zajęły Patras (Balyabadra) w północno-zachodniej części półwyspu. Port ten, trzymający wejście do Zatoki Korynckiej, jest kluczem do lądowego wejścia do Morei; jego zajęcie przygotowało grunt pod ostateczne zdobycie dwa lata później. Miasto było ostatnim wielkim przystankiem, przez który despoci bizantyjscy utrzymywali łączność ze światem łacińskim.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Zajęcie zachodniego wybrzeża Morza Czarnego: Amasra", "f43608fc"], "d": ["Amasra, umocniona kolonia Genui na zachodnim wybrzeżu Morza Czarnego, poddała się bez oporu pod wspólnym naciskiem floty i sił lądowych Mehmeda Zdobywcy. Port ten na wybrzeżu Bartın–Zonguldak stał jako łacińska kieszeń między ziemiami Candaroğulları a ziemiami osmańskimi; jego zajęcie scaliło wybrzeże. Upadek Amasry jest pierwszym krokiem wielkiej wyprawy czarnomorskiej, która dwa lata później (1461) miała ruszyć na Synopę i Trapezunt.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Zdobycie wyspy Lesbos", "fe17aeba"], "d": ["Armia osmańska pod dowództwem sułtana Mehmeda Zdobywcy w zilhiddże 866 po krótkim, lecz gwałtownym oblężeniu zabrała Lesbos z rąk rodu Gattilusio genueńskiego pochodzenia i anektowała ją. Upadek największej wyspy północnego Morza Egejskiego zlikwidował też ostatnią ważną bazę Genueńczyków w regionie. Wyspa, dzięki bliskości wybrzeża Anatolii, miała odtąd pełnić dla floty osmańskiej funkcję wysuniętego posterunku, a zarazem wejść do historii żeglugi jako miejsce wychowania braci Barbarossa.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Początek szesnastoletniej wojny osmańsko-weneckiej", "563ddb68"], "d": ["Wenecjanie, by powstrzymać osmańskie natarcie w Morei i na Morzu Egejskim, zawarli sojusz z władcami Karamanu i Akkoyunlu i rozpoczęli wojnę w 1463. Strategia okrążenia ustanowiona z Uzunem Hasanem na wschodzie, Wenecją na zachodzie i Karamanem pośrodku zmusiła Zdobywcę do walki na wielu frontach naraz. Trwająca szesnaście lat walka obejmowała wszystkie wielkie akcje epoki, od Otlukbeli po wyprawy albańskie, i miała zakończyć się dopiero traktatem stambulskim z 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Zdobycie większej części Hercegowiny: Trebinje i Mostar", "f54c0100"], "d": ["Ziemie księcia Hercegowiny Stjepana Vukčicia-Kosača, który ustanowił zarząd odrębny od Bośni, w trzy lata po upadku Królestwa Bośni w znacznej mierze przeszły pod zarząd osmański: na południu Trebinje zostało zdobyte w 1466 „wraz z niemal całym regionem Hercegowiny”. Mostar, powstały wokół dwóch małych twierdz przy moście na Neretwie, musiał zostać zajęty nieco przed zdobyciem Blagaju, ośrodka Hercegowiny, w latach 1466–1468; w bośniackim rejestrze icmal z lat 1468–1469 figuruje pod nazwą „Köprülü Hisar”. Zdobycie Hercegowiny wraz z pozostałymi twierdzami księstwa zakończono w 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["II wyprawa albańska — osobisty marsz Zdobywcy na Skanderbega", "9cdd2bfa"], "d": ["Aby złamać trwający ponad ćwierć wieku opór Skanderbega, sułtan Mehmed Zdobywca zorganizował w latach 1466–1467 wielkie wyprawy, którymi dowodził osobiście. Armia osmańska oblegała Krujë i zbudowała twierdzę Elbasan, by opanować region. Wyprawa, choć złamała grzbiet albańskiego oporu, nie zdołała zdobyć twierdzy; pełne poddanie regionu miało nastąpić dopiero w dziesięć lat po śmierci Skanderbega.", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["Straż przednia Akkoyunlu zajęła od Karakoyunlu twierdzę Bingöl", "51b94cbc"], "d": ["W ostatnich tygodniach wyprawy Cihana Szacha przeciw Uzunowi Hasanowi straż przednia Akkoyunlu zdobyła twierdzę Bingöl; wraz z zabiciem Cihana Szacha 10 listopada 1467 panowanie Karakoyunlu w regionie się skończyło.", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Upadek państwa Karakoyunlu: zabicie Cihan Szacha", "30bc6358"], "d": ["Cihan Szach, władca Karakoyunlu, który na wyprawie przeciw Uzunowi Hasanowi, wracając z powodu nadejścia zimy, został zaskoczony napadem, zginął podczas ucieczki między Bingöl a Kiğı. Po tym ciosie państwo się nie podniosło; ostatni władca Hasan Ali został w 1469 pojmany i zabity przez Uğurlu Mehmeda, syna Uzuna Hasana. Panowanie Karakoyunlu we Wschodniej Anatolii, Azerbejdżanie i Iraku, trwające blisko stulecie, przeszło w ten sposób na Akkoyunlu.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Śmierć Skanderbega — wygaśnięcie oporu albańskiego", "9158c35f"], "d": ["Skanderbeg, który wychowany na dworze osmańskim zbuntował się w 1444 po klęsce pod Zlaticą i przez ponad ćwierć wieku stawiał opór w Albanii, zmarł w Lezhë, gdzie się schronił. Opór, który wielokrotnie absorbował armie osmańskie za Murada II i Zdobywcy, utracił wraz z jego śmiercią przywództwo centralne. Po załamaniu się frontu albańskiego, podsycanego przez papiestwo i Wenecję, Osmanowie w ciągu dziesięciu lat zajęli Krujë i Szkodrę i ostatecznie przyłączyli region do swych ziem.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Ustanowienie zarządu osmańskiego w Kayseri: Gedik Ahmed Pasza zakończył istnienie Karamanoğulları", "33cf35fc"], "d": ["Wraz z zakończeniem przez Gediga Ahmeda Paszę istnienia Karamanoğulları w 1474 Kayseri weszło pod zarząd osmański; w XV wieku miasto zmieniało właściciela między Dulkadıroğulları, Ramazanoğulları i Karamanoğulları. Pod zarządem osmańskim Kayseri stało się ośrodkiem sandżaku beylerbeyliku Karamanu.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Samos opuszczone: koniec genueńskiej (Maona) własności", "5bdc380c"], "d": ["Według TDV wyspa została po 1475 opuszczona; w 1479 sułtan Mehmed Zdobywca zdobył wyspę i kazał zbudować twierdzę.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Klęska pod Račową (Vaslui) w Mołdawii", "a1a74bf7"], "d": ["Wojewoda mołdawski Stefan Wielki, wciągnąwszy siły osmańskie pod dowództwem beylerbeja Rumelii Hadıma Süleymana Paszy na grunt błotnisty, zadał im ciężką klęskę. Ta klęska, jedna z najcięższych porażek lądowych za czasów Zdobywcy, wywołała w Europie wielki oddźwięk i przyniosła Stefanowi sławę w świecie krzyżowców. Sułtan miał w następnym roku osobiście wyruszyć na wyprawę odwetową.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Zwycięstwo pod Valea Albă (Akdere) — wyprawa na Mołdawię", "45a66791"], "d": ["Sułtan Mehmed Zdobywca, który osobiście wyruszył na wyprawę, by pomścić klęskę pod Račową sprzed roku, zadał armią osmańską i oddziałom mołdawskim wielką klęskę na miejscu Valea Albă i wkroczył do Suczawy, ośrodka bejliku. Nie zdołano jednak zająć twierdz; wskutek braku żywności, dżumy, która wybuchła wśród janczarów, i węgierskich przygotowań armia musiała się wycofać. Ostateczne związanie Mołdawii miało zostać osiągnięte dopiero w następnych latach, wraz ze zdobyciem Kilii i Akkermanu w 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Zdobycie Krujë i dopełnienie zdobycia Albanii", "559a79b4"], "d": ["W dziesięć lat po śmierci Skanderbega, w 1478, wraz ze zdobyciem Krujë, Drivastu, Lezhë i Jablanicy zdobycie Albanii zostało w znacznej mierze dopełnione. Upadek twierdzy Krujë, która przez lata opierała się armiom osmańskim i była symbolem oporu Skanderbega, oznaczał koniec sojuszu wenecko-albańskiego w regionie. Pozostała Szkodra miała zostać pozostawiona Osmanom na mocy traktatu stambulskiego podpisanego w następnym roku.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Przyłączenie półwyspu Taman", "4ef917b8"], "d": ["Po zajęciu Kafy i Kerczu w 1475 flota wysłana przez Mehmeda Zdobywcę na wybrzeża kaukaskie zajęła, wraz z Anapą i Kopą, genueńską Matregę (Tamatarhan) na półwyspie Taman. W ten sposób oba brzegi cieśniny znalazły się pod kontrolą, a wejście do Morza Azowskiego stało się w pełni kontrolowane. Taman został przyłączony do sandżaku Kafy jako brama otwierająca się na Północny Kaukaz.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Wejście Samos pod zarząd osmański (Zdobywca)", "c877bc14"], "d": ["Sułtan Mehmed Zdobywca zdobył Samos, kazał zbudować twierdzę i na nowo uporządkował spis; twierdzę kazał zburzyć w 1483 z powodów politycznych Bayezid II.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Niepowodzenie oblężenia Rodos", "35a85c28"], "d": ["Flota 160 jednostek pod dowództwem Mesiha Paszy, wysłana z rozkazu sułtana Mehmeda Zdobywcy, obległa Rodos wiosną 885 (1480) i wyspa pozostawała w blokadzie przez trzy miesiące. Joannici pod wodzą wielkiego mistrza Pierre'a d'Aubusson, mimo ciężkich strat, bronili się zaciekle; gdy odparto także ostatni wielki szturm z 20 cemâziyelevvel 885, flota wycofała się 3 sierpnia. Po tej porażce mury miasta odbudowano od podstaw i uczyniono je najpotężniejszym umocnieniem Europy, a wyspę zdołał zdobyć dopiero w 1522 Sulejman.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Ikaria (Nikarya) weszła pod zarząd joannitów z Rodos", "5cbc2669"], "d": ["Ikaria między Samos a Chios znajdowała się od 1481 do 1521 pod zarządem joannitów z Rodos.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Bitwa pod Yenişehir — klęska księcia Cema", "c35abee2"], "d": ["Dwaj bracia, którzy po śmierci Zdobywcy wystąpili o tron, stanęli naprzeciw siebie na równinie Yenişehir, a książę Cem poniósł ostateczną klęskę. Książę, który przez osiemnaście dni rządził w Bursie i kazał czytać w swoim imieniu chutbę, musiał po klęsce schronić się najpierw w Konyi, a stamtąd na ziemiach mameluckich. Yenişehir rozpoczęło najdłużej trwający kryzys dynastyczny w dziejach osmańskich: sprawa Cema miała przez czternaście lat paraliżować osmańską politykę zagraniczną wobec Europy.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Aneksja Hercegowiny", "bf247891"], "d": ["Ziemie Księstwa Hercegowiny, które przetrwało po zdobyciu Bośni w 1463, stopniowo przechodziły pod zarząd osmański: Trebinje i Mostar zajęto w 1466, sandżak Hercegowiny utworzono w 1470, a ostatnie ziemie księstwa na wybrzeżu Adriatyku wraz z Herceg Novi zdobyto na początku 1482 i przyłączono do sandżaku. W ten sposób region górzysty za Adriatykiem stał się całkowicie osmański, a Bośnia i Hercegowina utworzyły jedną geografię administracyjną. Syn ostatniego księcia, który wszedł na dwór osmański, to Hersekzâde Ahmed Pasza, który miał wspiąć się aż do godności wielkiego wezyra.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Pozostawienie Zakynthos (Zaklise) Wenecji za coroczną daninę", "268a691a"], "d": ["Zakynthos, jedną z Wysp Jońskich zabranych rodowi Tocco pod koniec epoki Zdobywcy, pozostawiono Wenecji wobec dążenia nowego sułtana, zajętego sprawą Cema, do spokoju na Zachodzie. Wyspę przekazano zarządowi weneckiemu, który uznawał zwierzchnictwo osmańskie i płacił roczną daninę pięciuset dukatów. W ten sposób na Morzu Jońskim bezpośredni zarząd osmański pozostał tylko w Aya Mavra.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Schronienie księcia Cema na Rodos", "2228d6da"], "d": ["Książę Cem, którego próba oblężenia Konyi także nie przyniosła skutku, uciekł z Anatolii z około trzydziestoma ludźmi i dotarł na Rodos, gdzie rycerze św. Jana powitali go uroczyście. Gościna jednak szybko zamieniła się w niewolę; książę został przekazany najpierw Francji, a następnie papiestwu i stał się kartą w rękach polityki europejskiej. Bayezid II musiał płacić roczną opłatę w zamian za przetrzymywanie brata, a osmańskie ruchy wojskowe wymierzone w Zachód zostały zawieszone aż do śmierci Cema.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Początek wojny osmańsko-mameluckiej (front Çukurovy)", "3fe3f0c7"], "d": ["Walka o wpływy nad Dulkadıroğulları i wrogość pozostawiona przez schronienie księcia Cema na ziemiach mameluckich rozpoczęły w 1485 wojnę dwóch wielkich mocarstw sunnickich, która miała trwać sześć lat. W starciach na Çukurovie w okolicach Adany i Tarsusu strony nie zdołały uzyskać przewagi; armie osmańskie otrzymały kilka ciężkich ciosów. Wojna ta jest pierwszą fazą załamania stosunków osmańsko-mameluckich i otwarciem procesu, który miał zakończyć się trzydzieści lat później wyprawami Selima pod Mardż Dabik i Ridaniją.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Pokój osmańsko-mamelucki — pośrednictwo Tunisu", "60dd6719"], "d": ["W wojnie osmańsko-mameluckiej rozpoczętej w 1485 strony nie odniosły decydującego zwycięstwa; za pośrednictwem władcy Tunisu Osmana Hafsydy w 1491 doszło do porozumienia. Traktat w znacznej mierze przywrócił granice sprzed wojny, a rozrachunek między dwoma państwami islamu został odłożony o pokolenie. Sześcioletnia wyczerpująca walka jest jedną z głównych przyczyn ostrożnej polityki zagranicznej Bayezida II i jego skupienia się na urządzeniach wewnętrznych zamiast zwrotu ku wschodowi.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Przyjęcie sefardyjskich Żydów wypędzonych z Hiszpanii do państwa osmańskiego", "5c2b5c24"], "d": ["Po upadku Granady część Żydów uciekających przed prześladowaniami inkwizycji w Hiszpanii schroniła się na ziemiach osmańskich i została osiedlona w różnych miastach. Pod zarządem osmańskim te wspólnoty sefardyjskie zyskały swobody, jakich do tej pory nie widziały: osiedlania się, gdzie chciały, życia według swej wiary, otwierania instytucji edukacyjnych i budowy nowych synagog. Ta migracja, która dzięki przywiezionej wiedzy drukarskiej, medycznej i finansowej przekształciła życie gospodarcze Salonik i Stambułu, stała się w Europie najczęściej omawianym przykładem osmańskiego ładu tolerancji.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Śmierć księcia Cema — koniec czternastoletniego zakładnika", "f6588b70"], "d": ["Książę Cem, przekazany przez papiestwo królowi Francji Karolowi VIII, zmarł w miejscu zwanym Castel Capuana po wyruszeniu z Rzymu 27 stycznia 1495; źródła odnotowują, że mógł zostać otruty przez kręgi papieskie. Śmierć księcia, trzymanego przez czternaście lat w rękach państw europejskich jako karta zagrożenia przeciw Osmanom, ostatecznie rozwiązała ręce Bayezidowi II. Istotnie, sułtan miał odtąd wypowiedzieć wojnę Wenecji i poprowadzić flotę do pierwszego wielkiego zwycięstwa.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Zwycięstwo morskie pod Sapienzą (Zonchio) — pierwszy wielki sukces floty na Morzu Śródziemnym", "9754aaef"], "d": ["Bayezid II, któremu wraz z zakończeniem sprawy Cema rozwiązały się ręce, wypowiedział w 1499 wojnę Wenecji; flota osmańska pokonała pod Sapienzą (Zonchio) flotę wenecką i odniosła pierwsze wielkie zwycięstwo morskie na Morzu Śródziemnym. Dzięki temu zwycięstwu flota ogłosiła, że potrafi już stawić czoło Wenecji na morzu.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Utrata Kefalonii i Itaki", "60f0f687"], "d": ["Wenecja, wstrząśnięta zajęciem Modon i Koron, połączyła się z Hiszpanią i przeszła do kontrataku, oblegając Kefalonię, pozostającą w rękach osmańskich od 1479. Po czterdziestosiedmiodniowym oporze twierdza padła, a wyspa wraz z Itaką przeszła do Wenecji i przez trzysta lat nie wróciła pod zarząd osmański. Ta strata stworzyła równowagę, w której to, co zdobyto w Morei, zostało oddane na Morzu Jońskim.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Upadek Chanatu Złotej Ordy i wzrost znaczenia Krymu", "0d1dc515"], "d": ["Ostatni władca, Szejch Ahmed Chan (1481–1502), nie zdołał wydobyć kraju z kryzysu, w który popadł, a Chanat Złotej Ordy przeszedł do historii w 1502 wskutek ciosu chana krymskiego Mengliego Gireja. W wyniku sporów o tron i rozpadu na ziemiach dawnej Złotej Ordy powstały chanaty Krymu, Kazania, Nogajów, Astrachania i Sybiru. To zwycięstwo Krymu pod protekcją osmańską uczyniło wpływy osmańskie na północy Morza Czarnego niekwestionowanymi, a próżnię powstałą w regionie miała w następnym stuleciu wypełnić Moskwa.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Zakończenie wojny osmańsko-weneckiej i pokój", "125b1526"], "d": ["Wojna rozpoczęta w 1499, która wstrząsnęła Wenecją pod Sapienzą, Lepanto oraz utratą Modon i Koron, zakończyła się pokojem w 1502. Wenecja, utraciwszy najważniejsze bazy w Morei, musiała uznać przewagę osmańską w zamian za zachowanie przywilejów handlowych we wschodniej części Morza Śródziemnego. Panowanie Bayezida II, uchodzące za ostrożne, wyniosło tą wojną Osmanów po raz pierwszy do pozycji poważnej potęgi morskiej na Morzu Śródziemnym.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Powstanie Şahkuluego — powstanie Kızılbaszy od okolic Teke po Sivas", "3beadca7"], "d": ["Şahkulu Baba Tekeli, który pod wpływem propagandy safawidzkiej w Anatolii ujawnił swój bunt w 1510, w marcu 1511 napadł na rynek Antalyi, a w kwietniu pokonał siły osmańskie w okolicach Kütahyi. W ostatniej bitwie z wielkim wezyrem Hadımem Alim Paszą pod Sivas obie strony poniosły ciężkie straty; zginęli zarówno wielki wezyr, jak i przywódca powstania. Powstanie, które nadwątliło władzę państwa w Anatolii, obnażyło próżnię władzy w ostatnich latach Bayezida II i stało się najsilniejszym uzasadnieniem marszu księcia Selima na tron.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Abdykacja Bayezida II i wstąpienie na tron Selima Strasznego", "c4cfab69"], "d": ["Pod naciskiem księcia Selima, który w walce o tron z braćmi miał za sobą poparcie janczarów, Bayezid II abdykował 24 kwietnia 1512, a Selim I wstąpił tego samego dnia na tron jako dziewiąty władca osmański. Stary sułtan, jadąc do rodzinnej Dimetoki, zmarł w drodze we wsi Abalar koło Çorlu 25 rebîülevvel 918 (10 czerwca 1512). Trzydziestojednoletnie ostrożne i zwrócone do wewnątrz panowanie zastąpiła epoka Straszliwego, który w osiem lat miał podwoić granice imperium.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Zdobycie twierdzy Sinj", "83271ea5"], "d": ["Osmańskie siły akindżich na granicy bośniackiej zabrały Królestwu Węgier twierdzę Sinj, sięgającą w głąb Dalmacji. Było to wczesne ogniwo linii granicznej Dalmacji, która miała rozszerzyć się po dziewięciu latach wraz ze zdobyciem Kninu i okolic przez Gazi Hüsrev Beja; twierdza miała zostać utracona na rzecz Wenecji w 1686.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Bitwa pod Yenişehir i usunięcie księcia Ahmeda", "e2ed15dd"], "d": ["Sułtan Selim Straszny pokonał na równinie Yenişehir pod Bursą swego starszego brata, księcia Ahmeda, najsilniejszego rywala do tronu, i usunął go, biorąc do niewoli. Trwająca od 1511 walka braci została w ten sposób zamknięta, a wewnętrzny podział Anatolii się skończył. Selim, zabezpieczywszy tyły, zyskał swobodę, by zwrócić się ku sprawie safawidzkiej.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Wkroczenie sułtana Selima Strasznego do Tabrizu", "dad2e227"], "d": ["Po zwycięstwie pod Çaldıranem armia osmańska wkroczyła do stolicy safawidzkiej Tabrizu, a w mieście odczytano chutbę w imieniu sułtana. Selim zabawił tu tydzień i kazał przenieść do Stambułu część artystów i ulemów z Tabrizu; to przeniesienie miało głęboko wpłynąć na sztukę pałacową Osmanów. Choć miasto opuszczono wobec zbliżającej się zimy i niezadowolenia janczarów, przewaga Safawidów na Wschodzie została złamana. Na mapie miejsca przechodzące do Osmanów tego dnia nie sąsiadują ze sobą i tak ma być: Tabriz to dziewięciodniowa okupacja wojskowa; równina Erzincan poddała się podczas wyprawy bez walki, a leżąca pośrodku twierdza Kemah broniła się u Safawidów do 19 maja 1515; Siirt odebrał Safawidom, wyrzekłszy posłuszeństwo Osmanom, melik Hasankeyf Halil Bej, uwolniony z więzienia szacha İsmaila w Tabrizie — otaczający Diyarbakır pozostał safawidzki do 1515, a Hasankeyf do 1517.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Muş i Bingöl (Çapakçur) przeszły od Safawidów pod zarząd osmański", "b0a53b5a"], "d": ["Gdy po Çaldıranie Wschodnia Anatolia została odebrana Safawidom, Muş weszło w 921/1515 pod zarząd osmański; sąsiedni Çapakçur (Bingöl) został przyłączony do Osmanów w tym samym procesie.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Zdobycie twierdzy Kemah od Safawidów", "73fd8671"], "d": ["Sułtan Selim Straszny, który w drodze powrotnej spod Çaldıranu spędził zimę w Amasyi, powierzył zdobycie umocnionej twierdzy Kemah, trzymającej punkt przeprawy przez Eufrat, Bıyıklı Mehmedowi Paszy. Po oblężeniu, w którym wziął udział osobiście sułtan, twierdzę odebrano Safawidom i otwarto bramę Anatolii Wschodniej. To zdobycie jest pierwszym konkretnym krokiem przekształcającym zwycięstwo pod Çaldıranem w trwałą zdobycz terytorialną.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Zwycięstwo pod Turnadağ — Bejlik Dulkadir stał się zależny od Osmanów", "fd879145"], "d": ["Siły osmańskie pokonały beja Dulkadir Alâüddevle Bozkurta, który w czasie wyprawy pod Çaldıran zajął postawę dwuznaczną, na miejscu Ördekli między Göksun a Andırın; Alâüddevle zginął w tej bitwie. Bejlik nie został w tym czasie anektowany: po Alâüddevle na czele Bejliku Dulkadıroğulları sułtan Selim Straszny postawił Şehsuvaroğlu Alego Beja, a kraj z ośrodkiem Maraş–Elbistan trwał jako bejlik zależny od Osmanów. Bufor na granicy mameluckiej znalazł się w ten sposób pod kontrolą osmańską i otwarto drogę wyprawie egipskiej sprzed dwóch lat; aneksja miała nastąpić dopiero po zabiciu Alego Beja.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Zdobycie Âmid (Diyarbekir) i utworzenie beylerbeyliku Diyarbekir", "a6867d5b"], "d": ["Gdy İdrîs-i Bitlisî pozyskał dla Osmanów sunnickich bejów kurdyjskich w regionie, siły safawidzkie nie wytrzymały długiego oblężenia, a klucze Âmid wręczono Bıyıklı Mehmedowi Paszy. Miasto uczyniono ośrodkiem nowo utworzonego beylerbeyliku Diyarbekir. W ten sposób administracyjne jądro Górnej Mezopotamii przeszło w ręce osmańskie.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Zdobycie Harput — otwarcie drogi do Diyarbekir", "564eb269"], "d": ["Beylerbej Karamanu Hüsrev Pasza, który wyruszył, by uwolnić od oblężenia safawidzkiego Diyarbekir zajęty po Çaldıranie, zdobył po trzydniowym oblężeniu twierdzę Harput, której okolice wcześniej zajął Çerkez Hüseyin Bej. W ten sposób zabezpieczono drogę na wschód od Eufratu ku Diyarbekirowi.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Bitwa pod Koçhisar (Kızıltepe) — klęska Kara Chana", "9ea9e843"], "d": ["Armia osmańska pod dowództwem Bıyıklı Mehmeda Paszy pokonała w całodziennej bitwie polnej na miejscu Koruk na stepie Dede Garkın pod Koçhisar namiestnika safawidzkiego Kara Chana; ścięta głowa Kara Chana została wysłana do obozu sułtana. Następnie siły osmańskie wkroczyły do miasta Mardin, lecz po kilku dniach je opuściły; twierdza Mardin trzymana przez załogę safawidzką mogła zostać zajęta dopiero rok później. To zwycięstwo, zapewniając południową granicę Selima, umożliwiło mu zwrócenie się ku wyprawie egipskiej. W tym samym dniu przyłączono także inne miejscowości: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Wyjście sułtana Selima Strasznego ze Stambułu na wyprawę egipską", "ac258b4b"], "d": ["Sułtan Selim Straszny wyruszył ze Stambułu pozornie w ramach przygotowań do nowej wyprawy wschodniej przeciw Safawidom i skierował się na południe przez Akşehir. Nawiązanie przez sułtana mameluckiego Kansu Gavriego kontaktu z szachem İsmâilem i zagrożenie osmańskiego skrzydła wschodniego miało wkrótce doprowadzić do zmiany celu. Wyprawa jest początkiem wielkiej akcji, która miała trwać dwa lata i przekształcić Osmanów w imperium bliskowschodnie.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Zajęcie Zabîd: pierwsze wejście osmańskich żeglarzy na Morze Czerwone", "38740e0c"], "d": ["Wobec nacisku Portugalii na Oceanie Indyjskim Hüseyin Bej i Selman Reis, żeglarze pochodzenia osmańskiego wysłani na Morze Czerwone na żądanie sułtana mameluckiego Kansu Gavriego, zajęli swoimi flotami Zabîd. Akcja prowadzona jeszcze w służbie mameluckiej jest pierwszą faktyczną obecnością osmańskiej marynarki na linii Morze Czerwone–Indie. Gdy rok później Egipt przejdzie do Osmanów, ta sama flota zostanie podporządkowana bezpośrednio Stambułowi.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Oficjalne ogłoszenie celu wyprawy: mamelucy i Aleppo", "689e310d"], "d": ["Sułtan Selim Straszny, gdy Kansu Gavri porozumiał się z Safawidami i skierował swą armię na Aleppo, ogłosił jawnie celem wyprawy sułtana mameluckiego i Aleppo. W ten sposób trwająca od lat ukryta rywalizacja między dwoma państwami sunnickimi przekształciła się w otwartą wojnę. To ogłoszenie rozpoczęło czterotygodniowe odliczanie prowadzące do Mardż Dabik.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Niepowodzenie oblężenia Adenu: pierwsza próba na Morzu Czerwonym przeciw Portugalii", "8ffd46f2"], "d": ["Selman Reis i Hüseyin Bej, by zająć Aden, bramę Morza Czerwonego otwierającą się na Ocean Indyjski, prowadzili ośmiodniowe oblężenie, lecz wobec silnych umocnień miasta musieli się wycofać. To, że Adenu nie zdobyto, miało na wiele lat zakłócić południową strategię prowadzoną przeciw Portugalii. Ta próba jest pierwszym sprawdzianem osmańskiej polityki oceanicznej.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Związanie Bejliku Ramazanoğulları z Osmanami", "cfaa3754"], "d": ["Przy nadaniach dokonanych po zwycięstwie pod Mardż Dabik bejlik Ramazanoğulları z ośrodkiem w Adanie został nadany Mahmudowi Bejowi i objęty panowaniem osmańskim. Bejlik, który wyszedł z zależności mameluckiej, zamiast być zlikwidowany, został pozostawiony rodzinie ze statusem „ocaklık”; Ramazanoğulları nadal zarządzali Çukurovą jako sandżakbejowie osmańscy. Ten uprzywilejowany ład trwał do 1608, gdy Pîr Mansûr zrezygnował z bejliku. W tym samym dniu przyłączono także inne miejscowości: Malatya, Tarsus, Mosul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Wejście Aleppo, Rakki i Dajr az-Zaur pod panowanie osmańskie", "2088eb6a"], "d": ["Cztery dni po Mardż Dabik sułtan Selim Straszny wkroczył do Aleppo bez napotkania oporu, a w meczetach miasta czytano chutbę w jego imieniu. Tak szybki upadek Aleppo, uchodzącego za handlową i administracyjną stolicę Syrii, pokazuje, że władza mamelucka w regionie się załamała. Zajęcie miasta otworzyło naraz drogę do Damaszku, a stamtąd do Egiptu. W tym samym dniu przyłączono także inne miejscowości: Antiochia, Rakka, Dajr az-Zaur.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Spotkanie w Aleppo na Gökmeydan z kalifem abbasydzkim Mutawakkilem III", "22979f42"], "d": ["Kalif abbasydzki z Kairu Mutawakkil III, który dostał się do niewoli wraz z armią mameluck pod Mardż Dabik, został stawiony przed sułtanem w Aleppo na Gökmeydan, a sułtan Selim Straszny okazał mu wielki szacunek. Kalifat kairski, od 1261 symboliczny urząd w cieniu sułtanów mameluckich, przeszedł dzięki temu spotkaniu faktycznie pod protekcję osmańską. Kalif miał być później zabrany do Stambułu razem z sułtanem.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Wejście Trypolisu i Hamy pod zarząd osmański", "a1e19a79"], "d": ["Po Aleppo i Hamie również Trypolis na wybrzeżu syryjskim przeszedł bez oporu pod zarząd osmański. Miasto, jeden z najruchliwszych portów wschodniej części Morza Śródziemnego, było otwartą na morze bramą Damaszku i ośrodkiem handlu jedwabiem i cukrem. Wraz z jego zajęciem pas przybrzeżny Bilâdüşşam całkowicie zmienił właściciela.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Wejście Damaszku pod panowanie osmańskie", "2b844d91"], "d": ["Sułtan Selim Straszny, któremu po poddaniu się Hamy i Hims otworzyła się droga, dotarł 27 września pod Damaszek; nie wszedł od razu do miasta, lecz rozbił namiot na zewnątrz w miejscu Mastaba i wkroczył do środka z wielką ceremonią w dwunasty dzień po przybyciu. Zostawszy w Damaszku długo, ustanowił administracyjny ład Syrii i kazał zbudować grobowiec Muhyiddina Ibn Arabiego. W ten sposób cały Bilâdüşşam wyszedł spod zarządu mameluckiego. W tym samym dniu przyłączono także inne miejscowości: Bejrut.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Ogłoszenie Tomanbaya sułtanem mameluckim w Kairze", "6020d90d"], "d": ["Po śmierci Kansu Gavriego pod Mardż Dabik emirowie mameluccy wprowadzili na tron Tomanbaya, który miał zostać ostatnim sułtanem państwa. Nowy sułtan pochodzenia czerkieskiego przejął państwo, które straciło Syrię, miało wyczerpany skarb i było pozbawione broni palnej. Mimo to miał zorganizować ostatni opór przeciw osmańskiemu natarciu, budując linię obrony przed Kairem.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Bitwa pod Gazą (Han Yûnus): klęska Canbirdiego Gazâlîego", "9f1eb8cb"], "d": ["Sułtan Selim Straszny wysłał wielkiego wezyra Hadıma Sinana Paszę z czterotysięczną strażą przednią do Gazy. Canbirdi Gazâlî, mianowany przez Tomanbaya namiestnikiem Damaszku, próbował zatrzymać osmańską straż przednią na linii Gaza–Han Yûnus, lecz poniósł ciężką klęskę i uciekł do Egiptu. Wraz z rozproszeniem ostatniej mameluckiej siły buforowej w Palestynie droga na pustynię Synaj została całkowicie otwarta.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Na wschód od Jordanu: wejście Ammanu pod zarząd osmański", "9db62667"], "d": ["Po bitwie pod Gazą, gdy siły osmańskie przygotowujące się do wyprawy egipskiej schodziły na południe, Amman na wschód od Jordanu również wszedł pod zarząd osmański. Miasta przybrzeżne i wewnętrzne Palestyny (Jafa, Nablus, Sajda, Akka, Jerozolima) zmieniły właściciela już jesienią 1516, po Mardż Dabik. Miasta te przez cztery stulecia były zarządzane jako sandżaki ejaletu Damaszku.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Przybycie sułtana Selima Strasznego do Jerozolimy", "66d7bfad"], "d": ["Do Jerozolimy, która po Mardż Dabik przeszła pod zarząd osmański bez oporu, sułtan Selim Straszny przybył po bitwie pod Gazą wraz z notablami państwa i wojskiem. Sułtan odwiedził Kopułę na Skale i meczet Al-Aksa i potwierdził święty status miasta. Jerozolima miała pozostawać pod zarządem osmańskim od tej daty aż do grudnia 1917, pełne cztery stulecia.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Wkroczenie sułtana Selima Strasznego do Gazy i zwrot ku pustyni Synaj", "2106bfc7"], "d": ["Po klęsce Canbirdiego Gazâlîego pod Hanyûnus (21 grudnia 1516) Gaza była w rękach straży przedniej. Sułtan wkroczył do Gazy 2 stycznia 1517, spotkał się tu ze stojącym na czele straży przedniej Sinanem Paszą, a armia dokonała ostatnich przygotowań do przejścia do Egiptu. Na bezwodnej pustyni Katya (Synaj) od Gazy po Salihiję miano maszerować osiem postojów, przewożąc wodę na wielbłądach. Przejście to jest najbardziej ryzykowną i logistycznie najtrudniejszą fazą wyprawy.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Zajęcie Suezu — brama otwierająca się na Morze Czerwone", "05f3324e"], "d": ["Po zwycięstwie pod Ridaniją, wraz z wkroczeniem wojsk osmańskich do Kairu, Suez na północnym krańcu Morza Czerwonego przeszedł pod zarząd osmański. Ten port stoczniowy, z którego mamelucy wysyłali flotę na Ocean Indyjski, stał się bazą południowej polityki prowadzonej przeciw Portugalii. Suez jest północnym wlotem linii, na której trzy stulecia później otwarto kanał.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Pierwsze wkroczenie wojsk osmańskich do Kairu", "0a3f4f4d"], "d": ["Dzień po zwycięstwie pod Ridaniją pozwolono armiom osmańskim wejść do Kairu, a 24 stycznia oddziały rozlokowały się w mieście. Wkroczenie to nie oznaczało jednak pełnej kontroli nad miastem; Tomanbay wycofał się do Górnego Egiptu, a opór mamelucki nie został jeszcze złamany. Zdobycie Kairu miało zostać dopełnione nie w jeden dzień, lecz w krwawym procesie rozciągniętym na tygodnie.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Napad Tomanbaya na Kair i trzydniowe walki uliczne", "b83b6ce6"], "d": ["Tomanbay, który wycofał się do Górnego Egiptu, wkroczył z około siedmioma tysiącami ludzi nagle do Kairu w nocy z 27 na 28 stycznia i rozpoczął opór w mieście, stawiając oddziały osmańskie w niezwykle trudnym położeniu. W trwających trzy dni zaciętych walkach ulicznych mamelucy tymczasowo utrzymali większą część miasta. Opór mógł zostać złamany dopiero po wejściu do akcji artylerii osmańskiej i sił wzmocnienia.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Wejście Canbirdiego Gazâlîego w służbę osmańską", "a94ea459"], "d": ["Dawny emir mamelucki Canbirdi Gazâlî, który po Ridaniji wycofał się do Salihiji, zwrócił się do sułtana, prosząc o aman. Sułtan Selim Straszny, uznając, że będzie pożyteczny w ustanowieniu porządku w Egipcie i Syrii, przyjął go do swej służby. Ten wybór jest pierwszym wielkim przykładem osmańskiej polityki włączania kadr mameluckich do systemu zamiast ich likwidacji.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Uroczyste wkroczenie sułtana Selima Strasznego do Kairu i odczytanie chutby", "6d98080c"], "d": ["Po stłumieniu walk ulicznych sułtan wkroczył 15 lutego 1517 do Kairu w bardzo świetnej ceremonii, a w meczetach odczytano chutbę w jego imieniu. Odczytanie chutby w Kairze w imieniu sułtana osmańskiego jest ogłoszeniem prawnego końca panowania mameluckiego trwającego od 1250. Data ta uchodzi za symboliczny moment dopełnienia faktycznego zdobycia Egiptu.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Schwytanie ostatniego sułtana mameluckiego Tomanbaya w Terrûce", "7058e6ad"], "d": ["Tomanbay, który po opuszczeniu Kairu ukrywał się w delcie Nilu, został zadenuncjowany przez beduinów, którzy dali mu schronienie, i pojmany w okolicach Terrûce. Jego schwytanie zlikwidowało zorganizowany ośrodek oporu mameluckiego. Ostatni sułtan miał być odtąd przez czternaście dni trzymany w rękach osmańskich.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Stracenie Tomanbaya przy Bâbüzüveyle i koniec państwa mameluckiego", "ad9820be"], "d": ["Czternaście dni po schwytaniu Tomanbay został powieszony przy słynnej bramie Kairu Bâbüzüveyle; jego ciało pochowano później w medresie zbudowanej przez jego wuja. W ten sposób Państwo Mameluckie, rządzące Egiptem i Syrią od 1250, formalnie przeszło do historii. Wraz ze złamaniem oporu także miasta Górnego Egiptu (Saidu), takie jak Asjut i Asuan, zostały przyłączone do zarządu osmańskiego.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Atak floty portugalskiej na Dżuddę i obrona Selmana Reisa", "52322cf5"], "d": ["Flota portugalska licząca około trzydziestu galer i galeonów zaatakowała Dżuddę; Selman Reis, kierując obroną miasta, uniemożliwił wrogowi wylądowanie i zatopił kilka okrętów portugalskich. Obrona ta zapobiegła przejściu portu Mekki, a tym samym szlaku pielgrzymiego, w ręce państwa chrześcijańskiego. Dżudda miała po kilku miesiącach zostać oficjalnie włączona do zarządu osmańskiego dzięki bî'at Hidżazu.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Przejęcie Aleksandrii przez flotę — dopełnienie zdobycia Egiptu", "386878fe"], "d": ["Dokładnie cztery miesiące po Ridaniji i trzydzieści sześć dni po straceniu Tomanbaya, wraz z przybyciem do portu floty osmańskiej pod zarządem Câfera Beja, Aleksandria przeszła pod zarząd osmański; porty delty, takie jak Raszid i Damietta, zostały przyłączone w tym samym procesie. To, że wielki port Egiptu otwarty na Morze Śródziemne został przejęty miesiące po upadku Kairu i nie z lądu, lecz z morza, jasno pokazuje, że zdobycie zostało dokonane nie jedną bitwą, lecz region po regionie. Aleksandria miała odtąd stać się życiowym portem łączącym Stambuł z Kairem. W tym samym dniu przyłączono także inne miejscowości: Raszid (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Bezwojenne przyłączenie Hidżazu: bî'at Abû Numayya, syna szarifa Mekki", "c13b98c7"], "d": ["Sułtan Selim Straszny początkowo rozważał wysłanie wojska dla zajęcia Mekki i okolic, lecz zrezygnował z tego, gdy emir Mekki szarif Berekât zadeklarował posłuszeństwo. Dwunastoletni syn Berekâta, Abû Numayy, przybył do Kairu z darami ojca i kluczami Mekki i został przyjęty przez sułtana. Hidżaz nie przyłączył się więc do Osmanów jako automatyczny skutek Ridaniji, lecz po pięciu i pół miesiącach i bez jednego wystrzału, drogą układu i bî'at. W tym samym dniu przyłączono także inne miejscowości: Ta'if.", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Przyjęcie tytułu Hâdimü'l-Haremeyn i chutba w Medynie", "63b32b59"], "d": ["Po drugim przyjęciu delegacji mekkańskiej sułtan Selim Straszny oficjalnie objął protektorat nad Haremejn i zaczął używać tytułu „hâdimü'l-Haremeyni'ş-şerîfeyn” (sługa dwóch świętych sanktuariów). Szarif Berekât, włożywszy przysłaną mu szatę honorową, kazał odczytać chutbę w imieniu sułtana; gdy delegacja medyńska udała się do Stambułu, emirat Berekâta został potwierdzony beratem. Sułtan wysłał mieszkańcom Haremejn dwieście tysięcy sztuk złota i obfite zapasy żywności, rozpoczynając tradycję surre powtarzaną co roku. W tym samym dniu przyłączono także inne miejscowości: Yanbu, Tabuk.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Wejście Selmana Reisa w służbę osmańską i przekazanie polityki Morza Czerwonego", "771da99a"], "d": ["Selman Reis, który bronił Dżuddy przed Portugalczykami, przybył do Kairu i stanął przed sułtanem Selimem Strasznym; choć przez pewien czas był zatrzymany, w 1519 został wezwany do Stambułu i zobowiązał się przygotować trzydzieści galer i kilka galeonów przeciw zagrożeniu portugalskiemu. Spotkanie to jest początkiem przejęcia polityki Morza Czerwonego i Oceanu Indyjskiego ze spuścizny mameluckiej i związania jej bezpośrednio ze Stambułem. Osmanowie byli odtąd nie tylko państwem śródziemnomorskim, lecz także potęgą prowadzącą politykę oceaniczną.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Wyjazd sułtana Selima Strasznego z Kairu i beylerbejstwo Hayıra Beja", "8cd4fb23"], "d": ["Sułtan Selim Straszny, który spędził w Egipcie około ośmiu miesięcy, ustanawiając ład administracyjny, finansowy i wojskowy, opuścił Kair; Hayır Bej, dawny namiestnik Aleppo, który pod Mardż Dabik wycofał lewe skrzydło i przyspieszył klęskę mameluków, rozpoczął zarząd z Cytadeli jako pierwszy beylerbej osmański Egiptu. Wybór namiestnika pochodzenia mameluckiego był świadomą polityką przejściową, dzięki której nowy zarząd nie wydawał się obcy miejscowej ludności. W drodze powrotnej sułtan zabrał do Stambułu ostatniego kalifa abbasydzkiego Mutawakkila III oraz wybitnych artystów i uczonych Egiptu.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Koniec kairskiego kalifatu abbasydzkiego — przekaz o „ceremonii przekazania”", "1d357640"], "d": ["Sułtan Selim Straszny po zdobyciu Egiptu zabrał do Stambułu ostatniego kalifa Mutawakkila III al-Allaha, który dostał się do niewoli pod Mardż Dabik; kairski kalifat abbasydzki, od 1261 trwający bez władzy w cieniu sułtanów mameluckich, w ten sposób się skończył. Natomiast słynny przekaz, że kalifat został przekazany Selimowi w oficjalnej ceremonii w Hagia Sophia, po raz pierwszy występuje pod koniec XVIII wieku w dziele d'Ohssona i nie ma go w żadnym ze źródeł z epoki Selima. TDV İslâm Ansiklopedisi uznaje przekaz za zmyślenie, ponieważ nie ma oryginalnego źródła dokumentującego ceremonię; odnotowuje jednak, że dla przejścia kalifatu nie była też według szariatu potrzebna taka ceremonia przekazania.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum przyłączony do zarządu osmańskiego — złamanie wpływów safawidzkich we Wschodniej Anatolii", "78d1be02"], "d": ["Choć po zwycięstwie pod Çaldıranem (1514) wpływy osmańskie w regionie wzrosły, pełne zajęcie Erzurumu opóźniło się aż do złamania wpływów irańskich; miasto zostało przyłączone do zarządu osmańskiego dopiero po wyprawie egipskiej, w latach 1518–19. Erzurum znalazł się pod panowaniem safawidzkim w 1502, gdy szach İsmâil położył kres Bejlikowi Akkoyunlu; szesnastoletni okres się w ten sposób zamknął. W 1534, w czasie wyprawy Irakejn, miał zostać utworzony beylerbeylik Erzurumu. W latach 1518–1519 wraz z regionem Erzurum przyłączono do zarządu osmańskiego także Aşkale (dzień niepotwierdzony).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Początek powstań celâlich: powstanie Şeycha Celâla z Bozok", "99bd8a99"], "d": ["W okolicach Bozok pewien człowiek o imieniu Şeyh Celâl, ogłosiwszy się mahdim, zbuntował się w okolicach Tokat; choć powstanie stłumiono, jego imię przez stulecie stało się nazwą dla wszystkich ruchów zbójeckich i powstańczych w Anatolii. Celâlizm, połączony pod koniec XVI wieku z rozpadem ładu timarowego i naciskiem demograficznym, przekształcił się w najdłużej trwający problem bezpieczeństwa wewnętrznego imperium. Powstania spowodowały w Anatolii masowe migracje zwane „wielką ucieczką”.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Przyłączenie Algieru do Państwa Osmańskiego", "b8eba4c1"], "d": ["Hayreddin Reis, który opierał się w Afryce Północnej naciskowi hiszpańskiemu, zwrócił się do Stambułu, by się utrzymać, i oddał Algier sułtanowi, a chutbę odczytano w imieniu sułtana Selima Strasznego. W ten sposób Algier został oficjalnie przyłączony do ziem osmańskich, a Hayreddinowi wysłano z tytułem beylerbeja żołnierzy i działa. To przyłączenie położyło podwaliny osmańskiego panowania morskiego na zachodzie Morza Śródziemnego, które miało trwać stulecia. W tym samym dniu przyłączono także inne miejscowości: Konstantyna, Szerszel (Cherchell), Médéa (Titteri), Sétif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Śmierć sułtana Selima Strasznego w Çorlu", "9fe83744"], "d": ["Selim I, który w osiem lat ponad dwukrotnie powiększył ziemie państwa, wyruszył ze Stambułu 18 lipca 1520 na nową wyprawę; z powodu wielkiego guza, który wyrósł mu na plecach, nie mógł pójść dalej niż Çorlu. Mimo interwencji lekarzy choroba się pogłębiła i po dwumiesięcznym beznadziejnym leczeniu zmarł tu 8–9 şewwala 926 (21–22 września 1520). Dzięki Çaldıranowi, Mardż Dabik i Ridaniji zatrzymał Iran i zlikwidował Państwo Mameluckie, przynosząc Osmanom kalifat i protektorat nad Haremejn. Zostawił jednego syna: Sulejmana.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Wejście wyspy Ikaria (Nikarya) pod zarząd osmański", "6afa972b"], "d": ["Ikaria między Samos a Chios znajdowała się od 1481 do 1521 pod zarządem joannitów z Rodos; pierwszy okres osmański na wyspie rozpoczął się w 1522 i trwał do 1822. W tym okresie za zbieranie i płacenie podatków odpowiadał kaymakam; podobnie jak na innych wyspach Morza Egejskiego trwała też lokalna rada starszych (demogerontia), która od czasu do czasu wchodziła w konflikt z zarządem osmańskim.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Aneksja ziemi Dulkadir — ejalet Dulkadir z ośrodkiem w Maraşu", "595c3c30"], "d": ["Ziemia Dulkadir, trwająca od klęski pod Turnadağ w 1515 jako bejlik zależny od Osmanów, została po wymordowaniu Şehsuvaroğlu Alego Beja wraz z dziećmi w Artukova bezpośrednio przyłączona do ziem osmańskich i przekształcona w ejalet z ośrodkiem w Maraşu. Region Bozok bejliku został związany z zarządem osmańskim jako odrębny sandżak. W ten sposób zamknął się około dwustuletni okres Dulkadırlı w Maraşu, Elbistanie, Göksun, Gürün, Zamantı i Darende; bufor bejlik na granicy mameluckiej całkowicie zniknął.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Zdobycie Kninu", "a46d3117"], "d": ["W wyniku napadów sandżakbeja Bośni Gazi Hüsrev Beja w latach 927–928 (1521–1522) szereg twierdz weneckich, na czele z Kninem, Skradinem i Ostrovicą, przeszedł pod zarząd osmański; granicę odepchnięto za drugi łańcuch gór. Ten łańcuch zdobyczy położył podwaliny pod sandżak Dalmacji, który miał zostać dopełniony po piętnastu latach zajęciem Klisu.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Wycofanie się rycerzy: przekazanie Bodrum, Kos i Dodekanezu", "ea01666e"], "d": ["Zgodnie z warunkami poddania Rodos joannici opuścili nie tylko ośrodek wyspy, ale wszystkie pozycje, które trzymali od dwustu lat. Twierdza Bodrum (Saint Pierre) na wybrzeżu Anatolii oraz wyspy Kos, Kalymnos i Leros przeszły w ten sposób bez walki pod zarząd osmański. Wraz z tym przekazaniem, dopełnionym dwa tygodnie po upadku Rodos, obecność łacińska w południowo-wschodnim narożniku Morza Egejskiego całkowicie się skończyła.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Powstanie Hain Ahmeda Paszy w Egipcie", "b18bb805"], "d": ["Ahmed Pasza, który oczekując wielkiego wezyratu został wysłany na namiestnictwo Egiptu, ogłosił w Kairze niepodległość, mianując się „al-Malik al-Mansûr Sułtan Ahmed”. Powstanie szybko stłumiono, a paszę zabito, lecz wydarzenie pokazało kruchość kontroli centralnej w najbogatszym ejalecie imperium. Wobec tego İbrahim Pasza udał się do Egiptu i kazał przygotować słynne Kanunname Egiptu, na nowo porządkujące zarząd ejaletu.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Aneksja Północnej Bośni: Jajce i Banja Luka", "8ec86cfa"], "d": ["Gdy po Mohaczu węgierska linia obrony się załamała, sandżakbej Bośni Gazi Hüsrev Bej, maszerując w dolinę Vrbasu, zajął ostatnie twierdze bośniackie pozostające w rękach królestwa węgierskiego. Wraz z upadkiem Jajce i Banja Luki ejalet Bośni sięgnął na północy rzeki Sawy i narodził się front chorwacki. Banja Luka wkrótce stała się drugim ośrodkiem ejaletu.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Zajęcie Budy i oddanie jej Zápolyi", "fba4f89b"], "d": ["W drodze na wyprawę wiedeńską armia osmańska oblegała i odzyskała Budę, która wpadła w ręce Ferdynanda, i oddała miasto królowi Węgier pod protekcją osmańską, Jánosowi Szapolyaiemu. W ten sposób na Węgrzech ustanowiono w rywalizacji habsbursko-osmańskiej model buforowego królestwa wasalnego. Ten ład miał trwać do 1541, a po śmierci Zápolyi Buda miała zostać przekształcona w bezpośredni ejalet osmański.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Sulejman wyruszył na wyprawę niemiecką — wyzwanie rzucone Karolowi V", "7c3d7055"], "d": ["Po bezskutecznym oblężeniu Wiednia i ponownym oblężeniu Budy przez Ferdynanda sułtan wyruszył ze Stambułu, by tym razem bezpośrednio wciągnąć cesarza Karola V w bitwę polną. Armia miała w sierpniu zatrzymać się przy oporze małej twierdzy Güns, a ponieważ cesarz nie wyszedł do bitwy, wyprawa miała ograniczyć się do napadów. Wyprawa przygotowała grunt pod pierwszy pokój z Habsburgami w następnym roku.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Wyprawa niemiecka i oblężenie Güns (Kőszeg)", "8aec937a"], "d": ["Sulejman, chcąc zmusić Karola V do bitwy polnej, poprowadził armię na Austrię; mała twierdza Güns, broniąc się dwadzieścia pięć dni, opóźniła natarcie armii. Ponieważ cesarz nie wyszedł do bitwy, akindżi uderzyli na okolice Wiednia, a wobec postępu pory roku zawrócono. Wyprawa nie przyniosła zdobyczy terytorialnych, lecz posadziwszy Habsburgów przy stole przygotowała grunt pod pokój w następnym roku.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Traktat stambulski — pierwszy pokój z Habsburgami", "b085767a"], "d": ["Sułtan, który przyjął posła Ferdynanda Corneliusa, zgodził się na rozejm i powstał pierwszy oficjalny tekst pokojowy między Osmanami a Austrią. Na mocy traktatu Ferdynand zgodził się płacić roczny podatek za ziemie węgierskie, które trzymał, a arcyksiąże austriacki w protokole został uznany za równego wielkiemu wezyrowi. Ten nierówny status był jawnym wyrazem osmańskich pretensji do wyższości w XVI wieku.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Zajęcie Karsu i otwarcie granicy północno-wschodniej", "742e3101"], "d": ["Gdy kolumna czołowa wyprawy Irakejn zwróciła się z Erzurumu na wschód, twierdza Kars, znajdująca się w rękach atabegatu gruzińskiego i leżąca w ruinie od czasów Timura, została przejęta bez oporu. Miasto, trzymając przejście między łukiem Arasu a Çıldır, uchodziło za klucz północnej bramy otwierającej się na Iran. Ta zdobycz stała się pierwszym ogniwem beylerbeyliku Karsu, który miał powstać po trzydziestu latach, i linii kaukaskiej.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Pierwsze wkroczenie do Tabrizu — otwarcie wyprawy Irakejn", "cf7ed4e3"], "d": ["İbrahim Pasza, który ruszył naprzód jako serdar-ı ekrem, wkroczył bez oporu do stolicy safawidzkiej Tabrizu, gdy szach Tahmasp, unikając bitwy polnej, wycofał się w głąb kraju. Sulejman dotarł do miasta we wrześniu; jednak wskutek nadejścia zimy i zbytniego wydłużenia linii zaopatrzenia armia zwróciła się w kierunku Bagdadu, a Tabriz nie mógł być utrzymany przez dłuższy czas. Miasto zajęte po raz drugi po Çaldıranie stało się miejscem, w którym Osmanowie nauczyli się, że na wschodzie zdobyć jest łatwo, a utrzymać trudno.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Zdobycie Tunisu przez Barbarossę", "d8754216"], "d": ["Kapudan pasza Barbarossa Hayreddin Pasza, po uderzeniu flotą na wybrzeża Włoch, zwrócił się ku Tunisowi i wkroczył do miasta, zmusiwszy do ucieczki władcę Hafsydów Mulaja Hasana. Zajęcie Tunisu dzięki jego położeniu kontrolującemu Cieśninę Sycylijską nagle obróciło równowagę sił w zachodniej części Morza Śródziemnego na korzyść Osmanów. Panowanie to nie miało jednak trwać długo, a Karol V miał w następnym roku odpowiedzieć wielką flotą.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Utrata Tunisu na rzecz Karola V", "a691f0f8"], "d": ["Karol V, po zdobyciu Halk al-Wadi wielką wyprawą wspartą flotami genueńską i papieską, zajął Tunis i przywrócił na tron Mulaja Hasana pod protekcją hiszpańską. W mieście osadzono garnizon hiszpański i osmańskie natarcie w środkowej części Morza Śródziemnego zostało tymczasowo zatrzymane. Ostateczne zdobycie Tunisu miało stać się możliwe dopiero po czterdziestu latach, w 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Akcja Gazi Hüsrev Beja wzdłuż Sawy: Bosanski Brod i Jasenovac", "3740ec83"], "d": ["Po zajęciu Jajce i Banja Luki w 1528 twierdze wzdłuż rzeki Sawy pozostawały jeszcze przez pewien czas na granicy chorwacko-slawońskiej podległej koronie habsburskiej. Gazi Hüsrev Bej, który w 1536 po raz trzeci został sandżakbejem Bośni, w tym samym roku, zajmując Požegę i okolice, przyłączył do zarządu osmańskiego także twierdze Brod i Jasenovac nad Sawą. Północna granica Bośni sięgnęła w ten sposób Sawy; region został dopełniony po dwóch latach zajęciem Dubicy.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Stracenie Makbula İbrahima Paszy", "348aa7b8"], "d": ["İbrahim Pasza, który przez trzynaście lat był wielkim wezyrem, najbliższym przyjacielem Sulejmana i faktycznie drugim człowiekiem państwa, został uduszony i stracony w pałacu, do którego wezwano go na iftar, bez podania żadnego powodu. Za czynniki jego śmierci uważa się jego postawę w wyprawie Irakejn, używanie tytułu „serasker sułtan” oraz układy wewnątrz pałacu. Stracenie jest punktem zwrotnym pokazującym, że w osmańskim zarządzie centralnym wielcy wezyrowie nie mają absolutnego bezpieczeństwa.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Zdobycie twierdzy Klis i utworzenie sandżaku Dalmacji", "6ffd4ebf"], "d": ["Murad Bej, neofita chorwackiego pochodzenia i kethüda Gazi Hüsrev Beja, zajął od Wenecji strategiczną twierdzę Klis tuż na północ od Splitu. Bezpośrednio po zdobyciu Klis uczyniono ośrodkiem nowego sandżaku i kazy obejmującego okolice; granice tego sandżaku w znacznej mierze wyznaczyły ramy osmańskiej Chorwacji. To zdobycie, następujące piętnaście lat po Kninie, dopełniło administracyjny szkielet wnętrza Dalmacji.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Oblężenie Korfu i wojna z Wenecją", "11af95bd"], "d": ["Po wyprawie do Apulii armia osmańska wysadziła wojsko na Korfu i oblegała potężną twierdzę wenecką na wyspie. Wskutek stromego położenia twierdzy, ciężkich strat i warunków pory roku blokadę zniesiono i wycofano się 6 września. Choć oblężenie nie przyniosło skutku, wojna otwarta z Wenecją zakończyła się przyłączeniem do Osmanów wielu wysp na Morzu Egejskim i Adriatyku oraz zwycięstwem pod Prewezą w następnym roku.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Wyprawa Barbarossy na Morze Egejskie: zajęcie wysp zarządzanych bezpośrednio przez Wenecję", "1b32ed96"], "d": ["Flota, wracając spod oblężenia Korfu, wykorzystując wypowiedzenie wojny Wenecji, przejmowała jedną po drugiej wyspy Morza Egejskiego podlegające nie księstwu, lecz bezpośrednio Wenecji. Eginę zdobyto po zaciętym oporze, Astypalaja w rękach rodu Querini oraz Karpathos i Kasos się poddały, a Patmos pod zarządem klasztoru przyjęło protekcję osmańską. Księstwo Naksos pozostawiono natomiast na miejscu, związane daniną; jego aneksja miała czekać do 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Wyprawa Barbarossy na północne Morze Egejskie: zajęcie Skyros i Północnych Sporad", "20ab688e"], "d": ["W drodze do Prewezy flota przejęła jedną po drugiej wyspy północnego Morza Egejskiego, które po zdobyciu Stambułu schroniły się u Wenecji. Skyros na północ od Negroponte oraz Skiathos, Skopelos i Alonissos trzymające wejście do Zatoki Salonickiej weszły w ten sposób pod zarząd osmański. Te wyspy zamknęły ostatnią północnoegejską próżnię, która, choć Negroponte zdobyto w 1470, pozostawała jeszcze przez sześćdziesiąt osiem lat w rękach Wenecji.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Zajęcie Adenu i aneksja wybrzeża Jemenu", "e7d46d8f"], "d": ["Flota wypływająca z Suezu na wyprawę indyjską, ponieważ nie można było wyjść na ocean bez zabezpieczenia Morza Czerwonego, zwróciła się najpierw ku wybrzeżu Jemenu. Hadım Süleyman Pasza wszedł 3 sierpnia 1538 do portu Aden; władca Tâhirîdów Âmir b. Dâvud, skłonny do Portugalczyków, został sprowadzony do bramy kapitana i stracony, a w mieście zostawiono 500-osobową załogę. Podczas tej samej wyprawy przyjęto także poddanie Mokha oraz wysp Kamaran i Farasan panujących nad cieśniną, i położono podwaliny pod beylerbeylik Jemenu. W ten sposób państwo osmańskie po raz pierwszy zdobyło całe północne wybrzeże Bab al-Mandab; Sana i regiony wewnętrzne miały czekać jeszcze dziewięć lat.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Wyprawa na Mołdawię i aneksja regionu Budżak (Bender)", "90a88a56"], "d": ["W wyprawie przeciw wojewodzie mołdawskiemu Petru Rareșowi, który nie wypełniał zobowiązań wobec Osmanów, zdobyto Suczawę, a miasto Jassy zostało złupione przez chana krymskiego Sâhiba Gireja. Sułtan wprowadził na wojewodztwo Stefana Çekirge i przyłączył Bender wraz z regionem Budżak (południowa Besarabia) bezpośrednio do ziem osmańskich. Ta aneksja stała się jednym z ogniw przekształcających północno-zachodnie wybrzeża Morza Czarnego w osmańskie morze wewnętrzne. Mołdawia była już województwem zależnym od Osmanów; wyprawa ta nie zabrała ziemi obcemu państwu, lecz jedynie odebrała wojewodzie zarząd wewnętrzny Benderu i Budżaku i związała go bezpośrednio z sułtanem; reszta wojewodztwa zachowała status zależny. Ta sama struktura miała się powtórzyć w 1484 w Kilii i Akkermanie, a w 1713 w Chocimiu: twierdze graniczne bezpośrednio, ziemie wewnętrzne zależne.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Przejęcie Nauplionu (Anabolu) na mocy traktatu", "104d0937"], "d": ["Trwająca po Prewezie trzy lata wojna z Wenecją zakończyła się zgodą republiki na zostawienie dwóch ostatnich twierdz w Morei. Nauplion (Anabolu) i Monemwazja (Benefşe), których nie zdobyto w oblężeniu, zostały przekazane Osmanom przy stole, oprócz trzystu tysięcy dukatów odszkodowania wojennego. Półwysep Morea w ten sposób zjednoczył się tak, że nie pozostał na nim ani jeden ślad Wenecji.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Wejście Segedynu pod zarząd osmański i utworzenie liwy Segedynu", "019aa000"], "d": ["Po pełnym ustanowieniu zarządu osmańskiego w Budzie w 1541 notable Segedynu przyjęli panowanie Ferdynanda I i przygotowali się do obrony zbrojnej. Beylerbej Budy Küçük Bâlî Pasza na początku 1543 kazał wezwać zarządców miasta i stracić ich pod zarzutem zdrady, a następnie wysłał oddział, by zająć miasto. W tym czasie utworzono liwę Segedynu i na pierwszego sandżakbeja mianowano Derviş Beja, syna Bâlîego Paszy; liwa początkowo rozciągała się między Dunajem a Cisą.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Zdobycie Valpo, Siklósu i Pécsu", "2ca030a3"], "d": ["Pierwszym celem wyprawy węgierskiej, podjętej dwa lata po aneksji Budy, było zabezpieczenie południowego skrzydła nowego ejaletu między Drawą a Dunajem. Po zdobyciu twierdz Valpo i Siklós poddał się Pécs, ośrodek Baranyi. Miasto miało stać się najludniejszym i najbardziej rozbudowanym ośrodkiem osmańskich Węgier, a historyk İbrahim Peçuylu miał od niego wziąć swe przezwisko.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Zdobycie Ostrzyhomia i Székesfehérvár", "efca9e05"], "d": ["W wyprawie węgierskiej, którą Sulejman prowadził osobiście, po dwuipółtygodniowym oblężeniu Ostrzyhom, ośrodek religijny Królestwa Węgier i miasto arcybiskupie, wszedł pod zarząd osmański. Następnie zajęto także Székesfehérvár, miasto koronacji królów węgierskich, i pas obronny ejaletu Budy został dopełniony. Ostrzyhom miał pozostać w rękach osmańskich do 1595 jako kluczowa twierdza linii Dunaju.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Północno-zachodni pas obrony Budy: Vác, Hatvan i Simontornya", "733ee5ce"], "d": ["Po zdobyciu Ostrzyhomia i Székesfehérvár beylerbej Budy ruszył bez wyprawy sułtana, by dopełnić pierścień twierdz otaczających stolicę. Vác w zakolu Dunaju, Hatvan, brama Alföldu, i Simontornya na linii Sió zostały przejęte jedna po drugiej. Zdobycze tego cichego roku przekształciły Budę z miasta pogranicznego w ośrodek ejaletu, który miał przetrwać sto czterdzieści lat.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Aneksja Basry i wyjście do Zatoki Perskiej", "02f87c11"], "d": ["Władca Basry Râşid b. Megāmis w czasie zdobycia Bagdadu (1534) zadeklarował Sulejmanowi posłuszeństwo, a w 1538 przysłał klucze miasta. Gdy zastępujący go szejch Yahyâ zwrócił się przeciw Osmanom, beylerbej Bagdadu Ayas Pasza ruszył lądem, a sandżakbej Mosulu z 120 okrętami Eufratem; Ayas Pasza wkroczył do Basry 26 grudnia 1545, a miasto stało się ośrodkiem beylerbeyliku. Port u ujścia Szatt al-Arab był bramą, przez którą Osmanowie otworzyli się na zatokę kontrolowaną przez Portugalię z Ormuzu; traktatem z Amasyi z 1555 Iran także uznał ten stan.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Zdobycie Sany i wnętrza Jemenu", "d31ded85"], "d": ["Po Ta'izz zajęto także Sanę, a cały kraj został związany z beylerbeylikiem. Jednak wskutek stromej geografii i różnicy wyznaniowej to panowanie nigdy nie było spokojne; Jemen stał się dla Osmanów frontem nieustannie pochłaniającym żołnierzy.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Zdobycie Ta'izz", "d4509df9"], "d": ["W Jemenie, gdzie dziewięć lat wcześniej poprzestano na pasie wybrzeża, wobec rosnącej siły imamów zajdyckich w górzystym wnętrzu siły Özdemira Paszy weszły na wyżynę i zajęły Ta'izz.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Traktat stambulski — pięcioletni pokój z Habsburgami", "41f81773"], "d": ["Między Osmanami a Habsburgami podpisano pięcioletni pokój; Ferdynand zgodził się płacić rocznie 30 000 dukatów za ziemie węgierskie, które trzymał. Traktat prawnie utrwalił faktyczny stan Węgier podzielonych na trzy części. Zabezpieczenie w ten sposób frontu zachodniego dało Sulejmanowi możliwość zorganizowania nowych wypraw na Iran.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Druga wyprawa irańska i ponowne zajęcie Tabrizu", "e82365df"], "d": ["W wyprawie podjętej z zachęty brata szacha Tahmaspa, Elkasa Mirzy, który zbuntował się przeciw niemu i schronił w Stambule, armia po raz drugi weszła do Tabrizu. Ponieważ Safawidzi znów nie weszli do bitwy polnej i wycofali się, paląc ziemię, w mieście można było zostać tylko kilka tygodni. Wyprawa przesądziła, że Tabrizu nie da się utrzymać, i skierowała osmańską strategię ku utworzeniu trwałej linii granicznej, czyli ku umocnieniu Wanu.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Zdobycie Wanu i ustalenie granicy wschodniej", "fc8f930b"], "d": ["Twierdza Wan, oblężona w drodze powrotnej z Tabrizu, dzięki położeniu na skale wznoszącej się nad wschodnim brzegiem jeziora była niekwestionowanym kluczem regionu i po krótkim oblężeniu się poddała. Miasto natychmiast uczyniono ośrodkiem beylerbeyliku; sandżaki Erciş, Adilcevaz i Hakkâri podporządkowano mu. W odróżnieniu od Tabrizu Wan został utrzymany i przez czterysta lat pozostał najdalej wysuniętą trwałą pozycją Osmanów na wschodzie.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Aneksja Al-Hasa i Al-Katif — arabskie wybrzeże Zatoki", "f6701e60"], "d": ["Po zajęciu Basry zdobyto Al-Katif, który na zachodnim wybrzeżu Zatoki stał się wysuniętym posterunkiem Portugalii, i wraz z oazami Al-Hasa we wnętrzu utworzono nowy beylerbeylik. To stąd wychodziły akcje skierowane na Bahrajn i Ormuz. Państwo osmańskie zyskało w ten sposób głos jednocześnie na wybrzeżach półwyspu Arabskiego nad Morzem Czerwonym i Zatoką Perską.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Utrata Şehrizoru — bej Erdelanu Sührâb skłonił się ku Safawidom", "5600efc9"], "d": ["Region Şehrizoru, który w czasie wyprawy Irakejn (1535) uznał zwierzchnictwo osmańskie, znajdował się pod zarządem emira Erdelanu Bige Beja rezydującego w twierdzy Zalm. Po śmierci Bige Beja w 1550 jego brat Sührâb, który zajął twierdzę Zalm i opanował bejlik, zwrócił się ku Safawidom i wypowiedział posłuszeństwo Osmanom; region Şehrizoru wyszedł w ten sposób spod wpływów osmańskich. Region został odzyskany dopiero w 1554, podczas wyprawy nachiczewańskiej, po oblężeniu i zajęciu twierdzy Zalm.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Zajęcie Ardahanu i dorzecza Çıldır", "14c9eb76"], "d": ["Beylerbej Erzurumu, w czasie trwającej wojny z Safawidami zwróciwszy się ku ziemiom atabegów gruzińskich na łuku Kury, przyłączył do zarządu osmańskiego Ardahan i okolice Çıldır. Linia Kars–Ardahan została w ten sposób zjednoczona, a wyżyny otwierające się na Gruzję na północnym wschodzie objęto kontrolą. Ostateczny ład administracyjny regionu miał zostać dopełniony po dwudziestu siedmiu latach utworzeniem ejaletu Çıldır.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokollu Mehmed Pasza przekroczył Dunaj — początek wojny o Siedmiogród", "38fde931"], "d": ["Wobec zamętu wywołanego przez mnicha Martinuzziego, opiekuna króla Siedmiogrodu, małego Jánosa Zsigmonda, i oddania przez Siedmiogród twierdz Banatu Ferdynandowi uznano za konieczną nową wyprawę; dowództwo powierzono beylerbejowi Rumelii Sokollu Mehmedowi Paszy. Armia, mimo zwodzących zabiegów Martinuzziego, przekroczyła Dunaj i zajęła Becse, Becskerek, Csanád i Lippę; jednak oblężenie Timișoary zniesiono 16 listopada z powodu mrozów. W ten sposób na Węgrzech rozpoczęła się nowa wojna osmańsko-habsburska.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["Miasto Lipova (Lippa) wpadło w ręce armii austriackiej Castaldo — twierdza poddała się 5 grudnia", "a0e1ff0d"], "d": ["Lipovę, zajętą przez Sokollu Mehmeda Paszę w październiku 1551, armia generała Castaldo oblegała od 4 listopada; po dwóch dniach miasto wpadło w ręce Austriaków. Ulama Pasza z 5000-osobową załogą bronił twierdzy jeszcze dziewięć dni i 5 grudnia 1551 wyszedł na mocy układu. Do upadku Timișoary w 1552 Lipova pozostawała w rękach Habsburgów.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Utrzymanie przez siły wysłane z Timișoary palanek Banatu Południowego — Versec, Haram, Keve", "edca0921"], "d": ["Po poddaniu się Timișoary armii osmańskiej oddziały odłączone od armii oblężniczej zwróciły się ku małym palankom Banatu; według relacji Bánlakyego palanki Versec, Facset, Mehádia, Csákóvár, Haramvár i Keve były trzymane przez te siły. W ten sposób także Haram nad Dunajem wpadł w ręce osmańskie.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Zdobycie Szolnoku i niepowodzenie oblężenia Egeru", "a7156e8f"], "d": ["Po zdobyciu Timișoary dwie połączone armie osmańskie zajęły niemal bez walki Szolnok nad Cisą, gdy najemnicy opuścili twierdzę. Oblężona następnie twierdza Eger nie została zdobyta wobec trzydziestoośmiodniowego oporu dwutysięcznego garnizonu pod dowództwem Istvána Dobó, a armia, gdy nadeszła zima, się wycofała. To, że w tej samej wyprawie jedna twierdza padła łatwo, a druga się oparła, było pierwszym jawnym znakiem, że granica na Węgrzech nie przesuwa się już sama na korzyść Osmanów.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Sojusz osmańsko-francuski — oddanie floty francuskiej pod rozkazy osmańskie", "a8e01b22"], "d": ["Traktatem z 1 lutego 1553 flotę francuską oddano pod rozkazy floty osmańskiej; przewidziano wspólne działania w zachodniej części Morza Śródziemnego przeciw Hiszpanii. Po traktacie Turgut Reis wyruszył 15 czerwca 1553 z czterdziestoma pięcioma galerami wesprzeć Francję. Był to pierwszy oficjalny traktat sojuszniczy przenoszący handlowy grunt kapitulacji z 1536 na współpracę wojskową.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Stracenie księcia Mustafy w Konya Ereğli", "dec36858"], "d": ["Książę Mustafa, który wszedł do namiotu ojca, by dołączyć do armii zebranej na wyprawę nachiczewańską, w chwili gdy miał stanąć przed obliczem sułtana spotkał katów i został uduszony. Zabicie następcy, wielce kochanego w armii, wywołało głęboki gniew wśród janczarów, a Rüstem Pasza został odwołany z wezyratu. Wydarzenie weszło do literatury i pamięci ludowej jako jedno z najbardziej spornych załamań osmańskiej polityki książęcej.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Przesunięcie granicy Nubii na południe wraz z Ibrim", "c57d5d77"], "d": ["Południowa granica beylerbeyliku Egiptu została przesunięta poza drugą kataraktę, gdy twierdza Ibrim, wznosząca się na skalistym przylądku nad Nilem, została umocniona przez Özdemira Beja, a Dolna Nubia całkowicie przyłączona do osmańskiego Egiptu. (W Ibrim osmańska organizacja administracyjna została ustanowiona po zdobyciu Egiptu; na mapie Ibrim jest pokazywany jako osmański od 1517. Rok ten jest przybliżony, źródło nie podaje roku.) Twierdza była zaporą przeciw napadom z Nubii, a zarazem punktem kontroli szlaku złota i niewolników prowadzącego do Sennaru. Osadzona tu bośniacka załoga okazała się tak trwała, że jej potomkowie byli w twierdzy jeszcze trzysta lat później. Źródła podają dwie różne relacje o czasie wejścia Ibrim pod zarząd osmański: hasło TDV o Sudanie wiąże przyłączenie Dolnej Nubii do osmańskiego Egiptu z akcją Özdemira Paszy w połowie XVI wieku, natomiast hasło o Nubii pisze, że region aż po dolinę Halfa i organizacja administracyjna w Ibrim zostały ustanowione bezpośrednio po zdobyciu z 1517. Sandżak Ibrim został 26 lipca 1573 przyłączony do ejaletu Habesz.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Zdobycie Bidżaji (Bougie) od Hiszpanów", "49691cda"], "d": ["Bidżaja, w rękach Hiszpanii od czterdziestu trzech lat i dzieląca wybrzeże między Algierem a Konstantyną na dwie części, poddała się po oblężeniu z lądu i morza. Wraz z upadkiem twierdzy wybrzeże odżaku algierskiego stało się nieprzerwane aż po Oran. W Hiszpanii ta strata wywołała tak wielkie oburzenie, że dowódca Alonso de Peralta, który oddał twierdzę, został w kraju stracony.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Przyłączenie Zeili do Ejaletu Habesz", "7bbf369a"], "d": ["Port Zeila na afrykańskim wybrzeżu Zatoki Adeńskiej, na południowym krańcu ejaletu Habesz, został związany z zarządem osmańskim. Miasto, brama Sułtanatu Adal otwierająca się na morze, było ostatnim punktem zaopatrzenia dla okrętów wychodzących poza Bab al-Mandab. Wraz z przyłączeniem Zeili granica państwa osmańskiego w Afryce osiągnęła swój najdalszy południowy punkt.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Bitwa książąt pod Konyą", "1c8de387"], "d": ["Książę Bayezid, który wszedł do walki o tron, przybył pod Konyę z około 30 000 ludzi i w trwającej dwa dni walce przegrał z bratem księciem Selimem. Rozbity Bayezid schronił się przez Amasyę w Iranie u szacha Tahmaspa. Bitwa w ostatnich latach Sulejmana zamieniła kryzys sukcesji tronu w problem polityki zagranicznej.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Zwycięstwo morskie pod Dżerbą", "c7b905c1"], "d": ["Flota osmańska pod dowództwem Piyâle Paszy rozproszyła pod Dżerbą manewrem podziału na dwie części flotę sprzymierzonych — hiszpańsko-genueńsko-maltańską — zebraną w celu odzyskania Trypolisu. Sprzymierzeni stracili większość swych flot, a twierdza na wyspie wkrótce padła. Dżerba uchodzi, po Prewezie, za drugie wielkie zwycięstwo morskie umacniające przewagę osmańską na Morzu Śródziemnym.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Stracenie księcia Bayezida w Kazwinie", "a759de14"], "d": ["Książę Bayezid, który schronił się w Iranie, został po długich targach wydany przez szacha Tahmaspa delegacji osmańskiej i uduszony wraz z czterema synami. W zamian za wydanie Safawidzi uzyskali istotne ustępstwa materialne i gwarancje graniczne. Tą egzekucją ostatnia przeszkoda w drodze Selima II na tron została usunięta, a pokojowy ład traktatu z Amasyi został zachowany.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Zajęcie Chios od Genueńczyków", "a4559b96"], "d": ["Chios, zarządzane od dwustu lat jako kolonia handlowa należąca do genueńskiego rodu Giustiniani i płacące Osmanom daninę, zostało przejęte przez Piyâle Paszę bez jednego wystrzału pod pretekstem zaniedbywania daniny i udzielania portu okrętom wroga. Wraz z Chios i Psarą zlikwidowano ostatnią obecność genueńską na wschodnim wybrzeżu Morza Egejskiego. Wyspę przyłączono do ejaletu Cezâyir-i Bahr-i Sefîd, zachowując produkcję mastyksu i przywileje Chiotów.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Aneksja Księstwa Naksos — wszystkie Cyklady", "68f0ec0b"], "d": ["Łacińskie Księstwo Naksos, trwające od 1207 i płacące Osmanom daninę od 1537, zostało zniesione pod pretekstem skarg wywołanych uciskiem ludności przez ostatniego księcia Giacoma Crispa. Naksos, Paros, Antiparos, Andros, Syros, Mykonos, Ios, Santorini i wszystkie Cyklady wokół nich zostały jednym postanowieniem objęte bezpośrednim zarządem osmańskim. Sulejman oddał zarząd wysp na pewien czas Yasefowi Nasiemu; trzy i pół stulecia panowania łacińskiego dobiegło w ten sposób końca pośrodku Morza Egejskiego.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Powstanie w Jemenie i wyprawa Koca Sinana Paszy do Jemenu", "c8218d8e"], "d": ["Imam zajdycki Mutahhar, powołując się na przymusowe ściąganie podatków, zbuntował się i wyrzucił zarząd osmański z większej części Jemenu. Koca Sinan Pasza, wysłany ze Stambułu, w akcji prowadzonej w latach 1568–1570 zajął Kawkaban po długim oblężeniu i na nowo ustanowił panowanie osmańskie w regionie. Wyprawa miała życiowe znaczenie dla zachowania kontroli nad południową bramą Morza Czerwonego i szlakiem handlowym Oceanu Indyjskiego.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Sojusz obronny z Sułtanatem Aceh i pomoc na Oceanie Indyjskim", "8e835f24"], "d": ["Posłowie Aceh, którzy prosili Sulejmana o pomoc wobec ataków portugalskich, po śmierci sułtana pod Szigetvárem złożyli swoją wierność Selimowi II i podpisano z nim traktat obronny. Sułtan rozkazał wysłać z Aleksandrii działa, muszkiety, amunicję i rzemieślników; przygotowano siedemnaście okrętów wojennych do wysłania na wody indyjskie. Rozrost powstania w Jemenie uniemożliwił wyjście floty, lecz osmańscy artylerzyści i rzemieślnicy, którzy dotarli do Aceh, pozostawili w regionie trwały ślad.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Lądowanie na Cyprze: zajęcie Limassol", "9074ccc9"], "d": ["Armia osmańska, która wylądowała na wyspie, zajęła Limassol bez większego oporu i następnego dnia zwróciła się ku Larnace. Dzięki niezadowoleniu miejscowej ludności z zarządu weneckiego i pomocy dla sił osmańskich także w Larnace nie napotkano poważnego oporu; przystań Tuzla uczyniono bazą lądowania żołnierzy i sprzętu. Wenecja skupiła obronę w Nikozji i Famaguście; namiestnik Pafos oznajmił serdarowi posłuszeństwo dopiero po upadku Nikozji.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Zdobycie Nikozji", "413d866b"], "d": ["Po rozpoczętym 25 lipca 1570 i trwającym czterdzieści pięć dni oblężeniu Nikozja, stolica Cypru pod zarządem weneckim, poddała się armii osmańskiej. Upadek ośrodka wyspy zepchnął wenecki opór do twierdzy Famagusta. Zdobycie wywołało na Zachodzie wielki oddźwięk i przyspieszyło proces prowadzący do utworzenia floty Świętej Ligi z inicjatywy papieża.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Poddanie Kyrenii — północne wybrzeże Cypru", "39fdeea5"], "d": ["Zdobycie Nikozji 9 września z wycięciem obrońców złamało opór na północy Cypru. Twierdza Kyrenia za górami Pentadaktylos, dowiedziawszy się o losie stolicy, poddała się po ośmiu dniach na warunkach, a garnizon wysłano z wyspy z pozwoleniem na odejście. Na wyspie flaga wenecka została tylko w Famaguście; ta miała się jeszcze bronić jedenaście miesięcy.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Odbudowa floty po Lepanto", "db51fe44"], "d": ["Pierwszą sprawą Kılıça Alego Paszy, mianowanego po klęsce pod Lepanto kapudanem paszą, była odbudowa floty, która poniosła ciężkie straty; stocznie pracowały bez przerwy przez całą zimę 1571–1572. W czerwcu 1572 na Morze Śródziemne wypłynęła nowa flota złożona z około 250 galer i 300 galer ochotniczych reisów. To szybkie odbudowanie pokazało, że Lepanto nie złamało trwale osmańskiej potęgi morskiej.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Traktat stambulski z Wenecją — uznanie Cypru", "4d08ef50"], "d": ["Wenecja, pozostawiona sama po rozpadzie Świętej Ligi, zawarła z Osmanami odrębny pokój, oficjalnie uznała, że Cypr należy do Osmanów, i zgodziła się płacić odszkodowanie wojenne. Traktat jasno ukazał, że zwycięstwo pod Lepanto nie przyniosło światu chrześcijańskiemu zysku politycznego. Wenecja miała odtąd przez siedemdziesiąt lat unikać wchodzenia w bezpośrednią wojnę z Osmanami.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Śmierć Selima II", "c289f5ee"], "d": ["Selim II po upadku przez około dwa miesiące nie mógł wychodzić na divan i zmarł. Jego śmierć była utrzymywana w pałacu w tajemnicy przez dwanaście dni, aż jego najstarszy syn Murad z Manisy przybył do Stambułu. Co do dnia śmierci źródła się rozchodzą: Selânikî podaje 15 grudnia; Gerlach, Mehmed b. Mehmed i Cenâbî podają 13 grudnia.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Ogłoszenie śmierci Selima II i wstąpienie na tron Murada III", "84334d70"], "d": ["Śmierć Selima II i wstąpienie na tron Murada III, sprowadzonego z Manisy, ogłoszono oficjalnie 22 grudnia 1574. Nowy sułtan miał pozostać na tronie dwadzieścia jeden lat, a jego panowanie pozostało znane z długich wojen z Iranem na wschodzie, wigilii Długiej Wojny na zachodzie i dewaluacji akçe wewnątrz kraju. Do śmierci Sokollu Mehmeda Paszy w 1579 w zarządzie państwa trwał dawny ład.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Bitwa pod Wadi al-Mahazin (Alcazarquivir) — Abd al-Malik, wspierany przez Osmanów, zniszczył armię portugalską", "21280dac"], "d": ["Abd al-Malik, który z osmańskim poparciem zasiadł na tronie Maroka, zniszczył pod Wadi al-Mahazin wielką armię króla Portugalii Sebastiana; ponieważ w bitwie zginęli jednocześnie trzej władcy, w źródłach zachodnich zwana jest „bitwą trzech królów”. Potęga wojskowa Portugalii się załamała, a kraj wkrótce wpadł w ręce Hiszpanii. Abd al-Malik także zginął w bitwie; jego następca brat Ahmad al-Mansur oznajmił zwycięstwo w Stambule przez delegację. Stosunek między oboma państwami pozostał nie na poziomie daniny czy zależności, lecz wymiany posłów i darów, a wkrótce zaostrzył się z powodu sprawy darów.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Złożenie przez mieszkańców Derbentu oświadczenia wierności Lali Mustafie Paszy — Żelazna Brama pod zarządem osmańskim", "9c55aeff"], "d": ["W czasie wyprawy szyrwańskiej siedmioosobowa delegacja mieszkańców Derbentu udała się do serdara Lali Mustafy Paszy w Ereş i złożyła oświadczenie wierności. Derbent (Żelazna Brama), zamykający wąskie przejście między murem kaukaskim a Morzem Kaspijskim, jako obowiązkowe przejście dróg lądowych z północy odegrał kluczową rolę w utrzymaniu Szyrwanu. Panowanie osmańskie trwało tu do 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Zdobycie Szyrwanu: zajęcie Szamachy", "9afae4c1"], "d": ["Armia, która po zwycięstwie pod Çıldır wkroczyła na Kaukaz, weszła do Szyrwanu, najbogatszej prowincji Safawidów nad Morzem Kaspijskim, i zajęła ośrodek miasto Szamachę. Özdemiroğlu Osman Pasza został tu mianowany beylerbejem, a północna odnoga Jedwabnego Szlaku znalazła się pod kontrolą osmańską. Szyrwan miał stać się frontem, który w trwającej dwanaście lat wojnie wschodniej najczęściej zmieniał właściciela i kosztował najdrożej.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Zajęcie Baku — wyjście nad brzeg Morza Kaspijskiego", "eb5adab8"], "d": ["Jako ostatnie ogniwo akcji szyrwańskiej zajęto port Baku na zachodnim brzegu Morza Kaspijskiego. Szyby naftowe wokół miasta były już w tym czasie znanym źródłem dochodów, a port był punktem wywozu jedwabiu irańskiego przychodzącego przez Morze Kaspijskie. Państwo osmańskie po raz pierwszy i jedyny w swej historii zyskało w ten sposób dostęp do Morza Kaspijskiego.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Zdobycie Erywania i budowa twierdzy", "7f623b7b"], "d": ["Ferhad Pasza, który w Karsie otrzymał rozkaz udania się do Erywania i zbudowania tam twierdzy, ruszył na Erywań i miasto zostało objęte kontrolą osmańską na początku ramadanu 991 (w połowie września 1583). W Erywaniu, trzymającym północną bramę doliny Arasu, zbudowano nową, wielką twierdzę, a miasto uczyniono ośrodkiem beylerbeyliku. Erywań, stojący pośrodku drogi armii między Karsem a Tabrizem, był logistycznym kręgosłupem frontu wschodniego. Twierdza została zbudowana tak solidnie, że przez następne dwa stulecia stała się niezmiennym celem wojen osmańsko-irańskich.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Aneksja Karabachu i Gandży", "29abaead"], "d": ["Jako ostatnią zdobycz dziesięcioletniej wojny wschodniej Ferhad Pasza ruszył w 1588 na Gandżę i 1 września wkroczył do miasta; region Karabach między Kurą a Arasem i jego ośrodek Gandża zostały objęte zarządem osmańskim. W ten sposób Szyrwan, Erywań i Karabach zjednoczyły się, tworząc na Kaukazie nieprzerwaną linię osmańską. Traktat Ferhada Paszy z 1590 miał potwierdzić tę granicę, lecz zdobyczy udało się utrzymać tylko dwadzieścia lat.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Zdobycie Bihaća", "651a7275"], "d": ["Beylerbej Bośni Telli Hasan Pasza, który w listopadzie 1591 zajął Ripač, przedpole Bihaća, w 1592 zajął także samo miasto i twierdzę; po dziesięciodniowym oblężeniu dowódca Lamberg się poddał. To zdobycie przesunęło granicę Bośni wzdłuż rzeki Una i było ostatnią wielką zdobyczą osmańską w przededniu Długiej Wojny, która wybuchła rok później, gdy Telli Hasan Pasza poległ jako męczennik pod Kulpą.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Początek osmańsko-austriackiej „Długiej Wojny”", "bd22c392"], "d": ["Gdy beylerbej Bośni Telli Hasan Pasza został rozbity i poległ jako męczennik pod Kulpą (Sisak), państwo osmańskie wypowiedziało Austrii wojnę i rozpoczęła się Długa Wojna, która miała trwać trzynaście lat. Ta wojna, w której decydująca była piechota uzbrojona w broń palną, przyspieszyła zatrudnianie sekbanów i żołnierzy z muszkietami w ładzie wojskowym osmańskim i pogłębiła upadek sipahich timarowych. Wojna miała zakończyć się w 1606 traktatem w Zsitvatorok.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koca Sinan Pasza wyruszył na wyprawę austriacką — pierwsza wyprawa Długiej Wojny", "d4a2f46d"], "d": ["Po tym, jak beylerbej Bośni Hasan Pasza został rozbity i poległ jako męczennik pod Siskiem (Sisak), wielki wezyr Koca Sinan Pasza, błyskotliwymi słowami i obietnicami przekonał sułtana do wojny i wyruszył z 12 000 janczarów i innymi oddziałami. W ten sposób otwarto pierwszą wyprawę wojny osmańsko-austriackiej, która miała trwać trzynaście lat.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Zdobycie Győr (Yanıkkale)", "14b75207"], "d": ["Wielki wezyr Koca Sinan Pasza po ponadmiesięcznym oblężeniu przyjął poddanie Győr, uchodzącego za klucz drogi do Wiednia. Upadek twierdzy wywołał w Europie wielką panikę i był najświetniejszą zdobyczą Osmanów w Długiej Wojnie. Twierdzę udało się jednak utrzymać tylko cztery lata.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Śmierć Murada III", "1b62e886"], "d": ["Po dwudziestojednoletnim panowaniu Murad III zmarł w dniach, gdy armia wołoska paliła Braiłę i dotarła pod Silistrę, i został pochowany w mauzoleum przy Hagia Sophia. Jego syn Mehmed III, wezwany z Manisy, dotarł dziesięć dni później do Stambułu i wstąpił na tron (27 stycznia 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Utrata Ostrzyhomia na rzecz Austrii", "f420d333"], "d": ["Obrońcy Ostrzyhomia, nie otrzymawszy dostatecznej pomocy w oblężeniu prowadzonym przez Karla von Mansfelda, oddali twierdzę arcyksięciu Maciejowi. Wraz z końcem pięćdziesięciodwuletniego panowania osmańskiego łańcuch obrony na linii Dunaju został przerwany, a Buda znalazła się pod bezpośrednim zagrożeniem. Twierdzę udało się odzyskać dopiero po dziesięciu latach, w 1605.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Zdobycie twierdzy Eger (Eğri)", "3e511629"], "d": ["Po trzytygodniowej walce potężna twierdza Eger, której Osmanowie wcześniej nigdy nie zdołali zdobyć, padła wraz z poddaniem się obrońców. To zdobycie, przy którym osobiście był obecny sułtan, w pewnej mierze naprawiło morale zachwiane utratą Ostrzyhomia i utworzono ejalet Eger. Wraz ze zwycięstwem pod Mezőkeresztes, odniesionym dwa tygodnie później, rok 1596 stał się najpomyślniejszym rokiem osmańskim w Długiej Wojnie.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Utrata Győr (Yanıkkale)", "b4ccc679"], "d": ["Oddziały pod dowództwem Miklósa Pálffyego i Adolfa von Schwarzenberga wysadziły petardą bramy twierdzy i odzyskały Győr. Utrata twierdzy, którą cztery lata wcześniej Koca Sinan Pasza zdobył wielkim wysiłkiem, załamała wysuniętą linię osmańską na Węgrzech. Choć w tym samym roku odparto siły wroga oblegające Budę, równowaga wojny coraz bardziej zamieniała się w wojnę na wyczerpanie.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Powstanie Karayazıcı Abdülhalima", "30493b0d"], "d": ["Karayazıcı Abdülhalim, który zebrał sekbanów i levendów uciekających z armii w Długiej Wojnie, objął kontrolą rozległy region w Anatolii Środkowej, zajął twierdzę Urfa (listopad 1599) i ogłosiwszy swoje panowanie z tytułem „Halim Szach”, wysyłał fermany noszące własną tugrę. Karayazıcı, uchodzący za pierwszego przywódcę wielkiej fali celâlich, zmarł w 1602, a jego ruch kontynuował brat Deli Hasan. Powstanie jest początkiem okresu „wielkiej ucieczki”, w którym chłopi anatolijscy masowo opuszczali swoją ziemię.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Obrona Nagykanizsy przez Tiryakiego Hasana Paszę", "d56a5e6a"], "d": ["Arcyksiążę Ferdynand i jego sprzymierzeńcy, chcący odzyskać Kanizsę zdobytą rok wcześniej, oblegali twierdzę ponad dwa miesiące; Tiryaki Hasan Pasza bronił się z 9000 ludzi. Choć nie otrzymał pomocy z zewnątrz, odparł generalne szturmy, a wypadami zmusił wroga do wycofania się z ciężkimi stratami. Obrona obrosła w historiografii osmańskiej legendą, a „Oblężenie Kanizsy” stało się samodzielnym gatunkiem literackim.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Śmierć Mehmeda III i wstąpienie na tron Ahmeda I", "da735fde"], "d": ["Po śmierci Mehmeda III 20 grudnia na tron wstąpił jego czternastoletni syn Ahmed I. To, że jest pierwszym sułtanem, który zasiadł na tronie w dzieciństwie i bez wyjścia do sandżaku, pokazuje, że zwyczaj kształcenia książąt w prowincji faktycznie się skończył. Za panowania Ahmeda I miano porzucić bratobójstwo i przejść do zasady „ekberiyet” (przejęcia tronu przez najstarszego mężczyznę dynastii).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Odzyskanie Ostrzyhomia", "7330f273"], "d": ["Wielki wezyr Lala Mehmed Pasza oblegał Ostrzyhom, utracony dziesięć lat wcześniej, i ponownie przyłączył go do zarządu osmańskiego. W tej samej wyprawie wyzwolono także Peszt i Vác, a Osmanowie uporządkowali swą linię na Węgrzech. Ten sukces zapewnił w następnym roku względnie silną pozycję przy stole w Zsitvatorok; Ostrzyhom miał pozostać w rękach osmańskich do 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Zwycięstwo na Równinie Oruç i stłumienie powstania Canbolatoğlu", "30f93532"], "d": ["Canbolatoğlu Ali Pasza, który założył w Aleppo niezależny bejlik i szukał sojuszu z Toskanią, został ciężko rozbity na Równinie Oruç przez wielkiego wezyra Kuyucu Murada Paszę. Wraz z ponownym ustanowieniem władzy centralnej w Syrii najniebezpieczniejsze ramię fali celâlich zostało złamane. Trwająca dwa lata bezlitosna likwidacja prowadzona przez Kuyucu Murada Paszę zapewniła w Anatolii spokój, choćby tymczasowy.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Zwycięstwo pod Alaçayır i stłumienie powstania Kalenderoğlu", "55db0485"], "d": ["Kalenderoğlu, przywódca celâlich, który nakładał daninę na regiony Manisy i Bursy, został rozbity pod Alaçayır przez Kuyucu Murada Paszę i musiał uciec do Iranu. Dzięki temu zwycięstwu rozproszono ostatnią z wielkich armii celâlich w Anatolii. Surowa likwidacja Kuyucu Murada Paszy, o której przekaz mówi, że wrzucał zabitych buntowników do wykopanych przez nich studni, choć zapewniła w krótkiej perspektywie porządek, nie mogła zrekompensować Anatolii strat ludności i produkcji.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Nadanie pierwszego ahidname Holandii", "5d9d117e"], "d": ["Poseł Zjednoczonej Republiki Niderlandów Cornelis Haga zdołał uzyskać od Ahmeda I ahidname w tym samym zakresie, co nadane Francji i Anglii. Holandia zyskała w ten sposób prawo do otwarcia poselstwa w Stambule, konsulatów w portach osmańskich i prowadzenia handlu pod własną banderą. To ahidname symbolizuje wejście na rynek osmański północnych potęg morskich, które zajęły miejsce Wenecji w handlu śródziemnomorskim.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Śmierć Ahmeda I i wstąpienie na tron Mustafy I — zasada ekberiyet", "9901c09e"], "d": ["Po pięćdziesięciojednodniowej chorobie żołądka zmarł dwudziestoośmioletni Ahmed I, a na tron zamiast jego syna wprowadzono brata Mustafę I. W ten sposób faktycznie porzucono ład sukcesji z ojca na syna i przejście do systemu „ekberiyet”, w którym na tron wstępuje najstarszy mężczyzna dynastii. To pierwsze, trwające dziewięćdziesiąt sześć dni panowanie jest też początkiem epoki wychowywania książąt w „klatce” (kafes).", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Detronizacja Mustafy I i wstąpienie na tron Młodego Osmana (Osmana II)", "e0f552f2"], "d": ["Mustafę I zdetronizowano po dziewięćdziesięciu sześciu dniach pod pretekstem, że jego zdrowie psychiczne nie jest w porządku, a sułtanem został czternastoletni syn Ahmeda I, Osman II. Według przekazu opartego na Hasanbeyzâde w decyzji o detronizacji wpływ miał kyzlar aga Mustafa Aga. Młody Osman, z projektem zniesienia korpusu janczarów i utworzenia nowej armii, uchodzi za pierwszą radykalną postać osmańskich dyskusji reformatorskich. Ten projekt miał po czterech latach kosztować go życie.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Traktat z Serav — odnowienie pokoju z Iranem", "e778aca8"], "d": ["Traktat z Serav, zawarty z Iranem po klęsce pod Pül-i Şikeste, w znacznej mierze potwierdził warunki traktatu Nasuha Paszy z 1612; roczną ilość jedwabiu wysyłaną przez Safawidów obniżono z dwustu ładunków do stu. W ten sposób zamknięto drugą fazę wojen wschodnich trwających od 1603. Pokój nie miał być długotrwały, a wojna miała znów rozgorzeć wraz z utratą Bagdadu w 1623.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Wyprawa pod Chocim i traktat chocimski", "bc4c823c"], "d": ["Wielkiej armii pod osobistym dowództwem Osmana II nie udało się przełamać umocnionego obozu, który przed Chocimiem założył Chodkiewicz, i po miesiącach szturmów nie osiągnięto wyniku. Na mocy traktatu podpisanego 9 października za granicę uznano Dniestr, a Polacy zobowiązali się powstrzymywać napady kozackie. Wyprawa, która mimo przedstawiania jej jako zwycięstwa nie dała wyniku, umocniła brak zaufania młodego sułtana do janczarów i jego zamiar likwidacji korpusu.", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["Odebranie Ormuzu Portugalczykom", "93e5f6cf"], "d": ["Siły safawidzkie oblegały i odzyskały Ormuz, od 1515 pozostający w rękach portugalskich; Kiszm i leżący na wybrzeżu Gamrun (Bandar Abbas) przeszły także pod zarząd safawidzki, a handel w Zatoce przeniósł się do nowego portu.", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Druga detronizacja Mustafy I i wstąpienie na tron Murada IV", "1b3a9e74"], "d": ["Mustafę I, który po zabiciu Osmana II został po raz drugi posadzony na tronie, po roku i trzech miesiącach ponownie zdetronizowano, a sułtanem ogłoszono jedenastoletniego Murada IV. Przez pierwsze dziewięć lat państwem faktycznie rządziła jego matka Kösem Sułtan i notable pałacowi. Murad IV miał od 1632 objąć zarząd osobiście i rozpocząć okres surowej centralizacji.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Utrata Bagdadu na rzecz Safawidów", "db81be0c"], "d": ["Po targach, które Bekir Subaşı, który zbuntował się w Bagdadzie, prowadził z Safawidami, jego syn Derviş Mehmed, broniący wewnętrznej twierdzy, oddał miasto siłom szacha Abbasa. Utrata jednego z symbolicznych miast spuścizny kalifatu i większej części Iraku wywołała w Stambule wielkie oburzenie. Odzyskanie Bagdadu miało przez piętnaście lat być jedynym celem osmańskiej polityki wschodniej.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Stłumienie powstania Abazy Mehmeda Paszy z ośrodkiem w Erzurum", "e6da2729"], "d": ["Beylerbej Erzurumu Abaza Mehmed Pasza, który pod pretekstem pomszczenia zabicia Osmana II zbuntował się przeciw janczarom, przez lata trzymał Anatolię Wschodnią pod swą kontrolą i stawiał opór centrum. Zmuszony do poddania się wskutek oblężenia Erzurumu przez wielkiego wezyra Hüsreva Paszę, został ułaskawiony i mianowany do Bośni. Koniec powstania był warunkiem wstępnym wyruszenia Murada IV na wyprawę na Iran.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Pierwsze stracenie szejhülislama: Ahîzâde Hüseyin Efendi", "a60a58c5"], "d": ["Szejhülislam Ahîzâde Hüseyin Efendi został stracony w okolicach Büyükçekmece pod pretekstem, że pośredniczył w zamęcie wojskowym i wysłał sułtanowi pisemne ostrzeżenie dotyczące procedury sądowej. To, że był pierwszym straconym szejhülislamem osmańskim, złamało zakorzenioną tradycję, według której najcięższą karą dla przedstawicieli ilmiye było zesłanie. Wydarzenie uchodzi za symbol zaostrzającej się władzy Murada IV i zachwiania równowagi państwo–ulemowie.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Zdobycie Erywania przez Murada IV", "b65a9b73"], "d": ["Murad IV, który wyruszył ze Stambułu 28 marca 1635, oblegał Erywań 28–29 lipca i 8 sierpnia przyjął poddanie twierdzy; następnie wkroczył do opuszczonego Tabrizu i kazał miasto zniszczyć. Sułtan na pamiątkę zwycięstwa kazał zbudować w Pałacu Topkapı Pawilon Erywański. Ta wyprawa była pierwszą wielką akcją wschodnią po trzydziestu latach przerwy, w której sułtan osobiście dowodził armią.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Utrata Erywania na rzecz Safawidów", "fbb8dd25"], "d": ["Po wycofaniu się armii osmańskiej siły szacha Safiego oblegały Erywań i odzyskały go w ciągu ośmiu miesięcy. To, że twierdza została utracona tak szybko, pokazało, jak trudne logistycznie jest trwałe panowanie na Kaukazie. Erywań miał też zostać pozostawiony Iranowi na mocy traktatu w Kasr-ı Şirin z 1639, a Osmanowie mieli zrezygnować z pretensji do Azerbejdżanu.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Ponowne zdobycie Bagdadu", "4d2f27f3"], "d": ["Murad IV, który wyruszył ze Stambułu 8 maja 1638, po czterdziestodniowym zaciętym oblężeniu odzyskał Bagdad, od piętnastu lat pozostający w rękach safawidzkich; podczas oblężenia wezyr Tayyar Mehmed Pasza poległ jako męczennik. Wraz ze zdobyciem miasta zarząd osmański w Iraku został odtworzony, a sułtan przyjął tytuł „Zdobywcy Bagdadu”. Zdobycie zostało utrwalone traktatem w Kasr-ı Şirin w następnym roku i położyło podwaliny pod dzisiejszą granicę turecko-irańską.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Śmierć Murada IV i wstąpienie na tron sułtana Ibrahima", "e2ca1ca0"], "d": ["Po śmierci Murada IV w wieku dwudziestu siedmiu lat (według rachuby hidżry dwudziestu ośmiu) na tron wstąpił jego brat Ibrahim, jedyny żyjący mężczyzna dynastii. Za panowania nowego sułtana, który przez lata żył w klatce, wydatki pałacowe i walki o wpływy wewnątrz pałacu wstrząsnęły ładem państwa. Po ośmiu latach, wskutek jego detronizacji i zabicia, miało miejsce drugie w dziejach osmańskich zabicie sułtana.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Odzyskanie twierdzy Azow od Kozaków", "e5fcf160"], "d": ["Twierdza Azow, którą Kozacy dońscy zajęli w 1637, została opuszczona wobec wspólnej akcji Sultanzâde Mehmeda Paszy i chana krymskiego Mehmeda IV Gireja; Kozacy, podpaliwszy twierdzę, się wycofali. Odzyskanie północnej bramy Morza Czarnego zamknęło niebezpieczny okres, w którym napady kozackie sięgały aż do Bosforu. Twierdza miała w 1696 zostać utracona, tym razem na rzecz cara Rosji Piotra I.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Początek wyprawy kreteńskiej i zdobycie Chanii", "a1b0c77f"], "d": ["Pod pretekstem, że korsarze maltańscy zaatakowali osmański statek pielgrzymi i schronili się na Krecie, wypowiedziano wojnę Wenecji, a flota pod dowództwem Yûsufa Paszy wysadziła na wyspie żołnierzy. Po pięćdziesięciu czterech dniach oblężenia zdobyto twierdzę Chania i na Krecie powstała pierwsza trwała baza osmańska. W ten sposób rozpoczęła się najdłużej trwająca wojna w dziejach osmańskich; wyspę udało się całkowicie zdobyć dopiero po dwudziestu czterech latach, w 1669.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Zdobycie Rethymno — podział Krety na dwie części", "8f2c4353"], "d": ["Rok po zdobyciu Chanii padła także twierdza Rethymno w środkowej części wyspy i zachodnia połowa Krety całkowicie weszła pod zarząd osmański. W rękach Wenecji pozostała tylko stolica Kandia i wschodni kraniec; wyspa żyła podzielona na dwie części przez dwadzieścia trzy lata. Zdobycie Rethymno było krokiem rozpoczynającym oblężenie Kandii — tu zaczęło się najdłuższe oblężenie w historii.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Utrata Klisu na rzecz Wenecji", "5473c22c"], "d": ["Na froncie dalmatyńskim wojny kreteńskiej (o Kandię) kontruderzenie weneckiego dowódcy Leonarda Foscolo objęło także Klis, ośrodek sandżaku od 1537; twierdza przeszła do Wenecji. To, że Osmanowie skupili całą siłę na Krecie, uniemożliwiło odzyskanie tej straty na granicy dalmatyńskiej — Klis nie miał już wrócić pod zarząd osmański; ośrodek sandżaku przeniesiono do Livna.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Początek oblężenia Kandii", "13016b10"], "d": ["Po zajęciu Chanii i Rethymno armia osmańska otoczyła Kandię, ostatnią wielką ostoję Wenecji na wyspie. Ta blokada, która miała trwać dwadzieścia jeden lat, weszła do historii jako jedno z najdłuższych oblężeń w dziejach wojskowości świata. Podczas oblężenia próby zamknięcia Dardaneli przez flotę wenecką miały przenieść wojnę w samo serce Morza Egejskiego.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Zabicie wielkiej matki sułtańskiej Kösem Sułtan", "9d763f79"], "d": ["Kösem Sułtan, mająca około sześćdziesięciu dwóch lat, została znaleziona i zabita w jednej z komnat Haremu przez Başlalę Uzuna Süleymana Agę i jego ludzi, działających z rozkazu Turhan Sułtan, matki Mehmeda IV. Śmierć tej potężnej kobiety dynastii, która kierowała polityką państwa za trzech sułtanów, uważa się za faktyczny koniec okresu zwanego „Sułtanatem Kobiet”. Opróżniona władza otworzyła drogę do objęcia po pięciu latach wezyratu przez Köprülü Mehmeda Paszę z nadzwyczajnymi uprawnieniami.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Klęska pod Çanakkale i utrata Bozcaady oraz Limnos", "e01a1f7e"], "d": ["Wielkie zwycięstwo morskie weneckiego admirała Mocenigo, odniesione w czerwcu 1656 przed Dardanelami, niemal całkowicie zniszczyło flotę osmańską; następnie zajęto Bozcaadę, Limnos i Samotrakę. Gdy cieśnina znalazła się w blokadzie weneckiej, w Stambule poszybowały ceny żywności i rozeszła się obawa przed atakiem na stolicę. Ta katastrofa była bezpośrednią przyczyną powołania we wrześniu 1656 Köprülü Mehmeda Paszy na wielkiego wezyra na warunkach i z nadzwyczajnymi uprawnieniami.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Zwycięstwo pod Çanakkale i odzyskanie Bozcaady", "603da863"], "d": ["Flota zmobilizowana przez Köprülü Mehmeda Paszę rozbiła 19 lipca 1657 przed cieśniną flotę wenecką; następnie siły pod dowództwem Kurda Paszy odzyskały 25 sierpnia Bozcaadę, a 30 sierpnia Wenecjanie całkowicie opuścili wyspę. W listopadzie wyzwolono także Limnos, przerwano blokadę Dardaneli i ponownie otwarto drogę zaopatrzenia Stambułu. Köprülü sam udał się na wyspę i kazał naprawić umocnienia; ten sukces jest pierwszym wielkim wojskowym zyskiem epoki Köprülü.", "af4d7bfd"]},
"OLAYLAR_EK5:1657-11-15:0":{"b": ["Odzyskanie Limnos od Wenecji", "a4c3c69b"], "d": ["Limnos, zajęte przez Wenecję w lipcu 1656, wróciło do Osmanów w listopadzie 1657.", "1d61fe33"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Zdobycie Yanova (Ineu) i wyprawa na Siedmiogród", "d1089616"], "d": ["Köprülü Mehmed Pasza, który wyruszył na wyprawę, by ukarać księcia Siedmiogrodu Jerzego II Rákócziego, który bez zezwolenia wyruszył na wyprawę polską i złamał protekcję osmańską, maszerując przez Belgrad zajął strategiczną twierdzę Yanova. Na Siedmiogród mianowano nowego księcia i surowo przypomniano o więzi wasalnej. Wyprawa ta była pierwszym ogniwem osmańskiej próby odtworzenia władzy w Europie Środkowej. Siedmiogród był już księstwem zależnym od Osmanów; zajęcie Yanova nie było zdobyciem od obcego państwa, lecz wyjęciem tej twierdzy z zarządu księstwa i podporządkowaniem jej bezpośrednio sandżakowi osmańskiemu; reszta księstwa pozostała w statusie zależnym.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Stłumienie powstania Abazy Hasana Paszy", "4ba74321"], "d": ["Abaza Hasan Pasza, który wobec surowych czystek Köprülü Mehmeda Paszy zyskał poparcie beylerbejów Anatolii i agów sekbanów, rozpoczął wielkie powstanie, żądając odwołania wielkiego wezyra. Powstanie stłumiono w Aleppo, a przywódców usunięto; było to ostatnie zbiorowe wystąpienie paszów prowincjonalnych przeciw centrum. Władza Köprülü stała się w ten sposób niekwestionowana, a urząd wielkiego wezyra znów wzniósł się do pozycji prawdziwego ośrodka wykonawczego państwa.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Zdobycie Váradu (Oradea)", "0e6ad300"], "d": ["W ramach wyprawy skierowanej przeciw księciu Siedmiogrodu Jerzemu II Rákóczemu, który wypowiedział wojnę Osmanom, zdobyto twierdzę i miasto Várad. Wraz z upadkiem jednej z kluczowych twierdz Siedmiogrodu utworzono w regionie nowy ejalet osmański (Ejalet Várad). Zdobycie zaalarmowało Habsburgów i stało się jedną z bezpośrednich przyczyn wojny osmańsko-austriackiej, która miała rozpocząć się po trzech latach. W tym samym dniu przyłączono także inne miejscowości: Varat. Również tu ziemi nie zabrano obcemu państwu: Siedmiogród był już zależnym księstwem osmańskim; ustanowienie ejaletu Várad jedynie wyjęło zarząd tego miasta spod zależnego księstwa i związało go bezpośrednio z sułtanem, tak jak dwa lata wcześniej w Yanova.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Bitwa pod Św. Gotardem (St. Gotthard)", "61ebc1f2"], "d": ["Siły osmańskie, które przekroczyły rzekę Raab, zostały zatrzymane przez sprzymierzoną armię europejską pod dowództwem Montecuccoliego i poniosły ciężkie straty. Bitwa uchodzi za punkt zwrotny w historii wojskowości, gdyż po raz pierwszy jawnie ukazała przewagę zdyscyplinowanego ognia piechoty uzbrojonej w muszkiety nad szarżą kawalerii osmańskiej. Mimo klęski Osmanom udało się uzyskać korzystne warunki w traktacie z Vasvár podpisanym dziewięć dni później.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Traktat w Vasvár", "089c978c"], "d": ["Traktat podpisany mimo klęski pod Św. Gotardem postanowił, że Uyvar i Várad pozostaną przy Osmanach, że Siedmiogród zostanie pozostawiony jako neutralny pod protekcją osmańską, a Austria zapłaci 200 000 kuruszy „daru”. Ten dwudziestoletni pokój jest jednym z rzadkich przykładów, gdy strona, która przegrała wojnę, zyskała przy stole. Niezadowolenie, jakie traktat wywołał w opinii habsburskiej, miało podsycić ruch Węgier Środkowych i pośrednio wyprawę wiedeńską 1683.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Początek rządów dejów w Algierze", "e99faa51"], "d": ["Odżak algierski i taife-i reîs (kapitanowie korsarzy) obalili ostatniego agę i wybrali Hacı Mehmeda dejem dożywotnio. Od tego czasu Algierem rządził nie beylerbej mianowany przez Stambuł, lecz dej wybierany przez miejscowy odżak ze swego grona; więź osmańska ograniczyła się do odczytywania imienia sułtana w chutbie, sandżaka i obowiązku wypraw. Algier przekształcił się w ten sposób z ejaletu w odżaklık — tę samą przemianę przeszły Tunis w 1705 pod Husajnidami i Trypolitania w 1711 pod Karamanlidami.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Początek wyprawy polskiej — Mehmed IV i Fâzıl Ahmed Pasza na czele armii", "75e15a39"], "d": ["Gdy trwały ataki Polski na hetmana Ukrainy Petra Doroszenkę, który przeszedł pod protekcję osmańską, Stambuł zażądał od króla polskiego zaprzestania napadów; gdy nie nadeszła odpowiedź pozytywna, postanowiono wyprawić się na Polskę. Wielki wezyr Fâzıl Ahmed Pasza wyruszył 4 czerwca 1672 do Polski z armią, w której był także sułtan. Wyprawa miała zakończyć się zdobyciem Kamieńca i traktatem w Buczaczu.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Zdobycie Kamieńca i utworzenie Ejaletu Podola", "c3f4f6d0"], "d": ["Po dziewięciodniowym oblężeniu Kamieniec, uchodzący za najpotężniejszą twierdzę Polski na wschodzie, został przyjęty w poddanie; Mehmed IV odprawił 2 września pierwszą piątkową modlitwę w meczecie przerobionym z katedry. Z twierdzy uczyniono ośrodek i utworzono Ejalet Podola, a sztandar osmański dotarł najdalej na północ na ziemiach dzisiejszej Ukrainy. Kamieniec miał pozostać północno-zachodnim krańcem imperium aż do traktatu w Karłowicach z 1699.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Pasza przejął Umań od Polski", "0d3543a0"], "d": ["Kara Mustafa Pasza, wysłany przeciw Polsce, przyjął od Polski Umań, jedną z jej twierdz; miasto pozostało pod zarządem osmańskim aż do Karłowic.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Zdobycie twierdzy Czehryn", "a17cedd0"], "d": ["Po akcji sprzed roku, która nie dała wyniku, wielki wezyr Merzifonlu Kara Mustafa Pasza, dowodząc osobiście, oblegał umocnioną twierdzę Czehryn (19/21 lipca) i zajął ją 21 sierpnia. Upadek twierdzy, symbolu rywalizacji osmańsko-rosyjskiej o hetmanat kozacki na Ukrainie, zmusił Rosję do pokoju. Ten sukces był jednym ze źródeł pewności siebie Merzifonlu przed zwróceniem się ku Wiedniowi.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Traktat w Bachczysaraju — pierwszy oficjalny pokój z Rosją", "df82bc0b"], "d": ["Po rokowaniach prowadzonych za pośrednictwem chana krymskiego po wyprawach czehryńskich podpisano między państwem osmańskim a Rosją dwudziestoletni pokój, uznając rzekę Özü (Dniepr) za granicę. Jako pierwszy obszerny traktat między tymi dwoma państwami uchodzi za dokument początkowy stosunków osmańsko-rosyjskich. Dzięki pokojowi front wschodni został zabezpieczony i armię można było skierować do Europy Środkowej.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Nadanie Imre Thökölyemu beratu na królestwo Węgier Środkowych", "3cd8d51d"], "d": ["Protestancki szlachcic węgierski Imre Thököly, który powstał przeciw naciskowi Habsburgów, od kwietnia 1682 zaczął być uważany za „wybranego króla Węgier Środkowych”, a 16 września beylerbej Budy İbrahim Pasza wręczył mu oznaki książęce. W ten sposób powstało pod protekcją osmańską nowe państwo wasalne węgierskie. Ta interwencja, czyniąc wojnę z Austrią nieuniknioną, rozpoczęła łańcuch prowadzący do II oblężenia Wiednia w następnym roku.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Utrata Aya Mavry (Lefkada) na rzecz Wenecji", "e6905fee"], "d": ["Flota Wenecji, która przystąpiła do Świętej Ligi, po ostrzelaniu miasta zajęła wyspę Aya Mavra na Morzu Jońskim. W tym samym roku, wraz z upadkiem Prewezy, osmańska kontrola nad wejściem na Adriatyk została złamana. Te straty były początkowymi krokami akcji, w której Morosini miał w trzy lata zająć całą Moreę.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Utrata Koronu na rzecz Wenecji", "2ed762bc"], "d": ["Siły weneckie pod dowództwem Morosiniego zajęły twierdzę Koron na południowo-zachodnim krańcu półwyspu Morea; miasto miało odtąd przez trzydzieści lat pozostawać pod zarządem weneckim. Upadek Koronu był pierwszym wielkim zyskiem akcji weneckiej mającej na celu zdobycie Morei. Twierdzę udało się odzyskać dopiero w 1715 armii osmańskiej pod dowództwem Silâhdara Alego Paszy.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Odzyskanie Aten — wycofanie się Wenecji", "03393b46"], "d": ["Morosini, który we wrześniu 1687 zbombardował Akropol i wysadził Partenon, po spędzeniu zimy w Atenach zrozumiał, że nie utrzyma się w mieście. Wobec epidemii dżumy, trudności z zaopatrzeniem i odbudowy sił osmańskich garnizon wenecki opuścił miasto i wycofał się do Morei. Ateny wróciły więc bez walki pod zarząd osmański, lecz zniszczenia Partenonu nie dało się cofnąć.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Lipova (Lippa) poddała się Caraffie — przeszła w ręce Austrii", "7f0a8d38"], "d": ["Po trzydniowym oblężeniu Antonia Caraffy Lipova poddała się między 12 a 22 czerwca 1688 i przeszła w ręce Austrii. Osmanowie później odzyskali miasto, Austria zajęła je ponownie w 1691; w wyprawie z 1695 Osmanowie znów odzyskali kontrolę. W tym samym dniu atlas zapisuje przejście od Osmanów do Habsburgów innych miejscowości: Arad i Világos (Șiria). Dla Aradu źródło podaje tylko rok (MKL, Arad: w rękach osmańskich w latach 1551–1688); dzień wzięto z Lipovy, Világos podąża za łańcuchem Aradu (przybliżenie z deklaracją).", "0dfcf5af"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Odparcie weneckiego oblężenia Negroponte (Eğriboz)", "aae7e6a0"], "d": ["Morosini, który po zajęciu Morei zwrócił się ku Morzu Egejskiemu, próbował zdobyć Negroponte w trwającym ponad trzy miesiące oblężeniu; jednak wobec umocnień wzmocnionych zimą 1687–1688 i oporu garnizonu musiał wycofać się z ciężkimi stratami. Ta porażka zatrzymała natarcie Wenecji na Morzu Egejskim i nadwątliła wojskowy prestiż Morosiniego. Negroponte miało też w Karłowicach pozostać w rękach osmańskich.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Utrata twierdzy Kanizsa na rzecz Austrii", "553b45f3"], "d": ["Kanizsa, objęta od stycznia 1690 ścisłą blokadą 60-tysięcznej armii habsburskiej, po miesiącach oporu bez pomocy została utracona na mocy umowy o poddaniu podpisanej przez ostatniego komendanta Mustafę Paszę. W ten sposób w twierdzy znanej z legendarnej obrony Tiryakiego Hasana Paszy dobiegło końca dziewięćdziesięcioletnie panowanie osmańskie. Utrata Kanizsy była załamaniem ostatniej wielkiej ostoi Osmanów w zachodniej części Węgier.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["Śmierć Sulejmana II", "d2478080"], "d": ["Sulejman II, który po około czterdziestu latach w klatce został w 1687 wprowadzony na tron, zmarł w Edirne w piątek 22 czerwca 1691 około południa, gdy chory śledził przygotowania armii; jego panowanie trwało trzy lata, osiem miesięcy i dwa dni. Wielki wezyr dał wcześniej niezbędne polecenie, by na wypadek śmierci sułtana na tron wprowadzono jego brata Ahmeda. Modlitwę pogrzebową odprawiono tego samego dnia w Alay Köşkü; jego ciało przewieziono do Stambułu i pochowano w mauzoleum Sulejmana Prawodawcy po jego prawej stronie.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Wstąpienie Ahmeda II na tron", "52947b14"], "d": ["Po śmierci Sulejmana II czterdziestodziewięcioletni brat Ahmed II wstąpił na tron w Edirne. Jego panowanie przypadło na najcięższe lata wojen Świętej Ligi; dwa miesiące po wstąpieniu na tron pod Slankamenem poległ jako męczennik wielki wezyr Fâzıl Mustafa Pasza. Z kolei system mâlikâne wprowadzony w jego epoce stał się jednym z najważniejszych uregulowań zmieniających długoterminową strukturę osmańskich finansów.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["Śmierć Mehmeda IV w Edirne", "17388b7e"], "d": ["Mehmed Łowca, zdetronizowany w 1687, został w czasie węgierskiej wyprawy Sulejmana II z 1689 sprowadzony do Edirne i był też świadkiem panowania innego brata, Ahmeda II. Zmarł w tym ukochanym przez siebie mieście. Jego ciało przewieziono do Stambułu i pochowano w mauzoleum matki Turhan Sułtan przy Yenicami.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["Śmierć Ahmeda II w Edirne", "c6306c08"], "d": ["Ahmed II, którego czteroletnie panowanie upłynęło w wojnie, zmarł w Edirne w wieku pięćdziesięciu dwóch lat z powodu istiskā (obrzęku). Jego ciało przewieziono do Stambułu i pochowano w mauzoleum Sulejmana Prawodawcy. Na jego miejsce wstąpił jego bratanek Mustafa II.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Zajęcie Basry przez Persów", "a9cdf3a3"], "d": ["Gdy państwo osmańskie zajmowało się na zachodzie wojnami Świętej Ligi, Basra po epidemii dżumy z 1690 została złupiona najpierw przez szejcha Muntafiqów Mâni'a, a następnie przez chana Huwayzy Ferecullaha. Wykorzystując ten zamęt, Persowie zajęli miasto w 1696 i zostawili w Basrze załogę.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Traktat stambulski — oddanie Azowa Rosji", "79db4724"], "d": ["W Karłowicach z Rosją udało się zawrzeć tylko dwuletni rozejm; trwały pokój podpisano w Stambule po trudnych targach trwających półtora roku. Państwo osmańskie zrzekło się oficjalnie utraconej w 1696 twierdzy Azow i otaczających ją ziem na rzecz Rosji i zrezygnowało z rocznego podatku, który chan krymski pobierał od Moskwy. W zamian Rosja zyskała prawo utrzymywania w Stambule stałego posła; w ten sposób obecność rosyjska na północnym wybrzeżu Morza Czarnego została prawnie utrwalona.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Odzyskanie Kurny i Basry przez Daltabana Mustafę Paszę", "7adb777d"], "d": ["Daltaban Mustafa Pasza, mianowany po traktacie karłowickim namiestnikiem Bagdadu i seraskierem Basry, ruszył na południe z siłami z Aleppo, Rakki, Sivas i Karamanu oraz flotą rzeczną płynącą z Birecik. Okoliczni szejchowie plemion jeden po drugim okazali posłuszeństwo, perski komendant Basry Dâvud Chan opuścił miasto, a Kurna i Basra weszły ponownie pod zarząd osmański.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Śmierć Mustafy II", "626c394d"], "d": ["Mustafa II, który po wydarzeniu edyrneńskim zostawił tron bratu Ahmedowi III, zmarł około pięciu miesięcy po detronizacji w ukochanym Edirne. Do jego choroby dołączył także smutek wywołany ostatnimi wydarzeniami. Niektóre źródła zachodnie piszą, że wśród ludu rozpowszechnione było przekonanie, że został otruty.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Początek rządów mameluków (Kölemen) w Bagdadzie", "abe52618"], "d": ["Wraz z mianowaniem na namiestnika Bagdadu Hasana Paszy pochodzenia gruzińskiego rozpoczął się okres, w którym w Iraku zamiast namiestników mianowanych przez centrum zapanowała warstwa rządząca wywodząca się z ich własnych niewolników. Dzięki namiestnictwu Süleymana Paszy w 1749 system się utrwalił, a Bâbıâli musiało już mianować nie kogo chciało, lecz jednego z kölemenów, którzy przejęli wpływy. Ta półautonomiczna struktura, choć sprawdzała się w obronie granicy irańskiej, osłabiła kontrolę władzy centralnej nad Irakiem na półtora wieku.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Założenie dynastii Husajnidów w Tunisie", "cb1a98f9"], "d": ["W próżni władzy powstałej po inwazji sił algierskich na Tunis agę sipahich pochodzenia tureckiego Husajna b. Alego przejął bejlik i zyskał legitymację, oznajmiając wierność sułtanowi osmańskiemu. Założona przezeń dynastia rządziła Tunisem w latach 1705–1735 i 1756–1957; w miejsce zarządu odżaków powstał ład bejlika przechodzącego z ojca na syna. W ten sposób narodził się pierwszy przykład podległych centrum, lecz faktycznie autonomicznych struktur dynastycznych w odżakach Garbu.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Zdobycie Oranu i Mers el-Kébir od Hiszpanów", "b67ce06a"], "d": ["Siły beylerbeja Odżaku Algierskiego po długim oblężeniu zajęły Oran, od dwóch stuleci pozostający w rękach garnizonu hiszpańskiego, i port Mers el-Kébir. Był to największy sukces odżaków Garbu pod protekcją osmańską przeciw Hiszpanii na zachodzie Morza Śródziemnego i zabezpieczył zachodnie skrzydło Algieru. Miasto miało w 1732 ponownie paść ofiarą hiszpańskiej okupacji, lecz w 1792 miało zostać ostatecznie odzyskane.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Traktat z Prutu — odzyskanie Azowa i Taganrogu", "bac5d2a1"], "d": ["Siedmioartykułowy traktat, podpisany po poddaniu się armii rosyjskiej otoczonej nad Prutem, postanowił zwrot Osmanom twierdzy Azow wraz z terenem i amunicją. Umocnienia Taganrogu, Kamenki i Yenikale miały zostać zburzone, a strony nie miały budować w tych regionach nowych twierdz. Marynarka i ład baz, które Piotr I stworzył w ciągu szesnastu lat w Woroneżu i Azowie, się załamały; zejście Rosji nad Morze Czarne opóźniło się o około pięćdziesiąt lat.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Założenie dynastii Karamanlidów w Trypolitanii", "e1105d4a"], "d": ["W Trypolitanii, znużonej sporami agów odżaku, władzę przejął oficer kawalerii Ahmed Karamanlı i usankcjonował swoją sytuację beratem beylerbeja otrzymanym ze Stambułu. Rękami Ahmeda Paszy, jego syna Mehmeda Paszy i wnuka Yûsufa Paszy powstała dynastia trwająca w latach 1711–1835; pojawiła się półniezależna struktura, która zbudowała własną flotę i podpisywała traktaty bezpośrednio z państwami europejskimi. Ten okres miał się zakończyć dopiero w 1835, gdy ejalet został związany bezpośrednio z centrum.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Traktat adrianopolski z Rosją", "14901a70"], "d": ["Wskutek niedotrzymania obietnic danych nad Prutem dwukrotnie jeszcze wypowiedziano wojnę, a gdy w końcu Rosjanie przyjęli zobowiązania, w Edirne podpisano trwały pokój. Traktat potwierdził warunki z Prutu; Rosja miała nie mieszać się do spraw Polski, wycofać się z ziem kozackich i nie przeszkadzać w powrocie do kraju króla Szwecji Karola Żelaznogłowego. Zamknięcie w ten sposób frontu północnego umożliwiło państwu osmańskiemu zwrócenie twarzy ku frontowi Morei i Wenecji. W tym samym dniu przyłączono także inne miejscowości: Chocim.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Wypowiedzenie wojny Wenecji — przygotowanie wyprawy na Moreę", "d970b122"], "d": ["Pod pretekstem poparcia przez Wenecję powstańców czarnogórskich, zajmowania osmańskich statków handlowych oraz gnębienia ciężkimi podatkami Morei, zdobytej w Karłowicach, w Diwanie podjęto decyzję o wojnie. Wyprawa przygotowana przez wielkiego wezyra Silâhdara Damada Alego Paszę miała w następnym roku zakończyć się odzyskaniem całego półwyspu Morea w mniej niż sto dni. Ten sukces miał jednak poruszyć Austrię i w 1716 uchylić bramę znacznie cięższej wojny.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["Tinos (İstendil): poddanie ostatniej wyspy Wenecji na Morzu Egejskim", "4abec891"], "d": ["Flota wyruszająca na wyprawę morejską stanęła w drodze przed İstendil, jedyną wyspą pozostającą Wenecji na Morzu Egejskim. Wyspa, która mimo upadku Księstwa Naksos w 1566 dzięki ludności łacińskiej nosiła jeszcze sto pięćdziesiąt lat banderę wenecką, po krótkim oblężeniu poddała się bez przelewu krwi. W ten sposób ostatni ślad Wenecji na Morzu Egejskim został wymazany, a morze stało się całkowicie osmańskim morzem wewnętrznym.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Zdobycie Nauplionu — kluczowej twierdzy Morei", "62a5808a"], "d": ["Nauplion, stolica Wenecji w Morei i jej najpotężniejsza fortyfikacja, padł wraz z zajęciem bastionu Palamidi po dziewięciodniowym bombardowaniu. Tak szybkie zdobycie twierdzy złamało opór na reszcie półwyspu. Odzyskanie Morei utraconej w Karłowicach zostało faktycznie dopełnione właśnie tu. W tym samym dniu atlas zapisuje przejście od Wenecji do Osmanów innej miejscowości: Argos — podąża za łańcuchem ośrodka-brata Nauplionu (TDV anabolu; przybliżenie z deklaracją).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Poddanie Modonu", "43faa909"], "d": ["Po upadku Nauplionu twierdza Modon na południowo-zachodnim krańcu Morei została otoczona przez armię od lądu i flotę od morza i szybko się poddała. Port, z którego Wenecja przez dwieście lat korzystała w wyprawach na wschodnią część Morza Śródziemnego, był przystankiem obowiązkowym, gdzie okręty brały wodę i zapasy. Jego utrata zakończyła zdolność manewrową floty weneckiej na Morzu Egejskim.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Poddanie Koronu — dopełnienie wyprawy morejskiej", "e4b9c8a4"], "d": ["Wraz z poddaniem się twierdzy Koron, trzymającej wejście do Zatoki Mesyńskiej, zarząd wenecki na półwyspie Morea całkowicie się skończył. Półwysep utracony w Karłowicach został całkowicie odzyskany zaledwie trzy miesiące po rozpoczęciu wyprawy. W dalszym toku tej samej wyprawy, we wrześniu 1715, także wyspa Aya Mavra (Lefkada) na Morzu Jońskim została zabrana Wenecji. Ta szybkość zmusiła Wenecję do wciągnięcia Austrii do wojny i po trzech latach otworzyła drogę do Passarowitz.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Zajęcie wyspy Kythira (Çuha)", "494de6c6"], "d": ["Wyspa Kythira na południowym krańcu Morei została po dopełnieniu półwyspu przyjęta w poddanie przez flotę. Wyspa, pilnująca przejścia między Morzem Jońskim a Egejskim, była wysuniętym posterunkiem, którego Wenecja używała do kontroli tych wód. Nie pozostała jednak jedyną wyspą utrzymaną przez Osmanów: po trzech latach w Passarowitz została zwrócona Wenecji.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Austria i Wenecja zawarły sojusz — brama wojny osmańsko-austriackiej 1716–1718", "99511ca2"], "d": ["Po odzyskaniu przez Osmanów Morei od Wenecji Austria, twierdząc, że traktat karłowicki został naruszony, podpisała z Wenecją układ sojuszniczy; książę Eugeniusz w liście do wielkiego wezyra zażądał zwrotu miejsc zabranych Wenecji. Na naradzie w obozie Davutpaşa, pod naciskiem wielkiego wezyra Alego Paszy, wypowiedziano wojnę Austrii i w tym celu uzyskano fatwę od szejhülislama.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Wielki wezyr Ali Pasza wyruszył na wyprawę austriacką", "2fbdce42"], "d": ["Po wypowiedzeniu wojny Austrii serdar-ı ekrem Ali Pasza wyruszył na wyprawę austriacką z armią przekraczającą 100 000 ludzi; flota natomiast tego samego lata skierowała się na Korfu. Armia miała z Belgradu maszerować na Varadin, a w klęsce na początku sierpnia wielki wezyr miał polec jako męczennik.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Klęska pod Varadinem (Petrovaradin) — męczeńska śmierć Damada Alego Paszy", "265c1d81"], "d": ["Armia osmańska, która przez Belgrad przekroczyła Dunaj, spotkała się pod Varadinem z siłami austriackimi pod dowództwem księcia Eugeniusza; choć w pierwszym uderzeniu szarża janczarów przełamała okopy wroga, szeregi się rozpadły wraz z załamaniem skrzydła kawalerii. Wielki wezyr Silâhdar Damad Ali Pasza, trafiony w czoło, poległ jako męczennik, obóz i park artylerii w całości wpadły w ręce wroga. Ta klęska, którą osmańskie vekâyi'nâme wspominają jako „rok Varadinu”, była pierwszym ogniwem łańcucha prowadzącego do utraty Timișoary i w następnym roku Belgradu.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Niepowodzenie oblężenia Korfu", "b2aa7011"], "d": ["Seraskier Morei Kara Mustafa Pasza od strony lądu, a kapudan pasza Canım Hoca Mehmed Pasza od strony morza z flotą nacierali na Korfu; wyspa była kluczową bazą Wenecji na Adriatyku. Jednak niezwykle silne umocnienia twierdzy, posiłki sprowadzone przez flotę wenecką i wieści o klęsce na froncie dunajskim doprowadziły do zniesienia oblężenia. To, że Korfu nie zdobyto, zgasiło nastrój wzbudzony ponownym zdobyciem Morei i przesunęło środek ciężkości wojny na Węgry.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Utrata Timișoary (Timişvar) na rzecz Austrii", "27fe1365"], "d": ["Po klęsce pod Varadinem książę Eugeniusz ruszył bezpośrednio na Timișoarę, a twierdza po oblężeniu trwającym ponad czterdzieści dni została oddana na mocy układu. Miasto, zdobyte w 1552 za Sulejmana, uchodzące przez 164 lata za wschodni filar obrony Węgier jako ośrodek beylerbeyliku, zostało w ten sposób utracone. Wraz z upadkiem Timișoary cały region Banatu przeszedł do Austrii, a granica osmańska została odepchnięta na południe od Dunaju. W tym samym dniu atlas zapisuje przejście od Osmanów do Habsburgów innych miejscowości: Csákóvár, Facset i Caransebeș (Karánsebes) — wraz z przekazaniem ejaletu Timișoary (TDV timisvar; dzień na poziomie miejscowości nie występuje w źródle, łańcuch ośrodka-brata, przybliżenie z deklaracją).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Poddanie twierdzy Haram (Nowa Palanka) Austrii — brzeg Dunaju w Banacie utracony", "38ee4c6d"], "d": ["Po upadku Timișoary austriacki generał kawalerii Mercy, któremu polecono zająć resztę Banatu, ruszył 14 listopada na Haram (Nową Palankę) nad Dunajem; gdy 16 listopada dotarł do twierdzy, 200-osobowy garnizon osmański podniósł białą flagę i poddał się pod warunkiem swobodnego wycofania. W ten sposób linia Dunaju w Banacie Południowym, w rękach osmańskich od 1552, przeszła także do Austrii. W tym samym dniu atlas zapisuje przejście od Osmanów do Habsburgów innej miejscowości: Versec — podąża za łańcuchem ośrodka-brata Haramu (Bánlaky 0019/1703; przybliżenie z deklaracją).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Traktat w Passarowitz — Morea zdobyta, Belgrad i Banat utracone", "d46aa216"], "d": ["Morea została odzyskana od Wenecji, lecz Austria, która weszła do wojny, zyskała przewagę przy stole dzięki zwycięstwom odniesionym pod Petrovaradinem i Belgradem. Traktat podpisany za pośrednictwem Anglii i Holandii pozostawił Moreę przy Osmanach, w zamian za co Belgrad wraz z Serbią Północną, Banatem i Małą Wołoszczyzną oddano Austrii; w ujęciu TDV „Północna Bośnia została całkowicie pozostawiona Austrii” — twierdze takie jak Bosanska Dubica i Bosanski Brod nad Sawą przechodzą na mapie od tego dnia do Austrii (dokładną granicę wyznaczyli po kolei komisarze, TDV nie wymienia tych twierdz z nazwy); Wenecja zachowała natomiast pozycje na wybrzeżu Morza Jońskiego, takie jak Preweza i Kythira. Dzięki podpisanemu w tym samym dniu ahidname handlowemu cło od towarów austriackich obniżono z pięciu do trzech procent. Traktat, potwierdzając osmański odwrót w Europie Środkowej, ustanowił otwartym przezeń dwudziestosiedmioletnim pokojem grunt pod Epokę Tulipanów (1718–1730): pod rządami Nevşehirli Damada İbrahima Paszy pierwsza drukarnia osmańska (1727, İbrahim Müteferrika), zespoły tłumaczy, obserwacje szczepienia przeciw ospie i nowe życie pałacowo-kulturalne są plonem tych lat pokoju. W tym samym dniu atlas zapisuje zmianę właściciela innych miejscowości: Craiova, Râmnicu Vâlcea (Rimnik) i Turnu Severin (Mała Wołoszczyzna/Oltenia, od Osmanów do Austrii) oraz Aya Mavra (Lefkada) (od Osmanów do Wenecji; TDV ayamavra: w 1718 wyspa została zrzeczona na rzecz Wenecji traktatem z Passarowitz). W Małej Wołoszczyźnie ponadto Târgu Jiu przechodzi do Austrii; Vonitsa (TDV pasarofca-antlasmasi) i Kythira (TDV cuka-adasi: art. 3 Passarowitz) przechodzą do Wenecji.", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Wyprawa wschodnia: zajęcie Tbilisi i początek wojny z Iranem", "78343dc2"], "d": ["Wobec załamania się państwa Safawidów wskutek inwazji afgańskiej i zejścia Rosji nad brzegi Morza Kaspijskiego państwo osmańskie wysłało armię na wschód, by próżnia nie przypadła całkowicie wpływom rosyjskim. Po zajęciu Tbilisi Gruzję objęto zarządem osmańskim; następnie natarcie trwało w kierunku Gandży, Erywania i Nachiczewanu. Wyprawa prowadzona za pokojowym obliczem Epoki Tulipanów była początkiem długiej przygody wschodniej, która miała trwać trzynaście lat i zakończyć się zwrotem wszystkiego, co zdobyto.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Wyprawa irańska 1723: wejście do Szyrwanu i Gruzji", "c81189fc"], "d": ["Wobec załamania się państwa Safawidów wskutek inwazji afgańskiej otwarto wyprawę na wschód pod pretekstem zapobieżenia zejściu Rosji nad Morze Kaspijskie. Armia z Erzurumu weszła przez Gruzję do Tbilisi, a kolumna szyrwańska do Szamachy, odzyskując ziemie utracone sto trzydzieści lat wcześniej. Ta wyprawa była ostatnim wielkim natarciem Osmanów na Kaukazie.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Zajęcie Kermanszahu — brama Zagrosu", "ad14799f"], "d": ["Armia bagdadzka, przekroczywszy przełęcze Zagrosu, zajęła Kermanszah, uchodzący za zachodnią bramę Iranu. Miasto leżało na szlaku karawan i armii z Bagdadu do Isfahanu, a jego zajęcie zapewniało wschodnie bezpieczeństwo ejaletu Irak. To natarcie rozpoczęło w rozpadającym się państwie Safawidów wyścig podziału między Osmanami a Rosją.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Układ stambulski (Mukāsemenâme) — podział Iranu z Rosją", "fce8eec2"], "d": ["Aby nie dopuścić do zderzenia Osmanów z Rosją na ziemiach rozpadającego się państwa Safawidów, podpisano za pośrednictwem posła francuskiego traktat podziałowy. Zachodnie i południowe wybrzeża Morza Kaspijskiego pozostawiono Rosji, a Gruzję, Szyrwan, Azerbejdżan i miasta Zachodniego Iranu państwu osmańskiemu. Ten podział, który na papierze wyglądał na wielki zysk, wkrótce faktycznie stracił moc wraz z wzrostem znaczenia Nadir Szacha. Według traktatu urodzajne ziemie Szyrwanu, takie jak Szabran i Muszkur, pozostawiono po stronie rosyjskiej (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Zajęcie Nachiczewanu", "bdf14d0a"], "d": ["Siły osmańskie, które posuwały się wzdłuż Arasu, zajęły Nachiczewan i Ordubad; Culfa została także przyłączona do liwy Nachiczewan. Miasto, jako północno-zachodnia brama Iranu, zostało związane z nowo utworzonym ejaletem Erywań. W ten sposób granica osmańska ponownie osiągnęła najdalszą linię wschodnią z epoki Sulejmana.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Zdobycie Hamadanu", "e1339a97"], "d": ["Armia maszerująca z Kermanszahu na wschód zajęła po długim oblężeniu Hamadan na zachodnim progu płaskowyżu irańskiego. Miasto było ostatnim wielkim przystankiem na drodze do Isfahanu, najdalej na wschód wysuniętym punktem, jaki armie osmańskie zdołały osiągnąć od wyprawy Irakejn. Traktat stambulski (Mukavelenâme) podpisany z Rosją w tym samym roku przelał na papier podział rozpadającego się Iranu między Osmanów a Rosję.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Ponowne zdobycie Erywania", "88acabef"], "d": ["Po trwającym dziewięćdziesiąt dni ciężkim oblężeniu Erywań, kluczowa twierdza doliny Arasu, ponownie wszedł pod zarząd osmański. Twierdza zbudowana w 1583 i utracona w 1604 została tym razem umocniona silniejszym garnizonem. Długość oblężenia była wskaźnikiem, że armia osmańska nie posuwała się już łatwo. Nahije Karpi (Üçkilise), Şerür, Maku i Şüregel zostały też przyłączone do ejaletu Erywań.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Zajęcie Tabrizu — opanowanie Azerbejdżanu", "e502a4f7"], "d": ["Tabriz, ponownie oblężony po nieudanej próbie sprzed roku, poddał się armii osmańskiej po ciężkiej bitwie toczonej ulica po ulicy. Merend, Maragha i Sovukbulak (Mahabad), podległe prowincji Tabriz, weszły także pod zarząd osmański. W tym samym roku zajęto także Lori, Gandżę, Ardabil i Chorramabad, i w ten sposób faktycznie zajęto regiony przypadające Osmanom na mocy układu stambulskiego. Zasięg osiągnięty na wschodzie był najdalszą granicą od czasów traktatu Ferhada Paszy; utrzymanie go jednak położyło na armii i skarbie ciężkie brzemię.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Zdobycie Gandży — koniec wyprawy kaukaskiej", "875bca7a"], "d": ["Gandża, ostatni cel akcji kaukaskiej, została przyjęta w poddanie jako ośrodek Karabachu między Kurą a Arasem. Wraz z dopełnieniem linii Szyrwan–Erywań–Nachiczewan–Gandża państwo osmańskie osiągnęło na Kaukazie zasięg z 1590. Zdobycz ta okazała się jednak krótkotrwała: wzrost znaczenia Nadir Szacha miał w ciągu dziesięciu lat odzyskać cały region.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Traktat w Hamadanie — przyłączenie Zachodniego Iranu do Osmanów", "94a29dc3"], "d": ["Wraz z traktatem podpisanym z władcą Afgańczyków Aszrafem Szachem zakończyła się czteroletnia wojna, a ziemie Zachodniego Iranu zajęte przez państwo osmańskie zostały prawnie uznane. Aszraf Szach w zamian uznał kalifat sułtana osmańskiego i zobowiązał się, że w Iranie chutba będzie odczytywana w imieniu sułtana. To dyplomatyczne zwycięstwo było krótkotrwałe; kontrofensywa rozpoczęta przez Nadir Szacha w 1730 miała w ciągu kilku lat zmieść zdobycze traktatu.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoğlu Ali Pasza zajął Urmię (Rûmiye)", "eac7f64d"], "d": ["W wyprawie irańskiej Hekimoğlu Ali Pasza zajął najpierw Urmię (Rûmiye), a następnie opuszczony dla Osmanów Tabriz 15 listopada 1731. TDV nie podaje dnia zajęcia Urmii; wiadomo tylko rok i że nastąpiło przed Tabrizem.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Traktat Ahmeda Paszy — zwrot większej części Zachodniego Iranu", "590d839f"], "d": ["Wobec zwycięstwa Nadir Szacha pod Malâyir i następujących po sobie ofensyw irańskich namiestnik Bagdadu Ahmed Pasza podpisał tekst pokojowy bez konsultacji z centrum. Według traktatu za granicę uznano rzekę Aras; miasta Zachodniego Iranu, takie jak Hamadan, Kermanszah, Ardalan, Ardabil i Tabriz, zwrócono Iranowi, a Gandża i Tbilisi pozostały przy Osmanach. Ten tekst, przyjęty w Stambule z oburzeniem, został uznany za niewystarczający także przez Nadir Szacha i zanim minął rok 1732, wojna rozgorzała na nowo. Atlas uznaje też, że Kotur, podążający za łańcuchem Hoy, przeszedł tego dnia od Osmanów do Safawidów (TDV hoy; dzień właściwy dla Koturu nie występuje w źródle — przybliżenie z deklaracją).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Ponowna utrata Oranu na rzecz Hiszpanii", "20485027"], "d": ["Wielka flota desantowa wysłana przez króla Hiszpanii Filipa V stanęła pod dowództwem hrabiego Montemara pod Oranem i, rozbiwszy siły Odżaku Algierskiego, odzyskała miasto. Port zdobyty dwadzieścia cztery lata wcześniej miał przez sześćdziesiąt lat pozostać w rękach garnizonu hiszpańskiego. Ta strata, ukazująca granice siły odżaków Garbu na zachodzie Morza Śródziemnego, została zrekompensowana dopiero ostatecznym zdobyciem Oranu w 1792.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Reforma Odżaku Humbaracı na modłę europejską i założenie Humbarahâne", "d980cf2a"], "d": ["Humbaracı Ahmed Pasza, pochodzenia francuskiego, który wstąpił w służbę osmańską, przy poparciu wielkiego wezyra Hekimoğlu Alego Paszy przekształcił odżak humbaracich w płatny oddział zorganizowany na modłę europejską. Trzystu żołnierzom zwerbowanym w Bośni zapewniono regularne szkolenie oparte na rachunkach i geometrii; przygotowano nowe regulaminy dotyczące organizacji, wyposażenia i emerytury, wykonano według nowoczesnej techniki sto moździerzy i pięćdziesiąt tysięcy granatów. Humbarahâne, w którym wykładano geometrię, uchodzi za pierwszy zalążek nowoczesnego wojskowego kształcenia inżynierskiego w państwie osmańskim.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Śmierć Ahmeda III", "455f7fba"], "d": ["Ahmed III, zdetronizowany w 1730 przez powstanie Patrony Halila, spędził ostatnie sześć lat życia w apartamencie Pałacu Topkapı przeznaczonym dla zdetronizowanych sułtanów i zmarł w wieku sześćdziesięciu trzech lat. Został pochowany w Bahçekapı w mauzoleum swojej babki Turhan Sułtan przy Yenicami.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Traktat stambulski — zrzeczenie się Południowego Kaukazu na rzecz Iranu", "8c205aab"], "d": ["Druga wojna irańska, trwająca cztery lata, zakończyła się traktatem podpisanym po klęsce pod Arpaçay i utracie Gandży i Tbilisi. Państwo osmańskie wycofało się z całego Południowego Kaukazu i ziem Zachodniego Iranu, które zajmowało od 1723; granicę przywrócono do linii z Kasr-ı Şirin z 1639. Z trzynastoletnich wypraw wschodnich pozostały ciężkie brzemię finansowe i wyczerpany skarb; w zamian zamknięcie frontu wschodniego było życiowym zyskiem wobec nowej wojny rozpoczynającej się z Rosją.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Upadek twierdzy Oczaków (Özi) w ręce Rosjan", "f93e61f3"], "d": ["Armia rosyjska pod dowództwem marszałka Münnicha oblegała twierdzę Oczaków u ujścia Dniepru; wskutek wybuchu arsenału obrona się załamała, a twierdza padła z wielką stratą w ludziach. Utrata Oczakowa, uchodzącego za klucz północno-zachodniego wybrzeża Morza Czarnego, otworzyła Rosjanom drogę na Krym i wywołała w Stambule wielką panikę. Twierdza miała w następnym roku zostać opuszczona przez Rosjan wskutek zarazy i trudności zaopatrzeniowych i ponownie przejść do Osmanów.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Zwycięstwo pod Banja Luką — wyzwolenie Bośni", "f603865a"], "d": ["Gdy wojska austriackie wkroczyły do Bośni i oblegały Banja Lukę, namiestnik Bośni Hekimoğlu Ali Pasza pospieszył z odsieczą z siłami zebranymi spośród miejscowej ludności i zadał przeważającemu liczebnie wrogowi ciężką klęskę. Zwycięstwo to już w pierwszym ruchu zniweczyło austriacki plan okupacji Bośni, a północ ejaletu została całkowicie odzyskana. Banja Luka stała się jednym z punktów zwrotnych, które po 1683 podniosły morale armii osmańskiej, wciąż wycofującej się przed Austrią.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Zwycięstwo pod Grocką (Hisarcık) — otwarcie drogi do Belgradu", "2101cdff"], "d": ["Armia austriacka, która postępowała, by bronić Belgradu, została wciągnięta w zasadzkę w wąskim przesmyku nad Dunajem i poniosła ciężkie straty w trwającej cały dzień bitwie. Gdy siły marszałka Wallisa w nieładzie wycofywały się do Belgradu, armia osmańska stanęła pod twierdzą i rozpoczęła oblężenie. Grocka była najbardziej rozstrzygającym zwycięstwem w bitwie polnej odniesionym nad Austrią od Karłowic i bezpośrednio doprowadziła do odzyskania Belgradu.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Traktat w Nišu — pokój z Rosją, zneutralizowanie Azowa i powstrzymanie napadów krymskich", "674f974e"], "d": ["Rosja, pozostawiona sama po zgodzie Austrii na pokój w Belgradzie, musiała zakończyć wojnę za pośrednictwem posła francuskiego Villeneuve'a. Umocnienia twierdzy Azow zostały zburzone, a region ogłoszono terenem neutralnym między obu państwami; Rosja przyjęła warunek, że nie będzie utrzymywać na Morzu Czarnym okrętów wojennych ani handlowych. Cel Rosji, jakim było wyjście do morza, został w ten sposób odłożony o kolejne pokolenie, a państwo osmańskie po raz ostatni w XVIII wieku wstało od stołu z zyskiem.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Oczaków powrócił po rosyjskiej okupacji: twierdza oddana po zburzeniu na mocy pokoju 1739", "7ecc2bef"], "d": ["Rosjanie zajęli Oczaków 11 lipca 1737. W 1739, zgodnie z pokojem zawartym z Rosją, twierdzę oddano ponownie Osmanom po zburzeniu jej umocnień; Osmanowie trzymali Oczaków do 1788, aż do traktatu w Jassach.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Obrona Mosulu — odparcie Nadir Szacha", "c03ffbc1"], "d": ["Nadir Szach, który zajął Kirkuk i Irbil i stanął pod Mosulem, ostrzeliwał miasto przez czterdzieści dni i organizował jeden po drugim generalne szturmy. Obrona prowadzona przez namiestnika Hüseyina Paszę al-Dżalîlîego, który uzbroił także ludność miasta, zmusiła armię irańską do zniesienia oblężenia z ciężkimi stratami. Utrzymanie się Mosulu zapobiegło utracie całego Iraku i umocniło wpływy rodu Dżalîlî w mieście na stulecie.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Sojusz z Dirijji — założenie pierwszego Emiratu Saudyjskiego w Nadżdzie", "188751bf"], "d": ["Emir Muhammad b. Saud, który wziął pod swoją protekcję w Dirijji uczonego Muhammada b. Abd al-Wahhaba, wypędzonego z Uyaina, zawarł z nim sojusz oddający władzę polityczną w służbę misji religijnej. To porozumienie rozpoczęło nową historię rodu Saudów i zjednoczyło rozproszone emiraty oaz Nadżdu wokół jednego ruchu. Ta siła, która w ciągu pół wieku miała sięgnąć Karbali, Mekki i Medyny, miała zmusić państwo osmańskie do obrony swego panowania w Hidżazie.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Traktat z Kerden — koniec wojen osmańsko-irańskich", "1d3a919e"], "d": ["Traktat podpisany po ostatniej, czteroletniej wojnie odnowił bez zmian granicę z Kasr-ı Şirin z 1639; żadna ze stron nie osiągnęła zdobyczy terytorialnych. Uporczywe żądanie Nadir Szacha, by szyizm dżafarycki został uznany za piątą szkołę prawa, pozostało bez odpowiedzi; w zamian zgodzono się na swobodne odbywanie pielgrzymek przez pielgrzymów irańskich i wzajemną wymianę posłów. Wojny osmańsko-irańskie trwające ponad dwa stulecia faktycznie się w ten sposób zamknęły; ta granica zachowała się do dziś w znacznej mierze.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Śmierć Mahmuda I i wstąpienie na tron Osmana III", "30203700"], "d": ["Mahmud I, który w trwającym dwadzieścia cztery lata panowaniu odzyskał ziemie utracone w traktacie belgradzkim i poparł reformę Odżaku Humbaracı, zmarł, wracając z piątkowego selamlıku. Na jego miejsce wstąpił brat Osman III, który do pięćdziesiątego ósmego roku życia żył w klatce. Rozpoczęło się krótkie i niespokojne panowanie; za Osmana III, który w ciągu trzech lat zmienił sześciu wielkich wezyrów, w sprawach państwa zapanowało wyraźne zastoje.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Śmierć Osmana III i wstąpienie na tron Mustafy III", "3ac10f85"], "d": ["Po trzyletnim panowaniu, po śmierci Osmana III, na tron wstąpił Mustafa III, otwarty na idee reformatorskie i okazujący żywe zainteresowanie sprawami państwa. Nowy sułtan, opierając się na doświadczeniu wielkiego wezyra Koca Râgıba Paszy, próbował naprawić finanse i odnowić armię; w tym okresie utworzono artylerię szybką barona de Tott. Jednak wojna z Rosją, do której przystąpiono w 1768, miała zaćmić wszystkie osiągnięcia siedemnastoletniego panowania.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Wypowiedzenie wojny Rosji — wydarzenie w Baltă i początek wojny 1768–1774", "9c6aabe0"], "d": ["Gdy oddziały rosyjskie i kozackie ścigające Konfederację Barską w Polsce napadły na miasteczko Balta na granicy osmańskiej i je spaliły, Diwan podjął decyzję o wojnie, a poseł rosyjski został uwięziony w Yedikule. Wojna, do której przystąpiono bez poważnych przygotowań wojskowych i ogłoszoną sześć miesięcy wcześniej, od samego początku szła źle. Ta trwająca sześć lat walka miała przekształcić się w jeden z najcięższych łańcuchów klęsk w dziejach osmańskich, z pożarem floty pod Çeşme, klęską pod Kagułem i okupacją Krymu.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Utrata twierdzy Chocim na rzecz Rosjan", "66d43ea4"], "d": ["Gdy dwie próby armii rosyjskiej pod dowództwem księcia Golicyna zostały odparte, po klęsce wielkiego wezyra między Kamieńcem a Chocimiem armia się wycofała, a obrońcy opuścili twierdzę. Utrata bez oporu najpotężniejszej osmańskiej twierdzy na północ od Dunaju otworzyła Rosjanom bramy Wołoszczyzny i Mołdawii. Oba księstwa zostały w tym samym roku okupowane; Chocim udało się odzyskać dopiero w 1774 na mocy traktatu w Küczük Kajnardży.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Klęska na równinie Kagul (Kartal)", "6f408eaf"], "d": ["Trzy tygodnie po spaleniu floty pod Çeşme główna armia osmańska nad Dunajem rozproszyła się na równinie Kagul wobec o wiele mniejszych, lecz zdyscyplinowanych oddziałów marszałka Rumiancewa. Obóz, tabory i setki dział wpadły w ręce wroga; uciekające oddziały poniosły wielkie straty przy przekraczaniu Dunaju. Zniszczenie w tym samym lecie zarówno floty, jak i armii lądowej doprowadziło do kolejnego upadku Kilii, Akkermanu, Izmaiła i Benderu oraz do okupacji Krymu.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Rosyjska okupacja półwyspu krymskiego", "217837b0"], "d": ["Armie rosyjskie, które rok wcześniej zajęły Budżak, pod dowództwem księcia Dołgorukowa przekroczyły Perekop i zajęły cały półwysep krymski. Chana zdetronizowano, na czele postawiono prorosyjskiego Sâhiba Gireja i uczyniono pierwszy krok ku oderwaniu chanatu od Osmanów. Utrata Krymu, od trzech stuleci północnej tarczy Osmanów, była początkiem procesu, który w 1774 przyniósł niepodległość, a w 1783 bezpośrednią aneksję.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Śmierć Mustafy III i wstąpienie na tron Abdülhamida I", "42cba8e2"], "d": ["Na miejsce Mustafy III, który zmarł w najcięższym momencie wojny rosyjskiej, w wieku czterdziestu dziewięciu lat wstąpił na tron jego brat Abdülhamid I, który czterdzieści trzy lata spędził w klatce pałacu. Nowy sułtan, który odziedziczył jeden z najtrudniejszych okresów państwa, musiał zmierzyć się z ciężkimi warunkami traktatu w Küczük Kajnardży, który miał zostać podpisany w tym samym roku. Jego piętnastoletnie panowanie miało upłynąć pod znakiem utraty Krymu i nowej wojny z Rosją, a zakończyć się w 1789 udarem, którego doznał, czytając wiadomość o upadku Oczakowa.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Klęska pod Kozludżą — klęska prowadząca do Küczük Kajnardży", "8e0542f9"], "d": ["Siły osmańskie zgromadzone pod Şumnu zostały pokonane pod Kozludżą przez połączone kolumny Suworowa i Kamieńskiego, a większość armii się rozproszyła. Po tej klęsce nie było już na Bałkanach siły zdolnej stawić opór; rosyjskie straże przednie oblegały Şumnu, a kwatera wielkiego wezyra znalazła się pod zagrożeniem. Zasiadanie do stołu w Küczük Kajnardży przed upływem miesiąca i przyjęcie niezwykle ciężkich warunków są bezpośrednim skutkiem tej klęski.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Oddanie Bukowiny (Północnej Mołdawii) Austrii", "190f9caa"], "d": ["Austria, korzystając ze słabości wywołanej przez Küczük Kajnardżę, zażądała Bukowiny, łączącej Mołdawię z Siedmiogrodem, i bez wchodzenia do wojny, groźbą i łapówką, zdobyła tę ziemię. Utrata tego urodzajnego i strategicznego regionu na południowy zachód od Chocimia faktycznie podzieliła wojewodztwo mołdawskie na dwie części. To oddanie, dokonane bez jednego wystrzału, uznano za jeden z najjaśniejszych znaków, że państwo osmańskie utraciło już siłę odstraszania. W 1775 wraz z oddaniem Bukowiny Suczawa i Czerniowce przeszły do Austrii (dzień niepotwierdzony).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Perska okupacja Basry", "0161e709"], "d": ["Sâdık Han, brat władcy Zendów Kerima Chana, po rocznym oblężeniu zajął Basrę, a państwo osmańskie utraciło najważniejszy port nad Zatoką Perską. Okupacja bezpośrednio wstrząsnęła szlakiem handlu z Indiami, dochodami z daktyli i pereł oraz południową obroną Iraku. Miasto zdołano odzyskać dopiero w 1779, w czasie sporów o tron w Iranie po śmierci Kerima Chana.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Tenkihname z Aynalıkavak — tymczasowe porozumienie w sprawie Krymu", "9b3b0468"], "d": ["Dwa państwa, które stanęły na progu wojny o to, kto ma objąć chanat krymski, podpisały za pośrednictwem Francji w pałacu Aynalıkavak tekst wyjaśniający. Rosja zgodziła się wycofać wojsko z Krymu, a państwo osmańskie uznać chanat prorosyjskiego Şâhina Gireja; potwierdzono religijne prawo sułtana do kalifatu nad Krymem. Ta krucha równowaga, mająca trwać cztery lata, miała całkowicie się załamać w 1783 wraz z bezpośrednią aneksją półwyspu przez Rosję.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Budowa twierdzy Anapa — kaukaska linia obrony", "be92a80f"], "d": ["Gdy po Küczük Kajnardży Krym został utracony, przystąpiono do budowy nowej twierdzy u ujścia rzeki Kubań, by zachować wpływy osmańskie na Kaukazie. Anapa, zbudowana na pozostałościach kolonii genueńskiej, wraz z rynkiem, łaźniami i ponad dwustu pięćdziesięcioma sklepami wkrótce stała się miastem zapewniającym łączność z plemionami czerkieskimi. Twierdza przez czterdzieści osiem lat pozostawała najdalej wysuniętym posterunkiem Osmanów wobec zejścia Rosji na Kaukaz.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Odwołanie i stracenie wielkiego wezyra Halila Hamîda Paszy", "c44001ca"], "d": ["Reformatorski wielki wezyr Halil Hamîd Pasza, któremu Abdülhamid I przy różnych okazjach okazywał zadowolenie z jego usług, został około rana 31 marca 1785 nagle odwołany i zesłany do Gallipoli, a cały jego majątek skonfiskowano. Najpierw nadano mu ejalet Habesz, sandżak Dżudda i urząd szejha Mekki; gdy w kwietniu 1785, przygotowując się do drogi, przebywał na Bozcaadzie, został odwołany także z tego namiestnictwa i zabity na mocy wydanego fermanu o stracenie przez Karakethüdâzâde Alego, jednego z ludzi Cezayirlego Gazi Hasana Paszy. Jego odcięta głowa została wysłana do Stambułu i wystawiona przy Ortakapı. Według TDV ten nagły upadek interpretowano jako oskarżenie o spisek mający na celu zdetronizowanie sułtana i postawienie na jego miejscu księcia Selima, lecz prawdziwymi przyczynami były prawdopodobnie oburzenie na to, że milczał wobec aneksji Krymu, wrogość kręgów dotkniętych jego reformami i opozycja Gazi Hasana Paszy.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Wypowiedzenie wojny Rosji — rozpoczęcie wojny osmańsko-rosyjskiej 1787–1792", "3bfb870c"], "d": ["Po okazałej podróży Katarzyny II na Krym i objęciu przez nią protekcją Gruzji Diwan postanowił o wojnie, by cofnąć aneksję, a poseł rosyjski został ponownie zamknięty w Yedikule. Armia nie była jednak gotowa, skarb był pusty, a poszukiwanie sprzymierzeńców nie przyniosło skutku. Wojna, mająca trwać pięć lat, miała zakończyć się upadkiem Oczakowa z rzezią, utratą Izmaiła i ciężkimi warunkami traktatu w Jassach.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Przystąpienie Austrii do wojny — walka na dwóch frontach", "ae912290"], "d": ["Zgodnie z tajnym sojuszem zawartym z Rosją w 1781 cesarz austriacki Józef II wypowiedział wojnę państwu osmańskiemu i ruszył w kierunku Belgradu i Bośni. Armia osmańska musiała nagle walczyć na dwóch frontach naraz: z Rosją na północy i Austrią na zachodzie. Mimo zwycięstw odniesionych nad Austriakami pod Lazarethane, Mehadią i Şebeş front zachodni miał się załamać wraz z utratą Belgradu w 1789.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Sojusz osmańsko-pruski", "03b88e51"], "d": ["Selim III, który zaraz po wstąpieniu na tron szukał w Europie sprzymierzeńców, podpisał z Prusami traktat sojuszniczy przewidujący wzajemną pomoc; Prusy zobowiązały się wypowiedzieć wojnę Rosji i Austrii, a państwo osmańskie nie zawierać pokoju, dopóki Krym nie zostanie odzyskany. Był to pierwszy w dziejach osmańskich prawdziwy tekst wzajemnego sojuszu podpisany z państwem europejskim i wskazywał, że porzucono klasyczne pojmowanie, iż „nie ma sojuszu z niewiernymi”. Prusy do wojny nie przystąpiły, lecz zmuszając Austrię do pokoju otworzyły drogę traktatowi w Świsztowie.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Upadek twierdzy Izmaił i rzeź", "6a296b0c"], "d": ["Twierdza Izmaił, uchodząca za najpotężniejszą fortyfikację delty Dunaju, została zdobyta w ciągu jednego dnia w krwawym generalnym szturmie generała Suworowa; garnizon i ludność miasta w znacznej mierze wycięto. Rzeź ta, która wywołała szeroki oddźwięk w Europie, wywołała głęboki szok w osmańskiej opinii publicznej i złamała kręgosłup linii obrony Dunaju. Twierdza miała być rok później odzyskana na mocy traktatu w Jassach, lecz losy wojny były już rozstrzygnięte.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Traktat w Świsztowie — zamknięcie frontu austriackiego", "58741f1d"], "d": ["Dzięki naciskowi Prus i temu, że rewolucja francuska absorbowała Austrię na zachodzie, oba państwa doszły do pokoju w oparciu o granice sprzed wojny. Austria zwróciła wszystkie zajęte miejsca, w tym Belgrad; państwo osmańskie zgodziło się jedynie na drobne korekty na granicy chorwackiej. Zamknięcie frontu zachodniego na tych warunkach pozwoliło państwu osmańskiemu skupić całą siłę przeciw Rosji i ograniczyło stratę poniesioną w traktacie w Jassach. Dzięki tym korektom na granicy chorwackiej Cetin (Cetingrad) i Drežnik Grad przechodzą od Osmanów do Habsburgów (TDV zistovi-antlasmasi; Korić 2016, przyp. 118, art. 4). Orsova (Stara Orsova) jest natomiast jedynym miejscem, które nie zostało zwrócone (Bánlaky 0019/1796); atlas zapisuje prawne przekazanie na ten dzień (faktyczna okupacja 16 kwietnia 1790).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Traktat w Jassach — ostateczna utrata Krymu i granica na Dniestrze", "a56fd194"], "d": ["Na mocy traktatu podpisanego pod koniec pięcioletniej wojny za granicę uznano rzekę Turla (Dniestr); lewy brzeg rzeki przypadł Rosji, prawy pozostał przy Osmanach, a Oczaków wraz z okolicami został ostatecznie utracony. Państwo osmańskie całkowicie porzuciło nadzieję na odzyskanie Krymu i prawnie uznało aneksję z 1783; Wołoszczyznę i Mołdawię zwrócono z dwuletnim zwolnieniem od podatku. Przyjęcie także zobowiązania do zapłaty odszkodowania wojennego w wysokości dwunastu milionów kuruszy przesądziło o trwałym oddaniu północy Morza Czarnego Rosji. W tym samym dniu przyłączono także inne miejscowości: Izmaił.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Opuszczenie Oranu przez Hiszpanów i przekazanie Algierowi", "9f95cee6"], "d": ["Gdy twierdza i miasto zostały w znacznej mierze zniszczone w trzęsieniu ziemi w 1790, Hiszpania, która nie mogła już utrzymywać kosztownego garnizonu trzymanego od trzech stuleci, porozumiała się z odżakiem algierskim i oddała Oran i Mers el-Kébir bez wojny. W ten sposób zlikwidowano ostatnią europejską pozycję na wybrzeżu Afryki Północnej. Osmański Algier przez trzydzieści osiem lat aż do okupacji francuskiej panował nad całym wybrzeżem.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Faktyczne panowanie Pazvandoğlu Osmana w Widyniu", "0ce70361"], "d": ["Pazvandoğlu Osman, który zbuntował się przeciw przepisom Nizâm-ı Cedîd, kazał uciec namiestnikowi Widynia, zajął miasto i umocnił je głębokimi rowami wzdłuż Dunaju. W 1797 na szczycie siły zebrał blisko osiemdziesiąt tysięcy ludzi i objął kontrolą Nikopol, Świsztow, Ruse, Sofię i Niš; przedstawiał siebie nie jako buntownika, lecz jako reformatora. Trwające miesiącami oblężenie Bâbıâli z lat 1798–1799 nie przyniosło skutku i panował w Bułgarii Północnej jako półniezależny aż do śmierci w 1807.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Otwarcie Mühendishâne-i Berrî-i Hümâyun", "e9a3a34b"], "d": ["Aby kształcić artylerzystów, saperów i kartografów dla armii Nizâm-ı Cedîd, w Hasköy otwarto lądową szkołę inżynierską; był to odpowiednik w wojsku lądowym założonej w 1773 szkoły inżynierii morskiej. W programie nauczano algebry, geometrii, mechaniki, fortyfikacji i balistyki, a z języków europejskich tłumaczono książki z matematyki i artylerii. Ta szkoła, uchodząca za korzeń nowoczesnego kształcenia inżynierskiego w Turcji, uważana jest za początek dzisiejszego Uniwersytetu Technicznego w Stambule.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Wypowiedzenie wojny Francji i sojusz z Rosją i Anglią", "80e95bd7"], "d": ["Wobec inwazji Napoleona na Egipt państwo osmańskie, zrywając dwuipółwieczną tradycyjną przyjaźń z Francją, wypowiedziało Francji wojnę. W tym samym procesie po raz pierwszy w swej historii zawarło sojusz z Rosją i pozwoliło rosyjskiej flocie przejść przez cieśniny na Morze Śródziemne; następnie podpisano też sojusz z Anglią. Dzięki tym sojuszom Wyspy Jońskie zostały zabrane Francuzom, lecz otwarcie cieśnin dla obcej floty stworzyło precedens o ciężkich kosztach w przyszłości.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Odebranie Prewezy Francuzom — bitwa pod Nikopolis", "d8e5e892"], "d": ["Gdy Republika Wenecka upadła w 1797, Wyspy Jońskie oraz Preweza, Parga i Vonitsa na lądzie przeszły w ręce Francji. Namiestnik Janiny Ali Pasza z Tepedelen, wykorzystując wojnę wywołaną inwazją Francji na Egipt, ruszył na Prewezę i zadał garnizonowi francuskiemu ciężką klęskę wśród ruin Nikopolis poza miastem. W ten sposób port pozostawiony Wenecji w Passarowitz wszedł po osiemdziesięciu latach pod zarząd osmański. Butrint (Butrinto) upadł 25 października, gdy garnizon francuski wysadził umocnienia i wycofał się na Korfu (Curlin, Preveza B, 2010; dzień atlasu bierze od Prewezy) i wszedł pod zarząd osmański.", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Obrona Akki — odparcie Napoleona", "56b5c45b"], "d": ["Napoleon, który z Egiptu posuwał się do Syrii, oblegał Akkę i przez dwa miesiące przeprowadzał kolejne szturmy; miasto bronili Cezzâr Ahmed Pasza z poparciem floty angielskiej i oddziałami Nizâm-ı Cedîd wysłanymi ze Stambułu. Napoleon, który musiał znieść oblężenie i wycofać się do Egiptu, pogrzebał pod tymi murami marzenie o sięgnięciu na wschód. Wiadomość przyjęto w Stambule z wielką radością, a uznano ją za dowód, że nowo utworzona armia wyszkolona przeszła pierwszy poważny sprawdzian.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Napad wahhabitów na Karbalę", "522341ed"], "d": ["Siły wahhabickie wyruszające z Nadżdu wkroczyły do Karbali, złupiły miasto, zniszczyły mauzoleum imama Husajna i zabiły ponad trzy tysiące osób. Mameluccy namiestnicy państwa osmańskiego w Iraku nie zdołali zapobiec napadowi; wydarzenie wywołało wielką reakcję zarówno w Iranie, jak i w Stambule. Ten atak był ogłoszeniem, że ruch saudyjski przestał być emiratem oazy i przekształcił się w regionalną siłę zagrażającą świętym miastom osmańskim.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Aneksja Kartlii-Kachetii (Gruzja Wschodnia) przez Rosję", "3b650c5e"], "d": ["Carstwo Kartlii-Kachetii, które w 1783 przyjęło protekcję rosyjską, a w 1795 padło ofiarą niszczycielskiej wyprawy Iranu, zostało rozwiązane; rozkazem z 12 września 1801 ogłoszono je prowincją Rosji i zaczęto wprowadzać rosyjski system zarządu. Gruzja utraciła od tej daty niezależność; w ciągu kilku lat także Megrelia (1803), Imeretia i Gurija (1804) weszły pod panowanie rosyjskie, a Rosja dotarła do kaukaskiej granicy osmańskiej. Wraz z tym wydarzeniem Gori, Dusheti (Kartlia) i Telavi (Kachetia) przeszły do Rosji.", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Ewakuacja Egiptu przez Francuzów", "00cfdc8c"], "d": ["W wyniku wspólnej akcji sił osmańskich i angielskich z lądu i morza najpierw przyjęto poddanie Kairu, następnie Aleksandrii, a siły francuskie odesłano okrętami do kraju. Gdy trwająca trzy lata okupacja dobiegła końca, Egipt na papierze wrócił pod zarząd osmański, lecz walka o władzę między bejami mameluckimi a oddziałami albańskimi pogrążyła kraj w chaosie. Ta próżnia miała w ciągu kilku lat przygotować grunt pod wzrost znaczenia Mehmeda Alego z Kawali.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Traktat paryski — przywrócenie pokoju z Francją", "1b76991f"], "d": ["Na mocy traktatu podpisanego po ewakuacji Egiptu stan wojny między państwem osmańskim a Francją oficjalnie się zakończył, a dawne kapitulacje odnowiono. Zezwolono francuskim statkom handlowym wchodzić na Morze Czarne; w zamian Francja uznała integralność terytorialną Osmanów. Przywrócenie pokoju dało polityce zagranicznej Selima III, ściśniętej między Rosją a Anglią, ponownie pole manewru.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Zajęcie Ta'if przez wahhabitów", "7b791359"], "d": ["Siły wahhabickie pod dowództwem Suda b. Abd al-Aziza w pierwszym uderzeniu na Hidżaz oblegały i złupiły Ta'if; miasto padło jako pierwsza brama otwierająca się na święte ziemie. Dla sułtana osmańskiego noszącego miano protektora Haremejn był to cios bezpośrednio wstrząsający legitymacją panowania. Po dwóch i pół miesiąca ta sama armia miała pomaszerować na Mekkę.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Pierwsze zajęcie Mekki przez wahhabitów", "21157c05"], "d": ["Po dwóch i pół miesiąca od upadku Ta'if siły wahhabickie wkroczyły do Mekki, zburzyły grobowce i ustanowiły porządek według własnego rozumienia; szarif Gālib musiał wycofać się do Dżuddy. Zamknięcie szlaków pielgrzymich odbiło się echem w całym świecie islamu i zmusiło Stambuł do poproszenia o pomoc wojskową namiestnika Egiptu Mehmeda Alego. To pierwsze panowanie miało trwać jedynie trzy miesiące.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Odzyskanie Mekki przez szarifa Gāliba", "83d08dff"], "d": ["Szarif Gālib, który wycofał się do Dżuddy, oblegał Mekkę zebranymi siłami i po dwudziestopięciodniowym oblężeniu odzyskał miasto od wahhabitów; ponownie odczytano chutbę w imieniu Osmanów. To drugie panowanie również nie było trwałe — siły Sauda miały w 1806 ponownie zająć miasto.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Początek Pierwszego Powstania Serbskiego", "0f6e8767"], "d": ["Gdy zbuntowani dejowie janczarscy, którzy objęli rządy w Belgradzie, wymordowali zbiorowo serbskich notabli, rozpoczął się zbrojny opór pod wodzą Karađorđa. Ruch, prowadzony początkowo przeciw samym dejom i pozostający wierny sułtanowi, w krótkim czasie przekształcił się w powstanie narodowe żądające autonomii i niepodległości. Siły serbskie zajęły Belgrad w 1806; to powstanie stało się pierwszym ogniwem narodowych ruchów niepodległościowych na Bałkanach.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Okupacja Medyny przez wahhabitów", "84e310d7"], "d": ["Po Mekce także Medyna wpadła w ręce sił wahhabickich; skarbiec Rawdy Mutahhary został rozdysponowany, a kopulaste mauzolea w mieście zburzono. W ten sposób oba święte miasta naraz wyszły spod kontroli osmańskiej, a karawany pielgrzymów z Damaszku i Egiptu przez lata nie mogły wyruszyć. Medynę udało się odzyskać dopiero po siedmiu latach, w 1812, armii egipskiej pod dowództwem Tosuna Paszy, syna Mehmeda Alego Paszy.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Początek wojny z Rosją (wojna osmańsko-rosyjska 1806–1812) i zamknięcie cieśnin", "ea170804"], "d": ["Gdy Selim III, który po zwycięstwie Napoleona pod Austerlitz zbliżył się do Francji, mimo nacisku rosyjskiego odwołał wojewodów Wołoszczyzny i Mołdawii, armie rosyjskie zajęły oba księstwa i rozpoczęła się wojna. Państwo osmańskie zamknęło cieśniny dla floty rosyjskiej; w odpowiedzi Anglia stanęła po stronie Rosji i wysłała do Stambułu flotę. Ta wojna, mająca trwać sześć lat, splotła się z powstaniem Kabakçı i detronizacją Selima III i miała zakończyć się utratą Besarabii w traktacie bukareszteńskim z 1812.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Przybycie floty angielskiej pod Stambuł (akcja Duckwortha)", "195bb58f"], "d": ["Anglia, chcąc zmusić państwo osmańskie do zerwania więzi z Francją, przeprowadziła flotę pod dowództwem admirała Duckwortha przez Dardanele i zakotwiczyła pod Stambułem. Pod kierunkiem posła francuskiego Sébastianiego ludność Stambułu się zmobilizowała, baterie nadbrzeżne wzmocniono w ciągu dni, a flota musiała wycofać się, zanim zdołała ostrzelać miasto; w drodze powrotnej poniosła w Dardanelach ciężkie straty. Pierwsze tak bliskie zagrożenie stolicy przez obcą flotę umieściło sprawę cieśnin w centrum europejskiej dyplomacji.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Uduszenie Mustafy IV", "eeb75c20"], "d": ["Gdy Alemdar Mustafa Pasza został napadnięty i zginął, a powstańcy chcieli pomaszerować na pałac, zdetronizowany Mustafa IV został uduszony z rozkazu brata Mahmuda II. Jego ciało pochowano w Bahçekapı w mauzoleum ojca Abdülhamida I; wśród powstańców rozeszła się pogłoska, że trumna była pusta.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Traktat z Kal'a-i Sultâniyye — pokój z Anglią i zasada cieśnin", "fe282117"], "d": ["Traktatem podpisanym z Anglią po niepowodzeniu akcji Duckwortha wojna między obu państwami się zakończyła, a stare przywileje kupców angielskich zwrócono. Zapisane w tekście postanowienie zwane „kadîm kaide” (dawną zasadą) stanowiło, że w czasie pokoju żaden obcy okręt wojenny nie może przechodzić przez cieśniny. Zasada ta stała się prawną podstawą wszystkich międzynarodowych uregulowań, które miały kształtować reżim cieśnin w ciągu XIX wieku.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Klęska pod Slobozią — okrążenie armii dunajskiej", "54b60fd1"], "d": ["Większość armii osmańskiej, która przekroczyła Dunaj pod Ruse, została przez manewr okrążający Kutuzowa wykonany z przeciwległego brzegu rzeki zepchnięta pod Slobozią i skazana na głód. Tysiące żołnierzy musiało się poddać; siły wielkiego wezyra faktycznie się roztopiły, a Bâbıâli po miesiącu musiało prosić o rozejm. Ta klęska jest bezpośrednią przyczyną zgody na oddanie Besarabii w traktacie bukareszteńskim z 1812.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Odzyskanie Belgradu i stłumienie Pierwszego Powstania Serbskiego", "06f56f52"], "d": ["Serbscy powstańcy, pozbawieni na mocy traktatu bukareszteńskiego poparcia rosyjskiego, nie wytrzymali wobec wspólnej akcji sił nadciągających z Bośni i Rumelii; Hurşid Ahmed Pasza wkroczył do Belgradu i dziewięcioletnie powstanie zostało całkowicie stłumione. Karađorđe uciekł do Austrii, a sandżak Smederevo został ponownie związany bezpośrednio z zarządem osmańskim. Jednak zastosowane surowe środki miały po dwóch latach wywołać drugie, trwałe powstanie pod wodzą Miloša Obrenovicia.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Drugie Powstanie Serbskie i naczelne księstwo Miloša Obrenovicia", "e6e82ad2"], "d": ["Przeciw ciężkim środkom zastosowanym po stłumieniu pierwszego powstania wybuchło pod wodzą Miloša Obrenovicia nowe powstanie; tym razem Bâbıâli zamiast siły wybrało porozumienie. Na mocy zawartego układu Miloš został uznany z tytułem „naczelnego księcia”, a uprawnienia do ściągania podatków i prowadzenia spraw wewnętrznych pozostawiono serbskim knezom. Ten pierwszy zalążek faktycznej autonomii stał się punktem wyjścia procesu sięgającego ferman z 1830 i niepodległość z 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Powstanie na Wołoszczyźnie — przekroczenie Prutu przez Ypsilantiego i powstanie Vladimirescu", "67d46a98"], "d": ["Aleksander Ypsilanti, generał armii rosyjskiej, przekroczył w imieniu Filiki Eterii Prut i próbował wzniecić powszechne powstanie greckie na Wołoszczyźnie i w Mołdawii; w tych samych dniach Tudor Vladimirescu poruszył miejscowych chłopów. Oba ruchy nie zdołały się połączyć: Vladimirescu odpowiedział na wezwanie Ypsilantiego do wspólnej walki przeciw Turkom: „Nie powstałem przeciw Turkom, lecz przeciw Grekom”, i wkrótce został zabity przez ludzi Ypsilantiego. Powstanie zostało stłumione przez siły osmańskie w maju, lecz ład wojewodztw fanariockich się skończył, a ogień powstania przeniósł się na Moreę.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Założenie Drugiego Państwa Saudyjskiego w Rijadzie", "34dad3bd"], "d": ["Sześć lat po upadku Dirijji w 1818 i zburzeniu pierwszego państwa saudyjskiego Turkî b. Abdullah, usunąwszy garnizony egipskie z Nadżdu, założył nowy emirat saudyjski z ośrodkiem w Rijadzie. Nowa struktura, unikając sięgania do Hidżazu, wolała pozostać w Nadżdzie i trzymała się z dala od bezpośredniego starcia z siłami osmańsko-egipskimi. To drugie państwo miało trwać do końca stulecia i stanowić drugie ogniwo łańcucha prowadzącego do powstania dzisiejszej Arabii Saudyjskiej. W tym samym dniu utracono także inne miejscowości: Dirijja (Nadżd).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Traktat w Akkermanie — ustępstwa na rzecz Serbii i księstw", "c75f15d0"], "d": ["Państwo osmańskie, które po zniesieniu korpusu janczarów zostało bez armii, musiało wobec ultimatum Rosji przyjąć traktat o ciężkich warunkach. Potwierdzono obiecaną Serbii autonomię, uznano, że wojewodowie Wołoszczyzny i Mołdawii nie mogą być odwoływani bez zgody rosyjskiej, a rosyjskim statkom handlowym przyznano pełną swobodę w cieśninach. Gdy Bâbıâli dwa lata później z powodu sprawy greckiej ogłosiło, że traktatu nie uznaje, Rosja uznała to za powód do wojny.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Likwidacja systemu timarów", "84d5d1d6"], "d": ["W rok po zniesieniu korpusu janczarów około 5200 sipahich timarowych w pięćdziesięciu trzech sandżakach Rumelii i Anatolii zostało wraz z dochodami z timarów przekształconych w jazdę Asâkir-i Mansûre. W ten sposób reżim timarowy, czterowiekowy kręgosłup osmańskiego ładu ziemi, podatków i armii, faktycznie się skończył. Opróżnione timary przekazano skarbowi i otwarto drogę do przejścia na armię centralną na żołdzie i system podatków pieniężnych.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Założenie Tıphâne-i Âmire — początek nowoczesnego kształcenia medycznego", "ac3e57c0"], "d": ["Dla kształcenia lekarzy i chirurgów dla nowo utworzonej armii Asâkir-i Mansûre z propozycji hekimbaszy Mustafy Behçeta Efendiego otwarto w Şehzadebaşı Tıphâne-i Âmire. Zajęcia ułożono według programu europejskiego, a nauczanie prowadzono początkowo po francusku; po kilku latach założono także Cerrahhâne-i Âmire i połączono obie instytucje. Ta szkoła, uchodząca za początek nowoczesnego nauczania medycyny w Turcji, uważana jest za korzeń dzisiejszego Wydziału Lekarskiego w Stambule.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Początek wojny osmańsko-rosyjskiej 1828–1829", "9dff4e05"], "d": ["Po spaleniu floty pod Nawarynem i ogłoszeniu przez Bâbıâli, że nie uznaje traktatu z Akkermanu, Rosja wypowiedziała wojnę na dwóch frontach naraz. Ponieważ korpus janczarów został dopiero zniesiony, a nowa armia była w trakcie tworzenia, osmańska obrona była od początku słaba; gdy Rosjanie przekraczali Dunaj, na wschodzie zajęli Kars i Achalciche. Armia rosyjska, która w ciągu roku dotarła do Edirne, miała narzucić ciężkie warunki traktatu adrianopolskiego z 1829 i niepodległość Grecji.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Pierwszy traktat ze Stanami Zjednoczonymi", "d737516f"], "d": ["Na mocy traktatu handlowo-żeglarskiego, podpisanego po latach kontaktów, USA uzyskały w ziemiach osmańskich status najbardziej uprzywilejowanego narodu i prawo tranzytu handlowego przez cieśniny. Osobny tajny artykuł przewidywał, że Osmanowie w razie potrzeby mogą budować okręty w stoczniach amerykańskich oraz kupować gotowe okręty i drewno; Senat USA ratyfikował traktat, lecz ten tajny artykuł odrzucił głosami 27 do 18. Droga okrętów jednak się nie zamknęła: Henry Eckford sprzedał Osmanom w 1831 przywieziony okręt, a amerykańscy rzemieślnicy pracujący w Aynalıkavak dali flocie okręty nowego typu. Traktat ten stał się dokumentem pierwszych obszernych stosunków państwa osmańskiego z państwem spoza Europy.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Zakończenie rządów mameluków w Bagdadzie", "7e1d38a3"], "d": ["Mahmud II, prowadzący politykę centralizacji, ogłosił buntownikiem namiestnika Bagdadu Dâvuda Paszę, który nie przysyłał żądanych pieniędzy i kazał zabić urzędnika przysłanego z centrum. Siły pod dowództwem Alego Rızâ Paszy po dziewięćdziesięciodniowym oblężeniu zajęły miasto, a mamelucy zostali niemal całkowicie zlikwidowani. W ten sposób półniezależne rządy mameluków, trwające od 1704, dobiegły końca, a Irak został ponownie związany bezpośrednio z centrum.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Założenie Mekteb-i Harbiye w koszarach Maçka", "bf31c7d9"], "d": ["Aby zapewnić Asâkir-i Mansûre-i Muhammediyye oficerów wyszkolonych na modłę europejską, w koszarach Maçka otwarto Mekteb-i Fünûn-ı Harbiyye. Uczniów uczono matematyki, kartografii, fortyfikacji i języków obcych; wkrótce wysłano uczniów do Wiednia i Paryża, wzmacniając kadry. Szkoła ta stała się miejscem narodzin tradycji oficerów wykształconych w szkołach w armii osmańskiej, a więc nowego pokolenia żołnierzy-intelektualistów, które miało pojawić się pod koniec XIX wieku.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Związanie Trypolitanii bezpośrednio z centrum — koniec dynastii Karamanlidów", "faabcb96"], "d": ["Wskutek sporów o tron w rodzie Karamanlidów i wzrostu nacisku europejskiego po zajęciu Algieru przez Francję w 1830 Bâbıâli interweniowało bezpośrednio w Trypolitanii. Flota wysłana ze Stambułu weszła do miasta, ostatni bej Karamanlidów został odwołany i sprowadzony do Stambułu, a ejalet oddano namiestnikowi mianowanemu przez centrum. Gdy 124-letni okres dynastii dobiegł końca, umocniono ostatni kawałek ziemi w Afryce Północnej, którym państwo osmańskie zarządzało bezpośrednio.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Zniesienie defterdarlıku i utworzenie Ministerstwa Finansów", "89f8125e"], "d": ["Urząd defterdara, głowy klasycznego osmańskiego ładu finansowego, został zniesiony i utworzono Ministerstwo Finansów (Maliye Nezâreti) na modłę europejską, a rozproszone skarbce zebrano w jednym ręku. W tym samym roku inne jednostki Bâbıâli również zreorganizowano pod nazwą nezâret, przechodząc do struktury nowoczesnej rady ministrów. To uregulowanie było jednym z najważniejszych kroków przygotowujących administracyjne zaplecze Edyktu Tanzimatu ogłoszonego rok później.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Osiedlenie się Anglików w Adenie", "ddbd556b"], "d": ["Anglia, opierając się na umowie handlowo-przyjaźni zawartej w 1802 z sułtanem Lahidżu Ahmedem b. Abd al-Karîmem, wysadziła wojsko w porcie Aden i objęła miasto kontrolą. Port, trzymający wlot Morza Czerwonego, stał się jako baza zaopatrzenia w węgiel na drodze do Indii kluczowym punktem brytyjskiej strategii imperialnej. Choć pretensje państwa osmańskiego do Jemenu trwały na papierze, jego faktyczne panowanie na wybrzeżu południowym już od tej daty nie wróciło.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Powrót na wybrzeże Tihamy: zajęcie Hudaydy, Zabîd i Mokha", "353982d2"], "d": ["Na wybrzeże Jemenu, które po wycofaniu się armii egipskiej w 1840 pozostało bez pana, wylądowały pod nadzorem szarifa Mekki siły pod dowództwem Tevfika Paszy i objęły zarządem osmańskim porty Hudajda, Zabîd i Mokha. Choć chciano pomaszerować aż do Sany, wobec oporu ludności wrócono do Hudajdy; w ten sposób wyżyny pozostały przy imamach zajdyckich, a panowanie osmańskie przez dwadzieścia trzy lata trwało jedynie w pasie Tihamy. Wnętrze Jemenu miało zostać odzyskane dopiero w 1872 w wyprawie Ahmeda Muhtara Paszy.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Konwencja z Baltalimanı: wspólna protekcja osmańsko-rosyjska nad Wołoszczyzną i Mołdawią", "d3bb22e9"], "d": ["Gdy rewolucje 1848 przeniosły się na Wołoszczyznę i Mołdawię, siły osmańskie i rosyjskie zajęły księstwa wspólnie. Konwencją podpisaną w Baltalimanı postanowiono, że wojewodowie będą mianowani nie w drodze wyboru, lecz przez sułtana na siedem lat, a oba państwa ustanowią w regionie wspólną kontrolę. Porozumienie, zachowując osmańskie zwierzchnictwo na papierze, przyznało Rosji faktyczne prawo współudziału i przyspieszyło oderwanie się księstw naddunajskich od Osmanów.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Sprawa uchodźców węgierskich: schronienie się Kossutha i towarzyszy u Osmanów", "1c7d7ef4"], "d": ["Po stłumieniu węgierskiej rewolucji 1848–1849 przez interwencję rosyjsko-austriacką Lajos Kossuth i tysiące węgiersko-polskich uchodźców schroniło się na ziemiach osmańskich. Austria i Rosja ostro zażądały wydania uchodźców; Bâbıâli, z poparciem Anglii i Francji, wydanie odrzuciło i osiedliło grupę w Kütahyi. Otoczenie Kossutha przebywało tu około osiemnastu miesięcy, a setki uchodźców przyjęły islam i weszły w służbę osmańską. Wydarzenie uznano za jedno z rzadkich zwycięstw dyplomatycznych, które podniosły prestiż Osmanów epoki Tanzimatu w europejskiej opinii publicznej.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Założenie Encümen-i Dâniş: pierwszej akademii osmańskiej w Stambule", "6fda1365"], "d": ["Encümen-i Dâniş, założona uchwałą Meclis-i Maârif-i Umûmiyye, jest pierwszą osmańską akademią nauk utworzoną w celu przygotowywania tureckich książek naukowych i podręczników. Została uroczyście otwarta 18 lipca 1851 w budynku Dârülmaârif; wśród jej członków, miejscowych i zagranicznych, był także Ahmed Cevdet Pasza. Choć trwała krótko, dzieła takie jak Târih Cevdeta Paszy i Kavâid-i Osmâniyye były plonem tej instytucji i uchodzą za kamień węgielny uczynienia z tureckiego języka nauki.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Zwycięstwo pod Oltenițą: pierwszy sukces osmański na froncie dunajskim", "a660ad2f"], "d": ["W początkowej fazie wojny krymskiej serdar-ı ekrem Ömer Lütfi Pasza przekroczył Dunaj i odparł pod Oltenițą siły rosyjskie z ciężkimi stratami. Zwycięstwo, zatrzymując natarcie rosyjskie zaraz na początku wojny, pokazało Europie siłę, jaką armia osmańska zyskała dzięki szkoleniu po Tanzimacie. Ten sukces przygotował psychologiczny grunt ułatwiający decyzję Anglii i Francji o przystąpieniu do wojny po stronie osmańskiej.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Traktat sojuszniczy z Anglią i Francją w Stambule", "04809278"], "d": ["Traktat sojuszniczy podpisany w wojnie krymskiej przeciw Rosji między państwem osmańskim a Anglią i Francją postanowił, że trzy państwa będą prowadzić wspólne działania, a sprzymierzeni nie zawrą odrębnego pokoju przed końcem wojny. W ten sposób państwo osmańskie po raz pierwszy w swej historii weszło w sojusz wojskowy z wielkimi państwami europejskimi jako równa strona. Ten traktat stworzył też prawną podstawę oficjalnego przyjęcia Osmanów do europejskiego systemu państw w Paryżu dwa lata później.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Utworzenie Şehremaneti Stambułu: pierwsza nowoczesna organizacja miejska", "be4af27f"], "d": ["Kryzys infrastrukturalny wywołany przez żołnierzy sprzymierzonych zgromadzonych w Stambule w czasie wojny krymskiej i rosnącą ludność obnażył niewystarczalność klasycznego zarządu miasta opartego na kadiasie. W Şehremaneti utworzonym według wzorów europejskich zebrano w jednym ręku sprawy czystości, cen urzędowych, kontroli targów i budownictwa; w następnym roku w Beyoğlu–Galata utworzono Szósty Okręg Miejski (Altıncı Daire-i Belediye) jako region pilotażowy. Ten krok uchodzi za początek nowoczesnego zarządu miejskiego w państwie osmańskim.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Traktat paryski: koniec wojny krymskiej i przyjęcie Osmanów do europejskiego systemu państw", "4aee0e2a"], "d": ["Na mocy traktatu paryskiego kończącego wojnę krymską państwo osmańskie zostało ogłoszone równoprawnym członkiem europejskiego prawa międzynarodowego, a jego integralność terytorialna objęta wspólną gwarancją wielkich mocarstw. Morze Czarne zneutralizowano, pretensje Rosji do protektoratu nad prawosławnymi poddanymi, uzyskane od Küczük Kajnardży, unieważniono, a południe Besarabii (kazy Kilia, Cahul, Izmaił i Bolgrad) oddano Mołdawii. Jednak ten sam traktat, czyniąc Edykt Islahat zobowiązaniem międzynarodowym, uchylił też drzwi do ingerencji w sprawy wewnętrzne.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Otwarcie Pałacu Dolmabahçe: przeniesienie centrum zarządu z Topkapı", "71ad26d0"], "d": ["Pałac zamówiony przez Abdülmecida w 1842 u rodziny Balyan został po czternastoletniej budowie otwarty, a centrum zarządu państwa przeniosło się z czterowiekowego Topkapı nad brzeg Bosforu. Pałac, dzięki europejskiemu stylowi, kryształowym schodom i Sali Muayede, stał się kamiennym wyrazem pretensji Tanzimatu do westernizacji. Jego ogromny koszt stał się jedną z najczęściej krytykowanych pozycji lat, w których osmańskie finanse weszły w spiralę zadłużenia zagranicznego.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Zjednoczenie Wołoszczyzny i Mołdawii pod rządami Cuzy: narodziny Rumunii", "baef4da5"], "d": ["W wyborach przeprowadzonych po traktacie paryskim oba księstwa wybrały pułkownika Alexandru Ioana Cuzę na wojewodę, dokonując faktycznego zjednoczenia. Choć Bâbıâli i Austria się temu sprzeciwiły, musiano uznać fakt dokonany poparty przez Francję. Ta unia, która na papierze pozostała zależna od Osmanów, miała w 1862 przyjąć nazwę Rumunii, a w 1877 jednostronnie ogłosić niepodległość; jest punktem zwrotnym w rozpadzie panowania osmańskiego nad Dunajem.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Wydarzenie w Kuleli: pierwsza próba zamachu stanu przeciw Abdülmecidowi w Stambule", "e3653b21"], "d": ["Tajne stowarzyszenie wojskowo-cywilne, oburzone polityką Tanzimatu i równością przyznaną niemuzułmanom przez Edykt Islahat, planując zdetronizować sułtana, zostało zdemaskowane na zebraniu w meczecie Kılıç Ali Paşa. Ponieważ oskarżonych sądzono w koszarach Kuleli, wydarzenie nosi tę nazwę; kary śmierci zamieniono na zesłanie. Uważa się je za pierwszą próbę przewrotu pałacowego podjętą przez organizację założoną z powodów ideologicznych w dziejach osmańskich.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Wojna domowa druzyjsko-maronicka na Górze Liban i wydarzenia w Damaszku", "5595fdd6"], "d": ["Starcia, które wybuchły w maju 1860 po zabiciu dwóch Druzów w pobliżu Sajdy, przerodziły się w najkrwawszą wojnę domową druzyjsko-maronicką w górach i w lipcu przeniosły się do Damaszku, kończąc się śmiercią tysięcy chrześcijan. Po lądowaniu wojsk francuskich Bâbıâli wysłało do regionu Fuada Paszę z nadzwyczajnymi uprawnieniami; przeprowadzono surową akcję karną. Wydarzenia dostarczyły powodu do interwencji europejskiej i stały się bezpośrednią przyczyną uzyskania przez Liban specjalnego statusu.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Początek wydawania Tercümân-ı Ahvâl: pierwsza prywatna gazeta turecka w Stambule", "24792957"], "d": ["Tercümân-ı Ahvâl, wydawana przez Agâha Efendiego, której redakcję objął Şinâsi, jest pierwszą gazetą turecką wydawaną bez poparcia państwa. We wstępie pierwszego numeru bronione było prawo ludu do wypowiadania się w swoich sprawach, a gazeta, drukując w odcinkach Şair Evlenmesi Şinâsiego, uchyliła też drzwi nowoczesnej literaturze tureckiej. Narodziny pojęcia opinii publicznej i prasy opozycyjnej w państwie osmańskim wiąże się z tą datą.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Regulamin Góry Libanu: uprzywilejowany status mutasarrifatu dla Libanu", "bf375603"], "d": ["Regulamin przygotowany po masakrach 1860 pod naciskiem wielkich mocarstw uczynił Górę Liban uprzywilejowanym mutasarrifatem podległym bezpośrednio Bâbıâli, zarządzanym przez radę administracyjną ukształtowaną według równowagi między wyznaniami. Zastrzeżono, że mutasarrif ma być poddanym osmańskim chrześcijaninem katolikiem, a jego mianowanie ma być przedstawiane do zatwierdzenia wielkim mocarstwom; pierwszym mutasarrifem został Dâvud Pasza. Ten ład miał trwać do 1915 i stanowić zalążek nowoczesnego państwa libańskiego.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Śmierć Abdülmecida i wstąpienie na tron sułtana Abdülaziza", "27204d7c"], "d": ["Po śmierci Abdülmecida, który w dwudziestodwuletnim panowaniu podpisał edykty Tanzimatu i Islahat, a który uległ gruźlicy, na tron wstąpił jego brat Abdülaziz. Nowy sułtan w pierwszych latach dawał nadzieję środkami oszczędnościowymi i prostym trybem życia; uczynił z floty jedną z liczących się potęg świata. Jednak pod koniec jego panowania ciężki dług zagraniczny, bankructwo z 1875 i powstania bałkańskie nagromadziły się, przygotowując grunt pod ruch detronizacyjny z 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Przyjęcie przez zjednoczone księstwa nazwy Rumunia", "d960e3fc"], "d": ["Wołoszczyzna i Mołdawia, faktycznie zjednoczone wskutek podwójnego wyboru Cuzy w 1859, zebrały w 1862 swe zgromadzenia i rządy w Bukareszcie pod jednym dachem i oficjalnie przyjęły nazwę Rumunia. Choć państwo osmańskie prawnie zachowało status zwierzchnika i roczny podatek, faktycznie utraciło kontrolę nad księstwem. Koniec czterowiekowych wpływów osmańskich na północ od Dunaju symbolizuje ta data.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Przyłączenie Suakinu, Massawy i Dahlaku do Egiptu", "a0924860"], "d": ["Massawa, nadana w 1846 przez sułtana Abdülmecida wicekrólowi Egiptu Mehmedowi Alemu Paszy wraz z Suakinem jako sâliyâne (przydział dochodów), została za wicekróla İsmâila Paszy włączona wraz z Dahlakiem i Suakinem do posiadłości egipskich i zorganizowana ze statusem kaymakamatu. W ten sposób te trzy porty na afrykańskim wybrzeżu Morza Czerwonego, pozostając prawnie ziemią osmańską, przeszły w sensie administracyjnym bezpośrednio od Bâbıâli do Kairu — weszły do tej samej warstwy zależnej co sąsiedni Egipt i Sudan.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Początek powstania kreteńskiego (1866–1869)", "3679b861"], "d": ["Szerokie powstanie, które wybuchło na wyspie przy jawnym poparciu Grecji, po raz pierwszy uczyniło z żądania enosis (przyłączenia do Grecji) Greków kreteńskich sprawę międzynarodową. Trwająca trzy lata ciężka wojna górska przyniosła armii osmańskiej ciężkie straty i wywołała wielki oddźwięk w opinii europejskiej. Powstanie udało się wygasić dopiero w 1868, gdy Âlî Pasza udał się na wyspę i wprowadził w życie regulamin przyznający szerokie przywileje.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Wycofanie ostatnich garnizonów osmańskich z Belgradu i twierdz serbskich", "b34217db"], "d": ["Pod naciskiem wielkich mocarstw i uporczywym żądaniem księcia Mihaila Bâbıâli zgodziło się opuścić ostatnie bazy wojskowe, które pozostały w Serbii; 18 kwietnia 1867 zdjęto sztandar osmański w twierdzy Belgrad i klucze wręczono księciu. W ten sposób faktyczna obecność wojskowa Osmanów trwająca od 1521 dobiegła końca, a ostatnia wielka przeszkoda na drodze Serbii ku niepodległości została usunięta. Zwierzchnictwo sułtana sprowadzono do sprawy jedynie symbolicznego sztandaru i podatku.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Nadanie wicekrólom Egiptu tytułu chedywa", "09e10c12"], "d": ["W wyniku intensywnego lobbingu İsmâila Paszy z trzeciego pokolenia dynastii z Kawali i pieniędzy, które przelewał do Stambułu, namiestnikowi Egiptu nadano tytuł chedywa (hidiv), podkreślający jego wyższość nad innymi namiestnikami. W tych samych latach zmieniono też zasadę sukcesji tak, by przechodziła z ojca na syna, a Egiptowi przyznano uprawnienia o charakterze suwerennym, takie jak zadłużanie się za granicą, nadawanie odznaczeń i utrzymywanie konsulatów. Te kroki są pierwszym ogniwem łańcucha przyspieszającego prawne oderwanie Egiptu od Osmanów.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Regulamin Kreteński: szerokie przywileje administracyjne dla wyspy", "12052262"], "d": ["Aby zakończyć trzyletnie powstanie, wielki wezyr Âlî Pasza osobiście udał się na wyspę, a wydany za zgodą sułtana regulamin przyznał Kreteńczykom mieszane rady administracyjne, sądy lokalne, używanie języka greckiego w urzędowych czynnościach i ulgi podatkowe. To uregulowanie utrzymało panowanie osmańskie na wyspie przez następne trzydzieści lat. Jednak przywileje przyznane ludności chrześcijańskiej osłabiły pozycję muzułmańskich Kreteńczyków i zasiały ziarno kryzysu z lat 1896–1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Otwarcie Şûrâ-yı Devlet: utworzenie osmańskiej Rady Stanu", "70b16497"], "d": ["Irade z 5 marca 1868 podzieliło Meclis-i Ahkâm-ı Adliyye na dwie części: sprawy administracyjno-ustawodawcze przekazano Şûrâ-yı Devlet, a sądowe Dîvân-ı Ahkâm-ı Adliyye; instytucję otwarto uroczyście w Bâbıâli, a pierwszym jej przewodniczącym został Midhat Pasza. Powierzono jej przygotowywanie projektów ustaw, rozstrzyganie sporów administracyjnych i prowadzenie postępowań wobec urzędników. Dzięki mieszanej strukturze członków muzułmańskich i niemuzułmańskich uchodzi za pierwsze instytucjonalne zastosowanie idei podziału władz w państwie osmańskim.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Otwarcie Kanału Sueskiego: skrócenie drogi do Indii przez Egipt", "377ccd04"], "d": ["Budowa rozpoczęta w 1859 trwała dziesięć lat, a kanał o długości 163 kilometrów łączący Morze Śródziemne z Morzem Czerwonym oddano do użytku w wielkiej uroczystości. Gdy droga łącząca Europę z Indiami skróciła się o tysiące mil, Egipt nagle stał się kluczowym punktem światowego handlu. Ta wartość geostrategiczna miała stać się główną przyczyną okupacji Egiptu przez Anglię trzynaście lat po otwarciu kanału; dług, jaki kanał nałożył na Egipt, miał zaś doprowadzić chediwat do bankructwa.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Utworzenie Egzarchatu Bułgarskiego: oddzielenie Kościoła bułgarskiego od Fenaru", "33a8272c"], "d": ["Ferman sułtański utworzył odrębny, samodzielny Kościół bułgarski (egzarchat), niezależny od Patriarchatu Greckiego, a to, które kazy będą podległe egzarchatowi, pozostawiono głosowaniu ludności. Bâbıâli, które uczyniło ten krok, by złamać wpływy greckie, osiągnęło skutek odwrotny: Kościół stał się zorganizowanym ośrodkiem bułgarskiej tożsamości narodowej i bułgarskich pretensji do Macedonii. W ten sposób położono instytucjonalny grunt pod rywalizację bułgarsko-grecko-serbską na Bałkanach i powstania z 1876.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Objęcie Asiru zarządem bezpośrednim", "4559e099"], "d": ["Gdy wraz z otwarciem Kanału Sueskiego wzrosła strategiczna wartość Morza Czerwonego, zrozumiano, że gór Asiru pośrodku lądowej drogi do Jemenu nie można pozostawić bez kontroli. Siły Redifa Paszy, który wyruszył na wyprawę jemeńską, weszły do Abhy i związały region bezpośrednio z zarządem osmańskim; utworzono sandżak Asir. Wskutek górzystej geografii i wpływów Idrisidów to panowanie nigdy nie ustabilizowało się w pełni.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Wyprawa Midhata Paszy do Nadżdu: ponowne ustanowienie panowania osmańskiego w Al-Hasa", "7db51461"], "d": ["Namiestnik Bagdadu Midhat Pasza, wykorzystując spór o tron w rodzie Saudów, wysłał wojsko na zachodni brzeg Zatoki Perskiej i związał region Al-Hasa pod nazwą sandżaku Nadżd z wilajetem Basra. Abdullah b. Fajsal został mianowany mutasarrifem i panowanie osmańskie zostało ustanowione na papierze. Wyprawa miała na celu powstrzymanie rozszerzania się wpływów brytyjskich w Zatoce i w tym samym roku doprowadziła także do objęcia Kataru kontrolą osmańską.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Śmierć wielkiego wezyra Âlîego Paszy: koniec kadry Tanzimatu", "1cf0141c"], "d": ["Wraz ze śmiercią Âlîego Paszy, który po śmierci Fuada Paszy w 1869 dźwigał samotnie politykę Tanzimatu, wyczerpało się pokolenie mistrzów dyplomacji, którzy przez trzydzieści lat kierowali polityką zagraniczną państwa. Prorosyjskie i samowolne rządy Mahmuda Nedima Paszy, który przyszedł na jego miejsce, umocniły osobiste panowanie Abdülaziza. W ciągu pięciu lat po śmierci Âlîego Paszy skarb zbankrutował, Bałkany powstały, a zmiana panowania stała się nieunikniona.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Ustanowienie kontroli osmańskiej w Katarze", "3b453165"], "d": ["Na zaproszenie szejka Kāsima b. Sânîego, naciskanego przez Anglików, siły osmańskie wylądowały na półwyspie Katar, a jesienią 1871 zapewniono w regionie kontrolę osmańską. Katar został zorganizowany jako kaza podległa sandżakowi Nadżd, a szejka mianowano kaymakamem. Ten ruch był najbardziej konkretnym zyskiem wysuniętej polityki prowadzonej przez Midhata Paszę w Zatoce przeciw Anglii; sztandar osmański powiewał na półwyspie do 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Ferman o sukcesji w Tunisie — bejlik dla rodziny Mehmeda Sâdıka Paszy", "1509ebb0"], "d": ["Na mocy fermanu wydanego dzięki zabiegom Hayreddina Paszy, wysłanego do Stambułu przez beja Tunisu Mehmeda Sâdıka Paszę, który wykorzystał klęskę Francji w starciu z Prusami, Tunis został nadany w drodze dziedziczenia Mehmedowi Sâdıkowi Paszy i jego potomstwu, pozostając podległym bezpośrednio Stambułowi. Bez zgody sułtana nie miano prowadzić rokowań wojennych ani pokojowych, żadnej ziemi z kraju nie miano oddawać innym, a żądania osmańskie dotyczące żołnierzy miały być spełniane. Francja ferman nie uznała; po dziesięciu latach zajęła Tunis.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Zajęcie Sany: ponowne ustanowienie władzy osmańskiej w Jemenie", "978e20a0"], "d": ["Gdy wraz z otwarciem Kanału Sueskiego wzrosła strategiczna wartość Morza Czerwonego, Bâbıâli wysłało do Jemenu armię fırka-i ihtiyâtiyye pod dowództwem Ahmeda Muhtara Paszy. Wraz z zajęciem Sany władza państwa została ponownie ustanowiona w wnętrzu Jemenu, faktycznie utraconym od dwóch stuleci, a region uczyniono wilajetem. Jednak walka z imamami zajdyckimi nigdy się nie skończyła; powstania z 1891, 1898 i 1904 utworzyły najdroższy i najdłużej trwający front wewnętrzny Osmanów. W tym samym dniu przyłączono także inne miejscowości: Sana, Ta'izz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Początek powstania w Hercegowinie: ponowne rozpalenie kwestii wschodniej", "571b18ec"], "d": ["Powstanie chrześcijańskich chłopów wokół Nevesinje, wywołane ciężkimi podatkami i uciskiem ajanów, szybko rozszerzyło się na całą Hercegowinę i było zasilane ochotnikami z Serbii i Czarnogóry. Powstanie, które pociągnęło za sobą narzucanie reform przez Austrię i Rosję, wywołało w następnym roku powstania bułgarskie i wypowiedzenia wojny przez Serbię i Czarnogórę. W ten sposób pękło pierwsze ogniwo wielkiego łańcucha prowadzącego do wojny 93 i utraty Bałkanów w traktacie berlińskim.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Bankructwo finansów osmańskich: obniżenie spłat długu zagranicznego o połowę", "2cac2fa5"], "d": ["Pożyczki zaciągane kolejno od 1854, wydatki wojny krymskiej, budowy pałaców i głód w Anatolii z lat 1873–74 zamieniły deficyt budżetowy w przepaść przekraczającą pięć milionów lir. Rząd Mahmuda Nedima Paszy, ogłaszając, że spłaty odsetek i kapitału długu zostaną na pięć lat obniżone o połowę, faktycznie ogłosił moratorium. Ta decyzja, wywołująca wielką reakcję na giełdach europejskich, zapoczątkowała proces, który miał zakończyć się po sześciu latach dekretem Muharrema i utworzeniem Administracji Długu Publicznego (Düyûn-ı Umûmiyye).", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Detronizacja Murada V i wstąpienie na tron Abdülhamida II", "cffb2271"], "d": ["Murad V, który wstąpił na tron po detronizacji Abdülaziza, stał się niezdolny do sprawowania władzy wskutek zdrowia psychicznego nadwątlonego śmiercią stryja i wydarzeniem Çerkes Hasana; w ciągu dziewięćdziesięciotrzydniowego panowania jedynie przez siedem dni jego osąd był sprawny. Zdetronizowany na mocy fatwy szejhülislama, został zastąpiony przez brata Abdülhamida II. Nowy sułtan wstąpił na tron, obiecawszy Midhatowi Paszy, że ogłosi monarchię konstytucyjną; rozpoczynała się epoka mająca trwać trzydzieści trzy lata.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Konferencja w Stoczni (Tersane): narzucenie przez wielkie mocarstwa reform bałkańskich", "b5006a2c"], "d": ["Konferencja zebrana w Stambule przez wielkie mocarstwa w celu rozwiązania kryzysu bałkańskiego zażądała podziału Bułgarii na dwa autonomiczne wilajety i wprowadzenia w Bośni i Hercegowinie reform pod kontrolą międzynarodową. Bâbıâli, ogłaszając w dniu otwarcia konferencji salwami armatnimi Kanûn-ı Esâsî, próbowało odpowiedzieć na narzucane żądania reformą konstytucyjną. Delegaci, uznawszy to za zwłokę, rozeszli się 20 stycznia 1877; po czterech miesiącach Rosja wypowiedziała wojnę.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Otwarcie pierwszego Meclis-i Meb'ûsan w Dolmabahçe", "429bb279"], "d": ["115 posłów wybranych zgodnie z Kanûn-ı Esâsî zebrało się po raz pierwszy 19 marca 1877 w uroczystości w Sali Muayede Pałacu Dolmabahçe; w dziejach osmańskich rozpoczął się okres zgromadzenia przedstawicielskiego. Posłowie muzułmańscy i niemuzułmańscy ostro przesłuchiwali rząd, dyskutowali o prowadzeniu wojny i odpowiedzialności ministrów. Ta śmiała opozycja miała stać się główną przyczyną skrócenia życia zgromadzenia.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Początek obrony Plewny: opór Gazi Osmana Paszy", "0e04a878"], "d": ["Osman Pasza, który w wojnie 93 maszerował z Widynia do Plewny, by przeciąć armii rosyjskiej, która przekroczyła Dunaj, drogę do Stambułu, umocnił miasteczko szańcami i okopami i rozpoczął legendarną, pięciomiesięczną obronę. Trzy kolejne wielkie szturmy rosyjsko-rumuńskie odparto z ciężkimi stratami, a armia, którą osobiście kierował car Aleksander II, została zmuszona do oblężenia. Plewna przeszła do historii jako najświetniejszy sukces obronny armii osmańskiej w XIX wieku.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Upadek Plewny: załamanie frontu dunajskiego", "185e7602"], "d": ["Osman Pasza, któremu w pięciomiesięcznym oblężeniu skończyła się żywność, podjął wypad przez rzekę Vit; ranny i wzięty do niewoli, doprowadził do poddania miasta. Dowódcy rosyjscy powitali pojmanego paszę, zwracając mu szablę, a Osmanowi Paszy nadano tytuł „Gazi”. Wraz z upadkiem Plewny otwarto drogę armii rosyjskiej; w ciągu dwóch miesięcy padły Sofia, Płowdiw i Edirne, a rosyjskie straże przednie dotarły do Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Zajęcie Sofii przez siły rosyjskie", "ef369d22"], "d": ["Armia rosyjska, która po upadku Plewny przekroczyła Bałkany, wkroczyła do pozostawionej bez obrony Sofii. Miasto nie miało już wrócić pod zarząd osmański; pod koniec 1878 miało stać się częścią autonomicznego Księstwa Bułgarii, a w 1879 jego faktyczną stolicą. Na mapie Sofia od tej daty wychodzi spod bezpośredniego zarządu osmańskiego i przechodzi pod tymczasową okupację rosyjską, a następnie pod autonomiczny zarząd bułgarski.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Rozejm w Edirne: zamilknięcie broni w wojnie 93", "1f899180"], "d": ["Gdy Sofia, Płowdiw i Edirne padły kolejno, a armia rosyjska stanęła nad wybrzeżem Marmary, Bâbıâli musiało prosić o rozejm. Rozejm podpisany w Edirne narzucił Osmanom wstępne warunki pokojowe, takie jak autonomia Bułgarii, niepodległość Czarnogóry, Serbii i Rumunii oraz ciężkie odszkodowanie wojenne. Te warunki miały po miesiącu zamienić się w tekst traktatu w San Stefano.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Zawieszenie Meclis-i Meb'ûsan przez Abdülhamida II na czas nieokreślony", "e770b540"], "d": ["Wobec ostrej krytyki posłów, którzy uznali rząd i pałac za odpowiedzialnych za katastrofalny wynik wojny, Abdülhamid II, powołując się na uprawnienia przyznane mu przez Kanûn-ı Esâsî, zawiesił zgromadzenie na czas nieokreślony. Pierwszy parlament osmański, który działał około jedenastu miesięcy, w ten sposób się zamknął i rozpoczęła się epoka istibdadu mająca trwać trzydzieści lat. Zgromadzenie mogło zebrać się ponownie dopiero po rewolucji 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Traktat w San Stefano: projekt Wielkiej Bułgarii", "2c7cc611"], "d": ["Traktat w San Stefano, kończący wojnę 93, tworzył ogromną autonomiczną Bułgarię sięgającą Morza Egejskiego i obejmującą Macedonię; uznawał niepodległość Serbii, Czarnogóry i Rumunii; oddawał Rosji Kars, Ardahan, Batum i Doğubayazıt oraz nakładał niemożliwe do spłacenia odszkodowanie wojenne. Ten tekst, sprowadzający Rosję nad Morze Śródziemne, wywołał gwałtowną reakcję Anglii i Austrii. Nie został wprowadzony w życie i w ciągu czterech miesięcy został na nowo uregulowany Kongresem Berlińskim; mimo to pozostał dokumentem ogłaszającym koniec osmańskiej Rumelii.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Oddanie Karsu, Ardahanu i Batumu Rosji — elviye-i selâse", "99bdfad2"], "d": ["Na mocy traktatu berlińskiego państwo osmańskie oddało Kars, Ardahan i Batum Rosji w zamian za część odszkodowania wojennego; Doğubayazıt i dolina Eleşkirt, oddane Rosji w San Stefano, pozostały natomiast przy Osmanach. Choć Batum oddano jako port wolny, ten status mógł utrzymać tylko do 1886. Rosjanie uczynili z Karsu prowincję podległą generalnej gubernii Zakaukazia z ośrodkiem w Tyflisie; ludność z elviye-i selâse, sięgająca 100 000, musiała wyemigrować w stronę Erzurumu. Tym samym traktatem Południowa Besarabia (Kilia, Cahul, Bolgrad) została zwrócona Rosji przez Rumunię.", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Okupacja Bośni i Hercegowiny oraz Novi Pazaru przez Austro-Węgry", "e5f901df"], "d": ["Opierając się na uprawnieniach nadanych traktatem berlińskim, armie austro-węgierskie wkroczyły do Bośni; choć rząd osmański zgodził się nie stawiać oporu, miejscowa ludność muzułmańsko-prawosławna w Sarajewie i Mostarze chwyciła za broń i przez trzy miesiące okazywała zacięty opór. Okupację udało się zakończyć dopiero 20 października 1878. Prawne zwierzchnictwo sułtana trwało na papierze do 1908, lecz czterowiekowa osmańska Bośnia została faktycznie utracona i rozpoczęła się wielka fala emigracji muzułmanów. W tym samym dniu utracono także inne miejscowości: Banja Luka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Dekret Muharrema i utworzenie Administracji Długu Publicznego (Düyûn-ı Umûmiyye)", "02b7cc03"], "d": ["Rokowania prowadzone z przedstawicielami państw wierzycielskich po bankructwie z 1875 zakończyły się dekretem z 28 muharrema 1299 (20 grudnia 1881): kapitał długu obniżono o ponad połowę, w zamian najbardziej wydajne pozycje dochodowe, takie jak opłaty od soli, tytoniu, jedwabiu, stempli i ryb, przekazano bezpośrednio Administracji Długu Publicznego zarządzanej przez wierzycieli. Ta administracja, zatrudniająca tysiące urzędników, przekształciła się w odrębną organizację finansową wewnątrz państwa. Data ta jest uważana za moment, w którym osmańska niezależność finansowa faktycznie się skończyła.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — jedyny port, który nie wpadł w ręce Mahdiego", "5a37b198"], "d": ["Gdy od lutego 1884 wszystkie regiony wschodniego Sudanu poza Suakinem przeszły pod panowanie Muhammada Ahmada al-Mahdiego, port się utrzymał dzięki wojskowej ochronie trzybatalionowych sił brytyjskich pod dowództwem generała Grahama. Był to początek okresu, w którym rozeszły się stan faktyczny i prawny: choć wybrzeże znajdowało się faktycznie pod brytyjską kontrolą wojskową, jego więź administracyjna miała w 1885 zostać odebrana Egiptowi i związana bezpośrednio z wilajetem Jemen, czyli z Bâbıâli — ten ład trwał aż do zajęcia Zeili przez Francję w 1888.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Zabicie Midhata Paszy w więzieniu w Ta'if", "f4562261"], "d": ["Midhat Pasza, architekt Kanûn-ı Esâsî i symbol I Monarchii Konstytucyjnej, uznany za winnego przed Sądem Yıldız w sprawie śmierci Abdülaziza, miał karę śmierci zamienioną na zesłanie i został wysłany do Ta'if. Według zapisu TDV w nocy z 7 na 8 maja 1884 został uduszony w swojej celi, a jako oficjalną przyczynę ogłoszono chorobę „şîrpençe”. Jego śmierć stała się symbolem likwidacji opozycji konstytucyjnej w epoce Abdülhamida II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Przyznanie Niemcom koncesji na kolej Haydarpaşa–Ankara", "5705b163"], "d": ["Z woli sułtana koncesję na budowę i eksploatację linii Haydarpaşa–Ankara nadano bankierowi Alfredowi von Kaulla, reprezentującemu Deutsche Bank, i założono Towarzystwo Kolei Anatolijskich. Ta koncesja była punktem zwrotnym, który w osmańskim transporcie i polityce zagranicznej złamał monopol angielsko-francuski i umocnił wpływy niemieckie. Po jedenastu latach, wraz z koncesją na linię bagdadzką nadaną temu samemu towarzystwu, miało narodzić się marzenie o „Berlin–Bagdad”, które stało się jedną z głównych osi wielkiej rywalizacji mocarstw przed I wojną światową.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Założenie Towarzystwa Jedności Osmańskiej (İttihâd-ı Osmânî) w Stambule", "b7187939"], "d": ["Czterech uczniów Wojskowej Szkoły Medycznej założyło jako tajną organizację przeciw rządom istibdadu Towarzystwo Jedności Osmańskiej; ta struktura wkrótce przekształciła się w Komitet Jedności i Postępu, który miał zebrać pod swym dachem wszystkie elementy opozycyjne ruchu Młodych Turków. Organizacja oparta na zasadzie komórek połączyła się z emigrantami w Europie i oficerami w Salonikach. Kadra, która w 1908 miała wymusić ogłoszenie II Monarchii Konstytucyjnej, a po 1913 samodzielnie rządzić państwem, wyszła z tej małej komórki uczniowskiej.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Napad na Bank Osmański: akcja taszników w Galacie", "08b3095f"], "d": ["Uzbrojona grupa organizacji ormiańskiej Taszniak zajęła w Galacie siedzibę główną Banku Osmańskiego i wzięła zakładników, grożąc wysadzeniem budynku, aby zwrócić uwagę Europy na sprawę ormiańską. Kryzys zakończył się wskutek interwencji ambasadorów, w zamian za wywiezienie akcjonistów z kraju statkiem. Krwawe wydarzenia w Stambule w dniach następujących po napadzie okazały się rozstrzygające dla przekształcenia sprawy ormiańskiej w dźwignię interwencji międzynarodowej.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Początek wojny osmańsko-greckiej 1897: front tesalski", "33e490ab"], "d": ["Wobec wysadzenia przez Grecję floty i wojska na Krecie oraz napadów band na granicy Rumelii państwo osmańskie wypowiedziało wojnę. Armia osmańska wyszkolona przez niemiecką misję reformatorską szybko postępowała w Tesalii i w ciągu miesiąca zajęła Yenişehir, Çatalca i Domokos; armia grecka się rozpadła. Po interwencji wielkich mocarstw zdobyte ziemie zwrócono, lecz wojna pozostała jedynym rozstrzygającym zwycięstwem wojskowym epoki Abdülhamida II i nie zdołała zapobiec faktycznej utracie Krety.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Przyznanie Niemcom koncesji na linię Konya–Bagdad", "fd8b6cbd"], "d": ["Po wizycie cesarza Wilhelma II w Stambule i Damaszku w 1898 Towarzystwu Kolei Anatolijskich przyznano wstępną koncesję na linię z Konyi do Bagdadu i Basry. Projekt Kolei Bagdadzkiej oznaczał dla Osmanów wzmocnienie centralnej kontroli nad prowincjami arabskimi, a dla Niemiec dotarcie do Zatoki Perskiej. Projekt, któremu gwałtownie sprzeciwiły się Anglia i Rosja, stał się jedną z najbardziej spornych kwestii imperialnej rywalizacji prowadzącej do I wojny światowej.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Początek budowy Kolei Hidżaskiej w Damaszku", "62f58f68"], "d": ["Linię, którą nakazało irade Abdülhamida II z 2 maja 1900, rozpoczęto budować 1 września 1900 w oficjalnej uroczystości w Damaszku. Projekt zrealizowany wyłącznie dzięki datkom zebranym w świecie islamu i pracy osmańskich inżynierów-żołnierzy skrócił podróż pielgrzymów z Damaszku do Medyny z czterdziestu do pięciu dni. Było to zarówno dzieło prestiżowe umacniające duchowy autorytet kalifatu, jak i strategiczna inwestycja wzmacniająca kontrolę wojskową nad Hidżazem.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Program z Mürzsteg: międzynarodowa kontrola reform w Macedonii", "4c7464da"], "d": ["Po powstaniu w Ilindenu cesarze Rosji i Austrii spotkali się w Mürzsteg i przygotowali nowy pakiet reform dla Macedonii. Program przewidywał umieszczenie przy osmańskim generalnym inspektorze dwóch obcych agentów cywilnych, reorganizację żandarmerii przez oficerów europejskich oraz zmianę granic administracyjnych na zasadzie narodowościowej. Choć Bâbıâli stawiało opór, powołując się na naruszenie praw suwerennych, wobec wspólnego nacisku musiało się zgodzić; program stał się jednym z podstawowych czynników przyspieszających organizowanie się unionistów wśród młodych oficerów.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Śmierć Murada V", "396659a7"], "d": ["Murad V, który w 1876 pozostał na tronie około trzech miesięcy i został zdetronizowany, po próbach przywrócenia go na tron żył dwadzieścia osiem lat jako więzień pod ścisłą ochroną i zmarł na cukrzycę. Został pochowany w Cedîd Havâtîn Türbesi w Yenicami obok matki. Przeszedł do historii jako sułtan osmański, który najkrócej pozostał na tronie.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Utrata Sany na rzecz imama Yahyâ", "e7f876cb"], "d": ["Powstanie zajdyckiego imama Yahyâ Hamîdüddina, rozpoczęte w 1904, zakończyło się w kwietniu 1905 upadkiem Sany po oblężeniu; miasto wyszło spod zarządu osmańskiego, a w czasie oblężenia wybuchły głód i epidemia. Górzysta geografia Jemenu, długość linii zaopatrzenia i lokalna legitymacja imamatu zajdyckiego od początku czyniły panowanie osmańskie tu kruchym. Miasto miało po pięciu miesiącach zostać odzyskane za cenę ciężkich strat, lecz problem Jemenu nie miał zamknąć się do 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Zamach w Yıldız: atak bombowy na Abdülhamida II", "1ee2e1a6"], "d": ["Organizacja Taszniak dokonała zamachu, podkładając bombę z zegarem w landzie, gdy sułtan wychodził z piątkowego selamlıku; kilkuminutowe spóźnienie Abdülhamida, który rozmawiał z szejhülislamem, uratowało mu życie. W wybuchu zginęły dwadzieścia sześć osób, a ponad pięćdziesiąt zostało rannych. Wydarzenie jeszcze bardziej zaostrzyło obsesję sułtana na punkcie bezpieczeństwa i rządy istibdadu oparte na organizacji szpiegowskiej; stało się też tematem wiersza Tevfika Fikreta „Bir Lahza-i Taahhur”.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Odzyskanie Sany: stłumienie powstania imama Yahyâ", "dec3b8f9"], "d": ["Powstanie rozpoczęte w 1904 pod wodzą zajdyckiego imama Yahyâ zakończyło się w kwietniu 1905 upadkiem Sany, a w mieście wybuchły głód i epidemia. Armie wzmocnienia pod dowództwem Alego Rızâ Paszy i Ahmeda Feyziego Paszy, w akcji prowadzonej od 15 lipca do 1 września 1905, wspieranej także przez siły w Ta'izz, odzyskały miasto za cenę ciężkich strat i stłumiły powstanie. Wyprawa jemeńska przyniosła armii osmańskiej dziesiątki tysięcy strat i olbrzymie brzemię finansowe; wśród oficerów w Rumelii strach przed „zesłaniem do Jemenu” należał do głównych skarg podsycających organizowanie się unionistów.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Zebranie pierwszego Meclis-i Meb'ûsan II Monarchii Konstytucyjnej", "e7fd2716"], "d": ["Zgromadzenie utworzone w dwustopniowych wyborach po trzydziestoletniej przerwie zostało otwarte 17 grudnia 1908 przemówieniem sułtana, a jego przewodniczącym wybrano przywódcę ruchu Młodych Turków Ahmeda Rızâ Beja. Zgromadzenie złożone z posłów tureckich, arabskich, albańskich, greckich, ormiańskich i żydowskich było ostatnią wielką próbą ideału osmanizmu. Jednak niepodległość Bułgarii, aneksja Bośni i ogłoszenie przyłączenia Krety do Grecji zacieniły ten optymizm jeszcze przed otwarciem zgromadzenia.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Armia Akcji i detronizacja Abdülhamida II: wstąpienie na tron Mehmeda V Reşada", "6a65a704"], "d": ["Armia Akcji, która po wydarzeniu 31 marca wyruszyła z Salonik, wkroczyła do Stambułu w nocy z 22 na 23 kwietnia czterema kolumnami, a 24 kwietnia poddał się Pałac Yıldız. Meclis-i Umûmî-i Millî postanowiło 27 kwietnia o detronizacji Abdülhamida II; sułtana wysłano do Salonik, a na jego miejsce wprowadzono na tron brata Mehmeda V Reşada. Trzydziestotrzyletnie rządy osobiste w ten sposób się skończyły, lecz zajęła ich miejsce nowa epoka, w której sułtan stał się symbolem, a Komitet Jedności i Postępu rządził przy poparciu armii.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Powstanie albańskie: zbrojny opór w Kosowie i Szkodrze", "93ed30c6"], "d": ["Scentralizowana polityka podatkowa rządu unionistycznego, kampania zbierania broni i spór o alfabet łaciński poderwały do powstania plemiona albańskie, uważane dotąd za jeden z elementów najbardziej wiernych państwu. Choć armia pod dowództwem Mahmuda Şevketa Paszy stłumiła powstanie surowo, niepokój rozgorzał na nowo w 1911 i 1912. Te powstania zarówno nadwątliły armię osmańską w przededniu wojny bałkańskiej, jak i przyspieszyły narodziny albańskiego ruchu narodowego.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Traktat z Ouchy: oddanie Trypolitanii i Bengazi Włochom", "4ffa1fd2"], "d": ["Bâbıâli, które wobec przygotowań wojennych państw bałkańskich nie mogło zdecydować się na starcie na dwóch frontach, podpisało w szwajcarskiej miejscowości Ouchy tajny pokój z Włochami i opuściło Trypolitanię i Bengazi. Państwo osmańskie utraciło w ten sposób ostatnią ziemię w Afryce; w zamian obiecano zwrot zajętych przez Włochy Rodos i Dodekanezu, lecz obietnicy tej nigdy nie dotrzymano. Gdy podpisywano traktat, wojna bałkańska już się rozpoczęła. Wraz z tym wydarzeniem Murzuk (Fezzan), Ghat, Sebha, Ubari, Tirghan (Traghan), Zawila i al-Qatrun (Fezzan (sandżak wilajetu Trypolitanii)) przeszły pod zarząd włoski.", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Okupacja Limnos przez Grecję", "9555af1d"], "d": ["W I wojnie bałkańskiej flota grecka zajęła Limnos; port Mudros na wyspie stał się bazą do blokady Dardaneli. Wyspa została oddana Grecji w Lozannie (24 lipca 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Okupacja Thasos przez Grecję", "6c03c7f0"], "d": ["W I wojnie bałkańskiej Grecja zajęła Thasos i Samotrakę.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Okupacja Samotraki przez Grecję", "911e82a3"], "d": ["W I wojnie bałkańskiej Grecja zajęła Samotrakę.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Okupacja Lesbos przez Grecję", "6b2b07ba"], "d": ["Flota grecka wylądowała na Lesbos; wyspa została zajęta pod koniec I wojny bałkańskiej przez armię i flotę greckie. Konferencja Londyńska (maj 1913) potwierdziła ten stan.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Greckie lądowanie na Chios", "901c6539"], "d": ["W I wojnie bałkańskiej, po zbombardowaniu Chios 7 kwietnia 1912, Grecy wylądowali na wyspie; garnizon osmański poddał się 3 stycznia 1913. Wyspa została oddana Grecji traktatem lozańskim (24 lipca 1923).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Zabicie wielkiego wezyra Mahmuda Şevketa Paszy w zamachu w Stambule", "68e60e63"], "d": ["Mahmud Şevket Pasza, mianowany wielkim wezyrem po napadzie na Bâb-ı Âli, został zabity ogniem otwartym do jego powozu koło Çarşıkapı w drodze do Ministerstwa Wojny. Komitet Jedności i Postępu, zrzucając winę za zamach na opozycję, rozpoczął szeroką falę aresztowań i egzekucji, a Partia Wolności i Porozumienia została faktycznie zlikwidowana. Wraz z tym wydarzeniem ostatecznie ustanowiono jednopartyjną dyktaturę unionistów opartą na trójce Enver–Talat–Cemal.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Początek II wojny bałkańskiej: spór sprzymierzeńców o podział", "48d088a2"], "d": ["Sprzymierzeńcy bałkańscy, którzy nie mogli podzielić ziem zabranych Osmanom na mocy traktatu londyńskiego, zwrócili się przeciw sobie; druga wojna rozpoczęła się, gdy Bułgaria zaatakowała pozycje serbskie i greckie. Gdy przeciw Bułgarii na front weszły także Rumunia i Czarnogóra, armia bułgarska się załamała. Państwo osmańskie, wykorzystując okazję, przekroczyło linię Midye–Enez wytyczoną traktatem londyńskim i odzyskało Trację Wschodnią wraz z Edirne.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Traktat stambulski: pokój z Bułgarią i potwierdzenie Edirne", "c8c18b2d"], "d": ["Traktat podpisany po II wojnie bałkańskiej między państwem osmańskim a Bułgarią, uznając za granicę rzekę Maricę, prawnie potwierdził pozostanie przy Osmanach Edirne, Kırklareli, Dimetoki i Tracji Wschodniej. Dedeağaç pozostawiono Bułgarii (Kawala została natomiast w lipcu 1913, po bułgarskiej okupacji jesienią 1912, przekazana Grecji i potwierdzona jako grecka traktatem bukareszteńskim z 10 sierpnia 1913); uregulowano wzajemną wymianę ludności między oboma krajami oraz prawa muzułmanów w Bułgarii. Ten tekst jest gwarancją jedynego kawałka ziemi, jaki udało się odzyskać z bałkańskiej katastrofy. W tym samym dniu przyłączono także inne miejscowości: Gümülcine.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Odzyskanie Bozcaady i İmroz — traktat ateński", "ec084d09"], "d": ["Bozcaada i İmroz, wyspy północnego Morza Egejskiego zajęte przez Grecję w wojnie bałkańskiej i trzymające wejście do cieśniny, zostały w rokowaniach ateńskich uznane za niezbędne dla obrony Çanakkale i zwrócone Osmanom. Pozostałe wyspy zostały przy Grecji. Te dwie wyspy były ostatnimi ziemiami, jakie imperium trzymało na Morzu Egejskim, i w Lozannie również zostały pozostawione Turcji.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Traktat ateński: pokój z Grecją i przekazanie Salonik i Janiny", "8e94def7"], "d": ["Traktat podpisany między państwem osmańskim a Grecją oficjalnie uznał przejście do Grecji utraconych w wojnie bałkańskiej Salonik, Janiny i Macedonii Południowej oraz zrzekł się praw osmańskich do Krety. Szczegółowo uregulowano prawa religijne i własnościowe muzułmanów pozostających w Grecji, status wakfów i mianowanie muftich. Status wysp Morza Egejskiego pozostawiono natomiast nierozstrzygnięty, co pozostało źródłem stałego napięcia między obu państwami.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Podpisanie tajnego traktatu sojuszniczego osmańsko-niemieckiego w Stambule", "0472efb3"], "d": ["Gdy tylko w Europie wybuchła wojna, w rezydencji wielkiego wezyra Saida Halima Paszy podpisano tajny traktat sojuszniczy między państwem osmańskim a Niemcami; tekst przewidywał, że w razie przystąpienia Rosji do wojny przeciw Niemcom Osmanowie staną po stronie Niemiec. Traktat ukryto nawet przed gabinetem, znały go tylko cztery osoby. Po trzech miesiącach, wraz z napadem na Morze Czarne, państwo osmańskie miało zostać faktycznie wciągnięte do wojny, a losy imperium zostały związane tym dokumentem.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Jednostronne zniesienie kapitulacji", "ec773d18"], "d": ["Rząd osmański, w chwili gdy Europa była zajęta wojną, ogłosił, że od 1 października 1914 jednostronnie znosi kapitulacje przyznające cudzoziemcom przywileje sądowe, finansowe i celne. Zakończenie tego czterowiekowego ładu przywilejów przyjęto w kraju z wielkim entuzjazmem niepodległości, a w Stambule odbyły się obchody. Wszystkie państwa, łącznie z sprzymierzonymi Niemcami, zaprotestowały przeciw decyzji; kapitulacje miały definitywnie przejść do historii dopiero w 1923 w Lozannie.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Napad na Morze Czarne: ostrzelanie przez flotę osmańską portów rosyjskich", "8ad4ef61"], "d": ["Goeben i Breslau (Yavuz i Midilli), które uciekły z Niemiec i przyłączyły się do floty osmańskiej jakby „zakupione”, wypłynęły pod dowództwem admirała Souchona na Morze Czarne, ostrzelały porty rosyjskie i zatopiły okręty. Ten rozkaz Envera Paszy, wydany z ukrycia przed gabinetem, faktycznie zakończył neutralność. W ciągu tygodnia Rosja, Anglia i Francja wypowiedziały wojnę, a państwo osmańskie weszło nieodwołalnie do I wojny światowej.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Zajęcie Fao przez siły brytyjsko-indyjskie — otwarcie frontu irackiego", "08663813"], "d": ["Rankiem po dniu, w którym państwa Ententy wypowiedziały wojnę państwu osmańskiemu, brygada brytyjsko-indyjska oczekująca w Bahrajnie wylądowała w Fao u ujścia Szatt al-Arab. Mały oddział osmański w zrujnowanej twierdzy Fao wycofał się pod ogniem okrętów wojennych, a stacja indyjskiej linii telegraficznej wpadła w ręce Anglików. Front iracki został w ten sposób otwarty.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Ogłoszenie Cihâd-ı Ekber: odczytanie fatwy o dżihadzie w meczecie Fatiha", "2a6174e8"], "d": ["Pięć fatw wydanych przez szejhülislama Ürgüplü Hayriego Efendiego odczytano w imieniu kalifa-sułtana w meczecie Fatiha, wzywając wszystkich muzułmanów do dżihadu przeciw państwom Ententy. Ten ruch, na który Niemcy wiązały wielkie nadzieje, miał na celu poderwanie do powstania muzułmanów w koloniach angielskich i francuskich. Oczekiwane powszechne powstanie nie nastąpiło; wręcz przeciwnie, bunt emira Mekki szarifa Husajna z poparciem angielskim dwa lata później boleśnie pokazał granice politycznych wpływów kalifatu.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Poddanie Kurny Anglikom", "621d36b0"], "d": ["Siły namiestnika Basry Subhiego Beja, które po upadku Basry wycofały się do Kurny, gdzie łączą się Tygrys i Eufrat, poddały się rankiem 9 grudnia 1914 po walkach w dniach 4–8 grudnia.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["Objęcie Egiptu protekcją brytyjską i ogłoszenie sułtanatu", "55d4e520"], "d": ["Gdy państwo osmańskie przystąpiło do wojny, Anglia ogłosiła, że oficjalnie bierze pod protekcję Egipt, okupowany przez nią faktycznie od 1882; wicekról Abbas Hilmi Pasza, który pozostał wierny Osmanom, został odwołany, a na jego miejsce wprowadzono Hüseyina Kâmila z tytułem „sułtana”. W ten sposób prawne zwierzchnictwo osmańskie trwające od 1517 zostało jednostronnie zakończone. Bâbıâli decyzji nie uznało i po dwóch miesiącach podjęło próbę odzyskania Egiptu w akcji nad Kanałem.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Operacja pod Sarıkamış: katastrofa na froncie kaukaskim", "5cbde7f0"], "d": ["Enver Pasza, chcąc odzyskać utracone w 1878 Kars–Ardahan–Batum i poderwać Turków na Kaukazie do powstania, wysłał III Armię zimą w manewrze okrążającym siły rosyjskie przez góry Allahuekber. Wskutek niedostatecznego wyposażenia zimowego, wyczerpania zaopatrzenia i zamieci sięgającej minus trzydziestu stopni armia roztopiła się, zanim weszła do bitwy; dziesiątki tysięcy żołnierzy zamarzło. Operacja stała się jedną z najcięższych katastrof Osmanów w czasie wojny i na dwa lata pozostawiła front wschodni bez obrony.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Pierwsza akcja nad Kanałem: natarcie na Suez przez pustynię Synaj", "02dd72f5"], "d": ["Dowódca IV Armii Cemal Pasza, by uwolnić Egipt od okupacji angielskiej i zamknąć Kanał Sueski dla żeglugi, zorganizował natarcie przez pustynię Synaj. Choć oddziały osmańskie dotarły do wschodniego brzegu kanału i części z nich udało się przeprawić na drugą stronę, wskutek przewagi angielskiej i niewybuchnięcia oczekiwanego powstania ludności Egiptu się wycofały. Akcja nie osiągnęła celu, lecz zmuszając Anglię do utrzymywania w Egipcie wielkich sił wywołała pośredni skutek strategiczny.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Wydanie ustawy o przesiedleniu i osiedleniu (Tehcir)", "2f2bc22c"], "d": ["Po powstaniu w Wan i natarciu rosyjskim rząd wydał ustawę tymczasową zezwalającą dowódcom armii na przesiedlanie do innych regionów ludności uznanej za zakłócającą bezpieczeństwo na tyłach frontu, a sułtan zatwierdził ją 27 maja 1915. W wyniku zastosowania ustawy większość ludności ormiańskiej wschodnich i południowych prowincji Anatolii została skierowana w stronę Syrii i Mosulu; podczas przesiedlenia doszło do bardzo wielkich strat w ludziach wskutek chorób, głodu i napadów. Decyzja pozostała najcięższą i do dziś najbardziej sporną sprawą ostatnich lat osmańskich.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Oddziały osmańskie odzyskały Muş od okupacji rosyjskiej", "fb1be113"], "d": ["Sześć miesięcy po pierwszej rosyjskiej okupacji Muş osmański XVI Korpus wszedł do miasteczka w kontrnatarciu Bitlis–Muş.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muş ponownie wpadło w ręce rosyjskie", "43ad8a03"], "d": ["Wobec rosyjskiego kontrnatarcia oddział osmański opuścił Muş; miasteczko ponownie weszło pod okupację rosyjską między 22 a 25 sierpnia 1916 i pozostawało w jej rękach do wiosny 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muş ostatecznie wyzwolone spod okupacji rosyjskiej", "f0e89703"], "d": ["Muş, które w I wojnie światowej znalazło się pod okupacją rosyjską, zostało ostatecznie odzyskane przez siły osmańskie 1 maja 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Śmierć Abdülhamida II w Pałacu Beylerbeyi", "c9662582"], "d": ["Abdülhamid II, zdetronizowany w 1909 i sprowadzony najpierw do Salonik, a po utracie miasta w wojnie bałkańskiej do Stambułu, trzymany w areszcie domowym w Pałacu Beylerbeyi, zmarł. W trzydziestotrzyletnim panowaniu starał się zyskiwać czas, trzymając państwo z dala od wojen, lecz był też znany z rządów istibdadu. Jego pogrzeb, w którym wzięły udział wielkie tłumy, odbył się w mauzoleum Mahmuda I na Divanyolu; śmierć przypadła na rok wojny, w którym ład przez niego ustanowiony był już dawno zlikwidowany.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Traktat w Brześciu Litewskim: odzyskanie Karsu, Ardahanu i Batumu", "da82636f"], "d": ["Traktat podpisany między Rosją, która wycofała się z wojny po rewolucji bolszewickiej, a państwami centralnymi zamknął front wschodni i zwrócił państwu osmańskiemu Kars, Ardahan i Batum (Elviye-i Selâse), utracone na mocy traktatu berlińskiego z 1878. Była to jedyna zdobycz terytorialna w dziejach osmańskich uzyskana po czterdziestu latach przerwy. Po rozejmie w Mudros region miał jednak ponownie zostać utracony, a ostateczne rozwiązanie przyniósł traktat w Karsie z 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Oddziały osmańskie weszły do Artvinu", "ca7d1778"], "d": ["Oddziały osmańskie, które 25 marca przekroczyły granicę z 1914, ruszyły na Elviye-i Selâse, której Brześć Litewski zwrócił granicę sprzed 1878, i weszły do Artvinu 28 marca 1918. Artvin został oddany Rosji w 1878 jako część sandżaku Batum; hasło TDV o Artvinie podaje powrót jedynie jako „marzec 1918”, dzień podaje Mustafa Sarı.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan w ręku armii tureckiej", "7fd9e3db"], "d": ["W akcji Elviye-i Selâse armia osmańska po Artvinie zajęła Ardahan 3 kwietnia 1918; Ardahan padł w wojnie 93 w 1877 i został oddany Rosji w 1878. Kars miał zostać zajęty miesiąc później, 25 kwietnia.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Odzyskanie Batumu", "d37a1a0d"], "d": ["Armia osmańska, która po wycofaniu się Rosji z wojny na mocy traktatu w Brześciu Litewskim ruszyła na wschód, odzyskała po czterdziestu latach port Batum, utracony w 1878. Port na wschodnim krańcu Morza Czarnego był morskim wylotem ropy z Baku. Zdobycz trwała tylko siedem miesięcy; po rozejmie w Mudros region miał zostać opuszczony.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Kars wszedł pod zarząd osmański", "02cbf0b3"], "d": ["W Brześciu Litewskim postanowiono zwrot trzech sandżaków utraconych na mocy traktatu berlińskiego z 1878 — Karsu, Ardahanu i Batumu; armia osmańska weszła do Ardahanu 3 kwietnia, do Batumu 14 kwietnia, a do Karsu 25 kwietnia 1918 i zarząd został faktycznie ustanowiony. Te ziemie, zwane „Elviye-i Selâse”, uznano za rekompensatę strat trwających od wojny 93. Po rozejmie miały zostać ponownie utracone i ostatecznie przyłączone do Turcji dopiero traktatem w Karsie z 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Zajęcie Iğdır — natarcie w dolinie Arasu", "87ebf4d3"], "d": ["W ramach natarcia rozpoczętego w lutym 1918 oddziały tureckie pokonały oddziały ormiańskie pod Serdarabad na północ od Arasu i zajęły Iğdır 20 maja 1918. Iğdır nie wchodził do Elviye-i Selâse, lecz był kazą Sürmeli guberni erywańskiej; po około 180 latach w regionie ustanowiono pierwszy zarząd osmański.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Śmierć Mehmeda V Reşada i wstąpienie na tron Mehmeda VI Vahdeddina", "d302ba07"], "d": ["Mehmed V Reşad, którego dziewięcioletnie panowanie upłynęło w wojnach o Trypolitanię, bałkańskich i światowej, zmarł w najkrytyczniejszym okresie wojny, a na jego miejsce wstąpił na tron brat Vahdeddin pod imieniem Mehmeda VI. Nowy sułtan próbował wyzwolić się spod opieki kadry unionistycznej; gdy po czterech miesiącach podpisano rozejm, musiał kierować likwidacją imperium. Był trzydziestym szóstym i ostatnim sułtanem dynastii osmańskiej.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Przybycie floty Ententy pod Stambuł i faktyczna okupacja miasta", "d10cb14d"], "d": ["Po rozejmie w Mudros flota sprzymierzonych licząca ponad sześćdziesiąt jednostek, złożona z okrętów angielskich, francuskich, włoskich i greckich, zakotwiczyła przed Dolmabahçe, a Stambuł znalazł się faktycznie pod okupacją. Po czterystu sześćdziesięciu pięciu latach stolica po raz pierwszy znalazła się pod kontrolą obcych żołnierzy. Słowa „Jak przyszli, tak odejdą”, które według przekazu wypowiedział w tym samym dniu Mustafa Kemal Pasza, gdy zszedł do Haydarpaşa i zobaczył widok, miały stać się jednym z symbolicznych zdań Walki Narodowej.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Odwrót w regionie Arasu: Iğdır opuszczony", "57572ab4"], "d": ["Zgodnie z postanowieniem rozejmu w Mudros o wycofaniu się za granicę 1914 Yakup Şevki Pasza rozkazem z 21 listopada polecił wycofać oddziały poza granicą brzeską do 4 grudnia; Iğdır i okolice zostały w tym czasie całkowicie opuszczone. Następnie Rząd Aras-Turecki został pod koniec grudnia 1918 obalony przez Ormian.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Anglicy osiedlili się w Artvinie", "e2cb3153"], "d": ["Ponieważ rozejm w Mudros z 30 października 1918 postawił warunek wycofania armii osmańskiej za granicę z 1914, Artvin został opuszczony i 17 grudnia 1918 zajęty przez Anglików. Według hasła TDV o Artvinie okupacja angielska trwała do kwietnia 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Zarząd brytyjski w Batumie po Mudros", "9dd768fc"], "d": ["Zgodnie z rozejmem w Mudros z 30 października 1918 państwo osmańskie musiało wycofać się z Batumu; miasto zostało 24 grudnia 1918 zajęte przez oddziały brytyjskie. Batum, uczyniony w kwietniu 1918 odrębnym ośrodkiem sandżaku, pozostawał od tej daty do lipca 1920 pod kontrolą angielską.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan przeszedł pod panowanie gruzińskie", "97cf47f6"], "d": ["Ardahan, opuszczony po Mudros, został zajęty przez siły gruzińskie 20 kwietnia 1919, w dniach gdy rząd południowo-zachodniego Kaukazu był rozwiązywany przez Anglików. Panowanie gruzińskie miało trwać do 23 lutego 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston przekazał zarząd Karsu namiestnikowi ormiańskiemu", "efa81cb0"], "d": ["Angielski dowódca Preston, który 12–13 kwietnia 1919 rozwiązał Rząd Południowo-Zachodniego Kaukazu, 30 kwietnia 1919 zlikwidował tymczasowy rząd rad i przekazał zarząd miasta Ormianinowi Karganofowi, mianowanemu namiestnikiem Karsu; w Karsie rozpoczął się okres zarządu ormiańskiego, który trwał do zwycięstwa Kâzıma Karabekira 30 października 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Kongres w Erzurum: decyzja o oporze narodowym prowincji wschodnich", "41ef0457"], "d": ["Kongres zwołany przez Towarzystwo Obrony Praw Anatolii Wschodniej, odroczony wskutek nacisku angielskiego, otwarto z pięćdziesięcioma sześcioma delegatami i na jego przewodniczącego wybrano Mustafę Kemala Paszę, który zrezygnował ze służby wojskowej. Kongres ogłosił, że ojczyzna w granicach narodowych jest całością, że mandat i protektorat są nie do przyjęcia, a w razie rozpadu rządu naród weźmie swój los we własne ręce. Te uchwały miały po sześciu miesiącach stać się jądrem tekstu Paktu Narodowego (Misâk-ı Millî).", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Kongres w Sivas: zjednoczenie oporu narodowego pod jednym dachem", "0e9ad36b"], "d": ["Kongres, który rozpoczął obrady 4 września 1919 w Sivas Sultânîsi, zjednoczył towarzystwa obrony praw z całego kraju pod nazwą Towarzystwo Obrony Praw Anatolii i Rumelii i wybrał Komitet Reprezentacyjny (Heyet-i Temsîliyye). Propozycję mandatu amerykańskiego po długich dyskusjach odrzucono. Deklaracją opublikowaną 11 września Walka Narodowa stała się jednoośrodkowym, uprawnionym ruchem politycznym i rozpoczęła się otwarta walka o siłę z rządem stambulskim.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Protokół z Amasyi: rozmowy rządu stambulskiego z Komitetem Reprezentacyjnym", "40e6a6ab"], "d": ["Po upadku Damat Ferida i utworzeniu rządu Alego Rızâ Paszy minister marynarki Salih Pasza został wysłany do Amasyi na rozmowy z Komitetem Reprezentacyjnym. Na mocy uzgodnionych protokołów rząd stambulski faktycznie uznał istnienie ruchu anatolijskiego; zgodzono się na zwołanie Meclis-i Meb'ûsan, swobodne przeprowadzenie wyborów i ochronę granic narodowych. Było to pierwsze oficjalne zwycięstwo polityczne Walki Narodowej wobec Stambułu.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Przyjęcie Paktu Narodowego (Misâk-ı Millî) w ostatnim Zgromadzeniu Osmańskim", "6322865e"], "d": ["Tekst Ahd-i Millî, podpisany przez 121 posłów w ostatnim osmańskim Meclis-i Meb'ûsan, przewidywał niepodzielną całość ziem leżących w obrębie linii z Mudros i zamieszkanych przez muzułmańsko-turecką większość, plebiscyt w prowincjach arabskich i Tracji Zachodniej, zniesienie kapitulacji oraz pełną niepodległość polityczną i finansową. Tekst przyjęto jednogłośnie 17 lutego 1920 i ogłoszono światu. Ta deklaracja była zarówno programem politycznym Walki Narodowej, jak i mapą granic, których miano bronić w Lozannie; stała się bezpośrednią przyczyną oficjalnej okupacji Stambułu przez państwa Ententy 16 marca.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Gdy Anglicy się wycofali, Artvin pozostał w Gruzji", "6d086b06"], "d": ["Według hasła TDV o Artvinie okupacja angielska trwała do kwietnia 1920; Anglicy, wycofując się, zostawili miasto Gruzji. Artvin pozostał w rękach Gruzji aż do ultimatum Wielkiego Zgromadzenia Narodowego z 23 lutego 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batum przekazany zarządowi gruzińskiemu", "6523d095"], "d": ["Oficjalne przekazanie Batumu Gruzinom przez Anglików nastąpiło 7 lipca 1920 (hasło TDV o Batumie podaje tylko „lipiec 1920”). Rząd Ankary 25 lipca zaprotestował przeciw przekazaniu jako „okupacji”.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Traktat w Gümrü: pierwszy traktat międzynarodowy rządu Wielkiego Zgromadzenia Narodowego", "9232c690"], "d": ["Gdy armia frontu wschodniego pod dowództwem Kâzıma Karabekira odzyskała Sarıkamış i Kars, Armenia poprosiła o pokój i na mocy traktatu podpisanego w Gümrü uznała, że nie uznaje Sèvres i rezygnuje z żądań terytorialnych na wschodzie. Ten pierwszy traktat podpisany przez rząd Ankary stał się pierwszym dokumentem międzynarodowym faktycznie odrzucającym Sèvres i otworzył Wielkiemu Zgromadzeniu drogę do prawnego uznania. Granica wschodnia została w ten sposób zabezpieczona i możliwe stało się przesunięcie sił na front zachodni.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["I bitwa pod İnönü: pierwsze zwycięstwo armii regularnej", "4add3719"], "d": ["Nowo utworzona armia regularna zatrzymała siły greckie postępujące w kierunku Bursy na pozycjach İnönü i zmusiła je do odwrotu. Ten sukces o ograniczonej skali wojskowej miał bardzo wielkie skutki polityczne: rząd Ankary został zaproszony na Konferencję Londyńską, otwarto drogę do traktatu moskiewskiego z Rosją Sowiecką i przyjęto Ustawę Teşkilât-ı Esâsiyye. Wewnątrz kraju zaufanie do armii regularnej także się dzięki temu zwycięstwu umocniło.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["II bitwa pod İnönü: ponowne złamanie natarcia greckiego", "a974521c"], "d": ["Armia grecka, która nie osiągnęła wyniku na Konferencji Londyńskiej, przeszła do nowego natarcia z kierunków Bursy i Uşak, lecz ponownie została zatrzymana na wzgórzach İnönü i musiała się wycofać. Telegram Mustafy Kemala Paszy do İsmeta Paszy: „Tam pokonaliście nie tylko wroga, lecz także nieszczęsny los narodu”, został napisany po tym zwycięstwie. Bitwa podniosła międzynarodowy prestiż Walki Narodowej i przyspieszyła proces wycofywania się Włoch z Anatolii.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Porozumienie z Ankary: pokój z Francją i zamknięcie frontu południowego", "35fc32db"], "d": ["Porozumieniem podpisanym w Ankarze z Francją po zwycięstwie nad Sakarią wojna na froncie południowym się zakończyła; siły francuskie, opuściwszy Çukurovę i Południowy Wschód łącznie z Adaną, Antepem, Maraşem i Urfą, wycofały się na granicę syryjską. Jedno z państw Ententy faktycznie uznało w ten sposób rząd Ankary i na froncie Sèvres otworzyła się pierwsza rysa. Broń przejęta z opuszczonych regionów i uwolnione oddziały odegrały kluczową rolę w przygotowaniach do Wielkiej Ofensywy.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Rozejm w Mudanyi: bezwojenne przekazanie Stambułu i cieśnin", "ac0d9baf"], "d": ["Konferencja zebrana w Mudanyi, gdy po Wielkiej Ofensywie armia turecka stanęła naprzeciw sił angielskich pod Çanakkale i İzmitem, po jedenastodniowych trudnych targach zakończyła się rozejmem. Zgodzono się, że Tracja Wschodnia aż po Marycę zostanie w ciągu piętnastu dni opuszczona przez Grecję i przekazana pod zarząd turecki oraz że Stambuł i cieśniny zostaną oddane traktatem pokojowym. W ten sposób zbrojna faza Walki Narodowej zamknęła się dyplomatycznym zwycięstwem wywalczonym bez jednego wystrzału i otwarto bramę Lozanny.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Wyjazd Mehmeda VI Vahdeddina ze Stambułu i wybór Abdülmecida Efendiego na kalifa", "8ab0e847"], "d": ["Ostatni sułtan Mehmed VI Vahdeddin, którego pozycja stała się sporna po zniesieniu sułtanatu, opuścił Stambuł w piątek rano 17 listopada 1922 na angielskim pancerniku Malaya i udał się na Maltę. Wielkie Zgromadzenie Narodowe dwa dni później, 19 listopada, wybrało Abdülmecida Efendiego na kalifa pozbawionego władzy politycznej. Sześćset dwadzieścia trzy lata panowania dynastii osmańskiej w ten sposób faktycznie się skończyły; kalifat miał trwać symbolicznie jeszcze piętnaście miesięcy. Vahdeddin, który przeniósł się na Maltę, a następnie do Włoch, zamieszkał w Villa Nobel w San Remo; jego starania o przyjęcie do kraju muzułmańskiego nie przyniosły skutku i zmarł tam 16 maja 1926, powtórzywszy, że nigdy nie zrzekł się praw do sułtanatu i kalifatu.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Śmierć ostatniego sułtana Mehmeda VI Vahdeddina w San Remo", "7149ed0e"], "d": ["Ostatni sułtan osmański Mehmed Vahdeddin, który po opuszczeniu Stambułu osiadł w mieście San Remo we Włoszech, zmarł 16 maja 1926, nie otrzymawszy wieści o zebraniu kongresu kalifatu (13 maja 1926), w którym oznajmił, że nigdy nie zrzekł się praw do sułtanatu i kalifatu. Był w ciężkiej biedzie; miał 60 000 lirów długu wobec kupców San Remo, a wierzyciele, usłyszawszy o jego śmierci, kazali zająć sprzęty w jego domu.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Zdobycie przez Konuralpa regionu Bolu — Mudurnu, Konurapa i Bolu", "e245cd27"], "d": ["Konuralp, jeden z dowódców Orhana Gazi, zwracając się ku górzystemu regionowi na wschód od Sakaryi, objął zarządem osmańskim region Mudurnu, Konurapa i Bolu; miasteczko na równinie Düzce nazwano jego imieniem. Dokładna data zdobycia jest nieznana; relacja opiera się na przekazie Âşıkpaşazâde. Region był wówczas obszarem pogranicznym zmieniającym właściciela między Candaroğulları a Bizancjum; zdobycie po raz pierwszy zbliżyło Osmanów do zachodniego wybrzeża Morza Czarnego. Po bitwie pod Ankarą region miał ponownie przejść do Candaroğulları, lecz w epoce Zdobywcy miał zostać ostatecznie odzyskany.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Zajęcie bizantyjskich miasteczek na południe od Marmary — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Po zajęciu Nikei i İzmitu miasteczka, które pozostały w rękach Bizancjum na zachód od równiny Bursy, jedno po drugim weszły pod zarząd osmański. Gölyazı wokół jeziora Uluabat, Kirmasti nad rzeką Susurluk i Mihaliç dopełniły korytarz łączący południowe wybrzeże Marmary z ziemiami Karesi. Te miasteczka poddały się, nie doznawszy długo oblężenia, wskutek odcięcia ich okolic; obecność bizantyjska w regionie została w ten sposób zepchnięta do Zatoki Gemlik.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Korynt (Gördüs) przeszedł do Despotatu Morei", "392495eb"], "d": ["Korynt, od 1358 lenno rodu Acciajuoli z Florencji podległe Księstwu Achai, w 1395 przeszedł w ręce despoty Morei bizantyjskiego Teodora. Miasto pozostawało odtąd pod zarządem despotatu aż do zdobycia osmańskiego.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Aneksja Bejliku Hacıemîroğulları — Ordu i Ünye", "c064f07f"], "d": ["Bejlik turkmeński założony przez Bayrama Beja wokół Ordu i rozszerzony w latach 50. XIV wieku przez jego syna Hacı Emîra był małym, lecz strategicznym państwem przybrzeżnym z ośrodkiem w dzisiejszym Eskipazar: był jedynym obszarem niezależnego panowania między Samsunem a Trapezuntem. Emîr Süleyman w 1398, w akcji Bayezida Błyskawicy w Canik, oznajmił wierność, a po bitwie pod Ankarą bejlik odzyskał wolność. Za Murada II, w tych samych latach co likwidacja Tâceddinoğulları, ziemie bejliku zostały związane bezpośrednio z zarządem osmańskim, a wybrzeże Morza Czarnego od Samsunu po Giresun zjednoczyło się w jednym ręku.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Zdobycie Koryntu (Gördüs)", "87a2bc59"], "d": ["W wyprawie morejskiej Zdobywcy twierdzę Akrokorynt oblegano trzy miesiące i w końcu przyjęto jej poddanie drogą pokojową. Przesmyk koryncki, uchodzący za bramę Morei, przeszedł w ten sposób do Osmanów.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Przyłączenie Czarnogóry do zarządu osmańskiego — Cetinje", "7fdb7cc8"], "d": ["Gdy dynastia Crnojeviciów rządząca Zetą zrzekła się władzy w 1496, górzysty region Czarnogóry, będący zapleczem Szkodry, został objęty bezpośrednim zarządem osmańskim i zorganizowany najpierw jako odrębny sandżak, a następnie jako część sandżaku Szkodry. Klasztor w Cetinje pozostawiono na miejscu jako ośrodek religijny regionu. Wskutek surowości geografii zarząd tu nigdy nie działał tak ściśle jak na nizinach; po dwóch stuleciach władza władyków, która narodziła się z tego samego klasztoru, miała stać się jądrem faktycznej niepodległości.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Przyjęcie przez twierdzę Bayezid panowania osmańskiego w wyprawie Irakejn", "f29e2e17"], "d": ["Gdy wielki wezyr İbrahim Pasza podczas wyprawy Irakejn przybył w okolice Bingöl, Wan, Toprakkale, Avnik i twierdze Bayezid, wraz z wieloma plemionami kurdyjskimi regionu, zgodziły się wejść pod panowanie osmańskie. Bayezid przyłączył się do Osmanów w wyprawie Selima w 1514, lecz gdy armia zawróciła, Safawidzi odzyskali region.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Ponowne przejście Tabrizu do Safawidów — powrót z Irakejn", "80b8b761"], "d": ["W wyprawie Irakejn armia weszła do Tabrizu, lecz ponieważ głównym celem był Bagdad, w mieście nie zostawiono trwałego garnizonu. Gdy armia, która spędziła zimę w Bagdadzie, wracała na zachód, szach Tahmasp wszedł ponownie do opuszczonego Azerbejdżanu i odzyskał Tabriz. Był to powtarzający się schemat wojen osmańsko-safawidzkich: Tabriz zdobyto pięć razy, a za każdym razem nie utrzymano; miasto miało zyskać długotrwały garnizon osmański dopiero w 1585.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Wpadnięcie Wanu i Erciş w ręce Tahmaspa (stanowisko osmańskie skończyło się w 1534–35)", "cb93d561"], "d": ["W regionie, który w 1534 oddał Wan pod panowanie osmańskie, Ulama Pasza opierał się w twierdzy Wan oblężeniu safawidzkiemu; twierdza przeszła w ręce Safawidów, a siły safawidzkie oblegające Erciş wycofały się dzięki pomocy osmańskiej. Gdy Sulejman dotarł do Ahlat (23 września 1535), Wan był już w rękach Tahmaspa. Wan pozostawał safawidzki do 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Przejście sandżaku Bayezid pod panowanie safawidzkie (Wan i Erciş już w 1535 były safawidzkie)", "806a2cf1"], "d": ["Sandżak Bayezid, leżący pośrodku granicy osmańsko-safawidzkiej, ponownie wpadł w ręce Iranu (Kaya 2017 wspomina o tym „wraz z Wanem i Erciş”; jednak według Karataşa 2025 i TDV Wan i Erciş wróciły do Safawidów 22 września 1535 — zob. poprzedni wpis); w tej zmianie właściciela niektóre miejsca sandżaku zostały zniszczone. Sandżak wielokrotnie zmieniał właściciela między oboma państwami do ostatniej ćwierci XVI wieku.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Ponowne przejście sandżaku Bayezid do Osmanów w czasie wyprawy nachiczewańskiej", "cf0171fa"], "d": ["W trzeciej wyprawie irańskiej (nachiczewańskiej) Sulejmana sandżak Bayezid został ponownie objęty zarządem osmańskim. W wyprawie 1554 Bayazıt stał się ważną bazą dla armii; sandżak wszedł ostatecznie pod panowanie osmańskie w 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Utrata Erywania na rzecz szacha Abbasa", "34413cf2"], "d": ["Gdy w latach, w których powstania celâlich zablokowały Anatolię, front wschodni pozostał bez obrony, szach Abbas, który przeorganizował swoją armię na modłę europejską, przeszedł do natarcia. Twierdza Erywań, którą w 1583 kazał zbudować Ferhad Pasza, po siedmiomiesięcznym oblężeniu się poddała. Pierwsze ogniwo linii kaukaskiej zdobytej na mocy traktatu Ferhada Paszy zostało zerwane, a w ciągu następnych trzech lat cały Południowy Kaukaz miał zostać utracony.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Utrata Tbilisi i Gandży", "3fb51753"], "d": ["Po upadku Erywania armia safawidzka postępowała wzdłuż doliny Kury; Gandża, ośrodek Karabachu, i Tbilisi, stolica Gruzji, zostały utracone jedna po drugiej. Państwo osmańskie prowadziło równocześnie na froncie austriackim trwającą trzynaście lat Długą Wojnę i zmagało się w Anatolii z celâlimi; nie było sił, które można by wysłać na wschód. W ten sposób ład szerokich ejaletów kaukaskich ustanowiony traktatem Ferhada Paszy z 1590 faktycznie się skończył.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Utrata Szyrwanu — Szamacha, Baku i Derbent", "81beab11"], "d": ["Prowincja Szyrwan nad Morzem Kaspijskim, zdobyta w wyprawach Özdemiroğlu Osmana Paszy z lat 1578–1585, jako główne źródło handlu jedwabiem przynosiła osmańskim finansom znaczne dochody. Akcja szacha Abbasa skierowana na północ zlikwidowała ten ejalet, zajmując kolejno Szamachę, Baku i Derbent. Strata nie dotyczyła tylko ziemi: droga, którą jedwab irański płynął do Europy przez Osmanów, wyszła spod kontroli, a państwo Safawidów zaczęło sprzedawać jedwab przez Ocean Indyjski.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Utrata Ta'izz", "65f20d53"], "d": ["Osmanowie w 1038 (1629), wraz z panowaniem w Jemenie pozostawionym zarządowi Kâsimîdów w Sanie, opuścili także Ta'izz — pierwszy wielki krok procesu, w którym imamowie zajdyccy odzyskali wnętrze Jemenu.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Utrata Jemenu — panowanie imamów Kâsimîdów", "49e83e3c"], "d": ["Jemen od 1538 był ejaletem osmańskim; opór imamów zajdyckich nigdy jednak nie ustał. Powstanie rozpoczęte przez imama Kâsima rozprzestrzeniło się na cały kraj za czasów jego syna al-Mu'ayyada Muhammada, a garnizony osmańskie były kolejno oblegane. W latach, gdy Murad IV skupił się na Bagdadzie i Erywaniu, nie można było wysłać posiłków; Ta'izz utracono w 1629, a Mokha została w ostatniej fazie tego samego załamania opuszczona 22 października 1635. W 1635 ostatnie oddziały w Sanie i Zabîd również opuściły Jemen. W ten sposób wschodnie wybrzeże Morza Czerwonego pozostawało przez dwieście trzydzieści siedem lat poza imperium i dało się je odzyskać dopiero w 1872. Lahidż (al-Hawta) według TDV İslâm Ansiklopedisi było w rękach Osmanów do 1635; od tej daty wpływy miały imamy zajdyckie.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Opuszczenie Mokha", "c6b3061a"], "d": ["Mustafa Bej opuścił Mokha 10 cemâziyelevvel 1045 (22 października 1635) z pozostałymi siłami i bronią; następnie syn imama Kâsima, Hasan b. Kâsim, mianował do Zabîd i Mokha swoich ludzi i ustanowił kontrolę Kâsimîdów także na wybrzeżu Tihamy.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Utrata Al-Hasa na rzecz Emiratu Banu Chalid", "a9b6131a"], "d": ["Al-Hasa było ejaletem utworzonym w 1550, by zamknąć Portugalii zachodni brzeg Zatoki Perskiej; leżało jednak bardzo daleko od Stambułu, na końcu jednej drogi pustynnej. W latach, gdy oblężenie Krety pochłaniało zasoby, plemię Banu Chalid w regionie pod przywództwem Barraka b. Ghurajra wyparło garnizon osmański i założyło własny emirat. Zachodni brzeg Zatoki pozostawał przez półtora wieku w emiratach plemiennych; w 1795 miał przejść do Saudów, a w 1871 ponownie do Osmanów.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Utrata Prewezy i Vonitsy na rzecz Wenecji — otwarcie wybrzeża Epiru", "1201204c"], "d": ["Wenecja, która przystąpiła do Świętej Ligi, przed rozpoczęciem wyprawy morejskiej zajęła dwie twierdze trzymające wejście do Zatoki Ambrakijskiej: Prewezę i Vonitsę na przeciwległym brzegu. W tym samym lecie padła także Aya Mavra (Lefkada). Te trzy pozycje zapewniły bezpieczne wprowadzenie floty z Morza Jońskiego w głąb Grecji i stały się bazą akcji morejskiej rozpoczynającej się w następnym roku. Preweza i Vonitsa zostały pozostawione Wenecji także w Passarowitz; pod zarząd osmański miały wrócić dopiero w 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Utrata Szolnoku — rozpad linii Cisy", "51c2c8ef"], "d": ["Po upadku Uyvaru w sierpniu armia habsburska zwróciła się na południe i zajęła przyczółek na Cisie, Szolnok. Miasto było jedynym bezpiecznym przejściem między Budą a Siedmiogrodem; jego utrata oznaczała odcięcie od siebie twierdz osmańskich we wschodniej połowie Węgier. Rozstrzygające okazało się to, że w oblężeniu Budy w następnym roku przecięto drogę zaopatrzenia.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Utrata Modonu na rzecz Wenecji", "114c9cc0"], "d": ["Modon na południowo-zachodnim krańcu półwyspu Morea był portem, który Wenecja utraciła trzy stulecia wcześniej i nazywała „jednym z dwojga oczu państwa”. Twierdza oblężona po upadku Koronu została przyjęta w poddanie po ostrzale jednocześnie z lądu i morza. Akcja morejska Morosiniego zajęła w ten sposób całe zachodnie wybrzeże półwyspu i otworzyła drogę w głąb.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Utrata Pécsu", "99d54cf4"], "d": ["Po upadku Budy we wrześniu siły habsburskie zeszły na południe na zachód od Dunaju i zajęły Pécs, pozostający osmański od czasów Sulejmana. Miasto, znane z meczetu Gazi Kâsıma Paszy, było jednym z najrozwiniętszych ośrodków sandżaków ejaletu Budy. Jego utrata oznaczała otwarcie drogi schodzącej na równinę Mohacza; w następnym roku miała tu przeżyć dokładnie klęskę II Mohacza.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Utrata Segedynu", "9fbee1b2"], "d": ["Segedyn u zbiegu Cisy i Maroszu był południową bramą równiny węgierskiej i trzymał drogę do ejaletu Timișoary. Twierdza oblężona po upadku Budy i Pécsu tej samej jesieni szybko się poddała. Utrata trzech twierdz w jednym sezonie była znakiem, że ustanowiona od 1541 osmańska struktura administracyjna na Węgrzech zaczyna się załamywać. Atlas uznaje, że tego samego dnia także Zenta nad Cisą przeszła od Osmanów na stronę habsburską (dzień poddania właściwy dla Zenty nie został odczytany w źródle, dzień wzięto z Segedynu; TDV zenta: od października 1686 rozpoczęły się starcia między Osmanami a sprzymierzonymi pod przewodnictwem Habsburgów — przybliżenie z deklaracją).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Utrata Patras (Balyabadra) — północna brama Morei", "b9cff63c"], "d": ["Patras u wejścia do Zatoki Korynckiej było portem kontrolującym przejście między Moreą a Rumelią. Po zajęciu miasta przez armię wenecką twierdze po obu brzegach zatoki padły jedna po drugiej, a półwysep został całkowicie odizolowany od lądu. Na końcu tej akcji cała Morea przeszła do Wenecji; region miał być zarządzany do 1715 pod nazwą „Regno di Morea”.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Oddanie Koryntu (Gördüs) Wenecji", "9a25b6b9"], "d": ["Po upadku Patras Korynt został pokojowo pozostawiony Wenecjanom, a ludność muzułmańska opuściła miasto. W sierpniu 1687 armia Morosiniego zbierała się w Koryncie na wyprawę ateńską.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Utrata Egeru", "983391aa"], "d": ["Eger został zdobyty w 1596 w wyprawie, w której osobiście wziął udział Mehmed III, i stał się ośrodkiem ejaletu noszącego jego nazwę. Ta ostatnia wielka twierdza osmańska w Węgrzech Północnych, po klęsce pod II Mohaczem całkowicie otoczona, trwała jeszcze rok i poddała się z głodu. Wraz z jej utratą północne skrzydło państwa osmańskiego na Węgrzech zostało całkowicie zlikwidowane.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Utrata Székesfehérvár — miasta koronacji królów węgierskich", "c6147255"], "d": ["Miasto, w którym przez stulecia koronowano i grzebano królów węgierskich, zostało zajęte w 1543 przez Sulejmana i stało się jednym z najważniejszych ośrodków sandżaków ejaletu Budy. Około dwa lata po upadku Budy twierdza całkowicie odcięta od otoczenia się poddała. Wraz z tą stratą obecność osmańska na zachód od Dunaju została zepchnięta w okolice Sirmium i Osijeku.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Utrata Szigetvár", "834910a7"], "d": ["Szigetvár było twierdzą, w której Sulejman Prawodawca zmarł w 1566 podczas oblężenia, w trzynastej, ostatniej wyprawie; dlatego miało w pamięci osmańskiej miejsce symboliczne. Po stu dwudziestu trzech latach, gdy padły wszystkie otaczające twierdze, poddała się także twierdza chroniona przez bagna. Mauzoleum, w którym pochowano wnętrzności Sulejmana, i otaczające je miasteczko zostały po przejściu pod zarząd habsburski zburzone. W tym samym dniu atlas zapisuje przejście od Osmanów do Habsburgów innej miejscowości: Barcs — podąża za łańcuchem ośrodka-brata Szigetváru (Bánlaky 0017/1449; przybliżenie z deklaracją).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Utrata Váradu", "6cce360d"], "d": ["Várad był kluczową twierdzą otwierającą się na Siedmiogród, zdobytą w 1660 przez Köprülü Mehmeda Paszę i uczynioną ośrodkiem ejaletu noszącego jego nazwę. Twierdza, która po klęsce pod Slankamenem pozostała całkowicie sama, po blokadzie trwającej blisko dwa lata poddała się z głodu. Wraz z jej utratą wpływy osmańskie w Siedmiogrodzie faktycznie się skończyły, a panowanie habsburskie ustaliło się na wschód od Cisy.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Utrata Yanova — zamknięcie drogi do Siedmiogrodu", "4b5e30d8"], "d": ["Yanova była twierdzą zdobytą w 1658, trzymającą połączenie między Váradem a Timișoarą. Gdy bezpośrednio po upadku Váradu została odcięta od otoczenia, i ona została utracona. W ten sposób ejalet Timișoary został całkowicie odizolowany od północy i do Karłowic trwał jako jedyna ziemia na Węgrzech pozostająca w rękach osmańskich.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Ustanowienie rządów władyków w Czarnogórze — faktyczne oderwanie Cetinje", "a924b778"], "d": ["W latach, gdy wojna Świętej Ligi osłabiła kontrolę osmańską na Bałkanach, metropolia na czele klasztoru w Cetinje stała się urzędem przechodzącym z ojca na syna w rodzie Petrovićów, a region zyskał faktycznie odrębny zarząd. Dzięki niedostępności gór ta władyka przetrwała dwa stulecia w położeniu ani w pełni niezależnym, ani w pełni zależnym; jej niezależność miała zostać uznana prawnie dopiero traktatem berlińskim z 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Odzyskanie Koryntu (Gördüs)", "26f53e3a"], "d": ["Pierwszym wielkim przystankiem wyprawy morejskiej Damada Alego Paszy był Korynt; Osmanowie odzyskali miasto od Wenecjan w czerwcu 1715 i stąd ruszyli dalej na resztę półwyspu.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Natarcie Nâdira: utrata Tabrizu, Nachiczewanu, Hamadanu, Kermanszahu, Maragha i Kasr-ı Şîrîn", "d95efd59"], "d": ["Miasta Zachodniego Iranu zajęte w latach 1723–1727 dzięki załamaniu się państwa Safawidów zostały jedno po drugim utracone wskutek natarcia Nâdira Chana, który przejął faktyczną władzę w Iranie. W Azerbejdżanie także Ardabil i Chalchal wpadły w ręce Nâdira. Utrata Hamadanu, Kermanszahu i Kasr-ı Şîrîn wywołała w Stambule ciężki oddźwięk; to, że armia nie wyruszyła na wyprawę, lecz czekała w Üsküdar, i próby ukrycia straty były jedną z bezpośrednich przyczyn powstania Patrony Halila wybuchłego po sześciu tygodniach. Atlas uznaje też, że Kotur, podążający za łańcuchem Hoy, przeszedł tego dnia od Osmanów do Safawidów (Uluerler 2015, Turkish Studies 10/5, s. 6; dzień właściwy dla Koturu nie występuje w źródle — przybliżenie z deklaracją).", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Klęska pod Baghavard (Arpaçay) — utrata Kaukazu na rzecz Nâdira Chana", "4262f54c"], "d": ["Ejalety kaukaskie zdobyte w latach 1723–1725, dzięki załamaniu się państwa Safawidów, udało się utrzymać dziesięć lat. Nâdir Chan, który przejął faktyczną władzę w Iranie, zadał armii osmańskiej ciężką klęskę pod Baghavard w pobliżu Erywania; serdar Abdullah Köprülü Pasza poległ na polu bitwy. Po klęsce Erywań, Tbilisi, Gandża i Szyrwan zostały opuszczone w ciągu miesięcy. Granica wschodnia wróciła do linii z Kasr-ı Şîrîn z 1639, co miało zostać potwierdzone w 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Utrata Benderu na rzecz Rosjan", "0daca453"], "d": ["Po klęsce na równinie Kagul armia osmańska wycofała się na południe od Dunaju, a twierdze między Mołdawią a Oczakowem pozostały same. Bender, trzymający punkt przeprawy przez rzekę Turla, został po dwumiesięcznym oblężeniu zdobyty szturmem; miasto złupiono. Utrata twierdzy zerwała środkowe ogniwo linii obrony północnego Morza Czarnego, a po niej padły także Akerman i Kilia. W Küczük Kajnardży Bender miał zostać zwrócony, lecz w 1806 miał zostać utracony ponownie.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Objęcie emiratu Sabahów w Kuwejcie protekcją osmańską", "3584dba0"], "d": ["Według hasła TDV o Kuwejcie przystań założyło na początku XVIII wieku plemię Utub przybyłe z Nadżdu, a ród Sabahów przejął zarząd ku końcowi stulecia. W tych samych latach, gdy Al-Hasa wpadło w ręce Saudów, emirat, któremu wobec nacisku wahhabitów nie pozostał żaden wybór poza oparciem się o Basrę, wszedł pod protekcję osmańską. Więź ta miała zostać sformalizowana w 1871 uregulowaniem Basry przez Midhata Paszę, a Kuwejt miał być uznawany za jedną z trzech kaz sandżaku Basra; późniejsze pretensje terytorialne Iraku także opierają się na tym zapisie.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Utrata Mekki na rzecz wahhabitów", "2da23acd"], "d": ["Ruch wahhabicki, który narodził się w Nadżdzie, zwrócił się za Suda b. Abd al-Aziza ku Hidżazowi; po Ta'if i Medynie także Mekka została po raz drugi przyjęta w poddanie — emir Mekki szarif Gālib oddał miasto wahhabitom pod warunkiem pozostania na emiracie. Grobowce zburzono, a drogę karawan pielgrzymów z Damaszku i Kairu odcięto; przerwane zostało też w tych latach surre, które sułtan co roku posyłał do Haremejn — jedynym wyjątkiem w przydziale trwającym nieprzerwanie do 1915 jest okres panowania wahhabitów. Ponieważ tytuł protektora Haremejn był jedną z podstaw legitymacji sułtana, ta strata była poza stratą ziemi ciężkim ciosem politycznym; jej odzyskanie miało zająć siedem lat i stać się możliwe dzięki armii Mehmeda Alego Paszy z Kawali.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Koniec Republiki Dubrownickiej — okupacja francuska", "f8e27bf1"], "d": ["Francuzi, którzy na mocy traktatu z Campo Formio (1797) osiedlili się na wybrzeżu Dalmacji, zajęli 27 maja 1806 Dubrownik i położyli kres małej republice kupieckiej. W ten sposób trzy i pół stulecia zależnego statusu Dubrownika, który od 1458 płacąc Osmanom daninę zachowywał autonomię i przywileje handlowe, dobiegło końca; miasto i wyspa Mljet należąca do republiki przechodzą na mapie pod bezpośredni zarząd francuski.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Utrata Suchumi na rzecz Rosjan — otwarcie wybrzeża wschodniego Morza Czarnego", "adc96bd4"], "d": ["W wojnie osmańsko-rosyjskiej 1806–1812 flota rosyjska zwróciła się ku wschodniemu wybrzeżu Morza Czarnego i zajęła w Abchazji Sohumkale, na której opierało się panowanie osmańskie. Twierdza była ośrodkiem łączności z plemionami kaukaskimi i handlu przybrzeżnego. Wraz z jej utratą Rosja po raz pierwszy osiadła trwale na wschodnim wybrzeżu Morza Czarnego; wpływy osmańskie na Kaukazie zostały zepchnięte w okolice Anapy i Poti.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Pozostawienie Pargi pod zarządem osmańskim", "66e0cc5d"], "d": ["Parga od 1401 pozostawała w rękach Wenecji i nigdy nie weszła pod zarząd osmański; po upadku Wenecji przeszła kolejno do Francji i Anglii. Hasło TDV o Alim Paszy z Tepedelen streszcza sytuację tak: miasto poddało się Anglikom i zostało pozostawione zarządowi Alego Paszy dopiero w 1819. Przekazanie zakończyło się emigracją większości mieszkańców na Wyspy Jońskie. W ten sposób ostatnia z trójki Preweza–Parga–Vonitsa, pozostawionej Wenecji w Passarowitz, została przyłączona do imperium; Parga miała pozostać osmańska przez dziewięćdziesiąt cztery lata.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Przejście Koryntu (Gördüs) w ręce powstańców greckich", "892dcdc6"], "d": ["W czasie greckiej wojny o niepodległość Akrokorynt wpadł w ręce powstańców, a komendant twierdzy Kâmil Bej został wzięty do niewoli.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Utrata Nauplionu (Anabolu) na rzecz powstańców", "1a67fa50"], "d": ["Nauplion, najlepiej umocniony port Morei, po blokadzie trwającej ponad rok poddał się z głodu. Twierdza była od początku powstania ostatnią wielką ostoją kontroli osmańskiej na półwyspie; wraz z jej utratą cała Morea przeszła w ręce powstańców. Miasto miało wkrótce stać się pierwszą stolicą nowego państwa greckiego.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["Przejście Lepanto (İnebahtı) pod zarząd grecki", "c9d19d4b"], "d": ["Lepanto na północnym brzegu Zatoki Korynckiej, pozostające w rękach osmańskich do powstania greckiego, zostało utracone w kwietniu 1829 i weszło pod zarząd grecki; nazwę miasteczka zmieniono na antyczną Naupaktos. Ludność muzułmańska i żydowska miasta całkowicie zniknęła, a miejsce stało się małym miasteczkiem.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Francuska okupacja Algieru — koniec trzystuletniego odżaku", "0be8f568"], "d": ["Pod pretekstem incydentu z wachlarzem, który zrodził się ze sporu o należność, Francja trzymała wybrzeże algierskie w blokadzie przez trzy lata, a następnie wysadziła żołnierzy w Sidi Ferruch. Po trzytygodniowej akcji Hüseyin Dej się poddał, a osmański Odżak Algierski trwający od 1516 dobiegł końca. Okupacja nie ograniczyła się do stolicy; także Tlemcen, Szerszel i Médéa we wnętrzu kraju zostały w to samo lato utracone. Objęcie całego wybrzeża francuską kontrolą miało zająć jeszcze dwadzieścia cztery lata.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Oddanie Negroponte (Eğriboz) Grecji — wraz z wyspą (Karystos, Oreoi)", "7b524aa4"], "d": ["Negroponte, które w czasie greckiej wojny o niepodległość było sceną ciężkich walk, lecz pozostało w rękach osmańskich, zostało po wejściu w życie traktatu pokojowego oddane Grekom w 1831. Muzułmańscy mieszkańcy miasta, będącego od 1470 ważną bazą morską, sprzedali cały majątek za bardzo niskie ceny i masowo wyemigrowali na ziemie osmańskie; miasto długo stało puste, a niemiecki podróżnik Fallmerayer w 1842 nazwał je miastem widmem.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Zajęcie Oranu (Vehrân) przez Francuzów", "a8415d66"], "d": ["Oran, który Hiszpania oddała bez wojny w 1792, był największym portem na zachodzie Algierii. Sześć miesięcy po upadku stolicy oddziały francuskie wkroczyły do miasta. Akcja zachodnia rozpoczęta stąd miała wkrótce spotkać się z piętnastoletnim oporem emira Abd al-Kadira.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Zajęcie Annaby (Bône)", "21f37fb1"], "d": ["Annaba, port wschodniej Algierii blisko granicy z Tunezją, została zajęta przez siły francuskie i uczyniona bazą marszu na Konstantynę. Miasto było też najbliższym portem afrykańskim naprzeciw wyspy Sardynii.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Oddanie Aten nowemu państwu greckiemu (dzień, w którym oddziały bawarskie przejęły Akropol)", "deee4d37"], "d": ["Ateny, osmańskie od 1456, w czasie greckiej wojny o niepodległość kilkakrotnie zmieniały właściciela, a garnizon na Akropolu w 1827 ponownie wszedł pod kontrolę osmańską. Ponieważ miasto pozostało na północ od granicy wytyczonej protokołem londyńskim, zostało przekazane nowemu królestwu, a garnizon opuścił Akropol. Dzień atlasu jest dniem, w którym oddziały bawarskie przejęły Akropol; faktyczne wyjście garnizonu osmańskiego nastąpiło kilka dni później (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, rozdz. 13; Finlay, Journals and Letters, t. I, s. 67). W następnym roku Ateny zostały ogłoszone stolicą Grecji w miejsce Nauplionu.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Zajęcie Bidżaji (Bougie)", "a8927e00"], "d": ["Port Bidżaja, w którym góry Kabylii otwierają się na morze, był ostatnim niezależnym ogniwem linii wybrzeża między Algierem a Annabą. Zajęto go przy wsparciu artylerii okrętowej; leżące za nim górzyste wnętrze miało jednak nie wejść pod kontrolę francuską jeszcze przez trzydzieści lat. Te zajęcia na wybrzeżu tworzą rok po roku topnienie osmańskiego Algieru na mapie.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Zajęcie Sétif", "2073731a"], "d": ["Po upadku Konstantyny rok wcześniej siły francuskie weszły na wyżynę i zajęły dawne rzymskie miasto Sétif, tworząc tu trwały garnizon. Sétif było punktem, w którym krzyżowały się drogi karawan między wybrzeżem a Saharą; jego zajęcie pokazało, że Francja zaczęła kontrolować już nie tylko porty, lecz także wewnętrzną sieć handlową.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Zajęcie Biskry — utrata bramy Sahary", "d895cad0"], "d": ["Biskra była bramą otwierającą się na Saharę u południowego podnóża gór Atlas i ośrodkiem oaz daktylowych. Dzięki jej zajęciu w latach, gdy opór emira Abd al-Kadira zaczął się załamywać, kontrola francuska po raz pierwszy sięgnęła północnego brzegu pustyni. Dalsze działania miały już być akcją pustynną postępującą od oazy do oazy.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Zajęcie Touggourt — utrata całej Algierii", "33c056e2"], "d": ["Wraz z zajęciem oazowego miasta Touggourt na północy Sahary okupacja rozpoczęta w 1830 została dopełniona w północnej połowie dzisiejszej Algierii. Państwo osmańskie walczyło w tych latach w wojnie krymskiej w jednym obozie z Francją; choć nigdy oficjalnie nie zrzekło się prawnych pretensji do Algierii, faktycznie nie mogło zrobić ani kroku. Jedyną ziemią pozostającą w Afryce Północnej była Trypolitania.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Upadek El Obeid — przejście Kordofanu w ręce sił Mahdiego", "58299f62"], "d": ["Ruch rozpoczęty przez Muhammada Ahmada, który ogłosił się mahdim, szybko rozprzestrzenił się przeciw zarządowi egipskiemu w Sudanie. El Obeid, ośrodek Kordofanu, padło po czteromiesięcznym oblężeniu i stało się stolicą powstania; skarbiec i składy broni w mieście pozwoliły ruchowi przekształcić się w armię. Sudan był prawnie nadal ziemią chediwatu Egiptu zależnego od Osmanów, a więc strata wypada na mapie z ciała imperium.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Upadek Chartumu — utrata całego Sudanu", "d4b98464"], "d": ["Po dziesięciomiesięcznym oblężeniu siły Mahdiego weszły do Chartumu u zbiegu Nilu Błękitnego i Białego; namiestnik miasta Gordon został zabity, a wysłana na pomoc kolumna brytyjska spóźniła się o dwa dni. Od tej daty cały Sudan, w tym Sennar, Dongola i Kordofan, pozostawał przez czternaście lat pod zarządem Państwa Mahdiego. Region miał wejść pod wspólny zarząd angielsko-egipski dopiero w 1899, z całkowicie zerwaną więzią osmańską.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Włoska okupacja Massawy — utrata zachodniego wybrzeża Morza Czerwonego", "c333b95b"], "d": ["Port Massawa, ośrodek ejaletu Habesz, został zajęty przez Włochy korzystające z zamętu, w który pogrążyło Sudan powstanie mahdystów; stał się jądrem włoskiej Erytrei. Suakin na północy i archipelag Dahlak na morzu zostały utracone w tym samym procesie. W ten sposób panowanie osmańskie nad zachodnim wybrzeżem Morza Czerwonego trwające od czasów Selima Strasznego się skończyło, a morze stało się wodą obcą z obu brzegów.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Włoska okupacja Rodos", "e08662c5"], "d": ["Włochy, chcące w wojnie o Trypolitanię posadzić państwo osmańskie przy stole, przeniosły wojnę na Morze Śródziemne i wysadziły żołnierzy na Rodos. Wyspa została przejęta w ciągu kilku dni. Rodos, zdobyte w 1522 przez Sulejmana po długim oblężeniu i trzymane przez trzysta dziewięćdziesiąt lat, przestało w ten sposób być największą wyspową bazą imperium na wschodzie Morza Śródziemnego; choć w traktacie z Ouchy uznano to za okupację tymczasową, nie dało się go już odzyskać.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Włoska okupacja Dodekanezu", "200aacf2"], "d": ["W ciągu tygodnia po zajęciu Rodos flota włoska zajęła także okoliczne wyspy; archipelag ten miał później otrzymać nazwę „Dodekanez”. Większość wysp leżała kilka mil od wybrzeża Anatolii i kontrolowała południowo-wschodnie przejście Morza Egejskiego. Okupację w traktacie z Ouchy uznano za tymczasową w zamian za zrzeczenie się Trypolitanii, lecz Włochy nigdy nie opuściły wysp; miały zostać przekazane Grecji w 1947.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Okupacja Kos", "ab246c62"], "d": ["Kos, ostatnie ogniwo akcji dodekanezyjskiej, było urodzajną i zaludnioną wyspą tuż naprzeciw półwyspu Bodrum. Wraz z okupacją wszystkie wyspy w południowo-wschodnim narożniku Morza Egejskiego znalazły się pod kontrolą włoską, a południowo-zachodnie wybrzeże Anatolii zostało na całej długości otoczone obcym łańcuchem wysp.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Ogłoszenie niepodległości Ikarii", "c4452033"], "d": ["Na małej wyspie Ikaria między Samos a Chios ludność w atmosferze niepewności wywołanej włoskimi okupacjami zbuntowała się, wyparła z wyspy żandarmerię osmańską i ogłosiła „wolne państwo” trwające pięć miesięcy, z własną flagą, znaczkiem i zgromadzeniem. W listopadzie 1912 wyspa została przyłączona do Grecji. Mimo swej małości to wydarzenie jest jawnym wskaźnikiem tego, jak rozpadał się zarząd centralny na Morzu Egejskim.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Wyjście Samos spod zarządu osmańskiego", "3a862f2b"], "d": ["Samos było od 1832 autonomicznym emiratem płacącym Osmanom podatek i zarządzanym przez beja mianowanego przez Stambuł. W próżni stworzonej przez wojnę o Trypolitanię ruch unionistyczny na wyspie przejął zarząd i autonomiczny ład emiratu faktycznie się skończył; wyspa ogłosiła w tym samym roku przyłączenie do Grecji. Ta wyspa, oddalona o dwa kilometry od wybrzeża Anatolii, była jedną z pierwszych ziem utraconych na Morzu Egejskim.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Upadek Janiny — utrata Epiru i Pargi", "d42fce18"], "d": ["Janina, oblegana przez pięć miesięcy w wojnie bałkańskiej, poddała się po upadku pozycji Bizani; wraz z miastem cały Epir przeszedł do Grecji. Parga, podległa sandżakowi Janiny, została utracona w tym samym czasie i dziewięćdziesięcioczteroletni zarząd osmański się skończył. Utrata Janiny oznaczała zamknięcie ostatniego okna imperium otwierającego się na Adriatyk.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Upadek Edirne w ręce Bułgarów", "459d2e56"], "d": ["Po pięcioipółmiesięcznym oblężeniu Edirne, któremu skończyła się amunicja i żywność, się poddało; Şükrü Pasza został wzięty do niewoli. Upadek miasta osmańskiego od 1361 i będącego przez dziewięćdziesiąt dwa lata stolicą uznano za najcięższy cios wojny bałkańskiej. Edirne miało zostać odzyskane po czterech miesiącach, w II wojnie bałkańskiej, dzięki załamaniu się Bułgarii na innych frontach.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Utrata Yanbu na rzecz sił szarifa Husajna", "e291c816"], "d": ["Powstanie rozpoczęte przez szarifa Husajna w czerwcu rozszerzyło się na wybrzeże Morza Czerwonego; Yanbu, port Medyny, przeszło w ręce powstańców dzięki wsparciu floty angielskiej. Port stał się główną bramą napływu broni i pieniędzy z zewnątrz do powstania. W ten sposób siły Fahreddina Paszy w Medynie zostały odcięte od morza, a miasto pozostało samotnie na końcu kolei hidżaskiej.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["III bitwa pod Gazą — utrata Gazy i Han Yûnus", "c142a069"], "d": ["Po dwóch nieudanych próbach Allenby w trzecim natarciu przełamał front, obchodząc Beerszebę, a linia Gazy utrzymywana przez sześć miesięcy się załamała. Gaza i leżący na południe od niej Han Yûnus zostały opuszczone tego samego dnia. To przełamanie było początkiem rozpadu frontu palestyńskiego; Jerozolima miała paść po pięciu tygodniach.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Okupacja Gümülcine — utrata Tracji Zachodniej", "904d813c"], "d": ["Tracja Zachodnia, która po Mudros weszła najpierw pod kontrolę oddziałów Ententy, została postanowieniem konferencji w San Remo pozostawiona Grecji, a armia grecka wkroczyła do Gümülcine. Region odzyskany od Bułgarii w 1913 był ostatnią ziemią, jaką imperium utraciło w Rumelii. Status ludności tureckiej w regionie miał zostać uregulowany po trzech latach w Lozannie reżimem mniejszościowym. Wraz z tą okupacją kazy Gümülcine, İskeçe, Dedeağaç i Sofulu w Tracji Zachodniej przeszły do Grecji.", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Rozpad państwa Ilchanów: śmierć Abû Sa'îda Bahadura Chana", "0f187469"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Ilchanach śmierć Abû Sa'îda bez pozostawienia następcy doprowadziła do rozpadu państwa Ilchanów, panującego w Iranie od stulecia; emirowie, wykorzystując walki o tron, utworzyli lokalne dynastie, takie jak Dżalajirydzi, Karakoyunlu, Muzaffarydzi, Sarbadarzy Chorasanu i Eretnaoğulları. Ten rozpad podzielił region na mozaikę bejlików trwającą stulecie; w końcu miał zostać na nowo zjednoczony wyprawami Timura.", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["Opanowanie przez Timura większej części Iranu", "1cee2b82"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Timurze, od początku lat 80. XIV wieku likwidując jedna po drugiej lokalne dynastie po Ilchanach, takie jak Sarbadarzy, Kertowie i Muzaffarydzi, Timur w „trzyletniej wyprawie” z lat 1386–1388 faktycznie opanował większą część Iranu; ostateczny koniec dynastii Muzaffarydów miał nastąpić w 1393. Region został w ten sposób po stuletnim rozdrobnieniu ponownie związany jednym centralnym autorytetem.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Zwycięstwo nad Arasem: Kara Yûsuf pokonał timurydzkiego Abû Bakra Mirzę", "4b61a75a"], "d": ["Bej Karakoyunlu Kara Yûsuf, który po śmierci Timura w 1405 wrócił z wygnania, po zajęciu Avnik i odzyskaniu swoich ziem we Wschodniej Anatolii ruszył na Abû Bakra Mirzę, wnuka Timura, uchodzącego za pana Azerbejdżanu i dwóch Iraków, i pokonał go nad Arasem. To zwycięstwo nie dało Karakoyunlu Tabrizu: TDV `tebriz` pisze, że miasto w 1408 było w rękach Abû Bakra Mirzy; bitwą, która dała Azerbejdżan, jest Sardrud z 13 kwietnia 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Zwycięstwo pod Sardrud: Tabriz i Azerbejdżan przeszły do Karakoyunlu", "1f0a429d"], "d": ["Kara Yûsuf pokonał timurydzkiego Abû Bakra Mirzę po raz drugi po Arasie, pod Sardrud w pobliżu Tabrizu; to zwycięstwo dało Karakoyunlu Azerbejdżan. Następnie Kara Yûsuf powierzył Bistamowi Bejowi zdobycie Irâk-ı Acem;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Epidemia dżumy w Stambule i przeniesienie pałacu do Edirne", "70c7a163"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Stambule szybkie i intensywne osiedlanie się w mieście okresowo przygotowywało grunt do rozprzestrzeniania się epidemii; podczas epidemii dżumy w 1466 pałac i dostojnicy państwa tymczasowo wycofali się do Edirne. Ludność miasta ponosiła w takich epidemiach poważne straty.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Zakończenie przez Uzuna Hasana państwa Karakoyunlu", "ef68399e"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Uzunie Hasanie władca Akkoyunlu Uzun Hasan pokonał i zabił władcę Karakoyunlu Cihana Szacha w okolicach Bingöl–Sancak 12 rebîülâhir 872 / 10 listopada 1467; syn Cihana Szacha, Hasan Ali, został pokonany pod Merend we wrześniu 1468 i zabity pod Hamadanem w kwietniu–maju 1469, a państwo Karakoyunlu zostało ostatecznie zlikwidowane. Ziemie przeszły pod panowanie Akkoyunlu; państwo miało w ciągu następnej dekady rozszerzyć się aż do wnętrza Iranu.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Otwarcie medres Sahn-ı Semân do nauczania", "021f2a83"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Sahn-ı Semân te osiem medres założonych w ramach kompleksu Fatiha zostało pomyślanych jako najwyższa instytucja nauczania epoki i tworzyło szczyt osmańskiej hierarchii ilmiye. Urząd profesora i ukończenie tych medres uchodziły w następnych stuleciach za najbardziej prestiżowy szczebel w karierze kadiego i profesora.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Ukończenie Pałacu Topkapı (Saray-ı Cedîd)", "d2db6323"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Pałacu Topkapı źródła epoki rozchodzą się co do dat rozpoczęcia i ukończenia budowy; według daty 883 (1478) na inskrypcji Bâb-ı Hümâyun budowa, rozpoczęta z rozkazu Zdobywcy prawdopodobnie w 1465, była do tego roku w znacznej mierze ukończona, a pałac zajął miejsce ośrodka państwa w dawnym pałacu. W ten sposób sułtan przeniósł się do nowej rezydencji, która miała przez trzy stulecia być administracyjnym i ceremonialnym sercem państwa.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Wstąpienie Bayezida II na tron w Stambule", "9b686d04"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Bayezidzie II książę Bayezid, sandżakbej Amasyi, po otrzymaniu wieści o śmierci ojca szybko przybył do Stambułu i wstąpił na tron; wyprzedził ruszającego z Konyi brata Cema dzięki poparciu janczarów. Przy wstąpieniu na tron janczarom rozdano zwyczajowy podarek wstąpieniowy. Ta zmiana tronu zapaliła też lont walki między dwoma braćmi.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Ogłoszenie się sułtanem przez Cema w Bursie", "b355168a"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Cemie Sułtanie Cem, który przez Karaman dotarł do Bursy, zajął miasto, ogłosił się sułtanem i kazał odczytać chutbę. To krótkotrwałe panowanie zakończyło się, gdy siły wysłane przez starszego brata Bayezida II pokonały Cema pod Yenişehir. Wskutek klęski Cem musiał uciekać w stronę Egiptu.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Stracenie Gediga Ahmeda Paszy", "6d75a58c"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Gediku Ahmedzie Paszy, znany z wyprawy do Otranto i wielkiego wezyratu, został stracony w Edirne z rozkazu Bayezida II z powodu postawy w sprawie księcia Cema i obaw wywołanych jego wpływami. Śmierć jednego z najbardziej doświadczonych dowódców epoki Zdobywcy wywołała w pałacu szeroki oddźwięk.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Założenie pierwszej drukarni w Stambule", "04475930"], "d": ["Według hasła TDV İslâm Ansiklopedisi o drukarni żydowscy emigranci z Hiszpanii, bracia David i Samuel ibn Nahmias, założyli w Stambule pierwszą drukarnię drukującą czcionkami hebrajskimi. Odnotowano ją jako pierwszą próbę drukarską działającą w ziemiach osmańskich; druk tureckimi czcionkami arabskimi miał stać się możliwy znacznie później, w XVIII wieku.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Zajęcie Tabrizu przez szacha İsmaila: założenie państwa Safawidów", "014d81e6"], "d": ["Według haseł TDV İslâm Ansiklopedisi o Safawidach i Akkoyunlu młody szejch tekke w Ardabilu İsmail, z armią zebraną z kızılbaszów-murydów w Anatolii, zadał w okolicach Nachiczewanu ciężką klęskę sułtanowi Akkoyunlu Elvendowi; Elvend uciekł do Diyarbekir, a İsmail wkroczył do Tabrizu, zasiadł na tronie i ogłosił szyizm dwunastu imamów oficjalnym wyznaniem. W ten sposób zamknęły się zarówno panowanie Akkoyunlu, jak i okres bejlików po Ilchanach w regionie; powstało państwo Safawidów, które miało trwać trzy stulecia.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Trzęsienie ziemi „Małe Końca Świata” w Stambule", "53e3b1d6"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Stambule silne trzęsienie ziemi, które dotknęło miasto, wspominano wśród ludu jako „Małe Końca Świata”; w murach, meczetach i wielu budynkach powstały ciężkie szkody, doszło do licznych strat w ludziach. Z rozkazu Bayezida II w mieście rozpoczęto szeroką mobilizację naprawczą i budowlaną.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Początek powstania Şahkuluego", "3d9a4a90"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Şahkulu Babie Tekeli, Şahkulu, żywiony propagandą safawidzką, zebrał wokół siebie szeroką masę turkmeńską w regionie Teke i rozpoczął wielkie powstanie o charakterze religijno-społecznym. Powstanie, jako jeden z najpoważniejszych kryzysów bezpieczeństwa wewnętrznego epoki, głęboko wstrząsnęło centralnym autorytetem państwa.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Śmierć Bayezida II w drodze do Dimetoki", "c46e98c9"], "d": ["Dawny sułtan, który po abdykacji opuścił Stambuł, by udać się do rodzinnego miasta Dimetoka, posuwając się w lektyce pokonującej zaledwie 5–6 km dziennie, zasłabł we wsi Abalar koło Çorlu i zmarł 25 rebîülevvel 918 (10 czerwca 1512). Hasło TDV İslâm Ansiklopedisi uznaje przyczynę śmierci za bardzo wątpliwą; według niektórych źródeł miejscowych i zagranicznych rozważa się możliwość otrucia. Po trzydziestojednoletnim panowaniu zmarł w ten sposób ósmy sułtan z rodu Osmana Gazi.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Stracenie księcia Ahmeda z rozkazu Selima Strasznego", "65abb2f2"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Selimie I książę Ahmed, ulubieniec ojca Bayezida II i główny rywal do tronu, w walce podjętej po wstąpieniu brata Selima na tron został rozbity na równinie Yenişehir i schwytany podczas ucieczki z pola bitwy, po czym zabity. Tym wydarzeniem Selim w znacznej mierze zakończył rywalizację o tron między braćmi i bratankami.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["Mianowanie İbrahima Paszy wielkim wezyrem", "9c94c1e3"], "d": ["Według hasła TDV İslâm Ansiklopedisi o İbrâhîmie Paszy Makbulu İbrahim Pasza, awansowany z odabaszy do beylerbeja Rumelii i tego samego dnia do wielkiego wezyratu, został wielkim wezyrem 13 şaʿbana 929 (27 czerwca 1523). Było to mianowanie nie mające precedensu, polegające na przejściu ze służby pałacowej bezpośrednio do wielkiego wezyratu, i wskazywało na niezwykłą bliskość İbrahima Paszy wobec Sulejmana.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Mianowanie Barbarossy Hayreddina Paszy kapudanem paszą", "a0ff6bab"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Barbarossie Hayreddinie Paszy Hayreddin Pasza, znany z sukcesów w Algierze, został 6 kwietnia 1534 wezwany do Stambułu i mianowany kapudanem paszą oraz beylerbejem Cezâyir-i Bahr-i Sefîd. To mianowanie uchodzi za początek przebudowy floty osmańskiej i instytucjonalizacji potęgi morskiej na Morzu Śródziemnym.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rüstem Pasza po raz pierwszy wielkim wezyrem", "ddfcc014"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Rüstemie Paszy, po odwołaniu Hadıma Süleymana Paszy wskutek sporu z jednym z wezyrów, Rüstem Pasza został mianowany wielkim wezyrem 17 ramadanu 951 (2 grudnia 1544). Rüstem Pasza, którego bliskość pałacu wzrosła dzięki małżeństwu z Mihrimah Sułtan, stał się dzięki temu urzędowi jednym z najbardziej wpływowych mężów stanu epoki Sulejmana.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebüssuûd Efendi szejhülislamem", "11ed04f8"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Ebüssuûdzie Efendim Ebüssuûd Efendi, który przez osiem lat był kazaskerem Rumelii, został mianowany szejhülislamem w şaʿbanie 952 (październik 1545) i pozostał na tym urzędzie dwadzieścia osiem lat i jedenaście miesięcy. Ebüssuûd Efendi, znany z fatw dostosowujących kanunname Sulejmana do prawa szariatu, odegrał rozstrzygającą rolę w kształtowaniu instytucji prawnych i edukacyjnych swej epoki.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Śmierć Barbarossy Hayreddina Paszy", "3378a0bf"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Barbarossie Hayreddinie Paszy zmarł w Stambule 6 cemâziyelevvel 953 (5 lipca 1546) po krótkiej chorobie. Śmierć Barbarossy, pochowanego w mauzoleum przylegającym do medresy, którą kazał zbudować w Beşiktaş, została uznana za zamknięcie okresu przewagi na Morzu Śródziemnym, którą zbudowała flota osmańska.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Rozpoczęcie budowy meczetu i kompleksu Süleymaniye", "101ec36f"], "d": ["Według hasła TDV İslâm Ansiklopedisi o meczecie i kompleksie Süleymaniye kompleks, którego fundamenty położono w 1550 pod kierunkiem naczelnego architekta Sinana, został zaprojektowany jako wielki kompleks społeczny złożony z meczetu oraz medres, szpitala, imaretu i biblioteki. Budowa była jednym z największych programów budowlanych symbolizujących potęgę panowania Sulejmana i rozwój Stambułu.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Początek nowej fali dżumy w Stambule i okolicach", "547d6bf6"], "d": ["Według hasła TDV İslâm Ansiklopedisi o dżumie (tâun) jedna z epidemii XVI wieku dotykających świat islamu miała miejsce w latach 1552–1566 i była szczególnie dotkliwa w Stambule, Anatolii, Rumelii, Egipcie i Afryce Północnej. Rozszerzające się szlaki handlowe i rosnąca ruchliwość ludności zaliczane są do czynników ułatwiających rozprzestrzenianie się epidemii w najpotężniejszym okresie imperium.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Mianowanie Kary Ahmeda Paszy wielkim wezyrem", "a7d7748e"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Karze Ahmedzie Paszy Kara Ahmed Pasza, pełniący obowiązki drugiego wezyra, został awansowany do wielkiego wezyratu 27 şewwala 960 (5 października 1553) po nagłym odwołaniu urzędującego wielkiego wezyra. Ta zmiana wskazuje na okres zbiegający się w czasie ze straceniem księcia Mustafy, w którym równowagi sił wewnątrz pałacu szybko zmieniały właściciela.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Stracenie kapudana paszy Pîrî Reisa", "3b2ad7a0"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Pîrî Reisie, gdy do Egiptu dotarły oskarżenia, że przy zniesieniu oblężenia Ormuzu złupił za łapówkę mienie muzułmanów i opuścił armię na polu bitwy, słynny żeglarz i kartograf został stracony w Kairze pod koniec roku 960 (koniec 1553). Śmierć Pîrî Reisa, którego majątek skonfiskowano, uznawana jest za skutek rywalizacji między paszami w polityce morskiej w Basrze i na Oceanie Indyjskim.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Stracenie Kary Ahmeda Paszy, Rüstem Pasza ponownie wielkim wezyrem", "9a85076a"], "d": ["Według haseł TDV İslâm Ansiklopedisi o Rüstemie Paszy i Karze Ahmedzie Paszy, na miejsce Kary Ahmeda Paszy, nagle straconego 13 zilkade 962 (29 września 1555) w czasie zebrania diwanu, Rüstem Pasza został tego samego dnia po raz drugi mianowany wielkim wezyrem przy poparciu sułtanek Hürrem i Mihrimah. Kulisy wydarzenia pozostawiono w źródłach niejasne; oceniono je jako skutek intryg wewnątrz pałacu.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Śmierć Hürrem Sułtan", "1ae998b5"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Hürrem Sułtan Hürrem Sułtan, haseki sułtanka Sulejmana, mająca przez lata wielki wpływ wewnątrz pałacu, zmarła w Stambule 26 cemâziyelâhir 965 (15 kwietnia 1558) i została pochowana w mauzoleum w kompleksie meczetu Süleymaniye. Śmierć Hürrem Sułtan, która po śmierci wielkiej matki sułtańskiej Hafsy w 1534 umocniła swój autorytet nad haremem, usunęła też równoważący wpływ stojący na przeszkodzie rywalizacji o tron między jej synami Bayezidem i Selimem.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Awans Sokollu Mehmeda Paszy na wielkiego wezyra", "896391a2"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Sokollu Mehmedzie Paszy Sokollu Mehmed Pasza, który po śmierci Semiza Alego Paszy 30 zilkade 972 (29 czerwca 1565) awansował na wielkiego wezyra, został ostatnim wielkim wezyrem Sulejmana i pozostał na tym urzędzie także za Selima II i Murada III, stając się jednym z najdłużej urzędujących wielkich wezyrów w dziejach osmańskich.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selim II dotarł do Stambułu i wstąpił na tron", "0289ef97"], "d": ["Po śmierci Sulejmana Prawodawcy pod Szigetvárem wieść o niej była przez tygodnie utrzymywana w tajemnicy przez Sokollu Mehmeda Paszę, by nie zakłócić porządku. Według TDV İslâm Ansiklopedisi Selânikî podaje dzień przybycia Selima do Stambułu jako 15 rebîülevvel 974 (30 września 1566), podczas gdy większość współczesnych historyków uznaje za prawidłowy 9 rebîülevvel (24 września). Śmierć Sulejmana została oficjalnie ogłoszona dopiero 24–25 października 1566 w Belgradzie.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["Flota odbudowana przez Kılıça Alego Paszę zwodowana", "d0fc9f48"], "d": ["Po ciężkiej klęsce pod Lepanto (7 października 1571) przez całą zimę budowano okręty w stoczniach. Według TDV İslâm Ansiklopedisi 1 safera 980 (13 czerwca 1572) nowa flota złożona z 250 galer i około 300 galer ochotniczych reisów została zwodowana w pokazie siły.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Zamach na Sokollu Mehmeda Paszę i jego zabicie", "6ffa8dec"], "d": ["Sokollu Mehmed Pasza, który przez czternaście lat był wielkim wezyrem za trzech sułtanów, został zasztyletowany 20 şaʿbana 987 (12 października 1579) przez derwisza, który zbliżył się do niego na popołudniowym diwanie w jego rezydencji, jakby chciał złożyć petycję. Według TDV İslâm Ansiklopedisi dyskutuje się, czy zamach mógł mieć związek z zemstą za straconego szejcha Hamzawijja Hamzę Bâlîego.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Pierwsze ahidname handlowe z Anglią — nadanie Anglikom kapitulacji", "59c8e3ee"], "d": ["William Harborne, angielski przedstawiciel wysłany do Stambułu w październiku 1578, uzyskał od Murada III przy poparciu Sokollu Mehmeda Paszy i Hoca Sâdeddina Efendiego ahidname z 1580. Na mocy tego ahidname kupcy angielscy zyskali prawo korzystania w tym samym stopniu z przywilejów handlowych (kapitulacji) przyznanych wcześniej Francuzom i Wenecjanom. Między królową Elżbietą I a Muradem III wymieniono listy i nawiązano też oficjalne stosunki między obu państwami. Bezpośrednio po tych przywilejach w 1581 w Londynie założono Levant Company; Anglicy prowadzili swój handel w regionie za pośrednictwem tej spółki do 1825.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Zburzenie Obserwatorium Stambulskiego na mocy hatt-ı hümâyun", "3bc0c78c"], "d": ["Pod wpływem fatwy, że obserwatoria przynoszą krajom nieszczęście, i opozycji w pałacu Obserwatorium Stambulskie zostało zburzone wraz ze wszystkimi przyrządami na mocy hatt-ı hümâyun z 4 zilhidżdże 987 (22 stycznia 1580). Według TDV İslâm Ansiklopedisi był to krótkotrwały koniec instytucji założonej przez Takıyyüddina ar-Râsıda.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Początek obrzezania księcia Mehmeda na Atmeydanı", "c2926d5d"], "d": ["Książę Mehmed, syn Murada III, został obrzezany w okazałych uroczystościach, które rozpoczęły się 6 cemâziyelevvel 990 (29 maja 1582) i trwały pięćdziesiąt sześć–pięćdziesiąt siedem dni. Według TDV İslâm Ansiklopedisi uroczystości zorganizowane na Atmeydanı były jednym z najwspanialszych pałacowych obchodów swojej epoki.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Śmierć wielkiej matki sułtańskiej Nurbânû", "77d0a577"], "d": ["Matka Murada III, Nurbânû Sułtan, zmarła 22 zilkade 991 (7 grudnia 1583). Według TDV İslâm Ansiklopedisi jako wielka matka sułtańska prowadziła korespondencję z pałacami Wenecji i Francji, a senat wenecki zgodził się w tym samym roku przesłać jej w uznaniu zasług dar o wartości 2000 złotych weneckich.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Wydarzenie Beylerbeyi wybuchło z powodu zdewaluowanego akçe", "db2f2e61"], "d": ["Gdy państwo dokonywało płatności, obniżając zawartość srebra w akçe, sipahi i janczarzy otoczyli pałac i wzniecili krwawe powstanie, które weszło do historii pod nazwą Wydarzenia Beylerbeyi. Według hasła TDV İslâm Ansiklopedisi o Abdülkadirze Şeyhî Efendim szejhülislam został po tym wydarzeniu odwołany.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmed III wstąpił na tron, uduszono dziewiętnastu książąt", "2cd9a8c5"], "d": ["Mehmed III po śmierci ojca Murada III dotarł do Stambułu w piątek 16 cemâziyelevvel 1003 (27 stycznia 1595) i wstąpił na tron. Według TDV İslâm Ansiklopedisi tej samej nocy uduszono dziewiętnastu książąt, w tym czterech dorosłych (Mustafę, Bayezida, Osmana i Abdullaha); było to największe bratobójstwo w dziejach osmańskich.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sułtan zyskała wpływy jako wielka matka sułtańska", "000bec21"], "d": ["Safiye Sułtan, żona Murada III i matka Mehmeda III, wraz z wstąpieniem syna na tron awansowała jako wielka matka sułtańska na pozycję decydującą w polityce pałacowej. Według TDV İslâm Ansiklopedisi w tym okresie wpływy haremu sięgnęły wymiaru bezpośredniej ingerencji w sprawy państwa.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Mehmed III wyruszył osobiście na wyprawę pod naciskiem janczarów", "d3c50656"], "d": ["Mimo sprzeciwu wielkiego wezyra Damada İbrahima Paszy, pod naciskiem janczarów Mehmed III wyruszył 20 czerwca 1596 ze Stambułu na wyprawę jako pierwszy po Sulejmanie sułtan, który stanął osobiście na czele armii. Według TDV İslâm Ansiklopedisi oznaczało to ożywienie dawnej tradycji gaza.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["Epidemia dżumy rozpoczęta w latach 70. XVI wieku nadal dotykała Stambuł", "eb4ca37a"], "d": ["Według hasła TDV İslâm Ansiklopedisi o dżumie epidemia rozpoczęta w latach 70. XVI wieku utrzymywała swój wpływ do początków XVII wieku i dotknęła przede wszystkim Stambuł, a także Anatolię, Bałkany, Egipt i Afrykę Północną. Okresy epidemii stanowiły chroniczne zagrożenie często przerywające życie pałacu i miasta.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Śmierć Karayazıcı Abdülhalima, osłabienie ruchu powstańczego", "876ca7a6"], "d": ["Karayazıcı Abdülhalim, który po ciężkiej klęsce poniesionej 12 sierpnia 1601 w Sepetli koło Elbistan wycofał się ranny, zmarł w roku 1010 (1602). Według TDV İslâm Ansiklopedisi wieść o jego śmierci dotarła do Stambułu w ramadanie 1010 (luty–marzec 1602); źródła odnotowują, że jest sporne, czy jego śmierć nastąpiła wskutek rany, czy z rąk jego własnych ludzi.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Faktyczny koniec tradycji bratobójstwa", "9046c607"], "d": ["Ahmed I przy wstąpieniu na tron, w odróżnieniu od poprzednich sułtanów, nie kazał zabić brata księcia Mustafy i darował mu życie; ta decyzja uchodzi za początek faktycznego przyjęcia w osmańskim systemie sukcesji zasady ekberiyet-erşediyet. Hasło TDV İslâm Ansiklopedisi o „Mustafie I” przekazuje, że po tej dacie Mustafa wiódł w pałacu życie w odosobnieniu. Praktyka ta faktycznie położyła kres morderstwom przy wstąpieniu na tron trwającym od wieków.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Położenie fundamentów meczetu Sułtanahmet", "1683262f"], "d": ["Z rozkazu Ahmeda I na Atmeydanı w uroczystości położono fundamenty meczetu, który miał zbudować architekt Sedefkâr Mehmed Aga. Według hasła TDV İslâm Ansiklopedisi o „Meczecie i kompleksie Sułtana Ahmeda” budowla stała się też przedmiotem krytyki epoki jako pierwszy wielki meczet sułtański zbudowany bezpośrednio ze skarbu, bez zwycięstwa zdobywczego. Kompleks zaprojektowano tak, by obejmował wraz z meczetem także medresę, imaret i mauzoleum.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Zabicie Młodego Osmana przez janczarów (Hâile-i Osmâniye)", "324f6582"], "d": ["Janczarzy i sipahi, którzy zbuntowali się po pogłoskach, że pod pretekstem pielgrzymki opuści Stambuł i zamierza rozwiązać korpus janczarów, zdetronizowali Osmana II i kazali go udusić w lochach Yedikule. Według hasła TDV İslâm Ansiklopedisi o „Osmanie II” było to w dziejach osmańskich pierwsze wydarzenie, w którym sułtan został jawnie zabity wskutek buntu wojskowego, i wywołało głębokie załamanie w stosunkach dynastii z wojskiem. Jego ostatnie godziny upłynęły następująco: gdy próba schronienia się w rezydencji agi janczarów Alego Agi nie dała skutku, sułtan został, według słów TDV, „w straszliwy sposób, z odkrytą głową i w rozstroju”, posadzony na koniu i wśród ciężkich zniewag zaprowadzony najpierw do Orta Cami, gdzie był Mustafa I, a po południu tego samego dnia do Yedikule; według niektórych historyków, by udowodnić jego śmierć, odcięto mu ucho i nos i pokazano je matce Mustafy I. Po tym wydarzeniu Mustafa I został po raz drugi wprowadzony na tron. Wydarzenie zwane „Hâile-i Osmâniye” (tragedia Osmana) trwale zburzyło równowagę pałac–odżak i zapoczątkowało spory o legitymację trwające przez stulecie.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Ponowne wprowadzenie Mustafy I na tron", "34a0b29a"], "d": ["Po zabiciu Młodego Osmana przez janczarów, ponieważ w dynastii nie było innego dorosłego mężczyzny, Mustafa I został po raz drugi wprowadzony na tron. Według hasła TDV İslâm Ansiklopedisi o „Mustafie I” także to drugie panowanie, podobnie jak poprzednie, upłynęło bez faktycznego prowadzenia spraw państwa, a zarząd państwa pozostał w rękach wezyrów i wielkiej matki sułtańskiej. Ten trwający czternaście miesięcy okres zakończył się w 1623 wstąpieniem na tron Murada IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Pożar Cibali", "3e42fb08"], "d": ["Pożar, który wybuchł w Cibali i szybko rozprzestrzenił się pod wpływem wiatru, obrócił w popiół dużą część Stambułu; według hasła TDV İslâm Ansiklopedisi o „Stambule” źródła epoki przekazują, że spłonęły tysiące domów. Powiązanie pożaru z drewnianą zabudową i paleniem tytoniu stało się bezpośrednim powodem surowego zakazu tytoniu i kawiarni, który Murad IV ogłosił wkrótce potem. Katastrofa była tylko jednym z powtarzających się wielkich pożarów ówczesnego Stambułu.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Zakaz tytoniu i kawiarni Murada IV", "5dd71297"], "d": ["Po pożarze Cibali, z obawy przed pożarami i dla zapewnienia porządku, Murad IV zakazał palenia tytoniu i kawiarni; wobec nieprzestrzegających zakazu stosowano ciężkie kary, w tym karę śmierci. Według hasła TDV İslâm Ansiklopedisi o „Muradzie IV” sułtan prowadził tak surową politykę wewnętrznej dyscypliny, że osobiście, w przebraniu, chodził ulicami miasta, by kontrolować zakaz. Te surowe środki uważane są za część wysiłków Murada IV mających na celu odbudowę władzy centralnej.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Epidemia dżumy w Stambule", "f33f58c5"], "d": ["Za Murada IV Stambuł został wstrząśnięty ciężką epidemią dżumy, która dotknęła znaczną część ludności; handel w mieście i codzienne życie zostały przez miesiące zakłócone. Hasło TDV İslâm Ansiklopedisi o „Stambule” odnotowuje, że powtarzające się w XVII wieku epidemie poważnie wpłynęły na równowagę ludnościową miasta. W okresie epidemii pałac i elita na pewien czas przenosiły się do ogrodów i pawilonów poza miastem.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Lot na skrzydłach Hezarfena Ahmeda Çelebiego (przekaz)", "df474c04"], "d": ["Według przekazu podanego przez Evliyę Çelebiego Hezarfen Ahmed Çelebi, skoczywszy z Wieży Galata na skrzydłach, które sam zbudował, zdołał szybować aż do Üsküdar; choć jego historyczna pewność jest sporna, stał się symbolem technicznej wyobraźni. Sułtan, który początkowo go nagrodził, zesłał potem Hezarfena do Algieru wobec oddźwięku, jaki wywołało wydarzenie.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Zdobycie wpływów w pałacu przez Cinci Hocę Hüseyina Efendiego", "41d21572"], "d": ["Znachor Hüseyin Efendi, wezwany do pałacu, by leczyć dolegliwości psychiczne sułtana Ibrahima, szybko zyskał zaufanie sułtana i awansował aż do kazaskeratu Anatolii. Według hasła TDV İslâm Ansiklopedisi o „Hüseynie Efendim, Cinci Hoca” wykorzystywał te wpływy do gromadzenia majątku i ingerowania w wydarzenia polityczne epoki. Po śmierci Ibrahima został odsunięty od wszystkich urzędów i stracony w 1648.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Stracenie Kemankeşa Mustafy Paszy", "0ecc8030"], "d": ["Kemankeş Mustafa Pasza, który od czasów Murada IV był wielkim wezyrem i dzięki reformom finansowym uzyskał dla skarbu znaczną nadwyżkę, został uduszony i stracony po tym, jak rywale wewnątrz pałacu wpłynęli na Ibrahima i oskarżyli go o wzniecenie buntu janczarów. Według hasła TDV İslâm Ansiklopedisi o „Kemankeşu Mustafie Paszy” stracenie nastąpiło 21 zilkade 1053 / 31 stycznia 1644: Kemankeş Kara Mustafa Pasza został uduszony na Hocapaşa Çarşısı przez kata Karę Alego i pochowany w swym mauzoleum w Çarşıkapı. Jego śmierć jest wspominana jako uderzający przykład niestabilności urzędu wielkiego wezyra w epoce i zakończyła krótki okres surowych reform.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Decyzja diwanu o wyprawie kreteńskiej i wyjście floty", "9076827e"], "d": ["W Divan-ı Hümayun postanowiono o rozpoczęciu wielkiej wyprawy przeciw należącej do Wenecji wyspie Krecie, a flota osmańska pod dowództwem kapudana paszy wyruszyła ze Stambułu w kierunku Krety. Według hasła TDV İslâm Ansiklopedisi o „Krecie” ta decyzja stanowiła polityczny początek długiego okresu oblężenia i wojny, który miał trwać około dwudziestu pięciu lat. Rozpoczęcie wyprawy, jako największe przedsięwzięcie polityki zagranicznej epoki Ibrahima, wywołało szerokie dyskusje wśród dostojników państwa.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Wstąpienie na tron Mehmeda IV w wieku siedmiu lat", "a197a3bc"], "d": ["Bezpośrednio po detronizacji Ibrahima na tron wprowadzono jego siedmioletniego syna Mehmeda, który został sułtanem pod imieniem Mehmeda IV. Według hasła TDV İslâm Ansiklopedisi o „Mehmedzie IV” wstąpienie na tron w tak młodym wieku zaostrzyło walkę o wpływy wewnątrz pałacu między jego babką Kösem Sułtan a matką Turhan Sułtan. Ta walka o władzę miała zakończyć się w 1651 zabiciem Kösem Sułtan.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Reforma zrównoważonego budżetu Tarhuncu Ahmeda Paszy", "376fc7f2"], "d": ["Wielki wezyr Tarhuncu Ahmed Pasza, by przezwyciężyć kryzys finansowy wywołany długimi latami wojny, zastosował surowy program oszczędnościowy obejmujący także wydatki pałacowe i przygotował pierwszy znany w dziejach osmańskich zrównoważony budżet (lâyiha Tarhuncu). Według hasła TDV İslâm Ansiklopedisi o „Tarhuncu Ahmedzie Paszy” ta reforma przyniosła skarbowi znaczną nadwyżkę, lecz wywołała szerokie niezadowolenie w otoczeniu pałacowym i wyższej biurokracji. To niezadowolenie miało po roku zakończyć się jego straceniem.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Wydarzenie pod platanem (Çınar Vak'ası; Vak'a-i Vakvakiye)", "4c6ed90f"], "d": ["Według hasła TDV İslâm Ansiklopedisi o wydarzeniu pod platanem janczarzy i sipahi, którzy wrócili z wyprawy kreteńskiej bez wypłaty żołdu, zbuntowali się w Stambule i zażądali stracenia dostojników oskarżanych o korupcję. Propozycja wielkiego wezyra Zurnazena Mustafy Paszy dotycząca konfiskaty i zesłania nie została przyjęta; najpierw stracono trzech urzędników, a następnie blisko trzydziestu dostojników państwa, których ciała powieszono na platanach na placu Sułtanahmet. Dlatego wydarzenie zwane jest Çınar Vak'ası.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Mianowanie Köprülü Mehmeda Paszy wielkim wezyrem na warunkach", "3a6b7f8f"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Köprülü Mehmedzie Paszy Köprülü Mehmed Pasza, bliski osiemdziesiątki, przyjął pieczęć dopiero po tym, jak wymusił na wielkiej matce sułtańskiej Turhan Sułtan i Mehmedzie IV przyjęcie ciężkich warunków — niemieszania się do jego mianowań i niewiary w to, co mówi się przeciw niemu. Objął urząd 26 zilkade 1066 na miejsce Boynueğri Mehmeda Paszy i przystąpił do surowego przywracania dyscypliny państwa.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Stłumienie ruchu Kadızâdelich przez Köprülü Mehmeda Paszę", "5ec3ce84"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Kadızâdelich, Köprülü Mehmed Pasza, zaraz po objęciu urzędu zajął się konfliktem religijnym między otoczeniem Kadızâde Mehmeda Efendiego a ludźmi tarikatów. Po zasięgnięciu opinii ulemów wydał ferman o straceniu przywódców ruchu Üstüvânîego Mehmeda Efendiego, Türka Ahmeda i Divâne Mustafy, lecz karę zamieniono na zesłanie i trzech wysłano na Cypr; w ten sposób druga faza ruchu się skończyła.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Wielki pożar w Stambule: spalenie Ağakapısı", "b9253b66"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Ağakapısı w wielkim pożarze, który wybuchł w lipcu 1660 za Mehmeda IV, całkowicie spłonęła oficjalna kwatera agi janczarów, Ağakapısı, a następnie została odbudowana. Ten pożar był jednym z wielkich pożarów miejskich, które wielokrotnie nawiedzały ówczesny Stambuł.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Mianowanie Köprülüzâde Fâzıla Ahmeda Paszy wielkim wezyrem", "c1999b5c"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Köprülüzâde Fâzılu Ahmedzie Paszy po śmierci ojca Köprülü Mehmeda Paszy został 8 rebîülevvel 1072 (1 listopada 1661) mianowany wielkim wezyrem. Fâzıl Ahmed Pasza, w odróżnieniu od ojca znany jako łagodny, pobożny i opiekun uczonych i artystów, w czasie ponad piętnastoletniego wezyratu kazał założyć biblioteki i instytucje dobroczynne w Stambule i na zdobytych ziemiach.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Mianowanie Vânîego Mehmeda Efendiego kaznodzieją Yeni Cami i nauczycielem sułtana", "7ea6aaae"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Mehmedzie Efendim, Vânî, Vânî Mehmed Efendi, wezwany do Stambułu po objęciu wezyratu przez Köprülüzâde Fâzıla Ahmeda Paszę i przedstawiony Mehmedowi IV, szybko zyskał żywe zainteresowanie sułtana. W 1665 został mianowany kaznodzieją Yeni Cami i nauczycielem sułtana i stał się jednym z najbardziej wpływowych duchownych pałacu.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Mianowanie Merzifonlu Kary Mustafy Paszy wielkim wezyrem", "3d1e836c"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Merzifonlu Karze Mustafie Paszy po śmierci Fâzıla Ahmeda Paszy został 28 şaʿbana 1087 (5 listopada 1676) mianowany wielkim wezyrem. Merzifonlu, zięć i wychowanek rodu Köprülü, o długim doświadczeniu w zarządzaniu państwem, stał się jednym z najpotężniejszych i najbardziej wpływowych wielkich wezyrów Mehmeda IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Śmierć Vânîego Mehmeda Efendiego na zesłaniu", "cda714aa"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Mehmedzie Efendim, Vânî, Vânî Mehmed Efendi, uchodzący za jednego z głównych, którzy przekonali sułtana do wyprawy wiedeńskiej, po klęsce tej wyprawy został pod naciskiem opinii publicznej wypchnięty z łask i zesłany do miasteczka Kestel koło Bursy. Zmarł tu 14 zilkade 1096 (12 października 1685) i został pochowany przy wejściu do meczetu, który sam zbudował.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Mianowanie Köprülüzâde Fâzıla Mustafy Paszy wielkim wezyrem i jego reformy finansowe", "b048570e"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Köprülüzâde Fâzılu Mustafie Paszy Fâzıl Mustafa Pasza, mianowany wielkim wezyrem 11 muharrema 1101 (25 października 1689), uregulował na nowo sposób ściągania dżizji według zasad szariatu, zwalczał inflację mangırów i wzmocnił skarb, przekierowując środki z instytucji pałacowych. Ponadto wzmocnił zarząd prowincjonalny wiarygodnymi urzędnikami i kazał utworzyć lokalne rady podobne do diwanu centralnego.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Wejście w życie systemu mâlikâne", "316b8426"], "d": ["Według hasła TDV İslâm Ansiklopedisi o mâlikâne w ostatniej ćwierci XVII wieku wzrost kosztów wojny i spadek dochodów wskutek utraty ziem wprowadziły skarb w ciężki kryzys finansowy. W systemie mâlikâne, który wszedł w życie w 1106 (1695), mültezimom przyznano dożywotnie prawo do stałego podatku, wprowadzając zachętę do ochrony produkcji zamiast krótkoterminowego wyzysku.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Wstąpienie na tron Mustafy II", "b53656c7"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Mustafie II, Mustafa II, który wstąpił na tron w wieku trzydziestu jeden lat, ogłosił swój sułtanat bez czekania na zgodę wielkiego wezyra i szejhülislama; ceremonia przepasania mieczem odbyła się kilka dni później w Eski Cami. Sułtan, który wstąpił na tron w okresie trwających wojen wielofrontowych po klęsce pod Wiedniem, został ostatnim sułtanem osmańskim, który osobiście wyruszał na wyprawy.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Drugie mianowanie Feyzullaha Efendiego szejhülislamem", "1cf14cff"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Feyzullahu Efendim, Seyyid, Feyzullah Efendi został po wstąpieniu Mustafy II na tron po raz drugi mianowany szejhülislamem 11 şewwala 1106 (25 maja 1695). Jego wpływy na sułtana stopniowo rosły w trwającym ponad osiem lat okresie na tym urzędzie.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Obsadzenie przez Feyzullaha Efendiego synów na wyższych urzędach i narastająca reakcja", "a6398280"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Feyzullahu Efendim, Seyyid, szejhülislam otrzymał od Mustafy II niemający precedensu ferman o tym, że jego syn Fethullah Efendi zostanie po nim szejhülislamem, i umieścił swoich krewnych w młodym wieku na wysokich urzędach. Te praktyki wywołały szerokie niezadowolenie wśród klasy ilmiye, wojska i ludności Stambułu; połączone z pogłoskami o przeniesieniu stolicy do Edirne przygotowały grunt pod Wydarzenie Edyrneńskie 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Początek Wydarzenia Edyrneńskiego", "5a106458"], "d": ["Według hasła TDV o „Wydarzeniu Edyrneńskim” ruch rozpoczęty buntem żołnierzy, którzy nie dostali żołdu, w krótkim czasie przekształcił się w szerokie powstanie, w którym wzięli udział janczarzy, uczniowie medres, rzemieślnicy i lud. Głównym celem powstania był szejhülislam Feyzullah Efendi, o którym twierdzono, że nadmiernie ingeruje w sprawy państwa. Tłum liczący około 60 000 osób pomaszerował ze Stambułu do Edirne.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Wezyrat Nevşehirli Damada İbrahima Paszy", "8d627a6f"], "d": ["Według hasła TDV o „Damadzie İbrâhimie Paszy, Nevşehirli” został on mianowany na urząd wielkiego wezyra 8 cemâziyelâhir 1130 (9 maja 1718) w czasie trwających rokowań pokojowych z Austrią i zaraz po mianowaniu zwrócił się ku rokowaniom, które miały zakończyć wojnę; po dwóch miesiącach podpisano traktat z Passarowitz (21 lipca 1718). W ujęciu TDV „chciał zajmować się sprawami społecznymi i finansowymi, tęsknił za okresem pokoju, który pozwoliłby zapomnieć o wojnach kończących się od lat porażką”. Przeprowadził reformy w finansach, obniżył żołd żołnierzy i uzyskał w skarbie państwa znaczną nadwyżkę. Jego trwający dwanaście lat wezyrat stworzył polityczne ramy epoki noszącej jego imię (Epoki Tulipanów).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Założenie Odżaku Tulumbacı", "f58b0d97"], "d": ["Według hasła TDV o „Tulumbacı”, po sukcesie Gerçeka Dâvuda, który wrócił z wyprawy morejskiej 1715, w pożarach Stambułu przy użyciu sikawek (tulumba), wielki wezyr Nevşehirli Damad İbrahim Pasza polecił mu utworzenie oficjalnego odżaku straży pożarnej. Odżak założony w Koszarach Acemi Oğlanları z sześcioma oficerami i pięćdziesięcioma żołnierzami liczył w 1724 150, a w 1755 461 osób. Dâvud pozostał na czele odżaku do śmierci w 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["Przyjęcie Mehmeda Efendiego przez Ludwika XV", "0ff5b174"], "d": ["Według hasła TDV o „Yirmisekiz Çelebi Mehmedzie Efendim” poseł został oficjalnie przyjęty w Pałacu Tuileries przez króla Francji Ludwika XV i złożył dary i list Ahmeda III. Podczas wizyty zwiedził pałace w Wersalu, Trianon i Marly, szpitale, obserwatoria i wytwórnie; to, co zobaczył, zapisał w rysunkach.", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["Powrót Mehmeda Efendiego do Stambułu", "a09a8bba"], "d": ["Według hasła TDV o „Yirmisekiz Çelebi Mehmedzie Efendim” obserwacje posła, który wrócił z rocznego poselstwa w Paryżu, wpłynęły na architektoniczny gust Epoki Tulipanów. Późniejsza współpraca jego syna z İbrahimem Müteferrika przygotowała grunt pod założenie pierwszej tureckiej drukarni, najtrwalszego dziedzictwa poselstwa.", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Budowa pałacu Sâdâbâd", "aec9c65e"], "d": ["Według hasła TDV o „Sâdâbâd” nad brzegiem potoku Kağıthane zbudowano rozległy kompleks rozrywkowo-wypoczynkowy złożony z pałacu inspirowanego francuską architekturą pałacową, kanałów, fontann i pawilonów. Sâdâbâd, który stał się ulubionym miejscem rozrywki epoki, został uwieczniony w wierszach poety Nedîma. Kompleks został w znacznej mierze zniszczony podczas powstania Patrony Halila w 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Zajęcie Derbentu przez siły rosyjskie: wyprawa kaspijska Piotra I", "c2b269f9"], "d": ["Gdy państwo Safawidów wskutek inwazji afgańskiej pogrążyło się w wewnętrznym zamęcie, car Rosji Piotr I wyruszył na wyprawę w celu zajęcia ziem irańskich nad Morzem Kaspijskim; nadmorskie miasto Derbent poddało się siłom rosyjskim bez godnego uwagi oporu. Według hasła TDV İslâm Ansiklopedisi o Derbencie to zajęcie było początkiem trwającego trzynaście lat tymczasowego panowania rosyjskiego; państwo osmańskie, wykorzystując ten sam zamęt, zwróciło się ku zachodniej części Kaukazu. Armia z Astrachania przeprawiła się morzem do zatoki Agrachań, stamtąd lądem wzdłuż wybrzeża przez Tarku; szamchał Tarku, ugościwszy Piotra, wszedł w zależność od Rosji.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Zniesienie szamchalatu Tarku: zarząd bezpośrednio rosyjski", "b0f029c6"], "d": ["Szamchał Tarku Adil-Girej, który w 1722 ugościł Piotra i wszedł w zależność od Rosji, zbuntował się w 1725; Jeropkin zburzył Tarku jesienią 1725, szamchał został aresztowany i zesłany w połowie maja 1726, a szamchalat zniesiono. Tarku i okolice pozostawały pod bezpośrednim zarządem rosyjskim do traktatu w Gandży z 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Zezwolenie İbrahimowi Müteferrika na założenie drukarni", "0659dd0a"], "d": ["Według hasła TDV o „İbrâhimie Müteferrika” na mocy fermanu Ahmeda III i fatwy szejhülislama Yenişehirli Abdullaha Efendiego zezwolono na założenie pierwszej tureckiej drukarni. Drukarnia rozpoczęła działalność w stambulskiej dzielnicy Yavuzselim. Müteferrika wydrukował do śmierci w 1747 siedemnaście dzieł w dwudziestu trzech tomach.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Ukończenie pierwszej drukowanej książki — Słownika Vankulu", "684700e8"], "d": ["Według hasła TDV o „İbrâhimie Müteferrika” pierwsze dzieło drukarni, turecki przekład Siḥâh al-Dżawharî (Słownik Vankulu), zostało ukończone na początku 1729. Była to pierwsza książka drukowana pismem arabskim w ziemiach osmańskich i uchodzi za początek tureckiej historii drukarstwa.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Stracenie Nevşehirli Damada İbrahima Paszy", "50c64341"], "d": ["Według hasła TDV o „Damadzie İbrâhimie Paszy, Nevşehirli” ciało wielkiego wezyra, zabitego w pałacu w czasie powstania Patrony Halila, wleczone po ulicach Stambułu, zostało porzucone w pobliżu Fontanny Ahmeda III na placu Sułtanahmet. Jego dwunastoletni wezyrat i Epoka Tulipanów zakończyły się w ten sposób krwawo.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Abdykacja Ahmeda III, wstąpienie na tron Mahmuda I", "a43f5d40"], "d": ["Według hasła TDV o „Mahmudzie I” wobec nacisku powstańców Ahmed III zrezygnował z tronu, uzyskawszy gwarancje dla siebie i dzieci, i sam wprowadził na tron bratanka, księcia Mahmuda. Mahmud I, który zasiadł na tronie z radą stryja „weź sprawy państwa we własne ręce, nikomu nie ufaj”, przystąpił w pierwszej kolejności do złamania wpływów grupy powstańców, która wprowadziła go na tron.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Reforma odżaku artylerii przez Humbaracı Ahmeda Paszę", "ea3a7c64"], "d": ["Według hasła TDV o „Humbaracı” oficer pochodzenia francuskiego Ahmed Pasza, który przeszedł na islam, przystąpił za wielkiego wezyra Hekimoğlu Alego Paszy do reformy organizacji płatnych humbaracich na modłę europejską. Utworzył nową strukturę podległą bezpośrednio wielkiemu wezyrowi, liczącą 601 osób — 300 na żołdzie i 301 timarowych. Kazał wyprodukować według ówczesnej technologii 100 moździerzy i 50 000 kul.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Założenie Hendesehâne (pierwszego wzoru szkoły inżynierskiej)", "a77ed1f3"], "d": ["Według hasła TDV o „Mahmudzie I” Humbaracı Ahmed Pasza, zakładając w Üsküdar Hendesehâne zwane też Humbarahâne, dał uczniom wybranym spośród służby pałacowej i bostanci wojskowe wykształcenie oparte na matematyce i geometrii. Ta instytucja uchodzi za pierwszy wzór szkół inżynierskich, które miały rozwinąć się w późniejszym okresie.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Traktat w Gandży: zwrot Derbentu i Baku Iranowi", "ff19d531"], "d": ["Rosja, szukająca sojuszu z Iranem przeciw zagrożeniu osmańskiemu, zwróciła na mocy traktatu w Gandży miasta nad Morzem Kaspijskim, trzymane od trzynastu lat, Iranowi pod dowództwem Nadir Chana (który nie przyjął jeszcze tytułu szacha). Według hasła TDV İslâm Ansiklopedisi o Derbencie to wycofanie było skutkiem niechęci Rosji do walki na południu jednocześnie na dwóch frontach (osmańskim i irańskim) i umocniło wojskowy prestiż Nadira, który otworzył mu drogę do wstąpienia na tron kilka lat później. Tarki (Tarku) pod zarządem rosyjskim również wróciło tym wycofaniem na stronę irańską (na mapie używa się dnia traktatu w Gandży). Salyan i Szabran pod zarządem rosyjskim wracają także tym wycofaniem na stronę irańską (dzień właściwy dla miejscowości nie występuje w źródle, na mapie używa się dnia traktatu w Gandży — przybliżenie z deklaracją).", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Wstąpienie Nadir Szacha na tron na stepie Mugan: faktyczny koniec dynastii Safawidów", "4f640979"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Nadir Szachu kurułtaj liczący około dwudziestu tysięcy osób, zebrany na stepie Mugan, uporczywie domagał się, by stanął na czele Iranu; Nadir przyjął tę propozycję pod warunkiem porzucenia nadmiernie szyickiego rozumienia, które było przyczyną wojen między Safawidami a Osmanami, i przyjęcia umiarkowanego mazhabu dżafarytów, i 24 şewwala 1148 (8 marca 1736) wstąpił na tron z tytułem Nâdir Szach. Oznaczało to faktyczny koniec dwustuletniej dynastii Safawidów i założenie dynastii Afszarydów.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Początek epidemii dżumy w Stambule", "9fa82b56"], "d": ["Według hasła TDV o „Tâun” epidemia dżumy, która w latach 1739–1743 działała w świecie islamu, dotknęła w tym czasie także Stambuł. Hasło odnotowuje, że epidemie w XVIII wieku przebiegały względnie łagodniej niż w poprzednich stuleciach. Wśród okresów epidemii wymienia się także lata 1713, 1719, 1728–1729 i 1759–1765.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Pożar Hocapaşa", "321c7d0d"], "d": ["Według hasła TDV o „Meczecie Fatmy Sułtan” pożar Hocapaşa, który wybuchł w nocy, zniszczył Bâbıâli i okolice; przypuszcza się, że meczet Fatmy Sułtan w tej okolicy również ucierpiał w tym pożarze. Ta katastrofa, jeden z wielkich pożarów nawiedzających Stambuł za Osmana III, przyniosła ciężkie zniszczenia w centrum handlu i administracji miasta.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Wezyrat Koca Ragıpa Mehmeda Paszy", "a1846910"], "d": ["Ragıp Pasza, znany jako poeta i dyplomata, został przez Osmana III mianowany na urząd wielkiego wezyra (po śmierci Osmana III w październiku 1757 pozostał na urzędzie, otrzymawszy od Mustafy III nową pieczęć). W czasie trwania wojen siedmioletnich prowadził zrównoważoną politykę zagraniczną, utrzymując państwo osmańskie poza konfliktami w Europie. W trwającym sześć lat wezyracie przywiązywał wagę także do działalności kulturalnej, jak zakładanie bibliotek.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Śmierć Ragıpa Paszy", "6bc19323"], "d": ["Ragıp Pasza zmarł po sześcioletnim wezyracie. Wraz z jego śmiercią skończył się najdłużej trwający i zrównoważony wezyrat epoki Mustafy III.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Wielkie trzęsienie ziemi w Stambule i zawalenie się meczetu Fatiha", "2475b4dc"], "d": ["Według hasła TDV o „Meczecie i kompleksie Fatiha” w wielkim trzęsieniu ziemi z 1766 główna kopuła meczetu całkowicie się zawaliła, a ściany uległy uszkodzeniom nienadającym się do naprawy. Odbudowa rozpoczęta w 1767 z rozkazu Mustafy III pod kierunkiem architektów Sarıma İbrahima Efendiego i İzzeta Mehmeda Beja została ukończona w 1771 według nowego projektu różniącego się od dawnego planu.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Krótkotrwała próba szkoły artylerii pod kierunkiem barona de Tott", "4192260c"], "d": ["Według hasła TDV o „Mühendishâne-i Bahrî-i Hümâyun” niepowodzenia w wojnie osmańsko-rosyjskiej 1768 ukazały potrzebę technicznego kształcenia wojskowego; krótkotrwała szkoła artylerii otwarta przy udziale francuskiego oficera barona de Tott rozpoczęła działalność w październiku 1772, lecz okazała się nieskuteczna. Ta próba uchodzi za prekursora Mühendishâne-i Bahrî-i Hümâyun, które miało zostać założone w 1775.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Wstąpienie na tron Selima III", "00d046d9"], "d": ["Po śmierci Abdülhamida I na tron wstąpił jego bratanek Selim III. Według hasła TDV İslâm Ansiklopedisi o Selimie III nowy sułtan, który od czasów książęcych interesował się reformą armii europejskich, wkrótce po wstąpieniu na tron zaczął przygotowywać program gruntownej odnowy. Ten program miał w ciągu kilku lat zostać nazwany Nizâm-ı Cedîd.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Początek przygotowywania programu reform Nizâm-ı Cedîd", "eff78a68"], "d": ["Selim III kazał przygotować kompleksowy program odnowy na podstawie projektów żądanych od dostojników państwa i zagranicznych ekspertów. Według hasła TDV İslâm Ansiklopedisi o Nizâm-ı Cedîd program ten nie ograniczył się do utworzenia nowej armii; przekształcił się w szeroki ruch reformatorski obejmujący także finanse, zarząd prowincjonalny i dyplomację. Program miał w ciągu następnych piętnastu lat znaleźć zarówno zwolenników, jak i przeciwników.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Założenie stałych poselstw w stolicach europejskich", "2e9dc8a1"], "d": ["Selim III po raz pierwszy w dziejach państwa osmańskiego wysłał do wielkich ośrodków europejskich stałych posłów mających pełnić służbę nieprzerwanie. Według hasła TDV İslâm Ansiklopedisi o posle (Elçi) ten krok nadał trwałą organizację osmańskiej dyplomacji, prowadzonej do tej pory jedynie tymczasowymi, jednorazowymi delegacjami. Głównym zadaniem nowych poselstw było regularne informowanie Stambułu o wydarzeniach politycznych i wojskowych w Europie.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Utworzenie skarbu İrad-ı Cedîd", "ae5c8ce2"], "d": ["Dla pokrycia wydatków armii Nizâm-ı Cedîd i programu reform utworzono odrębny skarb. Według hasła TDV İslâm Ansiklopedisi o esham wśród dochodów nowego skarbu znajdowały się bezpośrednie prowadzenie niektórych mukataa przez państwo i objęcie kontrolą sprzedaży esham. To uregulowanie było próbą stworzenia nowego źródła poza tradycyjnym systemem finansowym.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Początek powstania Kabakçı Mustafy", "b98eee17"], "d": ["Niezadowolenie narastające wobec Nizâm-ı Cedîd wybuchło buntem żołnierzy yamak pod wodzą Kabakçı Mustafy. Według hasła TDV İslâm Ansiklopedisi o powstaniu Kabakçı powstańcy w krótkim czasie przejęli kontrolę w Stambule i zażądali głów dostojników państwa sprzyjających Nizâm-ı Cedîd. Powstanie zakończyło się w ciągu kilku dni detronizacją Selima III.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Detronizacja Selima III", "ff2c30ec"], "d": ["Pod naciskiem powstania Kabakçı Mustafy Selim III został zdetronizowany na mocy fatwy uzyskanej od szejhülislama. Według hasła TDV İslâm Ansiklopedisi o Selimie III ta decyzja była chwilą, w której trwający osiemnaście lat okres reform faktycznie się skończył; armię Nizâm-ı Cedîd również wkrótce rozwiązano. Selima zaczęto trzymać pod strażą w Pałacu Topkapı.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Wstąpienie na tron Mustafy IV", "8f1ac86c"], "d": ["Bezpośrednio po detronizacji Selima III sułtanem ogłoszono jego bratanka Mustafę IV. Według hasła TDV İslâm Ansiklopedisi o Mustafie IV nowy sułtan rozpoczął panowanie pod wpływem kręgów przeciwnych Nizâm-ı Cedîd, które poparły powstanie. Ten krótki okres był fazą niestabilności, w której władza centralna bardzo osłabła.", "58865f17"]}
});
